  var DVA_ALIAS = {
    noradrenalina: 'noradrenalina', norepinefrina: 'noradrenalina', nora: 'noradrenalina',
    adrenalina: 'adrenalina', adrena: 'adrenalina', epinefrina: 'adrenalina', epi: 'adrenalina',
    dobutamina: 'dobutamina', dobuta: 'dobutamina', dobu: 'dobutamina',
    vasopressina: 'vasopressina', vaso: 'vasopressina', pitressin: 'vasopressina',
    nitroprussiato: 'nitroprussiato', nipride: 'nitroprussiato',
    nitroglicerina: 'nitroglicerina', tridil: 'nitroglicerina'
  };

  function drogasVasoativas(droga, pesoKg, solucao) {
    var ID = 'dva', NOME = 'Infusão de Vasoativo';
    return seguro(ID, NOME, function () {
      var c = novoCtx();
      var chave = ausente(droga) ? 'noradrenalina' : DVA_ALIAS[semAcento(droga)];
      if (!chave) {
        c.erros.push('Droga não reconhecida (noradrenalina, adrenalina, dobutamina, vasopressina, nitroprussiato, nitroglicerina)');
        return falhaCtx(ID, NOME, c);
      }
      var d = DVA[chave];
      var peso = null;
      if (d.peso) peso = num(c, pesoKg, 'Peso (kg)', 30, 350);
      var tipoSol = ausente(solucao) ? 'padrao' : semAcento(solucao);
      if (tipoSol === 'concentrado' || tipoSol === 'concentrada' || tipoSol === '2x') tipoSol = 'concentrada';
      if (tipoSol !== 'padrao' && tipoSol !== 'concentrada') c.erros.push('Solução: use "padrao" ou "concentrada"');
      else if (!d.preparos[tipoSol]) c.erros.push('Solução "' + tipoSol + '" não disponível para ' + d.nome);
      if (pendente(c)) return falhaCtx(ID, d.nome, c);

      var prep = d.preparos[tipoSol];
      var mg = prep.mg;
      var volFinal = prep.vol;
      var conc = prep.conc;
      var textoPreparo = prep.ref;
      exigirFinito(conc);
      if (!(conc > 0)) throw new Error('CONCENTRACAO_ZERO');

      var maxRate = 0;
      var tabelaLegada = [];
      var linhas = d.doses.map(function (dose) {
        var ml;
        if (d.unidade === 'mcg/kg/min') ml = (dose * peso * 60) / conc;
        else if (d.unidade === 'mcg/min') ml = (dose * 60) / conc;
        else ml = (dose * 60) / conc;
        exigirFinito(ml);
        if (ml > maxRate) maxRate = ml;
        var mlArred = Math.round(ml * 10) / 10;
        tabelaLegada.push({ doseMcgKgMin: dose, mlH: mlArred, dose: dose });
        var mlTxt = (mlArred % 1 === 0 ? mlArred : fmt(mlArred, 1)) + ' mL/h';
        return fmt(dose, dose < 0.1 ? 2 : (dose % 1 === 0 ? 0 : 1)) + ' ' + d.unidade + ' → ' + mlTxt;
      });

      var base = [];
      if (d.peso) base.push('Peso: ' + fmt(peso, 1) + ' kg');
      base.push('Quantidade de fármaco: ' + fmt(mg, 0) + (d.unidade === 'UI/min' ? ' UI' : ' mg'));
      base.push('Volume final: ' + fmt(volFinal, 0) + ' mL');
      base.push('Concentração: ' + fmt(conc, d.unidade === 'UI/min' ? 1 : 0) + ' ' + d.conc);
      base.push(textoPreparo);

      var fichaD1 = (typeof CompatibilidadeYDvaService !== 'undefined') ? CompatibilidadeYDvaService.obterFichaDiluicao(chave) : null;
      if (fichaD1) {
        base.push('Diluente Padrão (D1): ' + fichaD1.diluenteD1);
        base.push('Acesso Recomendado: ' + fichaD1.acessoVenoso);
      }

      var avisos = ['Vazões calculadas para a concentração acima. Dupla checagem obrigatória na bomba.'];
      if (d.peso && gt(peso, 150)) avisos.unshift('⚠️ OBESIDADE SEVERA (> 150 kg): O cálculo por mcg/kg/min no peso real pode levar a taxas de infusão excessivas. Recomenda-se titular a dose estritamente pela PAM alvo (≥ 65 mmHg) e considerar o Peso Ideal ou Ajustado.');
      if (d.aviso) avisos.unshift(d.aviso);
      if (fichaD1 && fichaD1.solucaoIncompativelAviso) avisos.push(fichaD1.solucaoIncompativelAviso);

      var taxaFixaVaso = (chave === 'vasopressina' ? 9.0 : null);
      var doseInicialTxt = d.unidade === 'UI/min' 
        ? ('Dose fixa recomendada: ' + fmt(d.doses[0], 2) + ' UI/min (' + (taxaFixaVaso || 9) + ' mL/h na bomba)')
        : ('Dose inicial recomendada: ' + fmt(d.doses[0], d.doses[0] < 0.1 ? 2 : 1) + ' ' + d.unidade + ' (' + (tabelaLegada[0] ? tabelaLegada[0].mlH : '0') + ' mL/h na bomba)');

      var secoes = [
        ['🔴 AÇÃO IMEDIATA / DOSE DE ATAQUE', [
          doseInicialTxt,
          'Alvo imediato: PAM ≥ 65 mmHg (titulação seriada a cada 2 a 5 minutos)',
          (d.peso ? 'Peso considerado: ' + fmt(peso, 0) + ' kg (' + fmt(peso, 1) + ' kg)' : 'Dose fixa independente de peso')
        ]],
        ['🟡 DILUIÇÃO, VELOCIDADE DE INFUSÃO E MANUTENÇÃO', [
          textoPreparo,
          (fichaD1 ? '💧 Diluente Oficial (D1): ' + fichaD1.diluenteD1 : '💧 Diluente de escolha: SG 5% ou SF 0,9% conforme estabilidade'),
          (fichaD1 ? '💉 Acesso Venoso: ' + fichaD1.acessoVenoso : '💉 Acesso venoso central preferencial'),
          'Concentração da solução: ' + fmt(conc, d.unidade === 'UI/min' ? 1 : 0) + ' ' + d.conc,
          'Tabela de Vazão em Bomba de Infusão Contínua (BIC):'
        ].concat(linhas)],
        ['⚠️ ALERTAS DE SEGURANÇA E BLOQUEIOS', avisos],
        ['ℹ️ JUSTIFICATIVA CLÍNICA E REFERÊNCIAS', ['Droga vasoativa de 1ª linha / suporte hemodinâmico'].concat(d.acoes)]
      ];

      return sucesso({
        id: ID, nome: d.nome, estado: 'CALCULO', rotulo: 'CÁLCULO DE INFUSÃO · CONFERIR PREPARO',
        principal: fmt(conc, d.unidade === 'UI/min' ? 1 : 0) + ' ' + d.conc,
        secoes: secoes,
        avisos: avisos,
        dados: { droga: chave, concentracao: conc, unidadeConcentracao: d.conc, solucao: tipoSol, tabela: tabelaLegada },
        legado: {
          droga: d.nome,
          concentracaoMcgMl: conc,
          pesoKg: peso,
          tabela: tabelaLegada,
          taxaMlH: taxaFixaVaso || (tabelaLegada[0] ? tabelaLegada[0].mlH : null),
          preparo: textoPreparo
        },
        botoes: botoesEmergencia(ID, [btn('🎚️ Calcular outra dose', ID, 'dose'), btn('🧴 Revisar preparo', ID, 'preparo')])
      });
    });
  }

  // ═════════════════════════════ SEQUÊNCIA RÁPIDA DE INTUBAÇÃO ═════════════════════════════

  var SRI_FARMACOS = {
    etomidato:      { nome: 'Etomidato',      dose: 0.3, un: 'mg', conc: 2,  tetoMaximo: 40,  txt: '0,3 mg/kg · 2 mg/mL (ampola 20mg/10mL)',  grupo: 'indutor', contra: 'Evitar em sepse se suspeita de insuficiência adrenal aguda, risco de supressão adrenal transitória.' },
    quetamina:      { nome: 'Quetamina',      dose: 1.5, un: 'mg', conc: 50, tetoMaximo: 200, txt: '1,5 mg/kg · 50 mg/mL (ampola 50mg/mL)', grupo: 'indutor', contra: 'Broncodilatador (ideal em asma). Evitar em hipertensão craniana severa ou glaucoma sem uso prévio de opioide.' },
    propofol:       { nome: 'Propofol 1%',    dose: 1.5, un: 'mg', conc: 10, tetoMaximo: 200, txt: '1,5 mg/kg · 10 mg/mL (ampola 1%)',        grupo: 'indutor', contra: 'Hipotensor potente. Reduzir dose pela metade em choque hemodinâmico ou senilidade.' },
    midazolam:      { nome: 'Midazolam',      dose: 0.2, un: 'mg', conc: 5,  tetoMaximo: 15,  txt: '0,2 mg/kg · 5 mg/mL (ampola 5mg/mL)',   grupo: 'indutor', contra: 'Depressor miocárdico e venodilatador. Evitar em choque descompensado.' },
    rocuronio:      { nome: 'Rocurônio',      dose: 1.2, un: 'mg', conc: 10, tetoMaximo: 120, txt: '1,2 mg/kg · 10 mg/mL (frasco 50mg/5mL)', grupo: 'bloqueador', contra: 'Ação em ~45-60s. Escolha de excelência. Reversível com Sugamadex.' },
    succinilcolina: { nome: 'Succinilcolina', dose: 1.5, un: 'mg', conc: 10, tetoMaximo: 200, txt: '1,5 mg/kg · 10 mg/mL (frasco 100mg/10mL)', grupo: 'bloqueador', contra: '⚠️ CONTRAINDICADA em: Hipercalemia (> 5.5), grandes queimados, esmagamento, miopatias, paralisia/AVC > 48h (risco de PCR por hipercalemia). Teto máximo: 200 mg.' },
    fentanil:       { nome: 'Fentanil',       dose: 2.0, un: 'mcg',conc: 50, tetoMaximo: 250, txt: '2 mcg/kg · 50 mcg/mL (ampola 50mcg/mL)',  grupo: 'adjuvante', contra: 'Pico de ação em 3-5 min. Atenua reflexo simpático da laringoscopia.' }
  };

  function resolverFarmaco(ctx, v, grupo, rotulo) {
    if (ausente(v)) return null;
    var k = semAcento(v);
    if (k === 'succinil' || k === 'suxametonio') k = 'succinilcolina';
    if (k === 'rocuronio' || k === 'roc') k = 'rocuronio';
    if (k === 'ketamina' || k === 'cetamina') k = 'quetamina';
    if (k === 'nenhum' || k === 'nao') return null;
    var f = SRI_FARMACOS[k];
    if (!f || f.grupo !== grupo) { ctx.erros.push(rotulo + ': fármaco inválido para esta etapa'); return null; }
    return { chave: k, f: f };
  }

  /**
   * SRI / IOT (Pronto-Socorro & UTI)
   * Se indutor/bloqueador forem informados, gera relatório direcionado.
   * Se NÃO informados (ex: '/sri 70'), calcula e exibe o CARTÃO DE EMERGÊNCIA COMPLETO
   * para tomada de decisão imediata à beira-leito sem atraso de comunicação.
   */
  function sequenciaRapidaIntubacao(pesoKg, contextoClinico, indutor, bloqueador, adjuvante) {
    var ID = 'sri', NOME = 'Sequência Rápida de Intubação (SRI)';
    return seguro(ID, NOME, function () {
      var c = novoCtx();
      var peso = num(c, pesoKg, 'Peso (kg)', 30, 300);
      var ctxTxt = 'Padrão / Hemodinâmica Estável';
      var ctxChave = 'padrao';
      if (!ausente(contextoClinico)) {
        if (typeof contextoClinico !== 'string') c.erros.push('Contexto: texto esperado');
        else {
          var t = semAcento(contextoClinico);
          if (/choque|sepse|instav|hipotens/.test(t)) { ctxChave = 'choque'; ctxTxt = 'Choque / Instabilidade Hemodinâmica'; }
          else if (/asma|bronco|dpoc/.test(t)) { ctxChave = 'asma'; ctxTxt = 'Broncoespasmo Grave / Asma / DPOC'; }
          else if (/tce|neuro|avc/.test(t)) { ctxChave = 'tce'; ctxTxt = 'Neurointensivismo / TCE / AVC'; }
        }
      }
      var ind = resolverFarmaco(c, indutor, 'indutor', 'Indutor');
      var blq = resolverFarmaco(c, bloqueador, 'bloqueador', 'Bloqueador');
      var adj = resolverFarmaco(c, adjuvante, 'adjuvante', 'Adjuvante');
      if (pendente(c)) return falhaCtx(ID, NOME, c);

      // Pré-cálculo universal de todas as drogas para disponibilidade imediata
      function calcDose(farmaco) {
        var d = farmaco.dose * peso;
        if (farmaco.tetoMaximo && d > farmaco.tetoMaximo) {
          d = farmaco.tetoMaximo;
        }
        var ml = d / farmaco.conc;
        exigirFinito(d, ml);
        return {
          dose: Math.round(d * 10) / 10,
          ml: Math.round(ml * 10) / 10,
          un: farmaco.un,
          conc: farmaco.conc
        };
      }

      var dFentanil = calcDose(SRI_FARMACOS.fentanil);
      var dEtomidato = calcDose(SRI_FARMACOS.etomidato);
      var dQuetamina = calcDose(SRI_FARMACOS.quetamina);
      var dPropofol = calcDose(SRI_FARMACOS.propofol);
      var dMidazolam = calcDose(SRI_FARMACOS.midazolam);
      var dSuccinil = calcDose(SRI_FARMACOS.succinilcolina);
      var dRocuronio = calcDose(SRI_FARMACOS.rocuronio);

      var mostrarTodos = (ind === null && blq === null && adj === null && semAcento(String(adjuvante || '')) !== 'nenhum');
      var linhasDoses = [];
      if (mostrarTodos) {
        linhasDoses.push('1️⃣ Pré-tratamento: Fentanil (50 mcg/mL · 2 mcg/kg): ' + fmt(dFentanil.dose, 0) + ' mcg → ' + fmt(dFentanil.ml, 1) + ' mL IV lento');
        linhasDoses.push('2️⃣ Sedativos / Indução (escolha 1):');
        linhasDoses.push('   • Etomidato (2 mg/mL · 0,3 mg/kg): ' + fmt(dEtomidato.dose, 1) + ' mg → ' + fmt(dEtomidato.ml, 1) + ' mL IV');
        linhasDoses.push('   • Quetamina (50 mg/mL · 1,5 mg/kg): ' + fmt(dQuetamina.dose, 0) + ' mg → ' + fmt(dQuetamina.ml, 1) + ' mL IV');
        if (ctxChave !== 'choque') {
          linhasDoses.push('   • Propofol 1% (10 mg/mL · 1,5 mg/kg): ' + fmt(dPropofol.dose, 0) + ' mg → ' + fmt(dPropofol.ml, 1) + ' mL IV');
        }
        linhasDoses.push('3️⃣ Bloqueadores Neuromusculares (escolha 1):');
        linhasDoses.push('   • Succinilcolina (10 mg/mL · 1,5 mg/kg): ' + fmt(dSuccinil.dose, 0) + ' mg → ' + fmt(dSuccinil.ml, 1) + ' mL IV');
        linhasDoses.push('   • Rocurônio (10 mg/mL · 1,2 mg/kg): ' + fmt(dRocuronio.dose, 1) + ' mg → ' + fmt(dRocuronio.ml, 1) + ' mL IV');
      } else {
        if (adj && adj.chave === 'fentanil') {
          linhasDoses.push('1️⃣ Pré-tratamento Selecionado: Fentanil (50 mcg/mL · 2 mcg/kg): ' + fmt(dFentanil.dose, 0) + ' mcg → ' + fmt(dFentanil.ml, 1) + ' mL IV lento');
        } else if (semAcento(String(adjuvante || '')) === 'nenhum') {
          linhasDoses.push('1️⃣ Pré-tratamento: Nenhum adjuvante (sem opioide)');
        }
        if (ind) {
          var dInd = calcDose(ind.f);
          linhasDoses.push('2️⃣ Indutor Selecionado: ' + ind.f.nome + ' (' + ind.f.conc + ' ' + ind.f.un + '/mL · ' + fmt(ind.f.dose, 1) + ' ' + ind.f.un + '/kg): ' + fmt(dInd.dose, 1) + ' ' + ind.f.un + ' → ' + fmt(dInd.ml, 1) + ' mL IV'); if(ind.f.contra) linhasDoses.push('⚠️ ' + ind.f.contra);
        }
        if (blq) {
          var dBlq = calcDose(blq.f);
          linhasDoses.push('3️⃣ Bloqueador Selecionado: ' + blq.f.nome + ' (' + blq.f.conc + ' ' + blq.f.un + '/mL · ' + fmt(blq.f.dose, 1) + ' ' + blq.f.un + '/kg): ' + fmt(dBlq.dose, 1) + ' ' + blq.f.un + ' → ' + fmt(dBlq.ml, 1) + ' mL IV'); if(blq.f.contra) linhasDoses.push('⚠️ ' + blq.f.contra);
        }
      }

      var recomendacoes = [];
      if (gt(peso, 150)) {
        recomendacoes.push('⚠️ PACIENTE COM OBESIDADE GRAVE (> 150 kg): Fentanil, Propofol e Midazolam devem ser dosados pelo Peso Ideal (IBW). Rocurônio pelo Peso Ideal ou Ajustado (máx 150 mg). Succinilcolina pode ser calculada pelo peso real (máx 200 mg), prevenindo colapso hemodinâmico e bloqueio neuromuscular prolongado.');
      } else if (gt(peso, 100)) {
        recomendacoes.push('⚠️ PACIENTE COM OBESIDADE (≥ 100 kg): Atenção estrita à farmacocinética! Fentanil, Propofol, Etomidato e Midazolam devem ser dosados pelo Peso Ideal (IBW). Rocurônio pelo Peso Ideal ou Ajustado (máx 150 mg). Apenas Succinilcolina deve ser dosada pelo Peso Real (teto máximo de 200 mg).');
      }
      if (ctxChave === 'choque') {
        recomendacoes.push('🏆 Sedativo: Etomidato ou Quetamina (estabilidade cardiovascular).');
        recomendacoes.push('⚠️ Evite Midazolam e Propofol (risco alto de colapso hemodinâmico e vasodilatação).');
        recomendacoes.push('🏆 BNM: Rocurônio preferencial (Succinilcolina se K⁺ comprovadamente normal).');
      } else if (ctxChave === 'asma') {
        recomendacoes.push('🏆 Sedativo: Quetamina (potente broncodilatador simpaticomimético).');
        recomendacoes.push('🏆 BNM: Rocurônio ou Succinilcolina.');
      } else if (ctxChave === 'tce') {
        recomendacoes.push('🏆 Sedativo: Etomidato (mantém Pressão de Perfusão Cerebral e reduz PIC).');
        recomendacoes.push('💉 Fentanil 3 min antes da laringoscopia para atenuar pico simpático.');
        recomendacoes.push('🏆 BNM: Rocurônio preferencial.');
      } else {
        recomendacoes.push('🏆 Sedativo padrão: Etomidato ou Quetamina.');
        recomendacoes.push('🏆 BNM padrão: Succinilcolina ou Rocurônio.');
      }

      var avisos = [
        'Succinilcolina é contraindicada se hipercalemia, queimadura/grande trauma > 72h ou miopatias.',
        'Checklist 7 Ps: Preparação ➔ Pré-oxigenação ➔ Pré-tratamento ➔ Paralisia com indução ➔ Posicionamento ➔ Passagem do tubo ➔ Pós-intubação.'
      ];

      var secoes = [
        ['🔴 AÇÃO IMEDIATA / CONDUTA / DOSE DE ATAQUE', linhasDoses],
        ['🟡 DILUIÇÃO, VELOCIDADE DE INFUSÃO E MANUTENÇÃO', [
          'Peso base: ' + fmt(peso, 1) + ' kg · Cenário clínico: ' + ctxTxt,
          'Ordem cronológica: Pré-oxigenação ➔ Fentanil (lento 2 min) ➔ Indutor em bolus IV ➔ Bloqueador em bolus IV rápido ➔ Laringoscopia aos 45-60s'
        ]],
        ['⚠️ ALERTAS DE SEGURANÇA E BLOQUEIOS', avisos.concat(recomendacoes.filter(function(r) { return r.indexOf('⚠️') !== -1; }))],
        ['ℹ️ JUSTIFICATIVA CLÍNICA E REFERÊNCIAS', recomendacoes.filter(function(r) { return r.indexOf('⚠️') === -1; })]
      ];

      return sucesso({
        id: ID, nome: NOME, estado: 'PRIORITARIO', rotulo: 'SALA VERMELHA · SRI / IOT',
        principal: fmt(peso, 0) + ' kg · ' + ctxTxt,
        secoes: secoes,
        avisos: avisos,
        dados: {
          pesoKg: peso,
          contexto: ctxChave,
          fentanil: { doseMcg: dFentanil.dose, ml: dFentanil.ml },
          etomidato: { doseMg: dEtomidato.dose, ml: dEtomidato.ml },
          quetamina: { doseMg: dQuetamina.dose, ml: dQuetamina.ml },
          succinilcolina: { doseMg: dSuccinil.dose, ml: dSuccinil.ml },
          rocuronio: { doseMg: dRocuronio.dose, ml: dRocuronio.ml },
          propofol: { doseMg: dPropofol.dose, ml: dPropofol.ml }
        },
        legado: {
          pesoKg: peso,
          fentanil: { doseMcg: dFentanil.dose, ml: dFentanil.ml },
          etomidato: { doseMg: dEtomidato.dose, ml: dEtomidato.ml },
          quetamina: { doseMg: dQuetamina.dose, ml: dQuetamina.ml },
          succinilcolina: { doseMg: dSuccinil.dose, ml: dSuccinil.ml },
          rocuronio: { doseMg: dRocuronio.dose, ml: dRocuronio.ml }
        },
        botoes: botoesEmergencia(ID, [btn('✅ Checklist 7 Ps', ID, 'checklist'), btn('🫁 Via Aérea Difícil', ID, 'vad')])
      });
    });
  }

  // ═════════════════════════════ FÓRMULA DE PARKLAND (QUEIMADURAS) ═════════════════════════════

  /**
   * Fórmula de Parkland clássica (ATLS 10ª ed / SBA / ABA):
   * Volume Total 24h = 4 mL × Peso (kg) × % SCQ (Superfície Corpórea Queimada 2º e 3º graus)
   * Solução: Ringer Lactato (RL)
   * 1ª fase (primeiras 8h a contar do acidente): 50% do volume total
   * 2ª fase (próximas 16h): 50% do volume total
   */
  /**
   * Ressuscitação Volêmica no Grande Queimado (Consenso ABA 2024 / ATLS 11ª Ed / SBQ / Parkland):
   * - Adulto térmico/químico: 2 mL/kg/% SCQ (Ringer Lactato)
   * - Pediátrico (< 14 anos ou <= 30 kg): 3 mL/kg/% SCQ + Manutenção glicídica SG 5% (Holliday-Segar)
   * - Elétrica alta voltagem: 4 mL/kg/% SCQ (meta de diurese 1.0-1.5 mL/kg/h)
   * - Parkland clássico histórico (4 mL/kg/% SCQ) preservado para comparação
   * 1ª fase (primeiras 8h a contar do ACIDENTE): 50% do volume de expansão
   * 2ª fase (próximas 16h): 50% do volume de expansão
   */
  function parkland(pesoKg, scqPorcentagem, tipoQueimadura, idadeAnos, horasDecorridas, volumeJaInfundido) {
    var ID = 'parkland', NOME = 'Ressuscitação em Grandes Queimados (Consenso ABA / ATLS / Parkland)';
    return seguro(ID, NOME, function () {
      var c = novoCtx();
      var rawPeso = (typeof pesoKg === 'object' && pesoKg !== null) ? pesoKg.peso : pesoKg;
      var rawScq = (typeof pesoKg === 'object' && pesoKg !== null) ? (pesoKg.scq || pesoKg.sctq) : scqPorcentagem;
      var rawTipo = (typeof pesoKg === 'object' && pesoKg !== null) ? (pesoKg.tipoQueimadura || pesoKg.tipo) : tipoQueimadura;
      var rawIdade = (typeof pesoKg === 'object' && pesoKg !== null) ? pesoKg.idade : idadeAnos;
      var rawHoras = (typeof pesoKg === 'object' && pesoKg !== null) ? (pesoKg.horasDecorridas || pesoKg.horas) : horasDecorridas;
      var rawVolInfundido = (typeof pesoKg === 'object' && pesoKg !== null) ? (pesoKg.volumeJaInfundido || pesoKg.volumeInfundido) : volumeJaInfundido;

      var peso = num(c, rawPeso, 'Peso corporal (kg)', 0.5, 350);
      var scq = num(c, rawScq, 'Superfície Corpórea Queimada - SCQ (%)', 0.5, 100);
      if (pendente(c)) return falhaCtx(ID, NOME, c);

      var idade = (rawIdade !== undefined && rawIdade !== null && rawIdade !== '') ? Number(rawIdade) : null;
      var horas = Number(rawHoras || 0);
      var volJaInfundido = Number(rawVolInfundido || 0);

      var tipoNorm = String(rawTipo || 'termica').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
      var isEletrica = tipoNorm.indexOf('eletr') !== -1;
      var isPediatrico = tipoNorm.indexOf('ped') !== -1 || (idade !== null ? idade < 14 : peso <= 30);

      // Determinação do Fator ABA / ATLS (mL/kg/%SCQ)
      var fator = 2; // Padrão adulto térmico (ATLS 10ª/11ª Ed / ABA 2024)
      var perfil = 'Adulto — Queimadura Térmica/Química';
      var diretriz = 'Consenso ABA 2023/2024 & ATLS 10ª/11ª Ed. (2 mL/kg/%SCQ)';

      if (isEletrica) {
        fator = 4;
        perfil = isPediatrico ? 'Pediátrico — Queimadura Elétrica de Alta Voltagem' : 'Adulto — Queimadura Elétrica de Alta Voltagem';
        diretriz = 'Consenso ABA / ATLS — Alta Voltagem / Rabdomiólise (4 mL/kg/%SCQ)';
      } else if (isPediatrico) {
        fator = 3;
        perfil = 'Pediátrico (< 14 anos ou ≤ 30 kg) — Queimadura Térmica';
        diretriz = 'Consenso ABA / ATLS Pediátrico (3 mL/kg/%SCQ + Manutenção Glicídica)';
      }

      var volTotalAba = Math.round(fator * peso * scq); // Volume moderno ABA 2024
      var vol8hBruto = Math.round(volTotalAba / 2);
      var vol16h = Math.round(volTotalAba / 2);

      // Parkland Clássico (4 mL/kg/%SCQ) para histórico e rastreabilidade
      var volTotalClassico = Math.round(4 * peso * scq);
      var vol8hClassico = Math.round(volTotalClassico / 2);
      var vol16hClassico = Math.round(volTotalClassico / 2);

      var horasRestantes1 = Math.max(0.5, 8 - horas);
      var volRestante1 = Math.max(0, vol8hBruto - volJaInfundido);
      var vazao8h = horas < 8 ? Math.round(volRestante1 / horasRestantes1) : 0;
      var vazao16h = Math.round(vol16h / 16);

      // Manutenção Pediátrica Holliday-Segar (SG 5%)
      var volManutencao = 0;
      var vazaoManutencao = 0;
      if (isPediatrico) {
        if (peso <= 10) volManutencao = Math.round(peso * 100);
        else if (peso <= 20) volManutencao = Math.round(1000 + (peso - 10) * 50);
        else volManutencao = Math.round(1500 + (peso - 20) * 20);
        vazaoManutencao = Math.round(volManutencao / 24);
      }

      var debitoMin = Math.round(peso * (isEletrica ? 1.0 : (isPediatrico ? 1.0 : 0.5)) * 10) / 10;
      var debitoMax = Math.round(peso * (isEletrica ? 1.5 : (isPediatrico ? 1.0 : 1.0)) * 10) / 10;
      if (!isPediatrico && !isEletrica) {
        debitoMin = Math.max(30, debitoMin);
        debitoMax = Math.max(50, debitoMax);
      }

      var avisos = [
        '⏱️ MARCO ZERO DO TRAUMA: O relógio das primeiras 8 horas conta A PARTIR DO MOMENTO DO ACIDENTE/QUEIMADURA, não da chegada ao hospital.',
        '🔥 CÁLCULO DE %SCQ: Contabilize exclusivamente queimaduras de 2º e 3º graus. Eritema simples (1º grau) não entra na fórmula.',
        '💧 PREVENÇÃO DE FLUID CREEP: O consenso moderno da ABA/ATLS reduziu a reposição para 2 mL/kg/% em adultos para evitar sobrecarga hídrica, síndrome compartimental abdominal e edema pulmonar. Titular vazão pela diurese horária (±20% a 30%/h).',
        'Descontar da 1ª etapa qualquer volume de cristaloide já infundido no atendimento pré-hospitalar/transporte.'
      ];

      if (lt(peso, 10) || isPediatrico) {
        avisos.unshift('⚠️ QUEIMADURA EM PEDIATRIA / LACTENTE (< 10 kg): Crianças têm menor reserva hepática de glicogênio. Além do volume de expansão com Ringer Lactato (3 mL/kg/% SCQ), DEVE-SE adicionar hidratação venosa de manutenção com SG 5% (Holliday-Segar: ' + fmt(volManutencao, 0) + ' mL/dia = ' + fmt(vazaoManutencao, 0) + ' mL/h contínua) para prevenir hipoglicemia severa.');
      }
      if (gt(peso, 120)) {
        avisos.unshift('⚠️ OBESIDADE SEVERA (> 120 kg): O cálculo pelo peso real gera volumes massivos com risco extremo de "fluid creep", Síndrome Compartimental Abdominal e edema agudo de pulmão. Utilizar o Peso Ideal (IBW) ou fórmula ABA de 2 mL/kg/% SCQ e titular estritamente pelo débito urinário (alvo: 0,5 mL/kg/h).');
      }
      if (gt(scq, 50)) {
        avisos.unshift('🚨 GRANDE QUEIMADO CRÍTICO (SCQ > 50%): Risco altíssimo de choque distributivo/hipovolêmico precoce e hipotermia. Monitorização em Centro de Queimados e ressuscitação volêmica intensiva.');
      }
      if (isEletrica) {
        avisos.unshift('⚡ QUEIMADURA ELÉTRICA DE ALTA VOLTAGEM: Risco de mioglobinúria maciça e rabdomiólise com necrose muscular profunda. Fator de 4 mL/kg/% SCQ com meta de diurese elevada (1,0 a 1,5 mL/kg/h = 75 a 100 mL/h) até clareamento urinário.');
      }

      var badge = isEletrica ? '⚡ ALTA VOLTAGEM (4 mL/kg/%)' : (isPediatrico ? '👶 PEDIÁTRICO (3 mL/kg/% + SG 5%)' : '🔥 ADULTO TÉRMICO (2 mL/kg/%)');

      return sucesso({
        id: ID,
        nome: NOME,
        estado: 'CALCULO',
        rotulo: 'PARKLAND / ABA 2024 · ' + badge,
        principal: fmt(volTotalAba, 0) + ' mL em 24h (' + diretriz + ')',
        textoFormatado: '🔥 <b>RESSUSCITAÇÃO VOLÊMICA NO QUEIMADO (CONSENSO ABA / ATLS / PARKLAND)</b>\n\n' +
          '• <b>Perfil:</b> ' + perfil + '\n' +
          '• <b>Peso:</b> ' + fmt(peso, 1) + ' kg | <b>SCQ (2º/3º grau):</b> ' + fmt(scq, 0) + '%\n' +
          '• <b>Diretriz Atual (ABA 2024 / ATLS 11ª Ed):</b> <code>' + fmt(volTotalAba, 0) + ' mL</code> de Ringer Lactato (' + fator + ' mL/kg/%)\n' +
          '• <b>Comparativo Histórico (Parkland 4 mL/kg):</b> <code>' + fmt(volTotalClassico, 0) + ' mL</code> em 24h\n\n' +
          '⏱️ <b>Esquema de Infusão (Ringer Lactato):</b>\n' +
          '1️⃣ <b>1ª Etapa (Primeiras 8h do trauma):</b> <code>' + fmt(vol8hBruto, 0) + ' mL</code> → <b>' + fmt(vazao8h, 0) + ' mL/h</b> na BIC' +
          (horas > 0 ? ' (ajustado para ' + fmt(horasRestantes1, 1) + 'h restantes)' : '') + '\n' +
          '2️⃣ <b>2ª Etapa (Próximas 16h):</b> <code>' + fmt(vol16h, 0) + ' mL</code> → <b>' + fmt(vazao16h, 0) + ' mL/h</b> na BIC\n\n' +
          (isPediatrico ? '👶 <b>Manutenção Glicídica Paralela (Holliday-Segar):</b>\n• SG 5% + NaCl 0,45%: <code>' + fmt(volManutencao, 0) + ' mL/24h</code> → <b>' + fmt(vazaoManutencao, 0) + ' mL/h</b> contínua\n\n' : '') +
          '🎯 <b>Meta de Débito Urinário (SVD horária):</b>\n' +
          '• Alvo: <b>' + fmt(debitoMin, 1) + ' a ' + fmt(debitoMax, 1) + ' mL/h</b> (' + (isEletrica ? '1,0–1,5' : (isPediatrico ? '1,0' : '0,5')) + ' mL/kg/h)\n\n' +
          '⚠️ <b>Regras de Segurança ABA 2024 / ATLS / SBQ:</b>\n' +
          '• Titular vazão de Ringer Lactato em ±20% a 30% a cada hora conforme diurese.\n' +
          '• Descontar volume já recebido no pré-hospitalar das primeiras 8 horas.\n' +
          '• Monitorizar rigorosamente para prevenir sobrecarga ("fluid creep") e síndrome compartimental abdominal.',
        secoes: [
          ['PARÂMETROS E DIRETRIZ', [
            'Perfil: ' + perfil,
            'Peso: ' + fmt(peso, 1) + ' kg | SCQ: ' + fmt(scq, 0) + '%',
            'Fórmula Atual (ABA/ATLS): ' + fator + ' mL × ' + fmt(peso, 1) + ' kg × ' + fmt(scq, 0) + '%',
            'Comparativo Parkland Clássico: 4 mL × ' + fmt(peso, 1) + ' kg × ' + fmt(scq, 0) + '% (' + fmt(volTotalClassico, 0) + ' mL)'
          ]],
          ['CRONOGRAMA DE EXPANSÃO (RINGER LACTATO)', [
            '1ª Etapa (8h a contar do trauma): ' + fmt(vol8hBruto, 0) + ' mL (' + fmt(vazao8h, 0) + ' mL/h na BIC)',
            '2ª Etapa (16h seguintes): ' + fmt(vol16h, 0) + ' mL (' + fmt(vazao16h, 0) + ' mL/h na BIC)'
          ]],
          (isPediatrico ? ['MANUTENÇÃO PEDIÁTRICA HOLLIDAY-SEGAR (SG 5%)', [
            'Solução: SG 5% em NaCl 0,45%',
            'Volume 24h: ' + fmt(volManutencao, 0) + ' mL/dia (' + fmt(vazaoManutencao, 0) + ' mL/h contínua)'
          ]] : null),
          ['CONDUTAS E MONITORIZAÇÃO', avisos]
        ].filter(Boolean),
        avisos: avisos,
        dados: {
          pesoKg: peso,
          scq: scq,
          fatorMlKgScq: fator,
          isPediatrico: isPediatrico,
          isEletrica: isEletrica,
          perfilClinico: perfil,
          diretrizReferencia: diretriz,
          volumeTotal24hMl: volTotalAba,
          volumePrimeiras8hMl: vol8hBruto,
          vazaoPrimeiras8hMlH: vazao8h,
          volumeSeguintes16hMl: vol16h,
          vazaoSeguintes16hMlH: vazao16h,
          volumeManutencaoPediatrica24hMl: volManutencao,
          vazaoManutencaoPediatricaMlH: vazaoManutencao,
          debitoUrinarioAlvoMlH: { min: debitoMin, max: debitoMax },
          parklandClassico: {
            volumeTotal24hMl: volTotalClassico,
            volumePrimeiras8hMl: vol8hClassico,
            vazaoPrimeiras8hMlH: Math.round(vol8hClassico / 8)
          }
        },
        legado: {
          volumeTotalMl: volTotalAba,
          volume8hMl: vol8hBruto,
          vazao8hMlH: vazao8h,
          volume16hMl: vol16h,
          vazao16hMlH: vazao16h,
          parklandClassicoTotalMl: volTotalClassico
        },
        botoes: botoesEmergencia(ID, [btn('🧮 Novo cálculo', ID, 'voltar')])
      });
    });
  }

  function calcularParklandPorTextoLivre(texto) {
    if (!texto || typeof texto !== 'string') return null;
    var t = texto.toLowerCase();
    if (!/(?:parkland|queimadur[as]?)\b/i.test(t)) return null;

    var m1 = texto.match(/(?:parkland|queimadur[as]?)\b.*?(?:(\d+(?:[.,]\d+)?)\s*kg).*?(\d+(?:[.,]\d+)?)\s*%/i) ||
             texto.match(/(?:parkland|queimadur[as]?)\b.*?(\d+(?:[.,]\d+)?)\s*%.*?(?:(\d+(?:[.,]\d+)?)\s*kg)/i);
    if (m1) {
      var p1 = parseFloat((m1[1] || m1[2]).replace(',', '.'));
      var s1 = parseFloat((m1[2] || m1[1]).replace(',', '.'));
      return parkland(p1, s1);
    }

    var mPeso = texto.match(/(?:peso\s*[:=]?\s*)?(\d+(?:[.,]\d+)?)\s*kg\b/i);
    var mScq = texto.match(/(?:scq|superficie|queimadura)\s*[:=]?\s*(\d+(?:[.,]\d+)?)\s*%?/i) || texto.match(/(\d+(?:[.,]\d+)?)\s*%/i);
    if (mPeso && mScq) {
      var p = parseFloat(mPeso[1].replace(',', '.'));
      var s = parseFloat(mScq[1].replace(',', '.'));
      return parkland(p, s);
    }
    return null;
  }

  /**
   * MELD (Model for End-Stage Liver Disease - UNOS / Kamath et al. 2007) e MELD-Na (OPTN 2016)
   */
  function meld(bilirrubina, creatinina, inr, sodio, dialiseRecente) {
    var ID = 'meld', NOME = 'MELD / MELD-Na';
    return seguro(ID, NOME, function () {
      var c = novoCtx();
      var b = num(c, bilirrubina, 'Bilirrubina total (mg/dL)', 0.1, 100);
      var cr = num(c, creatinina, 'Creatinina (mg/dL)', 0.1, 30);
      var i = num(c, inr, 'INR', 0.5, 20);
      var na = num(c, sodio, 'Sódio sérico (mEq/L)', 100, 180, { opcional: true });
      var dialise = bool(c, dialiseRecente, 'Diálise recente (≥ 2x na última semana)', { opcional: true }) || false;
      if (pendente(c)) return falhaCtx(ID, NOME, c);

      // Regras UNOS: Valores mínimos = 1.0; Cr máxima = 4.0
      var bVal = Math.max(1.0, b);
      var inrVal = Math.max(1.0, i);
      var crVal = dialise ? 4.0 : Math.min(4.0, Math.max(1.0, cr));

      // Fórmula UNOS MELD:
      // 9.57 * ln(Cr) + 3.78 * ln(Bilirrubina) + 11.2 * ln(INR) + 6.43
      var meldScore = 9.57 * Math.log(crVal) + 3.78 * Math.log(bVal) + 11.2 * Math.log(inrVal) + 6.43;
      var meldArred = Math.round(meldScore);
      meldArred = Math.max(6, Math.min(40, meldArred));

      var meldNaArred = meldArred;
      var temMeldNa = false;
      if (na !== null && meldArred > 11) {
        temMeldNa = true;
        var naVal = Math.max(125, Math.min(137, na));
        var meldNa = meldArred + 1.32 * (137 - naVal) - (0.033 * meldArred * (137 - naVal));
        meldNaArred = Math.round(meldNa);
        meldNaArred = Math.max(6, Math.min(40, meldNaArred));
      }

      var mortalidade3m = '';
      var estado = 'BAIXO';
      if (meldArred >= 40) { mortalidade3m = '≥ 71,3% de mortalidade em 3 meses'; estado = 'PRIORITARIO'; }
      else if (meldArred >= 30) { mortalidade3m = '52,6% de mortalidade em 3 meses'; estado = 'PRIORITARIO'; }
      else if (meldArred >= 20) { mortalidade3m = '19,6% de mortalidade em 3 meses'; estado = 'ATENCAO'; }
      else if (meldArred >= 10) { mortalidade3m = '6,0% de mortalidade em 3 meses'; estado = 'ATENCAO'; }
      else { mortalidade3m = '1,9% de mortalidade em 3 meses'; estado = 'BAIXO'; }

      var principal = 'MELD ' + meldArred + (temMeldNa ? (' · MELD-Na ' + meldNaArred) : '');
      return sucesso({
        id: ID, nome: NOME, estado: estado, rotulo: 'ESTIMATIVA DE MORTALIDADE HEPÁTICA (MELD)',
        principal: principal,
        secoes: [
          ['PARÂMETROS UTILIZADOS', [
            'Bilirrubina: ' + fmt(b, 1) + ' mg/dL' + (b < 1.0 ? ' (ajustada para 1,0 pelo UNOS)' : ''),
            'Creatinina: ' + fmt(cr, 2) + ' mg/dL' + (dialise ? ' (fixada em 4,0 por diálise)' : (cr < 1.0 ? ' (ajustada para 1,0)' : '')),
            'INR: ' + fmt(i, 2) + (i < 1.0 ? ' (ajustado para 1,0)' : ''),
            (na !== null ? ('Sódio sérico: ' + fmt(na, 0) + ' mEq/L') : 'Sódio: não informado (MELD-Na não calculado)')
          ]],
          ['PROGNÓSTICO ESTIMADO', [mortalidade3m, 'Critério regulador de fila de transplante hepático no Brasil e UNOS.']]
        ],
        avisos: ['MELD pontua entre 6 e 40. Diálise pelo menos 2x nos últimos 7 dias fixa Cr em 4,0 mg/dL.'],
        dados: { meld: meldArred, meldNa: temMeldNa ? meldNaArred : null, dialise: dialise },
        legado: { pontuacao: meldArred, meld: meldArred, meldNa: temMeldNa ? meldNaArred : null, mortalidade: mortalidade3m }
      });
    });
  }

  /**
   * Escore FIB-4 (Fibrosis-4 Index) para MASLD / MASH (AASLD / EASL 2024).
   * Fórmula: (Idade [anos] × AST [U/L]) / (Plaquetas [10⁹/L] × √ALT [U/L])
   */
  function fib4(arg1, arg2, arg3, arg4) {
    var ID = 'fib4', NOME = 'Escore FIB-4 (MASLD / MASH)';
    return seguro(ID, NOME, function () {
      var c = novoCtx();
      var pIdade, pAst, pAlt, pPlaq;

      if (arg1 && typeof arg1 === 'object' && !Array.isArray(arg1)) {
        pIdade = arg1.idade;
        pAst = arg1.ast !== undefined ? arg1.ast : arg1.tgo;
        pAlt = arg1.alt !== undefined ? arg1.alt : arg1.tgp;
        pPlaq = arg1.plaquetas !== undefined ? arg1.plaquetas : arg1.plaq;
      } else {
        pIdade = arg1;
        pAst = arg2;
        pAlt = arg3;
        pPlaq = arg4;
      }

      var vIdade = num(c, pIdade, 'Idade (anos)', 18, 120);
      var vAst = num(c, pAst, 'AST / TGO (U/L)', 1, 10000);
      var vAlt = num(c, pAlt, 'ALT / TGP (U/L)', 1, 10000);
      var vPlaq = num(c, pPlaq, 'Plaquetas', 1, 2000000);

      if (pendente(c)) return falhaCtx(ID, NOME, c);

      // Normalização determinística de unidade de plaquetas:
      // Se inserido em /mm³ (ex: 210000), ajusta para 10⁹/L (210)
      var plaquetasNormalizadas = vPlaq;
      var unidadeConvertida = false;
      if (vPlaq > 2000) {
        plaquetasNormalizadas = vPlaq / 1000;
        unidadeConvertida = true;
      }

      var denominador = plaquetasNormalizadas * Math.sqrt(vAlt);
      exigirFinito(denominador);
      if (denominador <= 0) return falhaCtx(ID, NOME, c);

      var escoreBruto = (vIdade * vAst) / denominador;
      exigirFinito(escoreBruto);
      var escoreFib4 = Math.round(escoreBruto * 100) / 100;

      // Estratificação AASLD / EASL 2024 para MASLD
      var idoso = vIdade >= 65;
      var corteInferior = idoso ? 2.00 : 1.30;
      var corteSuperior = 2.67;

      var risco = '';
      var categoria = '';
      var estadiamentoFIB4 = '';
      var condutaSugerida = '';
      var estado = 'BAIXO';

      if (escoreFib4 < corteInferior) {
        risco = 'Baixo';
        estado = 'BAIXO';
        categoria = 'Baixo risco de fibrose hepática avançada (F0-F2)';
        estadiamentoFIB4 = 'F0-F2 provável (VPN > 90%)';
        condutaSugerida = 'Manejo na atenção primária. Reavaliar FIB-4 a cada 1 a 2 anos conforme fatores de risco metabólicos.';
      } else if (escoreFib4 <= corteSuperior) {
        risco = 'Intermediário';
        estado = 'ATENCAO';
        categoria = 'Risco indeterminado para fibrose avançada (Zona Cinzenta)';
        estadiamentoFIB4 = 'Indeterminado';
        condutaSugerida = 'Solicitar teste de segunda linha: Elastografia Hepática Transitória (VCTE/FibroScan) ou escore ELF. Se VCTE >= 8 kPa, encaminhar à Hepatologia.';
      } else {
        risco = 'Alto';
        estado = 'PRIORITARIO';
        categoria = 'Alto risco de fibrose hepática avançada ou cirrose (F3-F4)';
        estadiamentoFIB4 = 'F3-F4 provável (VPP ~60-80%)';
        condutaSugerida = 'Encaminhar prioritariamente à Hepatologia/Gastroenterologia para estadiamento completo e rastreio de hipertensão portal/CHCC.';
      }

      var avisos = [];
      if (idoso) {
        avisos.push('Corte ajustado para idade >= 65 anos (< 2,00 para baixo risco), prevenindo falsos positivos devidos ao avanço etário (AASLD/EASL 2024).');
      }
      if (vIdade < 35) {
        avisos.push('Atenção: O FIB-4 possui menor sensibilidade em adultos jovens com menos de 35 anos.');
      }
      if (vAst > 250 || vAlt > 250) {
        avisos.push('Elevação aguda de transaminases (> 250 U/L) pode superestimar falsamente o FIB-4.');
      }
      if (unidadeConvertida) {
        avisos.push('Plaquetas informadas (' + vPlaq + ') foram convertidas automaticamente para ' + plaquetasNormalizadas + ' × 10⁹/L.');
      }

      var principal = 'FIB-4 ' + escoreFib4.toFixed(2) + ' · Risco ' + risco;

      var secoes = [
        ['ESTRATIFICAÇÃO MASLD (AASLD/EASL 2024)', [
          'Categoria: ' + categoria,
          'Estadiamento: ' + estadiamentoFIB4,
          'Limiares aplicados (' + (idoso ? '>= 65 anos' : '< 65 anos') + '): Baixo < ' + corteInferior.toFixed(2) + ' | Intermediário ' + corteInferior.toFixed(2) + '–' + corteSuperior.toFixed(2) + ' | Alto > ' + corteSuperior.toFixed(2)
        ]],
        ['CONDUTA RECOMENDADA', [condutaSugerida]],
        ['PARÂMETROS INFORMADOS', [
          'Idade: ' + fmt(vIdade, 0) + ' anos',
          'AST (TGO): ' + fmt(vAst, 0) + ' U/L',
          'ALT (TGP): ' + fmt(vAlt, 0) + ' U/L',
          'Plaquetas: ' + fmt(plaquetasNormalizadas, 0) + ' × 10⁹/L'
        ]]
      ];

      return sucesso({
        id: ID,
        nome: NOME,
        estado: estado,
        rotulo: 'FIB-4: ' + categoria.toUpperCase(),
        principal: principal,
        secoes: secoes,
        avisos: avisos,
        dados: {
          fib4: escoreFib4,
          risco: risco,
          categoria: categoria,
          estadiamentoFIB4: estadiamentoFIB4,
          corteInferior: corteInferior,
          corteSuperior: corteSuperior,
          faixaEtaria: idoso ? '>= 65 anos' : '< 65 anos',
          conduta: condutaSugerida,
          metadadosMASLD: {
            diretrizReferencia: 'AASLD / EASL-EASD-EASO 2024 (MASLD)',
            faixaEtariaAplicada: idoso ? '>= 65 anos' : '< 65 anos',
            corteBaixoRisco: corteInferior,
            corteAltoRisco: corteSuperior,
            condutaRecomendada: condutaSugerida
          }
        },
        legado: {
          fib4: escoreFib4,
          risco: risco,
          categoria: categoria
        },
        botoes: botoesPadrao(ID, [btn('🔬 Elastografia', ID, 'vcte'), btn('✏️ Revisar dados', ID, 'editar')])
      });
    });
  }

