// ARQUIVO FONTE: 02_emergencia_crise_hipertensiva.js
// ==============================================================================

/**
 * ==============================================================================
 * ULTRA ROTINA · MÓDULO DE CRISE HIPERTENSIVA (PSEUDOCRISE, URGÊNCIA & EMERGÊNCIA)
 * ==============================================================================
 * Referência: Diretrizes Brasileiras de Hipertensão Arterial (SBC 2020 / 2024),
 * AHA/ACC 2023. Abordagem beira-leito com metas pressóricas e segurança farmacológica.
 * ==============================================================================
 */

var EmergenciaCriseHipertensivaService = (function () {
  'use strict';

  function classificarCrise(dados) {
    dados = dados || {};
    var pas = Number(dados.pas || dados.pressaoSistolica) || 180;
    var pad = Number(dados.pad || dados.pressaoDiastolica) || 110;
    var loa = dados.lesaoOrgaoAlvo || {};

    var temEap = Boolean(loa.eap || dados.eap || dados.edemaPulmao || dados.dispneiaGrave);
    var temEncefalopatia = Boolean(loa.encefalopatia || dados.encefalopatia || dados.confusao || dados.papiledema);
    var temDisseccao = Boolean(loa.disseccao || dados.disseccao || dados.dorRasgando);
    var temIam = Boolean(loa.iam || dados.iam || dados.dorPrecordial || dados.sca);
    var temAvc = Boolean(loa.avc || dados.avc || dados.deficitFocal);
    var temPreEclampsia = Boolean(loa.preeclampsia || dados.preeclampsia || dados.gestante);

    var temLoaAguda = temEap || temEncefalopatia || temDisseccao || temIam || temAvc || temPreEclampsia;

    var tipo = 'URGENCIA_HIPERTENSIVA';
    var titulo = 'Urgência Hipertensiva (PA Elevada sem Lesão de Órgão-Alvo)';
    var local = 'Sala de Observação / UPA';
    var metaPressorica = 'Redução gradual em 24 a 48 horas (meta de PAS 140-160 mmHg e PAD 90-100 mmHg). Queda inicial não deve ultrapassar 20-25% da PAM.';
    var medicacoes = [];
    var condutas = [];
    var alertas = [];

    // Checagem de Pseudocrise
    var dorAnsiedade = Boolean(dados.dor || dados.ansiedade || dados.estresse || dados.cefaleiaTensional);
    if (!temLoaAguda && (dorAnsiedade || (pas < 180 && pad < 120))) {
      tipo = 'PSEUDOCRISE_HIPERTENSIVA';
      titulo = 'Pseudocrise Hipertensiva (Elevação Reativa da PA)';
      local = 'Acolhimento / Sala de Medicação / UBS';
      metaPressorica = 'Não há indicação de redução agressiva imediata da PA. O foco é tratar o gatilho desencadeante.';
      
      condutas.push('• Repouso em ambiente calmo e silencioso por 30 a 60 minutos.');
      condutas.push('• Analgesia simples para dor (Dipirona 1g VO/IV) ou suporte para ansiedade/pânico.');
      condutas.push('• Reavaliar a pressão arterial após o repouso e analgesia.');
      condutas.push('• Se PA persistir muito elevada após repouso: administrar Captopril 25mg VO.');
      condutas.push('• Encaminhar para acompanhamento ambulatorial na UBS para ajuste da medicação de uso crônico.');
      
      alertas.push('⛔ NUNCA prescrever Nifedipino de ação rápida / sublingual: causa hipotensão súbita, taquicardia reflexa e risco de isquemia coronariana e cerebral.');
    } else if (temLoaAguda) {
      tipo = 'EMERGENCIA_HIPERTENSIVA';
      titulo = 'EMERGÊNCIA HIPERTENSIVA (Risco Iminente de Morte / Lesão de Órgão-Alvo)';
      local = '🚨 SALA VERMELHA / MONITORIZAÇÃO CONTÍNUA / UTI';

      if (temDisseccao) {
        metaPressorica = 'META AGUDA DISSECÇÃO DE AORTA: PAS < 120 mmHg e FC < 60 bpm em 20 minutos!';
        medicacoes.push('💉 1º PASSO: Betabloqueador IV (Esmolol em BIC ou Metoprolol 5mg IV a cada 5 min até FC < 60 bpm). NUNCA usar vasodilatador puro antes do betabloqueador (risco de cisalhamento aórtico).');
        medicacoes.push('💉 2º PASSO: Nitroprussiato de Sódio IV em BIC titulado (iniciar a 0.3 a 0.5 mcg/kg/min) até PAS < 120 mmHg.');
        condutas.push('• Acionar Cirurgia Cardíaca/Vascular imediatamente e solicitar Angio-TC de Aorta urgente.');
      } else if (temEap) {
        metaPressorica = 'META EAP HIPERTENSIVO: Redução de 20 a 30% da PAM em 30-60 min com melhora do desconforto respiratório.';
        medicacoes.push('💉 Nitroglicerina IV em BIC (5 mcg/min, titulando a cada 5 min) OU Nitroprussiato de Sódio IV se PAS muito elevada.');
        medicacoes.push('💉 Furosemida 40 a 80 mg IV em bolus.');
        condutas.push('• Oxigenioterapia com VNI (CPAP 8 a 10 cmH2O) — reduz pré-carga e necessidade de intubação.');
      } else if (temIam) {
        metaPressorica = 'META SCA/IAM: Controle da dor e redução gradual da PA com Nitroglicerina IV.';
        medicacoes.push('💉 Nitroglicerina IV contínua (alivia isquemia e pré-carga) + Betabloqueador oral precoce.');
        condutas.push('• Protocolo de SCA: AAS 300mg mastigado, Ticagrelor/Clopidogrel, anticoagulação e CAT de urgência.');
      } else if (temAvc) {
        metaPressorica = 'META AVC ISQUÊMICO: NÃO reduzir PA se PAS < 220 ou PAD < 120, EXCETO se candidato a trombólise (onde meta é PA < 185/110 mmHg).';
        medicacoes.push('💉 Se elegível para trombólise e PA > 185/110: Nitroprussiato de Sódio IV ou Labetalol IV.');
        condutas.push('• Tomografia de crânio sem contraste imediata e acionamento da equipe de AVC.');
      } else if (temPreEclampsia) {
        metaPressorica = 'META GESTANTE: PAS 140-150 mmHg e PAD 90-100 mmHg (evitar hipotensão para manter perfusão placentária).';
        medicacoes.push('💉 Hidralazina 5mg IV lento a cada 20 min (máx 20mg) OU Nifedipino Retard 20mg VO.');
        medicacoes.push('💉 Sulfato de Magnésio 50% (Esquema de Zuspan: 4g IV ataque + 1-2g/h manutenção) para profilaxia de convulsão.');
        condutas.push('• ⛔ Contraindicação Absoluta: IECAs, BRAs e Nitroprussiato (teratogênicos / toxicidade fetal).');
      } else {
        // Encefalopatia hipertensiva padrão
        metaPressorica = 'META GERAL: Reduzir PAM em 20 a 25% na primeira hora; depois atingir 160/100 mmHg em 2 a 6 horas.';
        medicacoes.push('💉 Nitroprussiato de Sódio IV em BIC contínua: 0.25 a 0.5 mcg/kg/min (proteger frasco da luz).');
      }

      alertas.push('🚨 Linha arterial (PA invasiva) recomendada se infusão prolongada de Nitroprussiato > 24-48h (risco de intoxicação por tiocianato/cianeto em insuficiência renal).');
    } else {
      // Urgência Hipertensiva
      condutas.push('• Permanência em leito de observação por 2 a 4 horas.');
      condutas.push('• Redução gradual da PA com anti-hipertensivo oral.');
      condutas.push('• Avaliação de fundo de olho e rastreio sumário (Eletrocardiograma, Creatinina, Urina 1).');
      condutas.push('• Orientar reavaliação ambulatorial em 48 a 72 horas para ajuste de drogas de ação prolongada.');

      medicacoes.push('💊 1ª Opção: Captopril 25mg a 50mg VO (início de ação em 15-30 min). Pode repetir 25mg após 1 hora se necessário.');
      medicacoes.push('💊 2ª Opção: Clonidina 0.100mg a 0.200mg VO (início de ação em 30-60 min).');
      medicacoes.push('💊 3ª Opção: Anlodipino 5mg a 10mg VO (se histórico prévio de bloqueador de canal de cálcio).');

      alertas.push('⚠️ Evitar normalizar a PA na urgência: reduções drásticas reduzem fluxo cerebral e renal em hipertensos crônicos.');
    }

    return {
      tipo: tipo,
      titulo: titulo,
      pas: pas,
      pad: pad,
      localRecomendado: local,
      metaPressorica: metaPressorica,
      condutas: condutas,
      medicacoes: medicacoes,
      alertas: alertas
    };
  }

  function formatarTextoTelegram(res) {
    var linhas = [];
    linhas.push('❤️ *MANEJO DE CRISE HIPERTENSIVA & PSEUDOCRISE*');
    linhas.push('📅 *Diretrizes SBC / AHA / ACC*');
    linhas.push('');
    linhas.push('*Classificação:* ' + res.titulo);
    linhas.push('*Pressão Aferida:* ' + res.pas + ' × ' + res.pad + ' mmHg');
    linhas.push('*Local Recomendado:* ' + res.localRecomendado);
    linhas.push('');
    linhas.push('🎯 *Meta Pressórica:*');
    linhas.push(res.metaPressorica);
    linhas.push('');
    if (res.medicacoes.length > 0) {
      linhas.push('💊 *Conduta Farmacológica:*');
      for (var i = 0; i < res.medicacoes.length; i++) {
        linhas.push(res.medicacoes[i]);
      }
      linhas.push('');
    }
    if (res.condutas.length > 0) {
      linhas.push('*Condutas Gerais:*');
      for (var j = 0; j < res.condutas.length; j++) {
        linhas.push(res.condutas[j]);
      }
      linhas.push('');
    }
    for (var k = 0; k < res.alertas.length; k++) {
      linhas.push(res.alertas[k]);
    }

    return linhas.join('\n');
  }

  function extrairParametrosTexto(texto) {
    texto = String(texto || '').toLowerCase();
    var pas = 180, pad = 110;
    var mPas = texto.match(/pas\s*[:=]?\s*(\d{2,3})/);
    var mPad = texto.match(/pad\s*[:=]?\s*(\d{2,3})/);
    if (mPas && mPad) {
      pas = parseInt(mPas[1], 10);
      pad = parseInt(mPad[1], 10);
    } else {
      var mPa = texto.match(/(\d{2,3})\s*[xX/]\s*(\d{2,3})/);
      if (mPa) {
        pas = parseInt(mPa[1], 10);
        pad = parseInt(mPa[2], 10);
      } else {
        var mPaEspaco = texto.match(/\b(1\d\d|2\d\d)\s+(\d{2,3})\b/);
        if (mPaEspaco) {
          pas = parseInt(mPaEspaco[1], 10);
          pad = parseInt(mPaEspaco[2], 10);
        }
      }
    }

    var loa = {
      eap: /(eap|edema agudo|congestao pulmonar|crepit)/i.test(texto),
      encefalopatia: /(encefalopatia|confus|papiledema|turvacao|coma)/i.test(texto),
      disseccao: /(dissecc|dor rasgando|dor transfix|assimetria de pulso)/i.test(texto),
      iam: /(iam|dor precordial|infarto|sca|supra)/i.test(texto),
      avc: /(avc|deficit|hemiplegia|afasia)/i.test(texto),
      preeclampsia: /(gestant|gravid|preeclamp|eclamp)/i.test(texto)
    };

    var dorAnsiedade = /(dor|ansiedad|panico|estresse|nervos|tensional)/i.test(texto);

    return {
      pas: pas,
      pad: pad,
      lesaoOrgaoAlvo: loa,
      dor: dorAnsiedade
    };
  }

  return {
    classificarCrise: classificarCrise,
    formatarTextoTelegram: formatarTextoTelegram,
    extrairParametrosTexto: extrairParametrosTexto
  };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = EmergenciaCriseHipertensivaService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_endocrinologia_diabetes.js
// ==============================================================================

/**
 * ==============================================================================
 * MÓDULO 02: ENDOCRINOLOGIA E DIABETES MELLITUS AVANÇADO (SBD / ADA)
 * ==============================================================================
 * Diretrizes Clínicas Oficiais:
 *  - Sociedade Brasileira de Diabetes (Diretrizes SBD 2024-2026)
 *  - American Diabetes Association (ADA Standards of Care in Diabetes 2024-2026)
 *  - Consenso Brasileiro de Emergências Hiperglicêmicas (CAD e EHH)
 *
 * PILARES CLÍNICOS DETERMINÍSTICOS:
 *  1. Calculadora Ambulatorial Basal-Bolus (DM1 e DM2):
 *     - DM1: 0.4 a 1.0 U/kg/dia com partição 50% Basal / 50% Prandial.
 *     - Fator de Sensibilidade à Insulina (FSI - Regra 1800 para análogos e 1500 para regular).
 *     - Relação Insulina:Carboidrato (ICR - Regra 500 para análogos).
 *     - DM2: Basalização inicial (10 UI ou 0.1 a 0.2 U/kg) e algoritmo de titulação 2-2-2.
 *     - Alertas de segurança farmacológica (suspensão de iSGLT2 perioperatório/grave contra CAD euglicêmica;
 *       ajuste de Metformina por TFG; bloqueio de sulfonilureias em idosos/renais).
 *  2. Protocolo de Hiperglicemia Hospitalar (Enfermaria e UTI):
 *     - Alvo hospitalar estruturado: 140 a 180 mg/dL (evitando < 110 mg/dL via ensaio NICE-SUGAR).
 *     - Condenação formal da "Sliding Scale" isolada sem basal.
 *     - Escala de correção rápida estratificada por sensibilidade (Sensível, Padrão, Resistente).
 *  3. Emergências Hiperglicêmicas: Cetoacidose Diabética (CAD) e Estado Hiperosmolar (EHH):
 *     - Estratificação diagnóstica e gravidade (CAD Leve, Moderada, Grave e EHH com Osmolaridade Efetiva).
 *     - Expansão volêmica inicial (15-20 mL/kg/h) e cálculo do Sódio Corrigido (Katz).
 *     - REGRA DE OURO DO POTÁSSIO: Bloqueio absoluto de Insulina IV se K < 3.3 mEq/L contra PCR por arritmia.
 *     - Titulação de Insulina Regular IV contínua (0.1 U/kg/h) com alvo de queda de 50-75 mg/dL/h.
 *     - Transição hídrica com SG 5% + SF 0.45% quando glicemia < 200 (CAD) ou < 250 (EHH).
 *     - Critérios restritivos de Bicarbonato de Sódio (apenas se pH < 6.90).
 *     - Critérios formais de resolução e Regra de Transição para SC (basal SC 1-2h antes de desligar a bomba).
 * ==============================================================================
 */

var EndocrinologiaDiabetesService = (function() {
  'use strict';

  // ───────────────────────────────────────────────────────────────────────────
  // 1. CALCULADORA BASAL-BOLUS AMBULATORIAL (DM1 & DM2)
  // ───────────────────────────────────────────────────────────────────────────

  function calcularInsulinaAmbulatorial(dados) {
    dados = dados || {};
    var peso = Number(dados.peso || 70);
    var tipoDm = Number(dados.tipoDm || 2);
    var descompensado = !!dados.descompensado;
    var tfg = dados.tfg !== undefined ? Number(dados.tfg) : 90;
    var ehIdoso = !!(dados.ehIdoso || (dados.idade && dados.idade >= 65));
    var emUsoIsglt2 = !!dados.emUsoIsglt2;

    if (peso <= 0) throw new Error('Peso inválido para cálculo de insulinoterapia.');

    var alertasFarmacologicos = [];

    // Alertas de Antidiabéticos Orais e Segurança
    if (emUsoIsglt2) {
      alertasFarmacologicos.push('⚠️ ALERTA iSGLT2: Suspender Dapagliflozina/Empagliflozina 3 a 4 dias antes de cirurgias eletivas ou imediatamente em casos de infecção/doença aguda (risco de Cetoacidose Diabética Euglicêmica com glicemia normal/pouco elevada).');
    }
    if (tfg < 30) {
      alertasFarmacologicos.push('⛔ CONTRAINDICAÇÃO METFORMINA: TFG < 30 mL/min contraindica formalmente a metformina devido ao risco de acidose lática grave. Suspender e ajustar para insulinoterapia.');
    } else if (tfg < 45) {
      alertasFarmacologicos.push('⚠️ AJUSTE METFORMINA: TFG entre 30 e 44 mL/min exige redução da dose máxima de metformina para 1.000 mg/dia com monitoramento renal semestral.');
    }
    if (ehIdoso) {
      alertasFarmacologicos.push('⚠️ CRITÉRIOS DE BEERS: Evitar sulfonilureias de longa ação (Glibenclamida) em idosos pelo risco severo de hipoglicemia prolongada e quedas. Preferir Gliclazida MR ou Insulina em esquema simplificado.');
    }

    if (tipoDm === 1) {
      // DM1: 0.5 U/kg/dia padrão (0.4 a 0.6 em fase inicial; até 0.8-1.0 em estresse/puberdade)
      var fatorDose = descompensado ? 0.6 : 0.5;
      var doseTotalDia = Math.max(1, Math.round(peso * fatorDose));
      var basal = Math.round(doseTotalDia * 0.5);
      var bolusTotal = doseTotalDia - basal;
      var bolusPorRefeicao = Math.round(bolusTotal / 3);

      // Regra 1800 para Fator de Sensibilidade (análogos rápidos)
      var fsi = Math.round(1800 / doseTotalDia);
      // Regra 500 para Relação Insulina:Carboidrato (ICR)
      var icr = Math.round(500 / doseTotalDia);

      return {
        sucesso: true,
        tipoDm: 'DM1',
        peso: peso,
        doseTotalDia: doseTotalDia,
        esquemaRecomendado: 'Basal-Bolus Intensivo (Múltiplas Doses Diárias)',
        basal: {
          dose: basal,
          tipo: 'Insulina Basal (Glargina U100/U300, Degludeca ou Detemir; ou NPH 2x/dia)',
          posologia: 'Administrar ' + basal + ' UI SC 1x ao dia (mesmo horário) ou NPH 2/3 pela manhã e 1/3 ao deitar.'
        },
        bolusPrandial: {
          doseTotalBolus: bolusTotal,
          dosePorRefeicaoFixa: bolusPorRefeicao,
          posologiaFixa: 'Administrar ' + bolusPorRefeicao + ' UI SC antes do café, almoço e jantar (análogo ultrarrápido 0-15 min antes da refeição).',
          contagemCarboidratos: {
            icr: icr,
            regraIcr: '1 UI de insulina para cada ' + icr + ' gramas de carboidrato consumidos.',
            fsi: fsi,
            regraFsi: 'Fator de Sensibilidade: 1 UI reduz aproximadamente ' + fsi + ' mg/dL de glicose.',
            metaGlicemicaPrandial: 'Alvo pré-prandial: 80 a 130 mg/dL; pós-prandial < 180 mg/dL.'
          }
        },
        alertasSeguranca: alertasFarmacologicos,
        orientacoes: 'Prescrever glicagão nasal ou injetável de resgate para hipoglicemia severa. Educação em contagem de carboidratos e automonitoramento capilar/sensor contínuo.'
      };
    } else if (tipoDm === 2) {
      // DM2: Início com Basalização oportuna (10 UI ou 0.1 a 0.2 U/kg)
      var doseBasalInicial = descompensado ? Math.max(10, Math.round(peso * 0.2)) : Math.max(10, Math.round(peso * 0.1));

      return {
        sucesso: true,
        tipoDm: 'DM2',
        peso: peso,
        esquemaRecomendado: 'Basalização Inicial (Insulina Noturna ou Matinal)',
        basal: {
          doseInicial: doseBasalInicial,
          tipo: 'Insulina Basal (Glargina, Degludeca ou NPH ao deitar)',
          posologia: 'Iniciar ' + doseBasalInicial + ' UI SC 1x ao dia (à noite ao deitar se NPH, ou horário fixo se análogo longo).'
        },
        algoritmoTitulacao: {
          regra: 'Titulação 2-2-2 / Treat-to-Target (SBD/ADA)',
          instrucao: 'Verificar glicemia de jejum por 3 dias consecutivos. Se média de jejum > 130 mg/dL, aumentar 2 UI da basal a cada 3 dias. Se média entre 80-130 mg/dL, manter dose. Se glicemia < 70 mg/dL, reduzir dose em 10-20% imediatamente.',
          adicaoBolusPrandial: 'Se basal titulada com jejum no alvo, mas HbA1c persistir elevada por glicemia pós-prandial > 180 mg/dL: progredir para esquema Basal-Plus adicionando 4 UI de insulina rápida antes da maior refeição do dia.'
        },
        alertasSeguranca: alertasFarmacologicos,
        orientacoes: 'Manter Metformina associada se tolerada e TFG >= 30 mL/min para reduzir demanda de insulina e ganho ponderal.'
      };
    }

    throw new Error('Tipo de DM inválido. Utilize 1 ou 2.');
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 2. PROTOCOLO HOSPITALAR DE CORREÇÃO E ALVO GLICÊMICO (ENFERMARIA & UTI)
  // ───────────────────────────────────────────────────────────────────────────

  function protocoloCorrecaoHospitalar(dados) {
    dados = dados || {};
    var glicemia = Number(dados.glicemia || 0);
    var perfil = String(dados.perfil || 'padrao').toLowerCase(); // 'sensivel', 'padrao', 'resistente'

    if (glicemia <= 0) throw new Error('Glicemia capilar inválida.');

    // Alvo Hospitalar Recomendado pela ADA/SBD: 140 a 180 mg/dL
    var doseCorrecao = 0;
    var conduta = '';
    var alertaCritico = '';

    if (glicemia < 70) {
      doseCorrecao = 0;
      conduta = 'HIPOGLICEMIA (Glicemia < 70 mg/dL): NÃO aplicar insulina. Administrar 15g de carboidrato rápido VO (150 mL de suco ou água com 1 colher de sopa de açúcar) se consciente; se inconsciente/NPO, infundir 40 a 50 mL de Glicose 50% EV em bolus. Reavaliar glicemia em 15 minutos (Regra dos 15).';
      alertaCritico = '🚨 HIPOGLICEMIA HOSPITALAR DETECTADA. Notificar enfermagem e equipe médica imediatamente.';
    } else if (glicemia < 140) {
      doseCorrecao = 0;
      conduta = 'Glicemia dentro da faixa segura / sem necessidade de correção imediata. Alvo hospitalar padrão: 140 a 180 mg/dL.';
    } else if (glicemia <= 180) {
      // Faixa Alvo da ADA/SBD (140-180 mg/dL): nenhuma insulina de correção em enfermaria
      doseCorrecao = perfil === 'resistente' ? 2 : 0;
      conduta = doseCorrecao > 0
        ? 'Glicemia no limite superior do alvo (' + glicemia + ' mg/dL). Aplicar ' + doseCorrecao + ' UI SC de Insulina Rápida apenas por perfil resistente.'
        : 'Glicemia no alvo terapêutico hospitalar (140 a 180 mg/dL). Nenhuma correção suplementar necessária.';
    } else if (glicemia <= 220) {
      if (perfil === 'sensivel') doseCorrecao = 2;
      else if (perfil === 'resistente') doseCorrecao = 6;
      else doseCorrecao = 4;
      conduta = 'Aplicar ' + doseCorrecao + ' UI de Insulina Rápida/Ultrarrápida SC.';
    } else if (glicemia <= 260) {
      if (perfil === 'sensivel') doseCorrecao = 4;
      else if (perfil === 'resistente') doseCorrecao = 8;
      else doseCorrecao = 6;
      conduta = 'Aplicar ' + doseCorrecao + ' UI de Insulina Rápida/Ultrarrápida SC.';
    } else if (glicemia <= 300) {
      if (perfil === 'sensivel') doseCorrecao = 6;
      else if (perfil === 'resistente') doseCorrecao = 10;
      else doseCorrecao = 8;
      conduta = 'Aplicar ' + doseCorrecao + ' UI de Insulina Rápida/Ultrarrápida SC.';
    } else {
      // Glicemia > 300 mg/dL
      if (perfil === 'sensivel') doseCorrecao = 8;
      else if (perfil === 'resistente') doseCorrecao = 14;
      else doseCorrecao = 10;
      conduta = 'Aplicar ' + doseCorrecao + ' UI de Insulina Rápida/Ultrarrápida SC.';
      alertaCritico = '⚠️ HIPERGLICEMIA GRAVE (> 300 mg/dL): Avaliar hidratação, cetonemia/cetonúria, gasometria e excluir emergência hiperglicêmica (CAD / EHH).';
    }

    return {
      sucesso: true,
      glicemiaMedida: glicemia,
      perfilSensibilidade: perfil,
      doseCorrecaoSc: doseCorrecao,
      alvoRecomendadoAdaSbd: '140 a 180 mg/dL (NICE-SUGAR trial)',
      condutaPrescricao: conduta,
      alertaCritico: alertaCritico,
      advertenciaSlidingScale: 'IMPORTANTE: A diretriz SBD/ADA condena o uso isolado de escala móvel ("Sliding Scale pura") sem insulina basal. Pacientes internados devem receber esquema Basal-Bolus planejado com esta escala servindo apenas como resgate complementar.'
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 3. MANEJO DE CRISES HIPERGLICÊMICAS: CAD E EHH (SBD / ADA)
  // ───────────────────────────────────────────────────────────────────────────

  function manejoCriseHiperglicemica(dados) {
    dados = dados || {};
    var peso = Number(dados.peso || 70);
    var tipoCrise = String(dados.tipo || 'CAD').toUpperCase(); // 'CAD' ou 'EHH'
    var glicemia = Number(dados.glicemia || 350);
    var potassio = Number(dados.potassio !== undefined ? dados.potassio : 4.2);
    var sodioMedido = Number(dados.sodio || 135);
    var phArterial = dados.ph !== undefined ? Number(dados.ph) : 7.15;
    var bicarbonato = dados.bicarbonato !== undefined ? Number(dados.bicarbonato) : 12;
    var cloreto = Number(dados.cloreto || 100);

    if (peso <= 0) throw new Error('Peso inválido para protocolo de cetoacidose/estado hiperosmolar.');

    // Cálculo do Sódio Corrigido (Fórmula de Katz / Hillier)
    // Na Corrigido = Na_medido + 0.016 * (Glicose - 100)
    var deltaGlicose = Math.max(0, glicemia - 100);
    var fatorCorrecaoNa = glicemia > 400 ? 0.020 : 0.016;
    var sodioCorrigido = Math.round((sodioMedido + (fatorCorrecaoNa * deltaGlicose)) * 10) / 10;

    // Cálculo do Anion Gap: Na - (Cl + HCO3)
    var anionGap = Math.round(sodioMedido - (cloreto + bicarbonato));

    // Cálculo da Osmolaridade Plasmática Efetiva: 2*Na + Glicose/18
    var osmolaridadeEfetiva = Math.round((2 * sodioMedido) + (glicemia / 18));

    // Estratificação de Gravidade da CAD
    var gravidadeCad = 'N/A';
    if (tipoCrise === 'CAD') {
      if (phArterial < 7.00 || bicarbonato < 10) gravidadeCad = 'GRAVE (UTI Obrigatória, gasometria seriada)';
      else if (phArterial <= 7.24 || bicarbonato < 15) gravidadeCad = 'MODERADA (Semi-intensiva ou UTI)';
      else gravidadeCad = 'LEVE';
    }

    var condutaPotassio = '';
    var condutaInsulina = '';
    var bloqueioInsulinaAtivo = false;
    var condutaHidratacao = '';
    var condutaBicarbonato = '';
    var alertasSentinela = [];

    // ─────────────────────────────────────────────────────────────────────────
    // REGRA DE OURO 1: POTÁSSIO & LIBERAÇÃO DA INSULINA
    // ─────────────────────────────────────────────────────────────────────────
    if (potassio > 8.0) {
      alertasSentinela.push('🚨 HIPERCALEMIA EXTREMA (K+ > 8.0 mEq/L: ' + potassio + ' mEq/L): Risco iminente de assistolia/FV e PCR. Proibida reposição de potássio. Administrar Gluconato de Cálcio 10% 20 mL IV imediatamente se qualquer alteração no ECG e acionar nefrologia para Hemodiálise de Urgência.');
      condutaPotassio = 'K+ > 8.0 mEq/L (' + potassio + ' mEq/L): Risco crítico de PCR. NÃO repor potássio. Gluconato de Cálcio 10% IV imediato para estabilização de membrana miocárdica. Checar ECG seriado e acionar suporte dialítico.';
      var vazaoInsExtrema = Math.min(15, Math.round(peso * 0.1 * 10) / 10);
      condutaInsulina = 'Iniciar Insulina Regular IV contínua: ' + vazaoInsExtrema + ' UI/h (0.1 UI/kg/h) em BIC para auxiliar no shift intracelular de K+. Monitorar K+ sérico a cada 1 a 2 horas.';
    } else if (potassio < 3.3) {
      bloqueioInsulinaAtivo = true;
      alertasSentinela.push('🚨 BLOQUEIO FATAL DE INSULINA: K+ < 3.3 mEq/L (' + potassio + ' mEq/L). Iniciar insulina com hipocalemia causa influxo celular agudo maciço de potássio, levando a arritmias ventriculares malignas e PCR súbita.');
      condutaPotassio = 'K+ < 3.3 mEq/L: PARAR/NÃO INICIAR insulina. Repor 20 a 40 mEq/h de KCl IV diluído em infusão contínua com monitorização cardíaca contínua até K+ atingir >= 3.3 mEq/L.';
      condutaInsulina = '⛔ INSULINOTERAPIA BLOQUEADA. Aguardar reposição vigorosa de potássio e documentação de K+ >= 3.3 mEq/L antes de iniciar qualquer dose de insulina.';
    } else if (potassio <= 5.2) {
      condutaPotassio = 'K+ entre 3.3 e 5.2 mEq/L (' + potassio + ' mEq/L): Adicionar 20 a 30 mEq de KCl em cada litro de fluido de manutenção para manter K+ entre 4.0 e 5.0 mEq/L durante toda a insulinoterapia.';
      var doseBolusOpcional = Math.min(15, Math.round(peso * 0.1 * 10) / 10);
      var vazaoBombaInsulina = Math.min(15, Math.round(peso * 0.1 * 10) / 10);
      condutaInsulina = 'Iniciar Insulina Regular IV contínua: ' + vazaoBombaInsulina + ' UI/h (0.1 UI/kg/h) em bomba de infusão (opcional bolus inicial de ' + doseBolusOpcional + ' UI EV). Alvo de redução: 50 a 75 mg/dL por hora.';
    } else {
      // K > 5.2 mEq/L
      condutaPotassio = 'K+ > 5.2 mEq/L (' + potassio + ' mEq/L): NÃO repor potássio neste momento. Checar eletrólitos a cada 2 horas (o potássio cairá rapidamente com a infusão de insulina e hidratação). Iniciar reposição assim que K < 5.3.';
      var vazaoInsKAlto = Math.min(15, Math.round(peso * 0.1 * 10) / 10);
      condutaInsulina = 'Iniciar Insulina Regular IV contínua: ' + vazaoInsKAlto + ' UI/h (0.1 UI/kg/h). Monitorar K+ sérico a cada 2 horas.';
    }

    // ─────────────────────────────────────────────────────────────────────────
    // REGRA DE OURO 2: EXPANSÃO VOLÊMICA E TRANSIÇÃO COM GLICOSE
    // ─────────────────────────────────────────────────────────────────────────
    var volPrimeiraHoraMin = Math.round(peso * 15);
    var volPrimeiraHoraMax = Math.round(peso * 20);

    if (peso > 150) {
      volPrimeiraHoraMin = Math.min(volPrimeiraHoraMin, 2000);
      volPrimeiraHoraMax = Math.min(volPrimeiraHoraMax, 2000);
      alertasSentinela.push('⚠️ OBESIDADE SEVERA (> 150 kg: ' + peso + ' kg): Volume de expansão da 1ª hora limitado ao teto seguro de 2.000 mL (2 L) para prevenir sobrecarga hídrica e edema pulmonar agudo. Dose inicial de insulina com teto de 15 UI/h.');
    }

    var fluidoManutencao = sodioCorrigido >= 135
      ? 'NaCl 0.45% a 250-500 mL/h (devido ao Sódio Corrigido normal/alto: ' + sodioCorrigido + ' mEq/L).'
      : 'SF 0.9% a 250-500 mL/h (devido ao Sódio Corrigido baixo: ' + sodioCorrigido + ' mEq/L).';

    var gatilhoGlicose = tipoCrise === 'CAD' ? 200 : 250;
    condutaHidratacao = '1. Primeira Hora: Infundir SF 0.9% 15 a 20 mL/kg/h (' + volPrimeiraHoraMin + ' a ' + volPrimeiraHoraMax + ' mL na 1ª hora).\n' +
      '2. Horas Subsequentes: Infundir ' + fluidoManutencao + '\n' +
      '3. Ponto de Corte de Salvaguarda: Assim que glicemia atingir < ' + gatilhoGlicose + ' mg/dL, associar Soro Glicosado a 5% com NaCl 0.45% (SG 5% + SF 0.45%) a 150-250 mL/h para manter glicemia entre ' + (tipoCrise === 'CAD' ? '150-200' : '200-300') + ' mg/dL enquanto a insulina IV continua até resolução completa da acidose e do Anion Gap.';

    // ─────────────────────────────────────────────────────────────────────────
    // REGRA DE OURO 3: BICARBONATO DE SÓDIO (CRITÉRIOS ESTREITOS)
    // ─────────────────────────────────────────────────────────────────────────
    if (tipoCrise === 'CAD') {
      if (phArterial < 6.80) {
        alertasSentinela.push('🚨 ACIDEMIA EXTREMA (pH < 6.80: ' + phArterial + '): Disfunção miocárdica crítica e vasoplegia refratária com risco iminente de PCR. Bicarbonato de sódio IV mandatório para elevar o pH acima de 7.00.');
        condutaBicarbonato = 'pH < 6.80 (' + phArterial + '): Acidemia extrema com risco iminente de PCR. Indicação emergencial mandatória de Bicarbonato de Sódio. Administrar 100 mmol de Bicarbonato de Sódio 8.4% diluídos em 400 mL de água destilada com 20 mEq de KCl em infusão lenta de 2 horas. Repetir gasometria de controle ao término.';
      } else if (phArterial < 6.90) {
        condutaBicarbonato = 'pH < 6.90 (' + phArterial + '): Indicação formal de Bicarbonato de Sódio. Administrar 100 mmol de Bicarbonato de Sódio 8.4% diluídos em 400 mL de água destilada com 20 mEq de KCl em infusão lenta de 2 horas. Repetir dosagem gasométrica após o término.';
      } else {
        condutaBicarbonato = 'pH >= 6.90 (' + phArterial + '): Bicarbonato de Sódio é FORMALMENTE CONTRAINDICADO. Consensos ADA/SBD demonstram aumento do risco de hipocalemia severa, edema cerebral e acidose paradoxal intracelular do SNC.';
      }
    } else {
      condutaBicarbonato = 'EHH: Bicarbonato de Sódio não indicado (ausência de cetoacidose primária).';
    }

    // ─────────────────────────────────────────────────────────────────────────
    // REGRA DE TRANSIÇÃO PARA SUBCUTÂNEA (SC)
    // ─────────────────────────────────────────────────────────────────────────
    var criteriosResolucao = tipoCrise === 'CAD'
      ? 'Critérios de Resolução da CAD: Glicemia < 200 mg/dL associada a Bicarbonato sérico >= 15 mEq/L, pH venoso > 7.30, Anion Gap normal (<= 12) e tolerância à via oral.'
      : 'Critérios de Resolução do EHH: Glicemia < 250 mg/dL, Osmolaridade efetiva < 315 mOsm/kg, recuperação da consciência e tolerância oral.';

    var protocoloTransicaoSc = 'REGRA DE OURO DA TRANSIÇÃO SC: A primeira dose de Insulina Subcutânea (Basal: Glargina/NPH + Bolus de refeição) DEVE ser aplicada 1 a 2 horas ANTES de desligar a bomba de infusão IV contínua. Desligar a bomba sem insulina SC prévia causa hiperglicemia e cetoacidose rebote imediata.';

    return {
      sucesso: true,
      tipoCrise: tipoCrise,
      gravidadeCad: gravidadeCad,
      peso: peso,
      glicemiaInicial: glicemia,
      potassioInicial: potassio,
      sodioMedido: sodioMedido,
      sodioCorrigidoKatz: sodioCorrigido,
      anionGap: anionGap,
      osmolaridadeEfetiva: osmolaridadeEfetiva,
      bloqueioInsulinaAtivo: bloqueioInsulinaAtivo,
      alertasSentinela: alertasSentinela,
      hidratacaoVenosa: condutaHidratacao,
      potassioConduta: condutaPotassio,
      insulinoterapiaConduta: condutaInsulina,
      bicarbonatoConduta: condutaBicarbonato,
      criteriosResolucao: criteriosResolucao,
      protocoloTransicaoSc: protocoloTransicaoSc
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 4. AVALIAÇÃO INTEGRADA E FORMATAÇÃO UI (TELEGRAM & COCKPIT)
  // ───────────────────────────────────────────────────────────────────────────

  function formatarResumoDiabetes(resultado) {
    if (!resultado) return 'Erro ao gerar resumo endocrinológico.';
    var l = [];

    if (resultado.tipoCrise) {
      // Formatação de Emergência (CAD / EHH)
      l.push('🚨 *PROTOCOLO DE EMERGÊNCIA HIPERGLICÊMICA (' + resultado.tipoCrise + ')*');
      l.push('════════════════════════════════════════════');
      l.push('⚖️ *Dados do Paciente:* ' + resultado.peso + ' kg | Glicemia: ' + resultado.glicemiaInicial + ' mg/dL');
      l.push('🧪 *Biomarcadores:* K+ ' + resultado.potassioInicial + ' mEq/L | Na+ Corrigido ' + resultado.sodioCorrigidoKatz + ' mEq/L | Anion Gap ' + resultado.anionGap + ' | Osmolaridade ' + resultado.osmolaridadeEfetiva + ' mOsm/kg');
      if (resultado.gravidadeCad !== 'N/A') {
        l.push('📊 *Gravidade CAD:* ' + resultado.gravidadeCad);
      }
      l.push('');

      if (resultado.alertasSentinela && resultado.alertasSentinela.length > 0) {
        resultado.alertasSentinela.forEach(function(a) {
          l.push(a);
        });
        l.push('');
      }

      l.push('💉 *1. INSULINOTERAPIA:*');
      l.push(resultado.insulinoterapiaConduta);
      l.push('');

      l.push('🍌 *2. CONDUTA DE POTÁSSIO:*');
      l.push(resultado.potassioConduta);
      l.push('');

      l.push('💧 *3. EXPANSÃO VOLÊMICA:*');
      l.push(resultado.hidratacaoVenosa);
      l.push('');

      l.push('🧪 *4. BICARBONATO DE SÓDIO:*');
      l.push(resultado.bicarbonatoConduta);
      l.push('');

      l.push('🎯 *5. CRITÉRIOS DE RESOLUÇÃO & TRANSIÇÃO:*');
      l.push(resultado.criteriosResolucao);
      l.push('💡 _' + resultado.protocoloTransicaoSc + '_');
    } else if (resultado.tipoDm) {
      // Formatação Ambulatorial Basal-Bolus
      l.push('🩺 *PRESCRIÇÃO DE INSULINOTERAPIA AMBULATORIAL (' + resultado.tipoDm + ')*');
      l.push('════════════════════════════════════════════');
      l.push('⚖️ Peso: ' + resultado.peso + ' kg | Estratégia: ' + resultado.esquemaRecomendado);
      if (resultado.doseTotalDia) {
        l.push('📊 Dose Total Diária Estimada: ' + resultado.doseTotalDia + ' UI/dia');
      }
      l.push('');
      l.push('💉 *Insulina Basal:*');
      l.push('• ' + (resultado.basal.posologia || resultado.basal.tipo));
      l.push('');

      if (resultado.bolusPrandial) {
        l.push('🍽️ *Insulina Prandial (Bolus):*');
        l.push('• ' + resultado.bolusPrandial.posologiaFixa);
        if (resultado.bolusPrandial.contagemCarboidratos) {
          l.push('• ' + resultado.bolusPrandial.contagemCarboidratos.regraIcr);
          l.push('• ' + resultado.bolusPrandial.contagemCarboidratos.regraFsi);
        }
        l.push('');
      }

      if (resultado.algoritmoTitulacao) {
        l.push('📈 *Algoritmo de Titulação:*');
        l.push('• ' + resultado.algoritmoTitulacao.instrucao);
        l.push('');
      }

      if (resultado.alertasSeguranca && resultado.alertasSeguranca.length > 0) {
        l.push('⚠️ *Alertas de Segurança Farmacológica:*');
        resultado.alertasSeguranca.forEach(function(al) {
          l.push('  ' + al);
        });
        l.push('');
      }

      l.push('📋 *Recomendações:* ' + resultado.orientacoes);
    }

    return l.join('\n');
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 4. SÍNDROME CARDIO-RENAL-METABÓLICA (CKM - AHA 2024)
  // ───────────────────────────────────────────────────────────────────────────

  /**
   * Avalia o Estadiamento da Síndrome Cardio-Renal-Metabólica (CKM - AHA 2024).
   *
   * @param {Object} params - Parâmetros clínicos e laboratoriais do paciente
   * @param {number} params.imc - Índice de Massa Corporal (kg/m²)
   * @param {boolean} [params.etniaAsiatica=false] - Ponto de corte de IMC/CA ajustado para asiáticos
   * @param {number} [params.circunferenciaAbdominal] - Em cm
   * @param {string} [params.sexo='M'] - 'M' ou 'F'
   * @param {number} [params.glicemiaJejum=85] - mg/dL
   * @param {number} [params.hba1c=5.0] - %
   * @param {boolean} [params.dm2Diagnostico=false] - Diagnóstico prévio de DM2
   * @param {boolean} [params.hasDiagnostico=false] - Diagnóstico prévio de Hipertensão
   * @param {number} [params.pas=120] - Pressão Arterial Sistólica (mmHg)
   * @param {number} [params.pad=80] - Pressão Arterial Diastólica (mmHg)
   * @param {number} [params.triglicerideos=100] - mg/dL
   * @param {boolean} [params.sindromeMetabolica=false] - Critérios de SM preenchidos
   * @param {number} params.tfg - Taxa de Filtração Glomerular estimada (mL/min/1.73m²)
   * @param {number} [params.rac=0] - Relação Albumina/Creatinina urinária (mg/g)
   * @param {boolean} [params.dialise=false] - Paciente em terapia renal substitutiva
   * @param {Object} [params.dcvSubclinica={}] - Marcadores de DCV subclínica
   * @param {Object} [params.dcvClinica={}] - Doença Cardiovascular Clínica estabelecida
   * @returns {Object} Resultado determinístico do estadiamento CKM e condutas
   */
  function avaliarSindromeCKM(params) {
    if (!params || typeof params.imc !== 'number' || typeof params.tfg !== 'number') {
      throw new Error("Parâmetros obrigatórios ausentes: 'imc' e 'tfg' devem ser fornecidos como números.");
    }

    const {
      imc,
      etniaAsiatica = false,
      circunferenciaAbdominal = 0,
      sexo = 'M',
      glicemiaJejum = 85,
      hba1c = 5.0,
      dm2Diagnostico = false,
      hasDiagnostico = false,
      pas = 120,
      pad = 80,
      triglicerideos = 100,
      sindromeMetabolica = false,
      tfg,
      rac = 0,
      dialise = false,
      dcvSubclinica = {},
      dcvClinica = {}
    } = params;

    const criteriosAtendidos = [];
    let estadio = "0";
    let nomeEstadio = "";
    let condutasEspecificas = [];

    // 1. Critérios de Adiposidade (Estádio 1)
    const corteImcSobrepeso = etniaAsiatica ? 23 : 25;
    const corteCaHomem = etniaAsiatica ? 90 : 102;
    const corteCaMulher = etniaAsiatica ? 80 : 88;
    const caAumentada = (sexo.toUpperCase() === 'M' && circunferenciaAbdominal >= corteCaHomem) ||
                        (sexo.toUpperCase() === 'F' && circunferenciaAbdominal >= corteCaMulher);
    const excessoAdiposidade = (imc >= corteImcSobrepeso) || caAumentada;

    // 2. Critérios Glicêmicos (Pré-DM vs DM2)
    const isDiabetes = dm2Diagnostico || glicemiaJejum >= 126 || hba1c >= 6.5;
    const isPreDiabetes = !isDiabetes && ((glicemiaJejum >= 100 && glicemiaJejum <= 125) || (hba1c >= 5.7 && hba1c <= 6.4));

    // 3. Critérios de Fatores de Risco Metabólicos (Estádio 2)
    const isHipertenso = hasDiagnostico || pas >= 130 || pad >= 80;
    const isHipertrigliceridemia = triglicerideos >= 135;

    // 4. Critérios Renais (KDIGO / AHA)
    const isFalenciaRenal = dialise || tfg < 15;
    const isDrcMuitoAltoRisco = !isFalenciaRenal && (
      tfg < 30 ||
      rac > 300 ||
      (tfg >= 30 && tfg < 45 && rac >= 30)
    );
    const isDrcModeradaAltoRisco = !isFalenciaRenal && !isDrcMuitoAltoRisco && (
      (tfg >= 30 && tfg < 60) ||
      (rac >= 30 && rac <= 300)
    );

    // 5. Critérios Cardiovasculares (Subclínico vs Clínico)
    const temDcvClinica = Boolean(
      dcvClinica.dac || dcvClinica.ic || dcvClinica.avc || dcvClinica.dap || dcvClinica.fa
    );

    const temDcvSubclinica = Boolean(
      (dcvSubclinica.escoreCalcioCoronario && dcvSubclinica.escoreCalcioCoronario >= 100) ||
      dcvSubclinica.biomarcadoresElevados ||
      dcvSubclinica.ecocardiogramaAlterado ||
      dcvSubclinica.riscoPreventAlto
    );

    if (temDcvClinica) {
      if (isFalenciaRenal) {
        estadio = "4b";
        nomeEstadio = "Estádio 4b: DCV Clínica na presença de Falência Renal (DRC G5 / Diálise)";
        criteriosAtendidos.push("Doença Cardiovascular Clínica manifesta associada a TFG < 15 mL/min/1.73m² ou diálise.");
        condutasEspecificas = [
          "Manejo multidisciplinar intensivo (Cardio-Nefro-Endócrino).",
          "Atenção às restrições de prescrição na DRC G5 (iSGLT2 não devem ser iniciados se TFG < 20, mas mantidos até diálise se já em uso).",
          "Agonistas de GLP-1 (Semaglutida, Liraglutida, Dulaglutida) podem ser usados com segurança até TFG < 15 mL/min.",
          "Controle rigoroso de volume, potássio e metabolismo mineral ósseo."
        ];
      } else {
        estadio = "4a";
        nomeEstadio = "Estádio 4a: DCV Clínica sem Falência Renal Terminal";
        if (dcvClinica.dac) criteriosAtendidos.push("Doença Arterial Coronariana (DAC/IAM)");
        if (dcvClinica.ic) criteriosAtendidos.push("Insuficiência Cardíaca (IC)");
        if (dcvClinica.avc) criteriosAtendidos.push("Doença Cerebrovascular (AVC/AIT)");
        if (dcvClinica.dap) criteriosAtendidos.push("Doença Arterial Periférica (DAP)");
        if (dcvClinica.fa) criteriosAtendidos.push("Fibrilação Atrial (FA)");

        condutasEspecificas = [
          "Prevenção secundária intensiva (Estatina de alta potência +/- Ezetimiba para LDL < 55 mg/dL).",
          "Priorização absoluta de fármacos cardioprotetores: iSGLT2 e/ou AR-GLP1 (ou co-agonista GIP/GLP-1).",
          "Se DRC albuminúrica (RAC >= 30) e DM2: associar IECA/BRA + iSGLT2 + Finerenona (se K+ <= 4.8 e TFG >= 25).",
          "Terapia antitrombótica e bloqueio neuro-hormonal conforme diretrizes específicas da DCV de base."
        ];
      }
    } else if (temDcvSubclinica || isDrcMuitoAltoRisco || isFalenciaRenal) {
      estadio = "3";
      nomeEstadio = "Estádio 3: DCV Subclínica ou Equivalente de Muito Alto Risco Renal/PREVENT";
      if (dcvSubclinica.escoreCalcioCoronario >= 100) criteriosAtendidos.push(`Escore de Cálcio Coronário (CAC) >= 100 (${dcvSubclinica.escoreCalcioCoronario} UA)`);
      if (dcvSubclinica.biomarcadoresElevados) criteriosAtendidos.push("Elevação subclínica de Troponina US ou BNP/NT-proBNP");
      if (dcvSubclinica.ecocardiogramaAlterado) criteriosAtendidos.push("Alteração ecocardiográfica subclínica (HVE ou disfunção assintomática)");
      if (dcvSubclinica.riscoPreventAlto) criteriosAtendidos.push("Risco cardiovascular PREVENT em 10 anos >= 20%");
      if (isDrcMuitoAltoRisco || isFalenciaRenal) criteriosAtendidos.push(`DRC de muito alto risco (TFG: ${tfg} mL/min, RAC: ${rac} mg/g)`);

      condutasEspecificas = [
        "Intensificação farmacológica preventiva para evitar progressão para DCV sintomática (IC/IAM/AVC).",
        "Início mandatório de iSGLT2 se DRC ou IC subclínica e TFG >= 20.",
        "Introdução de estatinas de alta intensidade (particularmente se CAC >= 100 ou DRC avançada não dialítica).",
        "Controle pressórico estrito (Meta PA < 130/80 mmHg, preferencialmente com IECA ou BRA se RAC >= 30)."
      ];
    } else if (isDiabetes || isHipertenso || isHipertrigliceridemia || sindromeMetabolica || isDrcModeradaAltoRisco) {
      estadio = "2";
      nomeEstadio = "Estádio 2: Fatores de Risco Metabólicos Estabelecidos e/ou DRC Moderada a Alto Risco";
      if (isDiabetes) criteriosAtendidos.push("Diabetes Mellitus tipo 2");
      if (isHipertenso) criteriosAtendidos.push(`Hipertensão Arterial (PA: ${pas}x${pad} mmHg)`);
      if (isHipertrigliceridemia) criteriosAtendidos.push(`Hipertrigliceridemia (${triglicerideos} mg/dL)`);
      if (sindromeMetabolica) criteriosAtendidos.push("Síndrome Metabólica");
      if (isDrcModeradaAltoRisco) criteriosAtendidos.push(`DRC moderado/alto risco (TFG: ${tfg} mL/min, RAC: ${rac} mg/g)`);

      condutasEspecificas = [
        "Rastreamento anual de DRC com dupla avaliação obrigatória: Creatinina sérica (TFGe) + Relação Albumina/Creatinina urinária (RAC).",
        "Se DRC presente (TFG < 60 ou RAC >= 30): iniciar IECA/BRA + iSGLT2 imediatamente.",
        "Se DM2: priorizar agentes com benefício cardiorrenal (iSGLT2 / AR-GLP1) e controle ponderal.",
        "Calcular escore PREVENT (AHA) para definir metas lipídicas e pressóricas."
      ];
    } else if (excessoAdiposidade || isPreDiabetes) {
      estadio = "1";
      nomeEstadio = "Estádio 1: Excesso ou Disfunção de Adiposidade (Pré-clínico)";
      if (excessoAdiposidade) criteriosAtendidos.push(`Excesso de adiposidade (IMC: ${imc} kg/m²${caAumentada ? ', Circunferência Abdominal aumentada' : ''})`);
      if (isPreDiabetes) criteriosAtendidos.push(`Pré-diabetes / Intolerância à glicose (GJ: ${glicemiaJejum} mg/dL, HbA1c: ${hba1c}%)`);

      condutasEspecificas = [
        "Meta primária: Perda ponderal >= 5% a 10% através de intervenção intensiva no estilo de vida.",
        "Se IMC >= 30 (ou >= 27 com pré-diabetes): considerar farmacoterapia antiobesidade (ex: Semaglutida 2.4mg ou Tirzepatida).",
        "Se Pré-diabetes: considerar Metformina.",
        "Rastreamento de PA, perfil lipídico e glicemia a cada 1-2 anos."
      ];
    } else {
      estadio = "0";
      nomeEstadio = "Estádio 0: Ausência de Fatores de Risco CKM";
      criteriosAtendidos.push("Antropometria, pressão arterial, glicemia, perfil lipídico e função renal normais.");
      condutasEspecificas = [
        "Manutenção da saúde cardiovascular primordial (Life's Essential 8 - AHA).",
        "Reavaliação clínica e triagem metabólica a cada 3 a 5 anos."
      ];
    }

    return {
      estadio,
      nomeEstadio,
      criteriosAtendidos,
      classificacaoRenal: {
        tfg,
        rac,
        status: isFalenciaRenal ? "Falência Renal (G5)" :
                isDrcMuitoAltoRisco ? "DRC Muito Alto Risco" :
                isDrcModeradaAltoRisco ? "DRC Risco Moderado/Alto" : "Normal / Baixo Risco"
      },
      condutasEspecificas,
      referencia: "AHA Presidential Advisory: Cardiovascular-Kidney-Metabolic Health (Circulation 2024)"
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 5. DIRETRIZES FARMACOLÓGICAS DE DM2 (ADA STANDARDS OF CARE 2025/2026)
  // ───────────────────────────────────────────────────────────────────────────

  /**
   * Algoritmo de Conduta Farmacológica no DM2 (Diretrizes ADA 2025/2026).
   * Priorização Classe I de iSGLT2 e/ou AR-GLP1 em pacientes com DCV, IC ou DRC,
   * INDEPENDENTEMENTE da HbA1c basal e do uso prévio de Metformina.
   *
   * @param {Object} params - Perfil clínico do paciente com DM2
   * @param {number} params.hba1c - Hemoglobina glicada atual (%)
   * @param {number} [params.metaHba1c=7.0] - Meta individualizada de HbA1c (%)
   * @param {number} params.tfg - Taxa de Filtração Glomerular (mL/min/1.73m²)
   * @param {number} [params.rac=0] - Relação Albumina/Creatinina urinária (mg/g)
   * @param {number} [params.imc=25] - Índice de Massa Corporal (kg/m²)
   * @param {boolean} [params.dcvAterosclerotica=false] - DAC, AVC isquêmico, DAP ou Alto Risco CV
   * @param {boolean} [params.insuficienciaCardiaca=false] - IC clínica (ICFEr, ICFElr ou ICFEp)
   * @param {boolean} [params.mashFibrose=false] - Esteato-hepatite associada à disfunção metabólica (MASH) com fibrose F2-F3
   * @param {boolean} [params.emUsoMetformina=false] - Se o paciente já utiliza metformina
   * @param {boolean} [params.contraindicacaoGlp1=false] - Contraindicação a agonistas GLP-1
   * @returns {Object} Plano terapêutico estruturado (ADA 2025/2026)
   */
  function prescreverTerapiaDM2_ADA2026(params) {
    if (!params || typeof params.hba1c !== 'number' || typeof params.tfg !== 'number') {
      throw new Error("Parâmetros obrigatórios ausentes: 'hba1c' e 'tfg' devem ser fornecidos.");
    }

    const {
      hba1c,
      metaHba1c = 7.0,
      tfg,
      rac = 0,
      imc = 25,
      dcvAterosclerotica = false,
      insuficienciaCardiaca = false,
      mashFibrose = false,
      emUsoMetformina = false,
      contraindicacaoGlp1 = false
    } = params;

    const prescricaoPrioritaria = [];
    const manejoGlicemicoPeso = [];
    const alertasSegurancaRenal = [];
    const classesRecomendadas = new Set();

    const temDRC = (tfg < 60) || (rac >= 30);
    const elegivelInicioSGLT2 = tfg >= 20;

    // 1.1 Insuficiência Cardíaca
    if (insuficienciaCardiaca) {
      if (elegivelInicioSGLT2) {
        classesRecomendadas.add("iSGLT2");
        prescricaoPrioritaria.push({
          indicacao: "Insuficiência Cardíaca (ICFEr / ICFEp)",
          evidencia: "Classe I, Nível A (ADA 2025/2026)",
          conduta: "Iniciar Inibidor de SGLT2 com benefício comprovado em IC (Dapagliflozina 10mg/dia ou Empagliflozina 10mg/dia) IMEDIATAMENTE, independentemente da HbA1c basal ou uso de metformina.",
          observacao: (imc >= 30 && !contraindicacaoGlp1)
            ? "Se ICFEp associada à obesidade (IMC >= 30): considerar associação de Semaglutida ou Tirzepatida para redução de sintomas e eventos de IC."
            : null
        });
      } else {
        alertasSegurancaRenal.push("TFG < 20 mL/min/1.73m²: Não iniciar iSGLT2 de novo. Se já em uso prévio, pode ser mantido até o início de diálise.");
      }
    }

    // 1.2 Doença Renal Crônica (TFG < 60 ou RAC >= 30)
    if (temDRC) {
      if (elegivelInicioSGLT2) {
        classesRecomendadas.add("iSGLT2");
        prescricaoPrioritaria.push({
          indicacao: `Doença Renal Crônica (TFG: ${tfg} mL/min | RAC: ${rac} mg/g)`,
          evidencia: "Classe I, Nível A (ADA 2025/2026 / KDIGO)",
          conduta: "Iniciar iSGLT2 com benefício nefroprotetor comprovado (Empagliflozina, Dapagliflozina ou Canagliflozina) IMEDIATAMENTE, independentemente da HbA1c ou uso de metformina.",
          observacao: (!contraindicacaoGlp1)
            ? "Associar ou substituir por Agonista de GLP-1 (Semaglutida com benefício nefroprotetor - Estudo FLOW) se intolerância ou necessidade adicional."
            : null
        });
        if (!contraindicacaoGlp1 && (rac >= 30 || tfg < 45)) {
          classesRecomendadas.add("AR-GLP1");
        }
      } else {
        if (!contraindicacaoGlp1) {
          classesRecomendadas.add("AR-GLP1");
          prescricaoPrioritaria.push({
            indicacao: `DRC Avançada (TFG ${tfg} mL/min < 20 mL/min)`,
            evidencia: "Classe I, Nível A (ADA 2025/2026)",
            conduta: "Como a TFG é < 20 mL/min, priorizar Agonista do Receptor de GLP-1 (Semaglutida, Liraglutida ou Dulaglutida) para redução de risco cardiovascular e controle glicêmico seguro."
          });
        }
      }
    }

    // 1.3 Doença Cardiovascular Aterosclerótica Estabelecida (DCVA)
    if (dcvAterosclerotica) {
      const opcoesDCVA = [];
      if (!contraindicacaoGlp1) {
        classesRecomendadas.add("AR-GLP1");
        opcoesDCVA.push("Agonista de GLP-1 com benefício CV comprovado (Semaglutida, Dulaglutida ou Liraglutida)");
      }
      if (elegivelInicioSGLT2) {
        classesRecomendadas.add("iSGLT2");
        opcoesDCVA.push("Inibidor de SGLT2 com benefício CV comprovado (Empagliflozina, Dapagliflozina ou Canagliflozina)");
      }

      prescricaoPrioritaria.push({
        indicacao: "Doença Cardiovascular Aterosclerótica (DCVA) Estabelecida / Alto Risco",
        evidencia: "Classe I, Nível A (ADA 2025/2026)",
        conduta: `Iniciar ${opcoesDCVA.join(" E/OU ")} IMEDIATAMENTE, independentemente da HbA1c basal e sem necessidade de aguardar falha da metformina.`,
        observacao: (elegivelInicioSGLT2 && !contraindicacaoGlp1)
          ? "Terapia combinada (AR-GLP1 + iSGLT2) deve ser considerada para redução aditiva de desfechos cardiovasculares e renais."
          : null
      });
    }

    // 2.1 MASH / Esteatose Metabólica
    if (mashFibrose && !contraindicacaoGlp1) {
      classesRecomendadas.add("AR-GLP1 / Co-agonista GIP/GLP-1");
      manejoGlicemicoPeso.push(
        "MASH com fibrose (F2-F3): Priorizar Agonista de GLP-1 (Semaglutida) ou Co-agonista Duplo GIP/GLP-1 (Tirzepatida) e/ou Pioglitazona (se ausência de IC) para resolução histológica da esteato-hepatite."
      );
    }

    // 2.2 Gestão de Peso
    if (imc >= 27 && !contraindicacaoGlp1) {
      classesRecomendadas.add("AR-GLP1 / Co-agonista GIP/GLP-1");
      manejoGlicemicoPeso.push(
        `Sobrepeso/Obesidade (IMC ${imc} kg/m²): Priorizar agentes de Muito Alta Eficácia para perda ponderal e redução de HbA1c (Tirzepatida ou Semaglutida).`
      );
    }

    // 2.3 Metformina
    if (tfg >= 45) {
      classesRecomendadas.add("Metformina");
      manejoGlicemicoPeso.push(
        emUsoMetformina
          ? "Manter Metformina em dose otimizada (até 2000 mg/dia) como terapia de base."
          : "Iniciar ou associar Metformina para eficácia glicêmica adicional, salvo contraindicação (não deve atrasar o início de iSGLT2/AR-GLP1 se indicados)."
      );
    } else if (tfg >= 30 && tfg < 45) {
      classesRecomendadas.add("Metformina (Dose Ajustada)");
      alertasSegurancaRenal.push(
        "TFG entre 30 e 44 mL/min/1.73m²: Reduzir dose máxima de Metformina para 1000 mg/dia."
      );
    } else {
      alertasSegurancaRenal.push(
        "TFG < 30 mL/min/1.73m²: CONTRAINDICADO o uso de Metformina (risco de acidose lática). Suspender imediatamente se estiver em uso."
      );
    }

    const deltaHba1c = +(hba1c - metaHba1c).toFixed(1);

    if (hba1c >= 10.0) {
      classesRecomendadas.add("Insulina Basal (+/- AR-GLP1)");
      manejoGlicemicoPeso.push(
        `HbA1c severamente elevada (${hba1c}%): Iniciar Insulina Basal (10 UI/dia ou 0.1-0.2 UI/kg/dia), preferencialmente com AR-GLP1.`
      );
    } else if (deltaHba1c >= 1.5) {
      manejoGlicemicoPeso.push(
        `HbA1c (${hba1c}%) está >= 1.5% acima da meta (${metaHba1c}%): Indicada TERAPIA COMBINADA DUPLA OU TRIPLA DESDE O INÍCIO (estratégia VERIFY / ADA 2026).`
      );
    } else if (deltaHba1c <= 0 && prescricaoPrioritaria.length > 0) {
      manejoGlicemicoPeso.push(
        `Atenção: Embora a HbA1c (${hba1c}%) esteja na meta (${metaHba1c}%), a introdução de iSGLT2 e/ou AR-GLP1 permanece MANDATÓRIA para redução de mortalidade cardiorrenal.`
      );
    }

    if (tfg < 45 && classesRecomendadas.has("iSGLT2")) {
      alertasSegurancaRenal.push(
        "Nota Farmacodinâmica: Com TFG < 45 mL/min, o efeito redutor de HbA1c dos iSGLT2 é atenuado, mas a proteção renal e contra IC permanece intacta."
      );
    }

    return {
      statusGlicemico: {
        hba1cAtual: hba1c,
        metaHba1c,
        acimaDaMeta: hba1c > metaHba1c,
        diferencaMeta: deltaHba1c
      },
      temIndicacaoCardiorrenalPrioritaria: prescricaoPrioritaria.length > 0,
      eixo1_ProtecaoOrgaoAlvo: prescricaoPrioritaria,
      eixo2_ControleGlicemicoPonderal: manejoGlicemicoPeso,
      alertasSegurancaRenal,
      classesFarmacologicasRecomendadas: Array.from(classesRecomendadas),
      referencia: "ADA Standards of Care in Diabetes - 2025/2026"
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // EXPORTAÇÃO PÚBLICA
  // ───────────────────────────────────────────────────────────────────────────

  return {
    calcularInsulinaAmbulatorial: calcularInsulinaAmbulatorial,
    protocoloCorrecaoHospitalar: protocoloCorrecaoHospitalar,
    manejoCriseHiperglicemica: manejoCriseHiperglicemica,
    formatarResumoDiabetes: formatarResumoDiabetes,
    avaliarSindromeCKM: avaliarSindromeCKM,
    prescreverTerapiaDM2_ADA2026: prescreverTerapiaDM2_ADA2026
  };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = EndocrinologiaDiabetesService;
  module.exports.EndocrinologiaDiabetesService = EndocrinologiaDiabetesService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_gasometria_acido_base.js
// ==============================================================================

/**
 * ═══════════════════════════════════════════════════════════════════════════════
 * Módulo de Inteligência Gasométrica e Distúrbios Ácido-Base
 * REGRA DOS 5 PASSOS — Motor Determinístico Beira-Leito
 * ═══════════════════════════════════════════════════════════════════════════════
 *
 * Baseado em:
 *  - Adrogué HJ, Madias NE. "Management of life-threatening acid–base disorders"
 *    (NEJM 1998 / update 2018)
 *  - Haber RJ. "A Practical Approach to Acid-Base Disorders" (West J Med 1991)
 *  - Fórmula de Winter: pCO₂ = 1.5 × HCO₃⁻ + 8 (±2) — NEJM 1967
 *  - Narins RG, Emmett M. "Simple and mixed acid-base disorders: a practical approach"
 *    (Medicine 1980)
 *  - SDRA: Definição de Berlim 2012 (JAMA)
 *  - Gradiente A-a: Guyton & Hall, Textbook of Medical Physiology, 14th ed.
 *
 * Passos implementados:
 *  1. Identificação do distúrbio primário (pH, PaCO₂, HCO₃⁻)
 *  2. Avaliação da compensação esperada (Winter, fórmulas metabólicas/respiratórias)
 *  3. Cálculo do Ânion Gap (AG) e AG corrigido por albumina
 *  4. Cálculo da Razão Delta (Delta-Delta) para distúrbios ocultos
 *  5. Avaliação da oxigenação: P/F Ratio, Gradiente A-a, SatO₂ esperada
 *
 * @author Ultra Rotina — Motor de Evolução Perpétua
 */

var GasometriaAcidoBaseService = (function () {
  'use strict';

  // ═══════════════════════════ CONSTANTES ════════════════════════════════════

  var EPS = 1e-9;
  var AG_NORMAL = 12;        // Ânion Gap de referência (mEq/L)
  var ALB_NORMAL = 4.0;      // Albumina sérica normal (g/dL)
  var HCO3_NORMAL = 24;      // HCO₃⁻ normal (mEq/L)
  var PCO2_NORMAL = 40;       // PaCO₂ normal (mmHg)
  var PH_NORMAL_LOW = 7.35;
  var PH_NORMAL_HIGH = 7.45;
  var HCO3_LOW = 22;
  var HCO3_HIGH = 26;
  var PCO2_LOW = 35;
  var PCO2_HIGH = 45;

  // ════════════════════════ HELPERS NUMÉRICOS ════════════════════════════════

  function lt(a, b)  { return a < b - EPS; }
  function lte(a, b) { return a <= b + EPS; }
  function gt(a, b)  { return a > b + EPS; }
  function gte(a, b) { return a >= b - EPS; }
  function entre(v, min, max) { return gte(v, min) && lte(v, max); }

  function arred(x, casas) {
    if (!Number.isFinite(x)) return x;
    var f = Math.pow(10, casas || 0);
    return Math.round((x + EPS) * f) / f;
  }
  function fmt(x, casas) {
    if (x === null || x === undefined) return '—';
    return arred(x, casas).toFixed(casas).replace('.', ',');
  }

  function validarNumero(val, nome, min, max, obrigatorio) {
    if (val === null || val === undefined || val === '') {
      if (obrigatorio) throw new Error('Parâmetro obrigatório ausente: ' + nome);
      return null;
    }
    var n = Number(val);
    if (!Number.isFinite(n)) throw new Error(nome + ': valor não numérico (' + val + ')');
    if (n < min || n > max) throw new Error(nome + ': valor ' + n + ' fora da faixa [' + min + '–' + max + ']');
    return n;
  }

  // ═══════════════ PASSO 1: DISTÚRBIO PRIMÁRIO ══════════════════════════════

  function identificarDisturbio(ph, pco2, hco3) {
    var pHbaixo = lt(ph, PH_NORMAL_LOW);
    var pHalto  = gt(ph, PH_NORMAL_HIGH);
    var acMet   = lt(hco3, HCO3_LOW);
    var alMet   = gt(hco3, HCO3_HIGH);
    var acResp  = gt(pco2, PCO2_HIGH);
    var alResp  = lt(pco2, PCO2_LOW);

    var tipo, subtipo, gravidade;

    if (pHbaixo) {
      if (acMet && acResp) {
        tipo = 'Acidose Mista (Metabólica + Respiratória)';
        subtipo = 'mista';
      } else if (acMet) {
        tipo = 'Acidose Metabólica';
        subtipo = 'acidose_metabolica';
      } else if (acResp) {
        tipo = 'Acidose Respiratória';
        subtipo = 'acidose_respiratoria';
      } else {
        tipo = 'Acidemia sem alteração evidente de PaCO₂/HCO₃⁻';
        subtipo = 'acidemia_indefinida';
      }
    } else if (pHalto) {
      if (alMet && alResp) {
        tipo = 'Alcalose Mista (Metabólica + Respiratória)';
        subtipo = 'mista';
      } else if (alMet) {
        tipo = 'Alcalose Metabólica';
        subtipo = 'alcalose_metabolica';
      } else if (alResp) {
        tipo = 'Alcalose Respiratória';
        subtipo = 'alcalose_respiratoria';
      } else {
        tipo = 'Alcalemia sem alteração evidente de PaCO₂/HCO₃⁻';
        subtipo = 'alcalemia_indefinida';
      }
    } else {
      if (acMet && alResp) {
        tipo = 'Distúrbio Misto com pH normal (Acidose Metabólica + Alcalose Respiratória)';
        subtipo = 'misto_ph_normal';
      } else if (alMet && acResp) {
        tipo = 'Distúrbio Misto com pH normal (Alcalose Metabólica + Acidose Respiratória)';
        subtipo = 'misto_ph_normal';
      } else if (acMet || alMet || acResp || alResp) {
        tipo = 'pH normal compensado ou distúrbio misto';
        subtipo = 'compensado';
      } else {
        tipo = 'Gasometria Normal — sem distúrbio ácido-base evidente';
        subtipo = 'normal';
      }
    }

    // Gravidade baseada no pH
    if (lt(ph, 7.10))      gravidade = 'CRITICA';
    else if (lt(ph, 7.20)) gravidade = 'GRAVE';
    else if (lt(ph, 7.30)) gravidade = 'MODERADA';
    else if (gt(ph, 7.60)) gravidade = 'CRITICA';
    else if (gt(ph, 7.55)) gravidade = 'GRAVE';
    else                   gravidade = 'LEVE_OU_NORMAL';

    return {
      descricao: tipo,
      subtipo: subtipo,
      gravidade: gravidade,
      flags: {
        pHbaixo: pHbaixo, pHalto: pHalto,
        acMet: acMet, alMet: alMet,
        acResp: acResp, alResp: alResp
      }
    };
  }

  // ═══════════════ PASSO 2: COMPENSAÇÃO ESPERADA ════════════════════════════

  function avaliarCompensacao(ph, pco2, hco3, flags) {
    var resultado = {
      formulaUsada: null,
      esperadoMin: null,
      esperadoMax: null,
      valorReal: null,
      parametroAvaliado: null,
      avaliacao: null,
      disturbioAssociado: null
    };

    // ─── Acidose Metabólica: Fórmula de Winter ──────────────────────
    if (flags.acMet && !flags.pHalto) {
      var base = 1.5 * hco3 + 8;
      resultado.formulaUsada = 'Winter: PaCO₂ = 1,5 × HCO₃⁻ + 8 (±2)';
      resultado.esperadoMin = arred(base - 2, 1);
      resultado.esperadoMax = arred(base + 2, 1);
      resultado.valorReal = pco2;
      resultado.parametroAvaliado = 'PaCO₂';

      if (gt(pco2, resultado.esperadoMax)) {
        resultado.avaliacao = 'PaCO₂ acima do esperado: Acidose Respiratória associada';
        resultado.disturbioAssociado = 'acidose_respiratoria';
      } else if (lt(pco2, resultado.esperadoMin)) {
        resultado.avaliacao = 'PaCO₂ abaixo do esperado: Alcalose Respiratória associada';
        resultado.disturbioAssociado = 'alcalose_respiratoria';
      } else {
        resultado.avaliacao = 'Resposta compensatória adequada';
        resultado.disturbioAssociado = null;
      }
    }

    // ─── Alcalose Metabólica ────────────────────────────────────────
    else if (flags.alMet && !flags.pHbaixo) {
      var base2 = PCO2_NORMAL + 0.7 * (hco3 - HCO3_NORMAL);
      resultado.formulaUsada = 'PaCO₂ = 40 + 0,7 × (HCO₃⁻ − 24) (±2)';
      resultado.esperadoMin = arred(base2 - 2, 1);
      resultado.esperadoMax = arred(base2 + 2, 1);
      resultado.valorReal = pco2;
      resultado.parametroAvaliado = 'PaCO₂';

      if (gt(pco2, resultado.esperadoMax)) {
        resultado.avaliacao = 'PaCO₂ acima do esperado: Acidose Respiratória associada';
        resultado.disturbioAssociado = 'acidose_respiratoria';
      } else if (lt(pco2, resultado.esperadoMin)) {
        resultado.avaliacao = 'PaCO₂ abaixo do esperado: Alcalose Respiratória associada';
        resultado.disturbioAssociado = 'alcalose_respiratoria';
      } else {
        resultado.avaliacao = 'Resposta compensatória adequada';
        resultado.disturbioAssociado = null;
      }
    }

    // ─── Acidose Respiratória (aguda vs crônica) ────────────────────
    else if (flags.acResp && !flags.acMet && flags.pHbaixo) {
      var aguda  = HCO3_NORMAL + 0.1 * (pco2 - PCO2_NORMAL);
      var cronica = HCO3_NORMAL + 0.35 * (pco2 - PCO2_NORMAL);
      resultado.formulaUsada = 'HCO₃⁻ agudo: +0,1 × Δ PaCO₂ | crônico: +0,35 × Δ PaCO₂';
      resultado.esperadoMin = arred(aguda - 2, 1);
      resultado.esperadoMax = arred(cronica + 2, 1);
      resultado.valorReal = hco3;
      resultado.parametroAvaliado = 'HCO₃⁻';

      if (lt(hco3, resultado.esperadoMin)) {
        resultado.avaliacao = 'HCO₃⁻ abaixo do esperado: Acidose Metabólica associada';
        resultado.disturbioAssociado = 'acidose_metabolica';
      } else if (gt(hco3, resultado.esperadoMax)) {
        resultado.avaliacao = 'HCO₃⁻ acima do esperado: Alcalose Metabólica associada';
        resultado.disturbioAssociado = 'alcalose_metabolica';
      } else {
        resultado.avaliacao = 'Compatível com acidose respiratória pura (aguda a crônica)';
        resultado.disturbioAssociado = null;
      }
    }

    // ─── Alcalose Respiratória (aguda vs crônica) ───────────────────
    else if (flags.alResp && !flags.alMet && flags.pHalto) {
      var aguda2  = HCO3_NORMAL - 0.2 * (PCO2_NORMAL - pco2);
      var cronica2 = HCO3_NORMAL - 0.5 * (PCO2_NORMAL - pco2);
      resultado.formulaUsada = 'HCO₃⁻ agudo: −0,2 × Δ PaCO₂ | crônico: −0,5 × Δ PaCO₂';
      resultado.esperadoMin = arred(cronica2 - 2, 1);
      resultado.esperadoMax = arred(aguda2 + 2, 1);
      resultado.valorReal = hco3;
      resultado.parametroAvaliado = 'HCO₃⁻';

      if (gt(hco3, resultado.esperadoMax)) {
        resultado.avaliacao = 'HCO₃⁻ acima do esperado: Alcalose Metabólica associada';
        resultado.disturbioAssociado = 'alcalose_metabolica';
      } else if (lt(hco3, resultado.esperadoMin)) {
        resultado.avaliacao = 'HCO₃⁻ abaixo do esperado: Acidose Metabólica associada';
        resultado.disturbioAssociado = 'acidose_metabolica';
      } else {
        resultado.avaliacao = 'Compatível com alcalose respiratória pura (aguda a crônica)';
        resultado.disturbioAssociado = null;
      }
    }

    return resultado;
  }

  // ═══════════════ PASSO 3: ÂNION GAP ═══════════════════════════════════════

  function calcularAnionGap(na, cl, hco3, albumina) {
    if (na === null || cl === null) {
      return { calculado: false, motivo: 'Na e/ou Cl ausentes' };
    }

    var ag = na - (cl + hco3);
    var agCorr = null;
    if (albumina !== null) {
      agCorr = ag + 2.5 * (ALB_NORMAL - albumina);
    }

    var agRef = agCorr !== null ? agCorr : ag;
    var elevado = gt(agRef, AG_NORMAL);
    var interpretacao;
    if (elevado) {
      interpretacao = 'Ânion Gap ELEVADO (> 12 mEq/L)';
    } else {
      interpretacao = 'Ânion Gap NORMAL (≤ 12 mEq/L)';
    }

    return {
      calculado: true,
      anionGap: arred(ag, 1),
      anionGapCorrigido: agCorr !== null ? arred(agCorr, 1) : null,
      agReferencia: arred(agRef, 1),
      elevado: elevado,
      interpretacao: interpretacao,
      albuminaUsada: albumina
    };
  }

  // ═══════════════ PASSO 4: RAZÃO DELTA (DELTA-DELTA) ═══════════════════════

  /**
   * Delta Ratio = (AG - 12) / (24 - HCO₃⁻)
   *
   * Interpretação:
   *  < 0.4  → Acidose hiperclorêmica pura (AG normal)
   *  0.4–0.8 → Acidose mista (AG elevado + hiperclorêmica)
   *  0.8–2.0 → Acidose de AG elevado pura
   *  > 2.0  → Alcalose metabólica associada (HCO₃⁻ "falsamente preservado")
   *
   * Referências:
   *  - Narins RG & Emmett M, Medicine 1980
   *  - Emmett M, Narins RG. Medicine (Baltimore) 1977;56:38-54
   */
  function calcularDeltaRatio(ag, hco3) {
    var resultado = {
      calculado: false,
      deltaAG: null,
      deltaHCO3: null,
      razaoDelta: null,
      interpretacao: null,
      diagnosticosDiferenciais: []
    };

    if (ag === null || !gt(ag, AG_NORMAL)) {
      resultado.motivo = 'AG não elevado — Delta Ratio não aplicável';
      return resultado;
    }

    var deltaAG   = ag - AG_NORMAL;
    var deltaHCO3 = HCO3_NORMAL - hco3;

    if (lte(deltaHCO3, 0)) {
      // HCO₃⁻ ≥ 24 com AG elevado → fortemente sugestivo de alcalose metabólica concomitante
      resultado.calculado = true;
      resultado.deltaAG = arred(deltaAG, 1);
      resultado.deltaHCO3 = arred(deltaHCO3, 1);
      resultado.razaoDelta = null; // Divisão por zero/negativo
      resultado.interpretacao = 'HCO₃⁻ ≥ 24 com AG elevado: Alcalose Metabólica concomitante fortemente sugestiva';
      resultado.diagnosticosDiferenciais = [
        'Vômitos persistentes com cetoacidose',
        'Uso de diuréticos de alça com acidose lática',
        'Aspiração nasogástrica + sepse'
      ];
      return resultado;
    }

    var ratio = deltaAG / deltaHCO3;
    resultado.calculado = true;
    resultado.deltaAG = arred(deltaAG, 1);
    resultado.deltaHCO3 = arred(deltaHCO3, 1);
    resultado.razaoDelta = arred(ratio, 2);

    if (lt(ratio, 0.4)) {
      resultado.interpretacao = 'Razão delta < 0,4: Acidose hiperclorêmica pura predominante (sem AG elevado significativo)';
      resultado.diagnosticosDiferenciais = [
        'Diarreia grave (perda intestinal de HCO₃⁻)',
        'Acidose tubular renal (ATR tipo I, II ou IV)',
        'Infusão excessiva de SF 0,9% (acidose dilucional)',
        'Uso de Acetazolamida',
        'Fístula biliar/pancreática',
        'Derivação ureterossigmoide'
      ];
    } else if (lt(ratio, 0.8)) {
      resultado.interpretacao = 'Razão delta 0,4–0,8: Acidose mista (AG elevado + componente hiperclorêmico)';
      resultado.diagnosticosDiferenciais = [
        'Cetoacidose diabética em resolução + SF 0,9% em excesso',
        'Sepse com acidose lática + ressuscitação com cristaloides',
        'Acidose urêmica + ATR associada'
      ];
    } else if (lte(ratio, 2.0)) {
      resultado.interpretacao = 'Razão delta 0,8–2,0: Acidose de AG elevado pura';
      resultado.diagnosticosDiferenciais = [
        'Cetoacidose diabética (CAD)',
        'Acidose lática (tipo A: hipóxia/choque; tipo B: fármacos/metformina)',
        'Uremia (TFG < 15 mL/min)',
        'Intoxicação por metanol, etilenoglicol ou salicilatos (MUDPILES)',
        'Rabdomiólise severa'
      ];
    } else {
      resultado.interpretacao = 'Razão delta > 2,0: Alcalose Metabólica associada oculta';
      resultado.diagnosticosDiferenciais = [
        'Vômitos + cetoacidose diabética',
        'Uso de diuréticos tiazídicos/alça com insuficiência renal',
        'Hipovolemia com contração de volume + acidose lática'
      ];
    }

    return resultado;
  }

  // ═══════════════ PASSO 5: OXIGENAÇÃO ══════════════════════════════════════

  /**
   * Gradiente Alvéolo-Arterial (A-a):
   *   PAO₂ = FiO₂ × (Patm - PH₂O) - PaCO₂ / QR
   *   A-a  = PAO₂ - PaO₂
   *
   * Normal: A-a = 2,5 + (0,21 × idade)  — com margem de ±5
   * Elevado sugere: shunt, V/Q mismatch, difusão prejudicada
   *
   * PaO₂/FiO₂ (P/F Ratio) — Classificação de Berlim 2012:
   *   > 300: normal | 200–300: SDRA Leve | 100–200: SDRA Moderada | ≤ 100: SDRA Grave
   */
  function avaliarOxigenacao(pao2, fio2Raw, pco2, idade, altitudeMetros) {
    var resultado = {
      pfRatio: null,
      classificacaoPF: null,
      gradienteAa: null,
      gradienteAaEsperado: null,
      gradienteAaElevado: null,
      pao2Alveolar: null,
      diagnosticosShunt: [],
      avisos: []
    };

    if (pao2 === null || fio2Raw === null) return resultado;

    var fio2 = fio2Raw > 1 ? fio2Raw / 100 : fio2Raw;
    if (fio2 < 0.21 - EPS || fio2 > 1 + EPS) {
      throw new Error('FiO₂ inválida: ' + fio2Raw + '. Informar entre 21-100% ou 0,21-1,0');
    }

    // P/F Ratio
    var pf = pao2 / fio2;
    resultado.pfRatio = Math.round(pf);
    if (gt(pf, 300))      resultado.classificacaoPF = 'Oxigenação Normal (P/F > 300)';
    else if (gt(pf, 200)) resultado.classificacaoPF = 'SDRA Leve (Berlim: P/F 201–300)';
    else if (gt(pf, 100)) resultado.classificacaoPF = 'SDRA Moderada (Berlim: P/F 101–200)';
    else                  resultado.classificacaoPF = 'SDRA Grave (Berlim: P/F ≤ 100)';

    if (lte(pf, 300)) {
      resultado.avisos.push('SDRA (Berlim 2012): exige opacidades bilaterais agudas, PEEP ≥ 5 cmH₂O e exclusão de causa cardiogênica pura.');
    }

    // Gradiente A-a (requer PaCO₂)
    if (pco2 !== null) {
      var patm = 760; // mmHg ao nível do mar
      if (altitudeMetros && altitudeMetros > 0) {
        patm = 760 * Math.pow(1 - 0.0000225577 * altitudeMetros, 5.25588);
      }
      var ph2o = 47; // pressão de vapor d'água a 37°C
      var qr = 0.8;  // quociente respiratório

      var pao2Alveolar = fio2 * (patm - ph2o) - pco2 / qr;
      resultado.pao2Alveolar = arred(pao2Alveolar, 1);

      var gradAa = pao2Alveolar - pao2;
      resultado.gradienteAa = arred(gradAa, 1);

      // A-a esperado para idade (se informada)
      if (idade !== null && idade !== undefined) {
        var aaNormal = 2.5 + 0.21 * idade;
        resultado.gradienteAaEsperado = arred(aaNormal, 1);
        resultado.gradienteAaElevado = gt(gradAa, aaNormal + 5);
      } else {
        // Sem idade: considerar elevado se > 15 (corte prático em adultos jovens)
        resultado.gradienteAaElevado = gt(gradAa, 15);
      }

      if (resultado.gradienteAaElevado) {
        resultado.diagnosticosShunt = [
          'Shunt intrapulmonar (SDRA, atelectasia, PNM extensa)',
          'Alteração ventilação-perfusão (V/Q mismatch): TEP, DPOC, asma grave',
          'Déficit de difusão (fibrose pulmonar, pneumocistose, edema intersticial)',
          'Shunt intracardíaco (CIA, CIV, Foramen oval patente)'
        ];
      }
    }

    return resultado;
  }

  // ══════════════════ DETECÇÃO DE DISTÚRBIOS TRIPLOS ════════════════════════

  /**
   * Um distúrbio triplo ocorre quando:
   *  1. Há acidose de AG elevado (distúrbio base)
   *  2. A Delta Ratio revela um SEGUNDO distúrbio oculto (< 0.8 → hiperclorêmica; > 2.0 → alcalose met)
   *  3. A compensação respiratória está inadequada (→ acid. resp. ou alc. resp. como TERCEIRO componente)
   *
   * Exemplo clássico: paciente com CAD (AG elevado) + vômitos (alcalose metabólica) + DPOC (acidose respiratória)
   */
  function detectarDisturbioTriplo(disturbio, compensacao, deltaRatio) {
    var triplo = {
      detectado: false,
      componentes: [],
      descricao: null
    };

    // Distúrbio triplo requer acidose metabólica de AG elevado como base
    if (disturbio.subtipo !== 'acidose_metabolica' && disturbio.subtipo !== 'mista') return triplo;
    if (!deltaRatio.calculado) return triplo;

    var segundoDisturbio = null;
    if (deltaRatio.razaoDelta !== null) {
      if (lt(deltaRatio.razaoDelta, 0.8)) {
        segundoDisturbio = 'Acidose Hiperclorêmica (AG normal)';
      } else if (gt(deltaRatio.razaoDelta, 2.0)) {
        segundoDisturbio = 'Alcalose Metabólica oculta';
      }
    } else if (deltaRatio.interpretacao && deltaRatio.interpretacao.indexOf('Alcalose Metabólica') !== -1) {
      segundoDisturbio = 'Alcalose Metabólica oculta';
    }

    var terceiroDisturbio = null;
    if (compensacao.disturbioAssociado === 'acidose_respiratoria') {
      terceiroDisturbio = 'Acidose Respiratória (compensação inadequada)';
    } else if (compensacao.disturbioAssociado === 'alcalose_respiratoria') {
      terceiroDisturbio = 'Alcalose Respiratória (hiperventilação excessiva)';
    }

    if (segundoDisturbio && terceiroDisturbio) {
      triplo.detectado = true;
      triplo.componentes = [
        'Acidose Metabólica de AG elevado',
        segundoDisturbio,
        terceiroDisturbio
      ];
      triplo.descricao = '⚠️ DISTÚRBIO ÁCIDO-BASE TRIPLO detectado: ' + triplo.componentes.join(' + ');
    }

    return triplo;
  }

  // ═══════════════ CONSISTÊNCIA INTERNA (HENDERSON-HASSELBALCH) ═════════════

  function verificarConsistencia(ph, pco2, hco3) {
    var phCalc = 6.1 + Math.log(hco3 / (0.0307 * pco2)) / Math.LN10;
    var diff = Math.abs(phCalc - ph);
    return {
      phCalculado: arred(phCalc, 3),
      diferenca: arred(diff, 3),
      consistente: lte(diff, 0.1),
      aviso: gt(diff, 0.1)
        ? 'Inconsistência interna (pH calculado ≈ ' + fmt(phCalc, 2) + '): conferir se a amostra é arterial e se os valores foram digitados corretamente.'
        : null
    };
  }

  // ═══════════════ DIAGNÓSTICOS DIFERENCIAIS POR TIPO ═══════════════════════

  function gerarDiferenciais(disturbio, agResult, deltaResult) {
    var diferenciais = [];

    if (disturbio.flags.acMet) {
      if (agResult.calculado && agResult.elevado) {
        diferenciais.push({
          categoria: 'Acidose Metabólica com AG Elevado (MUDPILES)',
          causas: [
            'M — Metanol (intoxicação)',
            'U — Uremia (IRA/DRC estágio 5, TFG < 15)',
            'D — Cetoacidose Diabética (CAD)',
            'P — Propilenoglicol (infusão IV prolongada)',
            'I — Isoniazida / Ferro (intoxicação)',
            'L — Acidose Lática (tipo A: choque/hipóxia; tipo B: metformina, linezolida)',
            'E — Etilenoglicol (intoxicação)',
            'S — Salicilatos (AAS em dose tóxica)'
          ]
        });
      } else if (agResult.calculado && !agResult.elevado) {
        diferenciais.push({
          categoria: 'Acidose Metabólica Hiperclorêmica (AG Normal)',
          causas: [
            'Diarreia grave (perda intestinal de HCO₃⁻)',
            'Acidose Tubular Renal tipo I (distal), II (proximal) ou IV (hipercalêmica)',
            'Infusão excessiva de SF 0,9% (acidose dilucional)',
            'Acetazolamida (inibidor da anidrase carbônica)',
            'Fístula biliar, pancreática ou entérica',
            'Derivação ureterossigmoide',
            'Fase de resolução de CAD (perda renal de cetoânions)'
          ]
        });
      }
    }

    if (disturbio.flags.alMet) {
      diferenciais.push({
        categoria: 'Alcalose Metabólica',
        causas: [
          'Responsiva a Cloro (Cl urinário < 20): vômitos, SNG em aspiração, uso de diuréticos (pós)',
          'Resistente a Cloro (Cl urinário > 20): hiperaldosteronismo, Cushing, estenose de artéria renal',
          'Contração de volume (alcalose de contração)',
          'Hipocalemia grave (shift transcelular de H⁺)',
          'Síndrome de Bartter / Gitelman',
          'Ingestão excessiva de bases (síndrome leite-álcali)'
        ]
      });
    }

    if (disturbio.flags.acResp) {
      diferenciais.push({
        categoria: 'Acidose Respiratória (hipoventilação)',
        causas: [
          'DPOC exacerbado',
          'Asma grave / Status asthmaticus',
          'Obesidade + síndrome de hipoventilação (Pickwick)',
          'Fraqueza muscular respiratória (miastenia, Guillain-Barré, ELA)',
          'Depressão do SNC (opioides, benzodiazepínicos, AVC de tronco)',
          'Pneumotórax hipertensivo',
          'Derrame pleural volumoso bilateral',
          'Obstrução de via aérea superior'
        ]
      });
    }

    if (disturbio.flags.alResp) {
      diferenciais.push({
        categoria: 'Alcalose Respiratória (hiperventilação)',
        causas: [
          'Dor / ansiedade / pânico (causa mais comum)',
          'Sepse precoce (fase hiperdinâmica)',
          'Insuficiência hepática aguda (estímulo central)',
          'TEP agudo',
          'Gravidez (progesterona ↑ drive ventilatório)',
          'Intoxicação por salicilatos (fase inicial → alcalose resp mista)',
          'Ventilação mecânica excessiva (iatrogênica)',
          'Altitude elevada'
        ]
      });
    }

    return diferenciais;
  }

  // ═══════════════ SUGESTÕES DE CONDUTA BEIRA-LEITO ═════════════════════════

  function sugerirCondutas(disturbio, agResult, oxigenacao) {
    var condutas = [];

    if (disturbio.gravidade === 'CRITICA' || disturbio.gravidade === 'GRAVE') {
      condutas.push('⚠️ PRIORIDADE MÁXIMA: pH crítico — considerar UTI, monitorização contínua e gasometria seriada a cada 1-2h.');
    }

    if (disturbio.flags.acMet && agResult.calculado && agResult.elevado) {
      condutas.push('Solicitar: Lactato, Glicemia capilar/plasmática, Cetonemia/cetonúria, Função renal (Ureia/Cr), Gap osmolar (se intoxicação).');
      condutas.push('Se lactato ↑: investigar choque, hipóxia tecidual, uso de metformina, sepse.');
      condutas.push('NaHCO₃ IV considerar APENAS se pH < 7,1 com instabilidade hemodinâmica (dose parcial: 1-2 mEq/kg, reavaliar).');
    }

    if (disturbio.flags.acMet && agResult.calculado && !agResult.elevado) {
      condutas.push('Solicitar: Eletrólitos urinários (Na, K, Cl), AG urinário (Na+K-Cl), pH urinário.');
      condutas.push('AG urinário positivo → sugere ATR (defeito de acidificação renal).');
      condutas.push('AG urinário negativo → sugere perda GI de HCO₃⁻ (diarreia).');
    }

    if (disturbio.flags.alMet) {
      condutas.push('Solicitar: Cl⁻ urinário para classificar em responsiva (< 20 mEq/L) vs resistente a Cloro.');
      condutas.push('Se Cl⁻ urinário < 20: expansão com SF 0,9% + reposição de KCl.');
      condutas.push('Se Cl⁻ urinário > 20: investigar hiperaldosteronismo, Cushing.');
    }

    if (disturbio.flags.acResp) {
      condutas.push('Avaliar necessidade de VNI (BiPAP) ou IOT se sinais de falência ventilatória (rebaixamento, FR > 35, fadiga).');
      condutas.push('Reverter causas tratáveis: Naloxona (opioides), Flumazenil (BZD com cautela).');
    }

    if (oxigenacao.pfRatio !== null && lte(oxigenacao.pfRatio, 200)) {
      condutas.push('P/F ≤ 200: ventilação protetora com VT 6 mL/kg (peso predito), Pplatô ≤ 30 cmH₂O, PEEP tabela ARDSnet.');
      condutas.push('Se P/F ≤ 150: considerar posição prona por ≥ 16h e bloqueio neuromuscular precoce (cisatracúrio).');
    }

    return condutas;
  }

  // ═══════════════════════ FUNÇÃO PRINCIPAL ══════════════════════════════════

  /**
   * Análise gasométrica completa — Regra dos 5 Passos
   *
   * @param {Object} dados Objeto com os parâmetros do paciente
   * @param {number} dados.ph         pH arterial (obrigatório, 6.5–8.0)
   * @param {number} dados.pco2       PaCO₂ em mmHg (obrigatório, 5–200)
   * @param {number} dados.hco3       HCO₃⁻ em mEq/L (obrigatório, 2–70)
   * @param {number} [dados.na]       Na⁺ sérico em mEq/L (opcional, 100–200)
   * @param {number} [dados.cl]       Cl⁻ sérico em mEq/L (opcional, 60–160)
   * @param {number} [dados.albumina] Albumina sérica em g/dL (opcional, 0.5–7.0)
   * @param {number} [dados.pao2]     PaO₂ em mmHg (opcional, 10–700)
   * @param {number} [dados.fio2]     FiO₂ em % (21–100) ou decimal (0.21–1.0)
   * @param {number} [dados.idade]    Idade em anos (opcional, para A-a gradient)
   * @param {number} [dados.altitude] Altitude em metros (opcional, default: nível do mar)
   * @param {number} [dados.lactato]  Lactato arterial em mmol/L (opcional)
   * @param {number} [dados.potassio] Potássio sérico em mEq/L (opcional)
   * @returns {Object} Resultado completo da análise gasométrica
   */
  /**
   * Cálculo determinístico isolado da Fórmula de Winter (Acidose Metabólica)
   * PaCO₂ esperada = 1,5 × HCO₃⁻ + 8 (±2)
   */
  function calcularWinter(hco3) {
    var h = validarNumero(hco3, 'HCO₃⁻', 2, 70, true);
    var base = 1.5 * h + 8;
    return {
      pco2Esperada: arred(base, 1),
      minimo: arred(base - 2, 1),
      maximo: arred(base + 2, 1),
      formula: 'Winter: PaCO₂ = 1,5 × HCO₃⁻ + 8 (±2)'
    };
  }

  function analisarGasometria(dados) {
    if (!dados || typeof dados !== 'object') {
      throw new Error('Parâmetros obrigatórios não fornecidos para análise gasométrica.');
    }

    // Normalização flexível de chaves (suporte a camelCase, maiúsculas e abreviações)
    var p_ph   = dados.ph !== undefined ? dados.ph : dados.pH;
    var p_pco2 = dados.pco2 !== undefined ? dados.pco2 : (dados.paCO2 !== undefined ? dados.paCO2 : dados.pCO2);
    var p_hco3 = dados.hco3 !== undefined ? dados.hco3 : (dados.HCO3 !== undefined ? dados.HCO3 : dados.bicarbonato);
    var p_na   = dados.na !== undefined ? dados.na : (dados.Na !== undefined ? dados.Na : dados.sodio);
    var p_cl   = dados.cl !== undefined ? dados.cl : (dados.Cl !== undefined ? dados.Cl : dados.cloro);
    var p_alb  = dados.albumina !== undefined ? dados.albumina : dados.alb;
    var p_pao2 = dados.pao2 !== undefined ? dados.pao2 : (dados.paO2 !== undefined ? dados.paO2 : dados.po2);
    var p_fio2 = dados.fio2 !== undefined ? dados.fio2 : dados.FiO2;
    var p_idade = dados.idade !== undefined ? dados.idade : dados.age;
    var p_alt   = dados.altitude;
    var p_lac   = dados.lactato !== undefined ? dados.lactato : dados.lac;
    var p_k     = dados.potassio !== undefined ? dados.potassio : (dados.k !== undefined ? dados.k : dados.K);

    // Validação de entradas
    var ph    = validarNumero(p_ph,   'pH',          6.0,  8.0,  true);
    var pco2  = validarNumero(p_pco2, 'PaCO₂ (mmHg)', 5,   200,  true);
    var hco3  = validarNumero(p_hco3, 'HCO₃⁻ (mEq/L)', 2,  70,   true);
    var na    = validarNumero(p_na,   'Na⁺ (mEq/L)', 100,  200,  false);
    var cl    = validarNumero(p_cl,   'Cl⁻ (mEq/L)', 60,   160,  false);
    var alb   = validarNumero(p_alb, 'Albumina (g/dL)', 0.5, 7.0, false);
    var pao2  = validarNumero(p_pao2, 'PaO₂ (mmHg)', 10,   700,  false);
    var fio2  = validarNumero(p_fio2, 'FiO₂',        0.21, 100,  false);
    var idade = validarNumero(p_idade, 'Idade (anos)', 0,   130,  false);
    var altitude = validarNumero(p_alt, 'Altitude (m)', 0, 9000, false);
    var lactato  = validarNumero(p_lac,  'Lactato (mmol/L)', 0, 40, false);
    var potassio = validarNumero(p_k, 'K⁺ (mEq/L)', 1.0, 12.0, false);

    var avisos = [];

    // Passo 0: Consistência Henderson-Hasselbalch
    var consistencia = verificarConsistencia(ph, pco2, hco3);
    if (consistencia.aviso) avisos.push(consistencia.aviso);

    // Passo 1: Identificar distúrbio primário
    var disturbio = identificarDisturbio(ph, pco2, hco3);

    // Passo 2: Avaliar compensação
    var compensacao = avaliarCompensacao(ph, pco2, hco3, disturbio.flags);

    // Passo 3: Calcular Ânion Gap
    var agResult = calcularAnionGap(na, cl, hco3, alb);
    if (!agResult.calculado && (na !== null || cl !== null)) {
      avisos.push('Ânion Gap não calculado: informar Na e Cl juntos.');
    }

    // Passo 4: Razão Delta
    var agRef = agResult.calculado ? agResult.agReferencia : null;
    var deltaResult = calcularDeltaRatio(agRef, hco3);

    // Passo 5: Oxigenação
    var oxigenacao = avaliarOxigenacao(pao2, fio2, pco2, idade, altitude);
    avisos = avisos.concat(oxigenacao.avisos);

    // Detecção de distúrbio triplo
    var triplo = detectarDisturbioTriplo(disturbio, compensacao, deltaResult);
    if (triplo.detectado) avisos.unshift(triplo.descricao);

    // Diagnósticos diferenciais
    var diferenciais = gerarDiferenciais(disturbio, agResult, deltaResult);

    // Condutas sugeridas
    var condutas = sugerirCondutas(disturbio, agResult, oxigenacao);

    // Alertas de extremos fisiológicos (pH < 6.80)
    if (lt(ph, 6.80)) {
      avisos.unshift('🚨 ACIDEMIA EXTREMA (pH < 6.80): Limite crítico de viabilidade fisiológica. Colapso cardiovascular iminente, perda do inotropismo cardíaco e vasoplegia refratária a catecolaminas. Risco iminente de PCR. Priorizar ressuscitação ventilatória agressiva e medidas imediatas de suporte.');
      condutas.unshift('Acidemia extrema (pH < 6.80): Monitorização invasiva contínua em UTI, suporte hemodinâmico avançado e consideração de bicarbonato de sódio IV de resgate.');
    }
    if (lte(hco3, 5)) {
      avisos.push('🚨 BICARBONATO EXTREMAMENTE CONSUMIDO (≤ 5 mEq/L): Acidose metabólica severa com esgotamento da capacidade tampão.');
    }

    // Alertas extras com dados complementares
    if (lactato !== null) {
      if (gt(lactato, 4.0)) {
        avisos.push('🔴 Lactato > 4 mmol/L: hiperlactatemia grave — excluir choque, hipóxia tecidual, sepse.');
        condutas.push('Lactato > 4: ressuscitação volêmica guiada + vasopressor se hipotensão refratária. Medir lactato seriado a cada 2-4h.');
      } else if (gt(lactato, 2.0)) {
        avisos.push('🟡 Lactato 2–4 mmol/L: hiperlactatemia leve a moderada.');
      }
    }

    if (potassio !== null) {
      if (lt(potassio, 3.0)) {
        avisos.push('⚠️ Hipocalemia (K⁺ < 3,0): corrigir ANTES de administrar NaHCO₃ (risco de arritmia fatal por shift intracelular).');
      } else if (gt(potassio, 8.0)) {
        avisos.push('🚨 HIPERCALEMIA EXTREMA (K⁺ > 8,0 mEq/L): Risco iminente de parada cardíaca em assistolia/FV. Gluconato de Cálcio 10% IV IMEDIATO para estabilização de membrana miocárdica e acionamento urgente de hemodiálise de emergência.');
        condutas.push('K⁺ > 8,0 mEq/L: Gluconato de Cálcio 10% 20 mL IV em 3 min imediatamente; solução polarizante e preparo de hemodiálise.');
      } else if (gt(potassio, 6.0)) {
        avisos.push('⚠️ Hipercalemia grave (K⁺ > 6,0): ECG urgente, Gluconato de Ca²⁺ IV, insulina+glicose, nebulização com salbutamol.');
      }
    }

    // Estado de prioridade
    var critico = lt(ph, 7.20) || gt(ph, 7.60) ||
                  (oxigenacao.pfRatio !== null && lte(oxigenacao.pfRatio, 100));
    var alterado = disturbio.subtipo !== 'normal';
    var estado = critico ? 'PRIORITARIO' : (alterado ? 'ATENCAO' : 'NORMAL');

    return {
      sucesso: true,
      estado: estado,

      // Passo 1
      disturbio: disturbio.descricao,
      subtipo: disturbio.subtipo,
      gravidade: disturbio.gravidade,

      // Passo 2
      compensacao: {
        formulaUsada: compensacao.formulaUsada,
        esperadoMin: compensacao.esperadoMin,
        esperadoMax: compensacao.esperadoMax,
        valorReal: compensacao.valorReal,
        parametroAvaliado: compensacao.parametroAvaliado,
        avaliacao: compensacao.avaliacao,
        disturbioAssociado: compensacao.disturbioAssociado
      },

      // Passo 3
      anionGap: agResult.calculado ? {
        calculado: true,
        ag: agResult.anionGap,
        anionGap: agResult.anionGap,
        agCorrigido: agResult.anionGapCorrigido,
        anionGapCorrigido: agResult.anionGapCorrigido,
        elevado: agResult.elevado,
        interpretacao: agResult.interpretacao
      } : null,

      // Passo 4
      deltaRatio: deltaResult.calculado ? {
        calculado: true,
        deltaAG: deltaResult.deltaAG,
        deltaHCO3: deltaResult.deltaHCO3,
        razao: deltaResult.razaoDelta,
        razaoDelta: deltaResult.razaoDelta,
        interpretacao: deltaResult.interpretacao,
        diagnosticosDiferenciais: deltaResult.diagnosticosDiferenciais
      } : null,

      // Passo 5
      oxigenacao: {
        pfRatio: oxigenacao.pfRatio,
        classificacaoPF: oxigenacao.classificacaoPF,
        gradienteAa: oxigenacao.gradienteAa,
        gradienteAaEsperado: oxigenacao.gradienteAaEsperado,
        gradienteAaElevado: oxigenacao.gradienteAaElevado,
        pao2Alveolar: oxigenacao.pao2Alveolar
      },

      // Distúrbio triplo
      disturbioTriplo: triplo.detectado ? triplo : null,

      // Henderson-Hasselbalch
      consistencia: consistencia,

      // Diagnósticos e condutas
      diferenciais: diferenciais,
      condutas: condutas,
      avisos: avisos,

      // Valores de entrada (para rastreabilidade)
      valoresEntrada: {
        ph: ph, pco2: pco2, hco3: hco3, na: na, cl: cl,
        albumina: alb, pao2: pao2, fio2: fio2, idade: idade,
        lactato: lactato, potassio: potassio
      }
    };
  }

  // ════════════════════════ FORMATAÇÃO TELEGRAM ══════════════════════════════

  function formatarTextoTelegram(resultado) {
    var linhas = [];

    // Cabeçalho
    linhas.push('🧪 <b>GASOMETRIA ARTERIAL — ANÁLISE DE 5 PASSOS</b>');
    linhas.push('');

    // Valores de entrada
    var v = resultado.valoresEntrada;
    linhas.push('📋 <b>DADOS:</b> pH ' + fmt(v.ph, 2) + ' | PaCO₂ ' + fmt(v.pco2, 0) +
      ' mmHg | HCO₃⁻ ' + fmt(v.hco3, 0) + ' mEq/L');
    if (v.na !== null) linhas.push('   Na⁺ ' + fmt(v.na, 0) + ' | Cl⁻ ' + fmt(v.cl, 0) +
      (v.albumina !== null ? ' | Alb ' + fmt(v.albumina, 1) + ' g/dL' : ''));
    if (v.pao2 !== null) linhas.push('   PaO₂ ' + fmt(v.pao2, 0) + ' mmHg | FiO₂ ' +
      fmt(v.fio2 > 1 ? v.fio2 : v.fio2 * 100, 0) + '%');
    if (v.lactato !== null) linhas.push('   Lactato ' + fmt(v.lactato, 1) + ' mmol/L');
    linhas.push('');

    // Passo 1: Distúrbio
    var emoji = resultado.estado === 'PRIORITARIO' ? '🔴' :
                resultado.estado === 'ATENCAO' ? '🟡' : '🟢';
    linhas.push(emoji + ' <b>PASSO 1 — DISTÚRBIO PRIMÁRIO:</b>');
    linhas.push('   ' + resultado.disturbio);
    if (resultado.gravidade !== 'LEVE_OU_NORMAL') {
      linhas.push('   Gravidade: <b>' + resultado.gravidade + '</b>');
    }
    linhas.push('');

    // Passo 2: Compensação
    var comp = resultado.compensacao;
    if (comp.formulaUsada) {
      linhas.push('📐 <b>PASSO 2 — COMPENSAÇÃO:</b>');
      linhas.push('   Fórmula: ' + comp.formulaUsada);
      linhas.push('   ' + comp.parametroAvaliado + ' esperado: ' +
        fmt(comp.esperadoMin, 1) + '–' + fmt(comp.esperadoMax, 1) + ' | Real: ' +
        fmt(comp.valorReal, 1));
      linhas.push('   → ' + comp.avaliacao);
      linhas.push('');
    }

    // Passo 3: Ânion Gap
    var ag = resultado.anionGap;
    if (ag) {
      linhas.push('🔬 <b>PASSO 3 — ÂNION GAP:</b>');
      linhas.push('   AG: ' + fmt(ag.ag, 1) + ' mEq/L' +
        (ag.agCorrigido !== null ? ' | AG corrigido: ' + fmt(ag.agCorrigido, 1) + ' mEq/L' : ''));
      linhas.push('   → ' + ag.interpretacao);
      linhas.push('');
    }

    // Passo 4: Delta Ratio
    var dr = resultado.deltaRatio;
    if (dr) {
      linhas.push('📊 <b>PASSO 4 — RAZÃO DELTA (Δ/Δ):</b>');
      if (dr.razao !== null) {
        linhas.push('   ΔAG: ' + fmt(dr.deltaAG, 1) + ' | ΔHCO₃⁻: ' + fmt(dr.deltaHCO3, 1) +
          ' | Razão: ' + fmt(dr.razao, 2));
      }
      linhas.push('   → ' + dr.interpretacao);
      if (dr.diagnosticosDiferenciais && dr.diagnosticosDiferenciais.length > 0) {
        linhas.push('   <i>Pensar em:</i>');
        for (var d = 0; d < dr.diagnosticosDiferenciais.length; d++) {
          linhas.push('     • ' + dr.diagnosticosDiferenciais[d]);
        }
      }
      linhas.push('');
    }

    // Passo 5: Oxigenação
    var ox = resultado.oxigenacao;
    if (ox.pfRatio !== null) {
      linhas.push('🫁 <b>PASSO 5 — OXIGENAÇÃO:</b>');
      linhas.push('   P/F: ' + ox.pfRatio + ' → ' + ox.classificacaoPF);
      if (ox.gradienteAa !== null) {
        linhas.push('   Gradiente A-a: ' + fmt(ox.gradienteAa, 1) + ' mmHg' +
          (ox.gradienteAaEsperado !== null ? ' (esperado ≤ ' + fmt(ox.gradienteAaEsperado, 1) + ')' : ''));
        linhas.push('   → Gradiente A-a ' + (ox.gradienteAaElevado ? 'ELEVADO' : 'Normal'));
      }
      linhas.push('');
    }

    // Distúrbio triplo
    if (resultado.disturbioTriplo) {
      linhas.push('⚠️ <b>DISTÚRBIO TRIPLO DETECTADO:</b>');
      for (var t = 0; t < resultado.disturbioTriplo.componentes.length; t++) {
        linhas.push('   ' + (t + 1) + '. ' + resultado.disturbioTriplo.componentes[t]);
      }
      linhas.push('');
    }

    // Diferenciais
    if (resultado.diferenciais.length > 0) {
      linhas.push('🔍 <b>DIAGNÓSTICOS DIFERENCIAIS:</b>');
      for (var i = 0; i < resultado.diferenciais.length; i++) {
        var cat = resultado.diferenciais[i];
        linhas.push('   <b>' + cat.categoria + '</b>');
        for (var j = 0; j < cat.causas.length; j++) {
          linhas.push('     • ' + cat.causas[j]);
        }
      }
      linhas.push('');
    }

    // Condutas
    if (resultado.condutas.length > 0) {
      linhas.push('💊 <b>CONDUTAS SUGERIDAS:</b>');
      for (var c = 0; c < resultado.condutas.length; c++) {
        linhas.push('   • ' + resultado.condutas[c]);
      }
      linhas.push('');
    }

    // Avisos
    if (resultado.avisos.length > 0) {
      linhas.push('📌 <b>AVISOS:</b>');
      for (var a = 0; a < resultado.avisos.length; a++) {
        linhas.push('   • ' + resultado.avisos[a]);
      }
    }

    return linhas.join('\n');
  }

  // ═════════════════════ PARSER E TECLADOS TELEGRAM ══════════════════════════

  /**
   * Extrai e valida parâmetros gasométricos a partir de texto livre ou comando do Telegram
   * @param {string} textoInput Texto fornecido pelo médico
   * @returns {Object} Resultado estruturado do parsing e validação
   */
  function extrairParametrosGasometria(textoInput) {
    if (!textoInput || typeof textoInput !== 'string') {
      return {
        sucesso: false,
        valido: false,
        vazio: true,
        incompleto: false,
        inversaoSuspeita: false,
        mensagemInversao: null,
        parametros: null,
        informados: [],
        ausentes: ['pH', 'pCO2', 'HCO3'],
        erro: 'Nenhum parâmetro fornecido.'
      };
    }

    var limpo = textoInput
      .replace(/^\/(?:gaso(?:metria)?|aniongap|gaso_calc)\b/i, '')
      .replace(/^(?:gasometria\s*(?:arterial)?|gaso|anion\s*gap)\s*[:=]?\s*/i, '')
      .trim();

    if (!limpo) {
      return {
        sucesso: false,
        valido: false,
        vazio: true,
        incompleto: false,
        inversaoSuspeita: false,
        mensagemInversao: null,
        parametros: null,
        informados: [],
        ausentes: ['pH', 'pCO2', 'HCO3'],
        erro: 'Texto vazio após remoção do comando.'
      };
    }

    function extrairNumero(re, t) {
      var m = t.match(re);
      if (!m) return null;
      var raw = m[1] !== undefined ? m[1] : m[0];
      var numStr = String(raw).replace(',', '.');
      var val = parseFloat(numStr);
      return Number.isFinite(val) ? val : null;
    }

    // 1. Extração por rótulos/chaves explícitas
    var g_ph = extrairNumero(/\bph\s*[:=]?\s*([0-9]+[.,]?[0-9]*)/i, limpo);
    var g_pco2 = extrairNumero(/\b(?:p?a?co2|pa\s*co2|co2)\s*[:=]?\s*([0-9]+[.,]?[0-9]*)/i, limpo);
    var g_hco3 = extrairNumero(/\b(?:hco3[-–]?|bicarb(?:onato)?|bic)\s*[:=]?\s*([0-9]+[.,]?[0-9]*)/i, limpo);
    var g_na = extrairNumero(/\b(?:na\+?|s[oó]dio|natremia)\s*[:=]?\s*([0-9]+[.,]?[0-9]*)/i, limpo);
    var g_cl = extrairNumero(/\b(?:cl[-–]?|cloro|cloremia)\s*[:=]?\s*([0-9]+[.,]?[0-9]*)/i, limpo);
    var g_alb = extrairNumero(/\b(?:alb(?:umina)?|albu)\s*[:=]?\s*([0-9]+[.,]?[0-9]*)/i, limpo);
    var g_pao2 = extrairNumero(/\b(?:p?a?o2|pa\s*o2|oxig[eê]nio)\s*[:=]?\s*([0-9]+[.,]?[0-9]*)/i, limpo);
    var g_fio2 = extrairNumero(/\b(?:fi\s*o2|fio2)\s*[:=]?\s*([0-9]+[.,]?[0-9]*)\s*%?/i, limpo);
    var g_lac = extrairNumero(/\b(?:lact(?:ato)?|[aá]cido\s+l[aá]tico)\s*[:=]?\s*([0-9]+[.,]?[0-9]*)/i, limpo);
    var g_k = extrairNumero(/\b(?:pot[aá]ssio|k\+?)\s*[:=]?\s*([0-9]+[.,]?[0-9]*)/i, limpo);
    var g_idade = extrairNumero(/\b(?:idade|anos)[:=]?\s*([0-9]+)|([0-9]+)\s*(?:anos|a\b)/i, limpo);

    // 2. Extração posicional inteligente se faltarem rótulos de pH, pCO2 ou HCO3
    if (g_ph === null || g_pco2 === null || g_hco3 === null) {
      var tokensNumericos = [];
      var regexNum = /([0-9]+(?:[.,][0-9]+)?)/g;
      var match;
      while ((match = regexNum.exec(limpo)) !== null) {
        tokensNumericos.push(parseFloat(match[1].replace(',', '.')));
      }

      if (tokensNumericos.length >= 3 && (g_ph === null && g_pco2 === null && g_hco3 === null)) {
        var t0 = tokensNumericos[0];
        var t1 = tokensNumericos[1];
        var t2 = tokensNumericos[2];

        // Ordem clássica beira-leito: [pH, pCO2, HCO3]
        if (t0 >= 6.0 && t0 <= 8.0 && t1 >= 5 && t1 <= 200 && t2 >= 2 && t2 <= 70) {
          g_ph = t0;
          g_pco2 = t1;
          g_hco3 = t2;

          if (tokensNumericos.length >= 4) {
            var t3 = tokensNumericos[3];
            if (t3 >= 100 && t3 <= 200 && g_na === null) {
              g_na = t3;
            } else if (t3 >= 10 && t3 <= 700 && g_pao2 === null) {
              g_pao2 = t3;
            }
          }
          if (tokensNumericos.length >= 5) {
            var t4 = tokensNumericos[4];
            if (t4 >= 60 && t4 <= 160 && g_cl === null) {
              g_cl = t4;
            } else if (t4 >= 0.21 && t4 <= 100 && g_fio2 === null) {
              g_fio2 = t4;
            }
          }
          if (tokensNumericos.length >= 6) {
            var t5 = tokensNumericos[5];
            if (t5 >= 0.5 && t5 <= 7.0 && g_alb === null) {
              g_alb = t5;
            }
          }
        }
      }
    }

    // 3. Detecção de inversão de digitação comum (ex: pH 25, pCO2 7.20)
    var inversaoSuspeita = false;
    var msgInversao = null;
    if (g_ph !== null && g_pco2 !== null) {
      if ((g_ph > 8.0 || g_ph < 6.0) && (g_pco2 >= 6.8 && g_pco2 <= 7.8)) {
        inversaoSuspeita = true;
        msgInversao = 'Valores aparentemente invertidos: pH informado como ' + g_ph + ' e pCO2 como ' + g_pco2 + '. Corrigindo para pH ' + g_pco2 + ' e pCO2 ' + g_ph + '.';
        var tmp = g_ph;
        g_ph = g_pco2;
        g_pco2 = tmp;
      }
    }

    // 4. Verificação de completude
    var informados = [];
    var ausentes = [];
    if (g_ph !== null) informados.push('pH ' + g_ph); else ausentes.push('pH');
    if (g_pco2 !== null) informados.push('pCO2 ' + g_pco2); else ausentes.push('pCO2');
    if (g_hco3 !== null) informados.push('HCO3 ' + g_hco3); else ausentes.push('HCO3');

    if (g_na !== null) informados.push('Na ' + g_na);
    if (g_cl !== null) informados.push('Cl ' + g_cl);
    if (g_alb !== null) informados.push('Alb ' + g_alb);
    if (g_pao2 !== null) informados.push('PaO2 ' + g_pao2);
    if (g_fio2 !== null) informados.push('FiO2 ' + g_fio2);
    if (g_lac !== null) informados.push('Lactato ' + g_lac);
    if (g_k !== null) informados.push('K ' + g_k);

    var incompleto = (g_ph === null || g_pco2 === null || g_hco3 === null);

    if (incompleto) {
      return {
        sucesso: false,
        valido: false,
        vazio: false,
        incompleto: true,
        inversaoSuspeita: inversaoSuspeita,
        mensagemInversao: msgInversao,
        informados: informados,
        ausentes: ausentes,
        parametros: {
          ph: g_ph,
          pco2: g_pco2,
          hco3: g_hco3,
          na: g_na,
          cl: g_cl,
          albumina: g_alb,
          pao2: g_pao2,
          fio2: g_fio2,
          lactato: g_lac,
          potassio: g_k,
          idade: g_idade
        },
        erro: 'Gasometria incompleta. Parâmetros obrigatórios ausentes: ' + ausentes.join(', ') + '.'
      };
    }

    // 5. Validação de faixas de viabilidade biológica
    if (g_ph < 6.0 || g_ph > 8.0) {
      return {
        sucesso: false,
        valido: false,
        vazio: false,
        incompleto: false,
        inversaoSuspeita: false,
        mensagemInversao: null,
        informados: informados,
        ausentes: [],
        parametros: null,
        erro: 'pH fora dos limites de sobrevivência humana viável (6.0 a 8.0): ' + g_ph
      };
    }
    if (g_pco2 < 5 || g_pco2 > 200) {
      return {
        sucesso: false,
        valido: false,
        vazio: false,
        incompleto: false,
        inversaoSuspeita: false,
        mensagemInversao: null,
        informados: informados,
        ausentes: [],
        parametros: null,
        erro: 'PaCO2 fora dos limites fisiológicos compatíveis (5 a 200 mmHg): ' + g_pco2
      };
    }
    if (g_hco3 < 2 || g_hco3 > 70) {
      return {
        sucesso: false,
        valido: false,
        vazio: false,
        incompleto: false,
        inversaoSuspeita: false,
        mensagemInversao: null,
        informados: informados,
        ausentes: [],
        parametros: null,
        erro: 'HCO3 fora dos limites fisiológicos compatíveis (2 a 70 mEq/L): ' + g_hco3
      };
    }

    return {
      sucesso: true,
      valido: true,
      vazio: false,
      incompleto: false,
      inversaoSuspeita: inversaoSuspeita,
      mensagemInversao: msgInversao,
      informados: informados,
      ausentes: [],
      parametros: {
        ph: g_ph,
        pco2: g_pco2,
        hco3: g_hco3,
        na: g_na,
        cl: g_cl,
        albumina: g_alb,
        pao2: g_pao2,
        fio2: g_fio2,
        lactato: g_lac,
        potassio: g_k,
        idade: g_idade
      },
      erro: null
    };
  }

  /**
   * Gera teclados inline interativos adaptados para o bot do Telegram
   */
  function obterTecladoInlineGasometria(modo, opcoes) {
    opcoes = opcoes || {};
    if (modo === 'inicial' || modo === 'ajuda' || modo === 'incompleto') {
      return {
        inline_keyboard: [
          [
            { text: "🚨 CAD (Winter)", callback_data: "ux:gaso:pre:cad" },
            { text: "🫁 DPOC (Acidose Resp)", callback_data: "ux:gaso:pre:dpoc" }
          ],
          [
            { text: "⚡ Sepse (Choque Lático)", callback_data: "ux:gaso:pre:sepse" },
            { text: "🤮 Vômitos (Alcalose Met)", callback_data: "ux:gaso:pre:vomitos" }
          ],
          [
            { text: "🌪️ Ansiedade/TEP (Alcalose)", callback_data: "ux:gaso:pre:alcaloseresp" },
            { text: "📐 Fórmula de Winter", callback_data: "ux:gaso:winter" }
          ],
          [
            { text: "🔙 Voltar ao Menu", callback_data: "ux:menu" },
            { text: "🏠 Início", callback_data: "ux:hub:inicio" }
          ]
        ]
      };
    }

    if (modo === 'winter') {
      return {
        inline_keyboard: [
          [
            { text: "HCO₃⁻ 8", callback_data: "ux:gaso:winter:calc:8" },
            { text: "HCO₃⁻ 10", callback_data: "ux:gaso:winter:calc:10" },
            { text: "HCO₃⁻ 12", callback_data: "ux:gaso:winter:calc:12" }
          ],
          [
            { text: "HCO₃⁻ 14", callback_data: "ux:gaso:winter:calc:14" },
            { text: "HCO₃⁻ 16", callback_data: "ux:gaso:winter:calc:16" },
            { text: "HCO₃⁻ 18", callback_data: "ux:gaso:winter:calc:18" }
          ],
          [
            { text: "🩸 Gasometria Completa", callback_data: "ux:iniciar:gaso" },
            { text: "🔙 Voltar", callback_data: "ux:hub:sala" }
          ]
        ]
      };
    }

    if (modo === 'resultado') {
      var linhas = [];
      var cacheKey = opcoes.cacheKey;
      var btnCopiar;
      if (cacheKey) {
        btnCopiar = { text: "📋 Copiar Laudo PEP", callback_data: "ux:copiar:" + cacheKey };
      } else {
        btnCopiar = { text: "🔄 Novo Cálculo", callback_data: "ux:iniciar:gaso" };
      }

      linhas.push([
        btnCopiar,
        { text: "🔄 Novo Cálculo", callback_data: "ux:iniciar:gaso" }
      ]);

      if (opcoes.temAcidoseMetabolica) {
        linhas.push([
          { text: "📐 Ver Compensação de Winter", callback_data: "ux:gaso:winter" }
        ]);
      }

      linhas.push([
        { text: "🚨 Sala Vermelha", callback_data: "ux:hub:sala" },
        { text: "🏠 Início", callback_data: "ux:hub:inicio" }
      ]);

      return { inline_keyboard: linhas };
    }

    return null;
  }

  /**
   * Retorna cenários clínicos clássicos predefinidos para agilidade beira-leito
   */
  function obterExemploGasometriaPredefinido(id) {
    var exemplos = {
      cad: {
        id: 'cad',
        titulo: 'Cetoacidose Diabética (CAD)',
        subtitulo: 'Acidose Metabólica com AG Elevado e Resposta de Winter Adequada',
        texto: 'pH 7.20, pCO2 23, HCO3 10, Na 140, Cl 105, Alb 4.0',
        parametros: { ph: 7.20, pco2: 23, hco3: 10, na: 140, cl: 105, albumina: 4.0 }
      },
      dpoc: {
        id: 'dpoc',
        titulo: 'DPOC Exacerbado / Retenção Crônica',
        subtitulo: 'Acidose Respiratória com Compensação Renal Crônica',
        texto: 'pH 7.32, pCO2 62, HCO3 31, PaO2 55, FiO2 24%',
        parametros: { ph: 7.32, pco2: 62, hco3: 31, pao2: 55, fio2: 24 }
      },
      sepse: {
        id: 'sepse',
        titulo: 'Choque Séptico / Hiperlactatemia',
        subtitulo: 'Acidose Lática Grave com Winter Adequado e Alerta de Choque',
        texto: 'pH 7.25, pCO2 28, HCO3 12, Na 138, Cl 102, Lactato 4.8',
        parametros: { ph: 7.25, pco2: 28, hco3: 12, na: 138, cl: 102, lactato: 4.8 }
      },
      vomitos: {
        id: 'vomitos',
        titulo: 'Vômitos Volumosos / Perdas Gástricas',
        subtitulo: 'Alcalose Metabólica Hipoclorêmica e Hipocalêmica por Perda de HCl',
        texto: 'pH 7.52, pCO2 48, HCO3 38, Na 137, Cl 88, K 2.8',
        parametros: { ph: 7.52, pco2: 48, hco3: 38, na: 137, cl: 88, potassio: 2.8 }
      },
      alcaloseresp: {
        id: 'alcaloseresp',
        titulo: 'Crise de Pânico / Hiperventilação / TEP',
        subtitulo: 'Alcalose Respiratória Aguda Pura',
        texto: 'pH 7.55, pCO2 24, HCO3 21, PaO2 95, FiO2 21%',
        parametros: { ph: 7.55, pco2: 24, hco3: 21, pao2: 95, fio2: 21 }
      }
    };
    return exemplos[id] || null;
  }

  // ════════════════════════ API PÚBLICA ══════════════════════════════════════

  var publico = {
    analisarGasometria: analisarGasometria,
    formatarTextoTelegram: formatarTextoTelegram,

    // Parser e Teclados Interativos Beira-Leito
    extrairParametrosGasometria: extrairParametrosGasometria,
    obterTecladoInlineGasometria: obterTecladoInlineGasometria,
    obterExemploGasometriaPredefinido: obterExemploGasometriaPredefinido,

    // Funções individuais expostas para testes unitários
    calcularWinter: calcularWinter,
    identificarDisturbio: identificarDisturbio,
    avaliarCompensacao: avaliarCompensacao,
    calcularAnionGap: calcularAnionGap,
    calcularDeltaRatio: calcularDeltaRatio,
    avaliarOxigenacao: avaliarOxigenacao,
    detectarDisturbioTriplo: detectarDisturbioTriplo,
    verificarConsistencia: verificarConsistencia,
    gerarDiferenciais: gerarDiferenciais,
    sugerirCondutas: sugerirCondutas
  };

  return publico;
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = GasometriaAcidoBaseService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_ginecologia_ambulatorial.js
// ==============================================================================

/**
 * ==============================================================================
 * MÓDULO 02-E: GINECOLOGIA AMBULATORIAL DE CONSULTÓRIO (SAÚDE DA MULHER)
 * ==============================================================================
 * Motor determinístico de alta fidelidade clínica e farmacológica para:
 *  - Rastreamento do Câncer de Colo Uterino (Diretrizes Brasileiras INCA/MS 2016+):
 *    faixa etária, periodicidade, laudos citopatológicos (ASC-US, LSIL, ASC-H,
 *    HSIL, AGC, Carcinoma), condutas na Atenção Básica e Colposcopia ("Ver e Tratar").
 *  - Sangramento Uterino Anormal (SUA - Classificação FIGO / PALM-COEIN):
 *    exclusão mandatória de gestação, estratificação de choque, hemostasia de
 *    urgência (Ácido Tranexâmico, ACO em doses altas, Progestagênios) e manejo crônico.
 *  - Critérios Médicos de Elegibilidade para Uso de Métodos Anticoncepcionais (OMS/MS):
 *    Categorias 1 a 4 com filtro rápido por comorbidades críticas (enxaqueca com aura,
 *    trombose prévia/ativa, HAS não controlada, tabagismo >=35a, pós-parto e lactação,
 *    câncer de mama, LES e diabetes com vasculopatia).
 *  - Síndromes Infecciosas Vulvovaginais (Leucorreias):
 *    Diagnóstico sindrômico e etiológico de Candidíase, Vaginose Bacteriana e
 *    Tricomoníase, critérios de Amsel, tratamentos de 1ª linha REMUME, alertas
 *    críticos na gestação (bloqueio de Fluconazol oral) e efeito dissulfiram.
 *
 * REFERÊNCIAS:
 *  - Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero (INCA/MS 2016).
 *  - FEBRASGO: Manual de Trato Genital Inferior; Manual de Anticoncepção; Tratado de Ginecologia.
 *  - Organização Mundial da Saúde (OMS): Medical Eligibility Criteria for Contraceptive Use (5th ed).
 *  - Federação Internacional de Ginecologia e Obstetrícia (FIGO): Classificação PALM-COEIN para SUA.
 *  - Ministério da Saúde: Protocolo Clínico e Diretrizes Terapêuticas (PCDT) para ISTs.
 * ==============================================================================
 */

var GinecologiaAmbulatorialService = (function() {
  'use strict';

  // ───────────────────────────────────────────────────────────────────────────
  // 1. RASTREAMENTO DO CÂNCER DO COLO UTERINO (INCA / MINISTÉRIO DA SAÚDE)
  // ───────────────────────────────────────────────────────────────────────────

  /**
   * Avalia a indicação de rastreio e conduta frente ao laudo citopatológico
   * de acordo com as Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero (INCA/MS).
   *
   * @param {Object} dados
   * @param {number} dados.idade
   * @param {string} dados.resultadoCitologia (ex: 'negativo', 'asc_us', 'lsil', 'asc_h', 'hsil', 'agc', 'carcinoma', 'insatisfatorio', 'rotina')
   * @param {number} [dados.examesAnterioresNegativos]
   * @param {boolean} [dados.imunossuprimida] (HIV+, imunossupressores, transplantadas)
   * @param {boolean} [dados.histerectomizadaTotal] (colo uterino totalmente ressecado por patologia benigna)
   * @param {boolean} [dados.gestante]
   * @param {boolean} [dados.ascUsOuLsilPrevio] (histórico de ASC-US ou LSIL persistente)
   */
  function avaliarRastreioColoUterino(dados) {
    dados = dados || {};
    var idade = Number(dados.idade);
    if (isNaN(idade) || idade < 0) idade = 30; // Idade padrão fértil se omitida

    var resultadoRaw = String(dados.resultadoCitologia || 'rotina').toLowerCase().trim();
    var examesNegativos = Number(dados.examesAnterioresNegativos || 0);
    var imunossuprimida = Boolean(dados.imunossuprimida);
    var histerectomizadaTotal = Boolean(dados.histerectomizadaTotal);
    var gestante = Boolean(dados.gestante);
    var lesaoPrevia = Boolean(dados.ascUsOuLsilPrevio);

    // Normalização do laudo citopatológico
    var citologia = 'ROTINA';
    if (resultadoRaw.indexOf('asc-h') >= 0 || resultadoRaw.indexOf('asch') >= 0 || resultadoRaw.indexOf('asc_h') >= 0) {
      citologia = 'ASC_H';
    } else if (resultadoRaw.indexOf('asc-us') >= 0 || resultadoRaw.indexOf('ascus') >= 0 || resultadoRaw.indexOf('asc_us') >= 0) {
      citologia = 'ASC_US';
    } else if (resultadoRaw.indexOf('hsil') >= 0 || resultadoRaw.indexOf('alto grau') >= 0 || resultadoRaw.indexOf('nic 2') >= 0 || resultadoRaw.indexOf('nic 3') >= 0) {
      citologia = 'HSIL';
    } else if (resultadoRaw.indexOf('lsil') >= 0 || resultadoRaw.indexOf('baixo grau') >= 0 || resultadoRaw.indexOf('nic 1') >= 0) {
      citologia = 'LSIL';
    } else if (resultadoRaw.indexOf('agc') >= 0 || resultadoRaw.indexOf('agus') >= 0 || resultadoRaw.indexOf('glandular') >= 0) {
      citologia = 'AGC';
    } else if (resultadoRaw.indexOf('carcinoma') >= 0 || resultadoRaw.indexOf('malign') >= 0 || resultadoRaw.indexOf('invasor') >= 0) {
      citologia = 'CARCINOMA_INVASOR';
    } else if (resultadoRaw.indexOf('insatisfat') >= 0 || resultadoRaw.indexOf('inadequada') >= 0) {
      citologia = 'INSATISFATORIO';
    } else if (resultadoRaw.indexOf('negat') >= 0 || resultadoRaw.indexOf('normal') >= 0 || resultadoRaw.indexOf('sem atipia') >= 0) {
      citologia = 'NEGATIVO';
    }

    var condutas = [];
    var alertas = [];
    var localAtendimento = 'ATENCAO_BASICA'; // 'ATENCAO_BASICA' ou 'COLPOSCOPIA_ESPECIALIZADA'
    var prazoRecomendado = '';
    var periodicidadeFutura = '';

    // CENÁRIO ESPECIAL: Histerectomizada Total por lesão benigna
    if (histerectomizadaTotal) {
      return {
        elegivelRastreio: false,
        idade: idade,
        citologia: citologia,
        classificacao: 'DISPENSADA_DO_RASTREAMENTO',
        localAtendimento: 'ATENCAO_BASICA',
        resumoConduta: 'Dispensada de rastreamento citopatológico de rotina.',
        condutas: [
          'Mulheres com histerectomia total (colo e corpo uterinos retirados) por patologias benignas e sem histórico prévio de lesão de alto grau (NIC II/III) não se beneficiam de rastreamento citopatológico de cúpula vaginal.',
          'Interromper a coleta de preventivo vaginal, salvo se queixa de sangramento ou histórico de NIC II, NIC III ou câncer ginecológico.'
        ],
        alertas: ['Se histerectomia subtotal (colo uterino preservado), o rastreamento deve seguir a rotina normal.'],
        diretrizReferencia: 'Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero (INCA/MS 2016)'
      };
    }

    // CENÁRIO ESPECIAL: Imunossuprimidas (HIV+, transplantadas, corticoterapia crônica)
    if (imunossuprimida) {
      alertas.push('⚠️ PROTOCOLO ESPECIAL DE IMUNOSSUPRESSÃO: Mulheres imunossuprimidas têm progressão acelerada e maior persistência de infecções oncogênicas por HPV.');
      if (citologia === 'NEGATIVO' || citologia === 'ROTINA') {
        localAtendimento = 'ATENCAO_BASICA';
        prazoRecomendado = 'Semestral no 1º ano; anual se negativos.';
        condutas.push('Iniciar rastreamento citopatológico logo após a sexarca (independentemente de ter 25 anos).');
        condutas.push('Periodicidade: Realizar exames a cada 6 meses no primeiro ano de acompanhamento.');
        condutas.push('Se ambos os exames semestrais forem normais, manter seguimento ANUAL enquanto durar a imunossupressão.');
        condutas.push('Se contagem de Linfócitos T CD4 < 200 céls/mm³, manter rastreamento semestral contínuo.');
      } else if (citologia === 'INSATISFATORIO') {
        prazoRecomendado = 'Repetir em 6 a 12 semanas.';
        condutas.push('Repetir a coleta citológica na Atenção Básica em 6 a 12 semanas.');
      } else {
        // Qualquer alteração citopatológica em imunossuprimida exige colposcopia imediata!
        localAtendimento = 'COLPOSCOPIA_ESPECIALIZADA';
        prazoRecomendado = 'Imediato (Colposcopia especializada)';
        condutas.push('Encaminhar IMEDIATAMENTE para Colposcopia especializada.');
        condutas.push('Em pacientes imunossuprimidas, qualquer atipia citológica (inclusive ASC-US ou LSIL) justifica colposcopia direta pelo alto risco de lesão precursora oculta.');
      }

      return {
        elegivelRastreio: true,
        idade: idade,
        imunossuprimida: true,
        citologia: citologia,
        classificacao: localAtendimento === 'COLPOSCOPIA_ESPECIALIZADA' ? 'COLPOSCOPIA_IMEDIATA_IMUNOSSUPRESSAO' : 'RASTREAMENTO_IMUNOSSUPRIMIDA',
        localAtendimento: localAtendimento,
        prazoRecomendado: prazoRecomendado,
        resumoConduta: localAtendimento === 'COLPOSCOPIA_ESPECIALIZADA' ? 'Encaminhar diretamente para Colposcopia por imunossupressão.' : 'Seguimento semestral/anual rigoroso.',
        condutas: condutas,
        alertas: alertas,
        diretrizReferencia: 'Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero (INCA/MS 2016)'
      };
    }

    // AVALIAÇÃO DETERMINÍSTICA POR FAIXA ETÁRIA (População Geral Não Imunossuprimida)
    if (idade < 25) {
      if (citologia === 'ROTINA' || citologia === 'NEGATIVO') {
        return {
          elegivelRastreio: false,
          idade: idade,
          citologia: citologia,
          classificacao: 'NAO_INDICADO_MENOR_25_ANOS',
          localAtendimento: 'ATENCAO_BASICA',
          resumoConduta: 'Rastreamento citopatológico NÃO é recomendado antes dos 25 anos.',
          condutas: [
            'As Diretrizes Brasileiras (INCA/MS) contraindicam o rastreamento citopatológico de rotina em mulheres com menos de 25 anos, mesmo com vida sexual ativa.',
            'Justificativa Clínica: Altíssima prevalência de infecção transitória por HPV nessa faixa etária, com resolução espontânea em mais de 90% dos casos e incidência de câncer invasor extremamente rara.',
            'Risco de Sobrerastreamento: Procedimentos excisionais desnecessários no colo uterino podem induzir estenose cervical, incompetência istmo-cervical e risco de parto prematuro futuro.',
            'Focar conduta em: Vacinação contra o HPV (esquema SUS dose única 9 a 14 anos), aconselhamento sobre sexo protegido (preservativos para prevenção de ISTs) e métodos contraceptivos.'
          ],
          alertas: ['Orientar a iniciar o rastreamento citológico formal de rotina ao completar 25 anos de idade.'],
          diretrizReferencia: 'Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero (INCA/MS 2016)'
        };
      } else if (citologia === 'ASC_US' || citologia === 'LSIL') {
        return {
          elegivelRastreio: true,
          idade: idade,
          citologia: citologia,
          classificacao: 'CONDUTA_EXPECTANTE_MENOR_25',
          localAtendimento: 'ATENCAO_BASICA',
          prazoRecomendado: 'Repetir aos 25 anos (ou em 3 anos)',
          resumoConduta: 'Conduta expectante e não intervencionista em menores de 25 anos.',
          condutas: [
            'Em mulheres com menos de 25 anos que apresentam ASC-US ou LSIL, a conduta recomendada pelo INCA/MS é EXPECTANTE.',
            'Não encaminhar para colposcopia imediata nem realizar biópsias excisionais precoces.',
            'Repetir a citologia oncótica aos 25 anos de idade (ou em intervalo de até 3 anos se idade muito próxima).'
          ],
          alertas: ['A taxa de clareamento viral espontâneo e regressão de LSIL/ASC-US supera 90% em adultas jovens.'],
          diretrizReferencia: 'Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero (INCA/MS 2016)'
        };
      }
      // Se for ASC-H, HSIL ou AGC em < 25 anos, segue para colposcopia abaixo.
    } else if (idade > 64) {
      if (examesNegativos >= 2 && citologia === 'ROTINA') {
        return {
          elegivelRastreio: false,
          idade: idade,
          citologia: citologia,
          classificacao: 'ENCERRAMENTO_RASTREAMENTO',
          localAtendimento: 'ATENCAO_BASICA',
          resumoConduta: 'Rastreamento pode ser encerrado (>= 65 anos com exames prévios normais).',
          condutas: [
            'Mulheres a partir de 65 anos que possuem histórico documentado de pelo menos 2 exames citopatológicos negativos consecutivos nos últimos 5 anos podem ter o rastreamento encerrado.',
            'A probabilidade de desenvolvimento de novas neoplasias cervicais de novo nessa faixa etária na ausência de lesões pregressas é clinicamente insignificante.'
          ],
          alertas: ['Se a mulher nunca realizou preventivo na vida ou não possui histórico, realizar 2 exames citológicos com intervalo de 1 ano; se ambos forem negativos, encerrar o rastreamento.'],
          diretrizReferencia: 'Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero (INCA/MS 2016)'
        };
      }
    }

    // CONDUTAS ESPECÍFICAS POR RESULTADO CITOPATOLÓGICO (>= 25 anos)
    switch (citologia) {
      case 'NEGATIVO':
      case 'ROTINA':
        localAtendimento = 'ATENCAO_BASICA';
        if (examesNegativos >= 2) {
          prazoRecomendado = 'Em 3 anos (Rastreamento Trienal)';
          periodicidadeFutura = 'A cada 3 anos até os 64 anos.';
          condutas.push('Seguimento de rotina trienal: Repetir a citologia em 3 anos na Atenção Básica.');
          condutas.push('Paciente possui >= 2 exames anuais consecutivos negativos, o que confere elevada segurança para intervalo trienal (Diretrizes INCA/MS).');
        } else {
          prazoRecomendado = 'Em 1 ano (Segundo exame consecutivo)';
          periodicidadeFutura = 'Após 2 exames anuais negativos consecutivos, o intervalo passa a ser a cada 3 anos.';
          condutas.push('Repetir citologia oncótica em 1 ano na Atenção Básica.');
          condutas.push('Conforme o protocolo do Ministério da Saúde, os 2 primeiros exames devem ser anuais consecutivos. Se ambos forem negativos, o intervalo passa a ser trienal.');
        }
        break;

      case 'ASC_US':
        // Células escamosas atípicas de significado indeterminado possivelmente não neoplásicas
        if (lesaoPrevia) {
          localAtendimento = 'COLPOSCOPIA_ESPECIALIZADA';
          prazoRecomendado = 'Colposcopia Imediata (ASC-US persistente)';
          condutas.push('Encaminhar para COLPOSCOPIA na Unidade Secundária / Especializada.');
          condutas.push('Indicação: Persistência de ASC-US em dois exames citopatológicos consecutivos.');
          alertas.push('Persistência de atipias celulares exige inspeção colposcópica com ácido acético e Teste de Schiller.');
        } else if (idade < 30) { // 25 a 29 anos
          localAtendimento = 'ATENCAO_BASICA';
          prazoRecomendado = 'Repetir citologia em 12 meses na UBS';
          condutas.push('Repetir o exame citopatológico em 12 MESES na Unidade Básica de Saúde.');
          condutas.push('Em mulheres de 25 a 29 anos com ASC-US, a taxa de regressão espontânea é alta, recomendando-se repetição em 1 ano.');
          condutas.push('Se o exame de repetição persistir com ASC-US ou pior (LSIL/HSIL/ASC-H), encaminhar imediatamente para colposcopia.');
        } else { // >= 30 anos
          localAtendimento = 'ATENCAO_BASICA';
          prazoRecomendado = 'Repetir citologia em 6 meses na UBS';
          condutas.push('Repetir o exame citopatológico em 6 MESES na Unidade Básica de Saúde.');
          condutas.push('Em mulheres com 30 anos ou mais com ASC-US, a probabilidade de infecção persistente por HPV é maior, justificando intervalo mais curto de repetição.');
          condutas.push('Se o exame de repetição persistir com ASC-US ou pior, encaminhar imediatamente para Colposcopia.');
        }
        break;

      case 'LSIL':
        // Lesão intraepitelial escamosa de baixo grau (NIC I / efeito citopático do HPV)
        if (lesaoPrevia) {
          localAtendimento = 'COLPOSCOPIA_ESPECIALIZADA';
          prazoRecomendado = 'Colposcopia Imediata (LSIL persistente)';
          condutas.push('Encaminhar para COLPOSCOPIA especializada.');
          condutas.push('Indicação: Persistência de lesão de baixo grau (LSIL) em 2 exames consecutivos.');
        } else {
          localAtendimento = 'ATENCAO_BASICA';
          prazoRecomendado = 'Repetir citologia em 6 meses na UBS';
          condutas.push('Repetir o exame citopatológico em 6 MESES na Unidade Básica de Saúde.');
          condutas.push('Em mulheres com 25 anos ou mais, a conduta inicial para LSIL é repetir a citologia em 6 meses na Atenção Primária.');
          condutas.push('Se o segundo exame for negativo: repetir novo exame em 6 meses. Se negativo novamente, paciente retorna à rotina trienal.');
          condutas.push('Se o segundo exame persistir com LSIL ou apresentar lesão mais grave, encaminhar obrigatoriamente para Colposcopia.');
        }
        break;

      case 'ASC_H':
        // Células escamosas atípicas não sendo possível afastar lesão de alto grau
        localAtendimento = 'COLPOSCOPIA_ESPECIALIZADA';
        prazoRecomendado = 'Colposcopia IMEDIATA';
        condutas.push('Encaminhar IMEDIATAMENTE para COLPOSCOPIA na Atenção Especializada.');
        condutas.push('Conduta formal: ASC-H possui alto valor preditivo para NIC II ou NIC III subjacente, não devendo aguardar repetição citológica.');
        alertas.push('🚨 ASC-H exige avaliação colposcópica minuciosa do canal endocervical e biópsia dirigida de áreas acetobrancas.');
        break;

      case 'HSIL':
        // Lesão intraepitelial escamosa de alto grau (NIC II, NIC III, Carcinoma in situ)
        localAtendimento = 'COLPOSCOPIA_ESPECIALIZADA';
        prazoRecomendado = 'Colposcopia IMEDIATA (Elegível para Ver e Tratar)';
        condutas.push('Encaminhar IMEDIATAMENTE para COLPOSCOPIA especializada com prioridade.');
        condutas.push('Estratégia "Ver e Tratar" (EZT / CAF / LEEP): Mulheres com 25 anos ou mais com laudo de HSIL cuja colposcopia confirme lesão de alto grau e apresente Zona de Transformação (ZT) tipos 1 ou 2 totalmente visíveis são elegíveis para Excisão Tipo 1 ou 2 no mesmo ato ambulatorial.');
        condutas.push('Se suspeita de microinvasão, ZT tipo 3 (não totalmente visível) ou discordância colpo-citológica: Realizar biópsia dirigida prévia ou conização clássica.');
        alertas.push('🚨 Alto risco de malignização se não conduzido oportunamente. Monitorar comparecimento à consulta de patologia cervical.');
        break;

      case 'AGC':
        // Células glandulares atípicas (antigo AGUS)
        localAtendimento = 'COLPOSCOPIA_ESPECIALIZADA';
        prazoRecomendado = 'Colposcopia IMEDIATA + Avaliação Endocervical e Endometrial';
        condutas.push('Encaminhar IMEDIATAMENTE para COLPOSCOPIA com avaliação mandatória do canal endocervical (escovado endocervical ou curetagem endocervical).');
        if (idade >= 35 || dados.sangramentoUterinoAnormal) {
          condutas.push('Investigação Endometrial Mandatória: Devido à idade >= 35 anos ou presença de SUA, solicitar Ultrassonografia Transvaginal e Biópsia Endometrial (Pipelle de Cornier ou Histeroscopia com biópsia) para investigar adenocarcinoma de endométrio.');
        } else {
          condutas.push('Se persistência ou fatores de risco adicionais, adicionar avaliação endometrial.');
        }
        alertas.push('⚠️ AGC associa-se a lesões glandulares de canal e endométrio que não são visualizadas facilmente na ectocérvice.');
        break;

      case 'CARCINOMA_INVASOR':
        localAtendimento = 'COLPOSCOPIA_ESPECIALIZADA';
        prazoRecomendado = 'Urgência Oncológica Imediata';
        condutas.push('Encaminhamento imediato com prioridade oncológica máxima para centro de referência de ginecologia oncológica.');
        condutas.push('Biópsia com estadiamento clínico e imagem pélvica de estadiamento.');
        alertas.push('⛔ URGÊNCIA ONCOLÓGICA: Notificar coordenação de regulação (SISREG / CROSS) sob código de suspeita de neoplasia maligna.');
        break;

      case 'INSATISFATORIO':
        localAtendimento = 'ATENCAO_BASICA';
        prazoRecomendado = 'Repetir em 6 a 12 semanas na UBS';
        condutas.push('Repetir a coleta citológica na Unidade Básica de Saúde no prazo de 6 a 12 semanas.');
        condutas.push('Orientações prévias à nova coleta: Abstinência sexual por 48 horas, não usar duchas vaginais ou cremes ginecológicos nas 48h anteriores, e coletar fora do período menstrual.');
        condutas.push('Garantir representação adequada tanto do componente ectocervical (espátula de Ayre) quanto endocervical (escova de canal).');
        break;

      default:
        localAtendimento = 'ATENCAO_BASICA';
        condutas.push('Avaliar histórico citológico prévio e manter rastreamento de rotina na UBS.');
        break;
    }

    if (gestante) {
      alertas.push('🤰 GESTAÇÃO: O rastreamento citopatológico pode ser realizado com segurança na gestante até o final do 3º trimestre (usar espátula de Ayre normalmente; evitar introdução profunda da escova endocervical no orifício interno). Procedimentos excisionais (LEEP/CAF) são contraindicados durante a gestação exceto suspeita de câncer invasor.');
    }

    return {
      elegivelRastreio: true,
      idade: idade,
      citologia: citologia,
      classificacao: 'CONDUTA_' + citologia,
      localAtendimento: localAtendimento,
      prazoRecomendado: prazoRecomendado,
      periodicidadeFutura: periodicidadeFutura,
      resumoConduta: condutas[0] || 'Seguimento ginecológico.',
      condutas: condutas,
      alertas: alertas,
      diretrizReferencia: 'Diretrizes Brasileiras para o Rastreamento do Câncer do Colo do Útero (INCA/MS 2016)'
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 2. SANGRAMENTO UTERINO ANORMAL (SUA - FIGO / PALM-COEIN)
  // ───────────────────────────────────────────────────────────────────────────

  /**
   * Avaliação diagnóstica e terapêutica determinística para Sangramento Uterino Anormal.
   * Classificação PALM-COEIN da FIGO e condutas hemostáticas de urgência vs ambulatorial.
   *
   * @param {Object} dados
   * @param {number} dados.idade
   * @param {string} [dados.betaHcg] ('positivo', 'negativo', 'nao_realizado')
   * @param {number} [dados.pas]
   * @param {number} [dados.fc]
   * @param {number} [dados.duracaoDias]
   * @param {string} [dados.intensidade] ('leve', 'moderada', 'grave_aguda')
   * @param {boolean} [dados.posMenopausa]
   * @param {number} [dados.espessuraEndometrioMm]
   * @param {boolean} [dados.contraindicacaoEstrogenio]
   * @param {Array<string>} [dados.etiologiasSuspeitas] (ex: ['polipo', 'mioma', 'adenomiose', 'coagulopatia', 'ovulatoria', 'endometrial', 'iatrogenica'])
   */
  function avaliarSangramentoUterinoAnormal(dados) {
    dados = dados || {};
    var idade = Number(dados.idade);
    if (isNaN(idade) || idade < 0) idade = 32;

    var betaHcg = String(dados.betaHcg || 'nao_realizado').toLowerCase().trim();
    var pas = Number(dados.pas || 120);
    var fc = Number(dados.fc || 78);
    var duracaoDias = Number(dados.duracaoDias || 5);
    var intensidade = String(dados.intensidade || 'moderada').toLowerCase();
    var posMenopausa = Boolean(dados.posMenopausa || idade >= 55);
    var espessuraEndometrio = dados.espessuraEndometrioMm !== undefined ? Number(dados.espessuraEndometrioMm) : null;
    var contraindicacaoEstrogenio = Boolean(dados.contraindicacaoEstrogenio);

    var etiologias = Array.isArray(dados.etiologiasSuspeitas) ? dados.etiologiasSuspeitas : [];
    var etiologiasStr = etiologias.join(' ').toLowerCase();

    var alertas = [];
    var condutasEmergencia = [];
    var condutasAmbulatoriais = [];
    var prescricoesSugeridas = [];
    var mnemocinoPalmCoein = [];

    // 1. Verificação de Choque Hemodinâmico
    var indiceChoque = pas > 0 ? (fc / pas) : 0;
    var choqueInstavel = pas < 90 || fc > 120 || indiceChoque >= 1.0;

    if (choqueInstavel) {
      alertas.push('🚨 INSTABILIDADE HEMODINÂMICA / CHOQUE HIPOVOLÊMICO (Índice de Choque = ' + indiceChoque.toFixed(2) + '): Encaminhar imediatamente para sala de emergência / centro cirúrgico!');
      condutasEmergencia.push('Obter 2 acessos venosos periféricos calibrosos (abocath 14G ou 16G).');
      condutasEmergencia.push('Ressuscitação volêmica imediata com Ringer Lactato ou SF 0,9% 1000 mL aquecido em bolus.');
      condutasEmergencia.push('Tipagem sanguínea, Prova Cruzada e reserva de concentrado de hemácias (acionar protocolo de transfusão maciça se refratário).');
      condutasEmergencia.push('Tamponamento uterino mecânico de urgência: Inserção intrauterina de sonda Foley nº 18 a 24 insuflada com 30 a 50 mL de solução fisiológica.');
      condutasEmergencia.push('Avaliação cirúrgica imediata para curetagem uterina hemostática de urgência ou histerectomia se sangramento incoercível.');
    }

    // 2. Exclusão Mandatória de Gestação em Mulheres em Idade Fértil
    var gravidezDetectada = false;
    if (idade >= 10 && idade <= 55 && !posMenopausa) {
      if (betaHcg === 'positivo') {
        gravidezDetectada = true;
        alertas.push('🤰 TESTE DE GRAVIDEZ POSITIVO: Sangramento na vigência de gestação NÃO é classificado como SUA ginecológico! Investigar ameaça de abortamento, gravidez ectópica ou mola hidatiforme.');
        return {
          gravidez: true,
          classificacao: 'SANGRAMENTO_PRIMEIRO_TRIMESTRE_OBSTETRICO',
          resumo: 'Gravidez confirmada. Redirecionar imediatamente para investigação obstétrica.',
          condutasEmergencia: [
            'Solicitar Ultrassonografia Transvaginal urgente para avaliar localização do saco gestacional e viabilidade fetal.',
            'Afastar Gravidez Ectópica (dor anexial, abdome agudo hemorrágico) e Ameaça de Abortamento.',
            'Se sangramento intenso ou dor pélvica aguda, encaminhar ao Pronto Atendimento Obstétrico.'
          ],
          alertas: alertas
        };
      } else if (betaHcg === 'nao_realizado') {
        alertas.push('⚠️ MANDATÓRIO: Realizar teste imunológico de gravidez (Beta-hCG) em toda mulher em idade fértil com queixa de SUA antes de qualquer conduta hormonal.');
        condutasEmergencia.push('Solicitar Beta-hCG quantitativo ou Teste Rápido de Gravidez na urina imediatamente.');
      }
    }

    // 3. Avaliação de Risco na Pós-Menopausa (Câncer de Endométrio)
    if (posMenopausa) {
      alertas.push('🚨 SANGRAMENTO NA PÓS-MENOPAUSA: Investigação obrigatória para afastar Carcinoma Endometrial (Câncer de Endométrio).');
      condutasAmbulatoriais.push('Solicitar Ultrassonografia Transvaginal com doppler para mensurar espessura da linha endometrial.');
      if (espessuraEndometrio !== null) {
        if (espessuraEndometrio > 4.0) {
          alertas.push('⛔ ENDOMÉTRIO ESPESSADO (> 4 mm na pós-menopausa sem TH): Indicação formal de biópsia endometrial!');
          condutasAmbulatoriais.push('Realizar Biópsia Endometrial ambulatorial (Cureta de Pipelle de Cornier) ou Histeroscopia com biópsia dirigida.');
        } else {
          condutasAmbulatoriais.push('Espessura endometrial <= 4 mm: Baixa probabilidade de câncer; etiologia mais provável é Atrofia Endometrial. Avaliar estrogênio tópico vaginal se atrofia urogenital associada.');
        }
      } else {
        condutasAmbulatoriais.push('Ponto de corte de segurança: Se eco endometrial > 4 mm (sem terapia hormonal) ou > 8 mm (em uso de terapia hormonal), indicar biópsia endometrial mandatória.');
      }
    }

    // 4. Mnemônico PALM-COEIN (FIGO 2011/2018)
    // Causas Estruturais (PALM)
    mnemocinoPalmCoein.push({ sigla: 'P', nome: 'Pólipo', presente: etiologiasStr.indexOf('polip') >= 0, tipo: 'Estrutural (Imagem/Histologia)' });
    mnemocinoPalmCoein.push({ sigla: 'A', nome: 'Adenomiose', presente: etiologiasStr.indexOf('adenom') >= 0, tipo: 'Estrutural (Imagem/Histologia)' });
    mnemocinoPalmCoein.push({ sigla: 'L', nome: 'Leiomioma', presente: etiologiasStr.indexOf('miom') >= 0, tipo: 'Estrutural (L-SM submucoso vs L-O outros)' });
    mnemocinoPalmCoein.push({ sigla: 'M', nome: 'Malignidade/Hiperplasia', presente: posMenopausa || etiologiasStr.indexOf('malign') >= 0 || etiologiasStr.indexOf('hiperplas') >= 0, tipo: 'Estrutural (Biópsia)' });
    // Causas Não Estruturais (COEIN)
    mnemocinoPalmCoein.push({ sigla: 'C', nome: 'Coagulopatia', presente: etiologiasStr.indexOf('coagul') >= 0 || etiologiasStr.indexOf('vwd') >= 0, tipo: 'Não Estrutural (Laboratório)' });
    mnemocinoPalmCoein.push({ sigla: 'O', nome: 'Disfunção Ovulatória', presente: etiologiasStr.indexOf('ovulat') >= 0 || etiologiasStr.indexOf('sop') >= 0, tipo: 'Não Estrutural (Ciclos irregulares)' });
    mnemocinoPalmCoein.push({ sigla: 'E', nome: 'Endometrial', presente: etiologiasStr.indexOf('endometr') >= 0 && etiologiasStr.indexOf('adenom') < 0, tipo: 'Não Estrutural (Inflamação/Hemostasia)' });
    mnemocinoPalmCoein.push({ sigla: 'I', nome: 'Iatrogênica', presente: etiologiasStr.indexOf('iatrog') >= 0 || etiologiasStr.indexOf('diu') >= 0 || etiologiasStr.indexOf('anticoag') >= 0, tipo: 'Não Estrutural (Fármacos/DIU)' });
    mnemocinoPalmCoein.push({ sigla: 'N', nome: 'Não classificada', presente: false, tipo: 'Não Estrutural (Malformação AV, etc.)' });

    // 5. Farmacoterapia Hemostática de Urgência (SUA Agudo Intenso / Hemorragia)
    var ehAgudoIntenso = intensidade === 'grave_aguda' || intensidade === 'intenso' || duracaoDias > 10;
    if (ehAgudoIntenso && !posMenopausa) {
      // 1ª Linha Não Hormonal: Ácido Tranexâmico
      prescricoesSugeridas.push({
        farmaco: 'Ácido Tranexâmico 500 mg',
        posologia: 'Tomar 2 comprimidos (1000 mg) por via oral de 8 em 8 horas durante o sangramento ativo intenso (por até 4 a 5 dias).',
        justificativa: 'Antifibrinolítico potente. Inibe o plasminogênio e estabiliza a fibrina endometrial, reduzindo a perda sanguínea em 40% a 50% sem risco hormonal.',
        linha: '1ª Linha Hemostática Não Hormonal'
      });

      // 2ª Linha Hormonal de Urgência: Conforme elegibilidade
      if (!contraindicacaoEstrogenio) {
        prescricoesSugeridas.push({
          farmaco: 'Anticoncepcional Oral Combinado Monofásico (Etinilestradiol 30mcg + Levonorgestrel 0,15mg)',
          posologia: 'Regime regressivo rápido: 1 comprimido VO a cada 8 horas por 3 a 4 dias (até hemostasia); em seguida, 1 cp a cada 12 horas por 3 dias; em seguida, 1 cp ao dia completando 21 dias.',
          justificativa: 'Promove hemostasia endometrial acelerada induzindo decidualização rápida e proliferação do estroma endometrial.',
          linha: 'Hemostasia Hormonal Combinada de Ataque'
        });
      } else {
        prescricoesSugeridas.push({
          farmaco: 'Acetato de Medroxiprogesterona 10 mg',
          posologia: 'Tomar 1 a 2 comprimidos (10 a 20 mg) por via oral de 8 em 8 horas até cessar o sangramento; após a hemostasia, reduzir para 10 mg ao dia por 14 a 21 dias.',
          justificativa: 'Esquema de progestagênio isolado para pacientes com contraindicação a estrogênios (trombofilia, tabagismo >35a, HAS grave).',
          linha: 'Hemostasia Hormonal com Progestagênio Isolado'
        });
      }
    }

    // 6. Terapia de Manutenção a Longo Prazo / SUA Crônico
    if (!posMenopausa) {
      condutasAmbulatoriais.push('1ª Linha Terapêutica de Manutenção: DIU liberador de Levonorgestrel (Mirena/Kyleena) — reduz o volume menstrual em mais de 85% a 90% em 3 meses.');
      condutasAmbulatoriais.push('Alternativas de 2ª Linha: Progestagênio contínuo (Desogestrel 75mcg/dia ou Medroxiprogesterona injetável trimestral) ou ACO de uso contínuo.');
      condutasAmbulatoriais.push('Anti-inflamatórios Não Esteroidais (AINEs): Ibuprofeno 600mg VO 8/8h ou Ácido Mefenâmico 500mg VO 8/8h durante os dias de menstruação (reduzem as prostaglandinas endometriais e o fluxo em até 30%).');
      condutasAmbulatoriais.push('Suplementação de Ferro: Se hemoglobina < 12 g/dL ou ferritina < 30 ng/mL, prescrever Sulfato Ferroso 200mg (40mg de Fe elementar) VO 1 a 2x ao dia com vitamina C longe das refeições.');
    }

    // Exames complementares de rastreio
    condutasAmbulatoriais.push('Exames Laboratoriais Essenciais: Hemograma completo com plaquetas, Ferritina sérica, TSH (afastar hipotireoidismo), Coagulograma (TP/TTPA), e Ultrassonografia Pélvica/Transvaginal.');

    return {
      idade: idade,
      posMenopausa: posMenopausa,
      intensidade: intensidade,
      choqueInstavel: choqueInstavel,
      indiceChoque: Number(indiceChoque.toFixed(2)),
      mnemonicoPalmCoein: mnemocinoPalmCoein,
      prescricoesSugeridas: prescricoesSugeridas,
      condutasEmergencia: condutasEmergencia,
      condutasAmbulatoriais: condutasAmbulatoriais,
      alertas: alertas,
      diretrizReferencia: 'Classificação FIGO (PALM-COEIN 2018) & Manuais FEBRASGO de Sangramento Uterino Anormal'
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 3. CRITÉRIOS DE ELEGIBILIDADE DE ANTICONCEPÇÃO DA OMS (CATEGORIAS 1 A 4)
  // ───────────────────────────────────────────────────────────────────────────

  /**
   * Avalia determinística e rigorosamente a segurança de cada método contraceptivo
   * segundo os Critérios Médicos de Elegibilidade da Organização Mundial da Saúde (OMS / CDC / FEBRASGO).
   *
   * @param {Object} dados
   * @param {number} dados.idade
   * @param {boolean} [dados.tabagismo]
   * @param {number} [dados.cigarrosDia]
   * @param {string} [dados.enxaqueca] ('nenhuma', 'sem_aura', 'com_aura')
   * @param {string} [dados.has] ('normotensa', 'controlada', 'grave_descontrolada') ou pas/pad
   * @param {number} [dados.pas]
   * @param {number} [dados.pad]
   * @param {boolean} [dados.historicoTev] (TVP ou TEP prévia ou atual)
   * @param {boolean} [dados.trombofilia] (mutação Fator V Leiden, SAF, etc.)
   * @param {string} [dados.cancerMama] ('nenhum', 'passado_5anos', 'atual')
   * @param {boolean} [dados.lactacao]
   * @param {number} [dados.semanasPosParto]
   * @param {string} [dados.diabetes] ('nao', 'sem_vasculopatia', 'com_vasculopatia_ou_mais_20anos')
   * @param {string} [dados.lupusSaf] ('nao', 'positivo', 'desconhecido')
   */
  function avaliarCriteriosElegibilidadeContracepcao(dados) {
    dados = dados || {};
    var idade = Number(dados.idade);
    if (isNaN(idade) || idade < 0) idade = 28;

    var tabagismo = Boolean(dados.tabagismo);
    var cigarrosDia = Number(dados.cigarrosDia || 0);
    if (cigarrosDia > 0) tabagismo = true;

    var enxaqueca = String(dados.enxaqueca || 'nenhuma').toLowerCase().trim();
    var hasStatus = String(dados.has || 'normotensa').toLowerCase().trim();
    var pas = Number(dados.pas || 120);
    var pad = Number(dados.pad || 80);
    if (pas >= 160 || pad >= 100) hasStatus = 'grave_descontrolada';
    else if (pas >= 140 || pad >= 90) hasStatus = 'controlada';

    var tev = Boolean(dados.historicoTev);
    var trombofilia = Boolean(dados.trombofilia);
    var cancerMama = String(dados.cancerMama || 'nenhum').toLowerCase().trim();
    var lactacao = Boolean(dados.lactacao);
    var semanasPosParto = dados.semanasPosParto !== undefined ? Number(dados.semanasPosParto) : (lactacao ? 4 : 52);
    var diabetes = String(dados.diabetes || 'nao').toLowerCase().trim();
    var lupus = String(dados.lupusSaf || 'nao').toLowerCase().trim();

    // Métodos a avaliar:
    // AHC: Anticoncepcionais Hormonais Combinados (pílula, injetável mensal, adesivo, anel)
    // POP: Progestagênios Orais Isolados (Desogestrel, Levonorgestrel minipílula)
    // AMPD: Injetável Trimestral (Acetato de Medroxiprogesterona de depósito)
    // IMPLANTE: Implante Subdérmico de Etonogestrel
    // DIU_CU: DIU de Cobre
    // DIU_LNG: DIU Liberador de Levonorgestrel (Mirena/Kyleena)

    var metodos = {
      AHC: { nome: 'Hormonais Combinados (Pílula, Adesivo, Anel, Injetável Mensal)', cat: 1, motivos: [] },
      POP: { nome: 'Progestagênio Oral Isolado (Minipílula / Desogestrel)', cat: 1, motivos: [] },
      AMPD: { nome: 'Injetável Trimestral (Acetato de Medroxiprogesterona)', cat: 1, motivos: [] },
      IMPLANTE: { nome: 'Implante Subdérmico de Etonogestrel', cat: 1, motivos: [] },
      DIU_CU: { nome: 'DIU de Cobre (Não hormonal)', cat: 1, motivos: [] },
      DIU_LNG: { nome: 'DIU de Levonorgestrel (Mirena / Kyleena)', cat: 1, motivos: [] }
    };

    function atualizarCat(metodoId, novaCat, motivo) {
      if (novaCat > metodos[metodoId].cat) {
        metodos[metodoId].cat = novaCat;
      }
      metodos[metodoId].motivos.push({ cat: novaCat, motivo: motivo });
    }

    // 1. Enxaqueca
    if (enxaqueca.indexOf('com_aura') >= 0 || enxaqueca.indexOf('aura') >= 0) {
      atualizarCat('AHC', 4, '⛔ ENXAQUECA COM AURA: Categoria 4 (Contraindicação absoluta). Risco altamente elevado de Acidente Vascular Cerebral Isquêmico (AVC).');
      atualizarCat('POP', 2, 'Enxaqueca com aura: Categoria 2 (Vantagens superam riscos teóricos).');
      atualizarCat('AMPD', 2, 'Enxaqueca com aura: Categoria 2.');
      atualizarCat('IMPLANTE', 2, 'Enxaqueca com aura: Categoria 2.');
      atualizarCat('DIU_LNG', 2, 'Enxaqueca com aura: Categoria 2.');
      atualizarCat('DIU_CU', 1, 'DIU de Cobre: Categoria 1 (Uso irrestrito, método não hormonal).');
    } else if (enxaqueca.indexOf('sem_aura') >= 0) {
      if (idade >= 35) {
        atualizarCat('AHC', 3, 'Enxaqueca sem aura em mulher >= 35 anos: Categoria 3 (Riscos superam benefícios).');
      } else {
        atualizarCat('AHC', 2, 'Enxaqueca sem aura em mulher < 35 anos: Categoria 2.');
      }
    }

    // 2. Trombose Venosa Profunda / TEP ou Trombofilia Conhecida
    if (tev || trombofilia) {
      var motivoTev = tev ? 'Histórico pessoal de TVP/TEP' : 'Trombofilia trombogênica conhecida';
      atualizarCat('AHC', 4, '⛔ ' + motivoTev + ': Categoria 4 (Contraindicação absoluta). O componente estrogênico eleva a síntese hepática de fatores de coagulação e risco de recorrência fatal.');
      atualizarCat('AMPD', 2, motivoTev + ': Categoria 2.');
      atualizarCat('POP', 2, motivoTev + ': Categoria 2.');
      atualizarCat('IMPLANTE', 2, motivoTev + ': Categoria 2.');
      atualizarCat('DIU_LNG', 2, motivoTev + ': Categoria 2.');
      atualizarCat('DIU_CU', 1, motivoTev + ': Categoria 1 (Uso irrestrito, método não hormonal).');
    }

    // 3. Hipertensão Arterial Sistêmica
    if (hasStatus === 'grave_descontrolada' || pas >= 160 || pad >= 100) {
      atualizarCat('AHC', 4, '⛔ HAS GRAVE / DESCONTROLADA (PA >= 160x100 mmHg): Categoria 4. Elevado risco sinérgico de AVC, IAM e dissecção.');
      atualizarCat('AMPD', 3, 'HAS Grave: Categoria 3 (Risco supera benefícios teóricos para injetável trimestral).');
      atualizarCat('POP', 2, 'HAS Grave: Categoria 2 (Progestagênio oral tem mínimo impacto pressórico).');
      atualizarCat('IMPLANTE', 2, 'HAS Grave: Categoria 2.');
      atualizarCat('DIU_LNG', 2, 'HAS Grave: Categoria 2.');
      atualizarCat('DIU_CU', 1, 'HAS Grave: Categoria 1 (Uso irrestrito).');
    } else if (hasStatus === 'controlada' || pas >= 140 || pad >= 90) {
      atualizarCat('AHC', 3, 'HAS Controlada (140-159 / 90-99 mmHg): Categoria 3 (Riscos geralmente superam benefícios para contraceptivos com estrogênio).');
      atualizarCat('AMPD', 2, 'HAS Controlada: Categoria 2.');
      atualizarCat('POP', 1, 'HAS Controlada: Categoria 1.');
      atualizarCat('IMPLANTE', 1, 'HAS Controlada: Categoria 1.');
      atualizarCat('DIU_LNG', 1, 'HAS Controlada: Categoria 1.');
      atualizarCat('DIU_CU', 1, 'HAS Controlada: Categoria 1.');
    }

    // 4. Tabagismo e Idade >= 35 anos
    if (tabagismo && idade >= 35) {
      if (cigarrosDia >= 15) {
        atualizarCat('AHC', 4, '⛔ TABAGISMO >= 15 CIGARROS/DIA COM IDADE >= 35 ANOS: Categoria 4 (Contraindicação absoluta). Risco maciço de Infarto Agudo do Miocárdio e trombose arterial.');
      } else {
        atualizarCat('AHC', 3, 'Tabagismo < 15 cigarros/dia com idade >= 35 anos: Categoria 3 (Riscos superam benefícios).');
      }
      atualizarCat('POP', 1, 'Tabagismo >= 35a: Categoria 1 (Livre de estrogênio, totalmente seguro).');
      atualizarCat('AMPD', 1, 'Tabagismo >= 35a: Categoria 1.');
      atualizarCat('IMPLANTE', 1, 'Tabagismo >= 35a: Categoria 1.');
      atualizarCat('DIU_CU', 1, 'Tabagismo >= 35a: Categoria 1.');
      atualizarCat('DIU_LNG', 1, 'Tabagismo >= 35a: Categoria 1.');
    } else if (tabagismo && idade < 35) {
      atualizarCat('AHC', 2, 'Tabagismo em mulher < 35 anos: Categoria 2.');
    }

    // 5. Pós-Parto e Aleitamento Materno (Lactação)
    if (lactacao) {
      if (semanasPosParto < 6) {
        atualizarCat('AHC', 4, '⛔ PÓS-PARTO < 6 SEMANAS EM AMAMENTAÇÃO: Categoria 4. O estrogênio passa para o leite materno, diminui o volume da lactação e eleva o risco de TEV puerperal.');
        atualizarCat('POP', 2, 'Pós-parto < 6 semanas com amamentação: Categoria 2 (Pode iniciar se alto risco de nova gestação, sem prejuízo à lactação).');
        atualizarCat('IMPLANTE', 2, 'Pós-parto < 6 semanas: Categoria 2.');
        atualizarCat('AMPD', 2, 'Pós-parto < 6 semanas: Categoria 2.');
        atualizarCat('DIU_LNG', 2, 'Pós-parto < 6 semanas: Categoria 2 (Inserção recomendada pós-parto imediato em até 48h ou após 4 semanas).');
        atualizarCat('DIU_CU', 1, 'DIU de Cobre no pós-parto: Categoria 1 (Não hormonal, seguro; inserir em até 48h ou após 4 semanas pós-parto).');
      } else if (semanasPosParto < 24) { // 6 semanas a 6 meses
        atualizarCat('AHC', 3, 'Pós-parto 6 semanas a 6 meses amamentando: Categoria 3.');
        atualizarCat('POP', 1, 'Pós-parto >= 6 semanas: Categoria 1.');
        atualizarCat('IMPLANTE', 1, 'Pós-parto >= 6 semanas: Categoria 1.');
        atualizarCat('AMPD', 1, 'Pós-parto >= 6 semanas: Categoria 1.');
        atualizarCat('DIU_LNG', 1, 'Pós-parto >= 6 semanas: Categoria 1.');
        atualizarCat('DIU_CU', 1, 'Pós-parto >= 6 semanas: Categoria 1.');
      }
    }

    // 6. Câncer de Mama Atual ou Prévio
    if (cancerMama === 'atual') {
      var motivoMama = '⛔ CÂNCER DE MAMA ATUAL: Categoria 4 para TODOS os métodos hormonais (tumores frequentemente dependentes de receptor de estrogênio/progesterona).';
      atualizarCat('AHC', 4, motivoMama);
      atualizarCat('POP', 4, motivoMama);
      atualizarCat('AMPD', 4, motivoMama);
      atualizarCat('IMPLANTE', 4, motivoMama);
      atualizarCat('DIU_LNG', 4, motivoMama);
      atualizarCat('DIU_CU', 1, 'DIU de Cobre: Categoria 1 (MÉTODO DE ESCOLHA ABSOLUTO! Sem hormônios, seguro no câncer de mama).');
    } else if (cancerMama === 'passado_5anos') {
      atualizarCat('AHC', 3, 'Histórico de câncer de mama > 5 anos sem evidência de doença: Categoria 3.');
      atualizarCat('POP', 3, 'Histórico de câncer de mama > 5 anos: Categoria 3.');
      atualizarCat('AMPD', 3, 'Histórico de câncer de mama > 5 anos: Categoria 3.');
      atualizarCat('IMPLANTE', 3, 'Histórico de câncer de mama > 5 anos: Categoria 3.');
      atualizarCat('DIU_LNG', 3, 'Histórico de câncer de mama > 5 anos: Categoria 3.');
      atualizarCat('DIU_CU', 1, 'DIU de Cobre: Categoria 1.');
    }

    // 7. Diabetes Mellitus com Vasculopatia ou > 20 anos de doença
    if (diabetes.indexOf('vasculopatia') >= 0 || diabetes.indexOf('20') >= 0) {
      atualizarCat('AHC', 4, '⛔ DIABETES COM VASCULOPATIA / NEFROPATIA / RETINOPATIA OU > 20 ANOS: Categoria 4 (Risco de eventos cardiovasculares isquêmicos).');
      atualizarCat('AMPD', 3, 'Diabetes com vasculopatia: Categoria 3.');
      atualizarCat('POP', 2, 'Diabetes com vasculopatia: Categoria 2.');
      atualizarCat('IMPLANTE', 2, 'Diabetes com vasculopatia: Categoria 2.');
      atualizarCat('DIU_LNG', 2, 'Diabetes com vasculopatia: Categoria 2.');
      atualizarCat('DIU_CU', 1, 'DIU de Cobre: Categoria 1.');
    }

    // 8. Lúpus Eritematoso Sistêmico (LES) com Anticorpos Antifosfolípide Positivos
    if (lupus === 'positivo') {
      atualizarCat('AHC', 4, '⛔ LES COM ANTICORPOS ANTIFOSFOLÍPIDE POSITIVOS: Categoria 4 (Risco altíssimo de trombose arterial e venosa).');
      atualizarCat('POP', 3, 'LES com anticorpos antifosfolípide: Categoria 3.');
      atualizarCat('AMPD', 3, 'LES com anticorpos antifosfolípide: Categoria 3.');
      atualizarCat('IMPLANTE', 3, 'LES com anticorpos antifosfolípide: Categoria 3.');
      atualizarCat('DIU_LNG', 3, 'LES com anticorpos antifosfolípide: Categoria 3.');
      atualizarCat('DIU_CU', 1, 'DIU de Cobre: Categoria 1 (Salvo se trombocitopenia grave associada).');
    }

    // Estruturação do Resultado e Classificação
    var metodosElegiveisCat1 = [];
    var metodosAceitaveisCat2 = [];
    var metodosEvitarCat3 = [];
    var metodosBloqueadosCat4 = [];

    var chaves = Object.keys(metodos);
    for (var i = 0; i < chaves.length; i++) {
      var id = chaves[i];
      var m = metodos[id];
      var item = {
        id: id,
        nome: m.nome,
        categoria: m.cat,
        justificativas: m.motivos.length > 0 ? m.motivos : [{ cat: m.cat, motivo: 'Sem restrições para esta condição clínica.' }]
      };

      if (m.cat === 1) metodosElegiveisCat1.push(item);
      else if (m.cat === 2) metodosAceitaveisCat2.push(item);
      else if (m.cat === 3) metodosEvitarCat3.push(item);
      else if (m.cat === 4) metodosBloqueadosCat4.push(item);
    }

    var resumoIndicacao = '';
    if (metodosElegiveisCat1.length > 0) {
      resumoIndicacao = 'Métodos de 1ª Escolha (Categoria 1 OMS): ' + metodosElegiveisCat1.map(function(x) { return x.nome; }).join('; ');
    } else if (metodosAceitaveisCat2.length > 0) {
      resumoIndicacao = 'Métodos Recomendados com Benefício Superior (Categoria 2 OMS): ' + metodosAceitaveisCat2.map(function(x) { return x.nome; }).join('; ');
    } else {
      resumoIndicacao = 'Avaliar indicação cirúrgica (Laqueadura) ou métodos de barreira estritos.';
    }

    return {
      idade: idade,
      resumoIndicacao: resumoIndicacao,
      metodosElegiveisCat1: metodosElegiveisCat1,
      metodosAceitaveisCat2: metodosAceitaveisCat2,
      metodosEvitarCat3: metodosEvitarCat3,
      metodosBloqueadosCat4: metodosBloqueadosCat4,
      detalhesPorMetodo: metodos,
      diretrizReferencia: 'Critérios Médicos de Elegibilidade para Uso de Métodos Anticoncepcionais (OMS 5ª ed. / FEBRASGO)'
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 4. SÍNDROMES INFECCIOSAS VULVOVAGINAIS (LEUCORREIAS / CORRIMENTOS)
  // ───────────────────────────────────────────────────────────────────────────

  /**
   * Avaliação determinística clínica, laboratorial (Amsel) e farmacológica
   * para Candidíase, Vaginose Bacteriana e Tricomoníase.
   *
   * @param {Object} dados
   * @param {string} [dados.sintomaPredominante] ('prurido', 'odor_fetido', 'ardencia', 'nenhum')
   * @param {string} [dados.aspectoCorrimento] ('grumoso_branco', 'branco_acinzentado_fino', 'amarelo_esverdeado_bolhoso')
   * @param {number} [dados.phVaginal] (ex: 4.0, 4.2, 5.0, 5.5, 6.0)
   * @param {string} [dados.whiffTest] ('positivo', 'negativo', 'nao_realizado')
   * @param {string} [dados.microscopia] ('clue_cells', 'hifas_esporos', 'protozoarios_moveis', 'normal')
   * @param {boolean} [dados.gestante]
   * @param {number} [dados.trimestreGestacao]
   * @param {boolean} [dados.recorrente] (>= 4 episódios no ano para candidíase)
   * @param {boolean} [dados.alergiaMetronidazol]
   */
  function avaliarInfeccaoVulvovaginal(dados) {
    dados = dados || {};
    var sintoma = String(dados.sintomaPredominante || '').toLowerCase();
    var aspecto = String(dados.aspectoCorrimento || '').toLowerCase();
    var ph = dados.phVaginal !== undefined && dados.phVaginal !== null ? Number(dados.phVaginal) : null;
    var whiff = String(dados.whiffTest || 'nao_realizado').toLowerCase();
    var microscopia = String(dados.microscopia || 'nao_realizado').toLowerCase();
    var gestante = Boolean(dados.gestante);
    var trimestre = Number(dados.trimestreGestacao || (gestante ? 2 : 0));
    var recorrente = Boolean(dados.recorrente);
    var alergiaMetronidazol = Boolean(dados.alergiaMetronidazol);

    // Pontuação diagnóstica determinística para cada síndrome
    var scoreCandidiase = 0;
    var scoreVaginose = 0;
    var scoreTricomoniase = 0;

    // Prurido vulvar intenso aponta para candidíase
    if (sintoma.indexOf('prur') >= 0) scoreCandidiase += 3;
    if (sintoma.indexOf('odor') >= 0 || sintoma.indexOf('fétid') >= 0 || sintoma.indexOf('fetid') >= 0 || sintoma.indexOf('peixe') >= 0) {
      scoreVaginose += 3;
      scoreTricomoniase += 2;
    }

    // Aspecto do corrimento
    if (aspecto.indexOf('grum') >= 0 || aspecto.indexOf('leite coalhado') >= 0 || aspecto.indexOf('branco_aderido') >= 0) {
      scoreCandidiase += 4;
    }
    if (aspecto.indexOf('acinzentad') >= 0 || aspecto.indexOf('fino') >= 0 || aspecto.indexOf('homogeneo') >= 0) {
      scoreVaginose += 4;
    }
    if (aspecto.indexOf('esverde') >= 0 || aspecto.indexOf('amarel') >= 0 || aspecto.indexOf('bolh') >= 0) {
      scoreTricomoniase += 4;
    }

    // pH Vaginal: normal em candidíase (<= 4.5), elevado em vaginose e tricomoníase (> 4.5)
    if (ph !== null) {
      if (ph <= 4.5) {
        scoreCandidiase += 3;
        scoreVaginose -= 2;
        scoreTricomoniase -= 2;
      } else if (ph > 4.5 && ph <= 5.5) {
        scoreVaginose += 3;
        scoreTricomoniase += 1;
      } else if (ph > 5.5) {
        scoreTricomoniase += 3;
        scoreVaginose += 2;
      }
    }

    // Whiff Test (Teste das Aminas com KOH 10%)
    if (whiff === 'positivo') {
      scoreVaginose += 4;
      scoreTricomoniase += 2;
      scoreCandidiase -= 3;
    } else if (whiff === 'negativo') {
      scoreCandidiase += 2;
      scoreVaginose -= 2;
    }

    // Microscopia a fresco (padrão ouro confirmatório beira-leito)
    if (microscopia.indexOf('hifa') >= 0 || microscopia.indexOf('esporo') >= 0 || microscopia.indexOf('levedur') >= 0) {
      scoreCandidiase += 10;
    }
    if (microscopia.indexOf('clue') >= 0 || microscopia.indexOf('guia') >= 0 || microscopia.indexOf('indicador') >= 0) {
      scoreVaginose += 10;
    }
    if (microscopia.indexOf('protozo') >= 0 || microscopia.indexOf('tricomon') >= 0 || microscopia.indexOf('flagel') >= 0) {
      scoreTricomoniase += 10;
    }

    // Diagnóstico Principal
    var diagnostico = 'INDEFINIDO';
    var diagnosticoDescricao = '';
    var prescricoes = [];
    var condutas = [];
    var alertas = [];

    if (scoreCandidiase >= scoreVaginose && scoreCandidiase >= scoreTricomoniase && scoreCandidiase >= 3) {
      diagnostico = 'CANDIDIASE_VULVOVAGINAL';
      diagnosticoDescricao = 'Candidíase Vulvovaginal (Candida albicans / espécies não-albicans)';

      condutas.push('Quadro caracterizado por prurido vulvar intenso, hiperemia de vulva, pH ácido (<= 4.5) e corrimento em grumos brancos ("leite coalhado").');

      // CONDUTA FARMACOLÓGICA CANDIDÍASE
      if (gestante) {
        alertas.push('⛔ CONTRAINDICAÇÃO ABSOLUTA: Fluconazol oral é CONTRAINDICADO durante a gestação (risco aumentado de anomalias craniofaciais, cardíacas e abortamento).');
        prescricoes.push({
          farmaco: 'Miconazol nitrato creme vaginal 2% (20 mg/g)',
          posologia: 'Aplicar 1 aplicador cheio (aprox. 5g) via intravaginal profunda, à noite ao deitar, durante 7 noites consecutivas.',
          justificativa: 'Tratamento tópico de escolha absoluto na gestante (categoria B na gestação; mínima absorção sistêmica).',
          tipo: 'Tópico Gestacional Obrigatório'
        });
        prescricoes.push({
          farmaco: 'Alternativa Tópica: Nistatina creme vaginal 100.000 UI/g',
          posologia: 'Aplicar 1 aplicador cheio via intravaginal à noite ao deitar por 14 noites consecutivas.',
          justificativa: 'Opção padrão do SUS/REMUME.',
          tipo: 'Alternativa Tópica'
        });
      } else if (recorrente) {
        condutas.push('Protocolo de Candidíase Recorrente (>= 4 episódios no ano):');
        prescricoes.push({
          farmaco: 'Fluconazol 150 mg (Fase de Indução)',
          posologia: 'Tomar 1 cápsula por via oral a cada 72 horas por 3 doses (D1, D4 e D7).',
          justificativa: 'Erradicação fúngica profunda na fase de indução de remissão.',
          tipo: 'Fase de Indução'
        });
        prescricoes.push({
          farmaco: 'Fluconazol 150 mg (Fase de Manutenção)',
          posologia: 'Tomar 1 cápsula por via oral uma vez por semana durante 6 meses.',
          justificativa: 'Manutenção supressiva para prevenir recidivas sintomáticas.',
          tipo: 'Fase de Manutenção (6 meses)'
        });
        condutas.push('Investigar comorbidades: Solicitar Hemoglobina Glicada (afastar Diabetes Mellitus descompensado) e sorologia para HIV.');
      } else {
        // Não gestante / Não recorrente
        prescricoes.push({
          farmaco: 'Fluconazol 150 mg VO',
          posologia: 'Tomar 1 cápsula por via oral em dose única.',
          justificativa: 'Tratamento oral cômodo de 1ª linha com alta taxa de cura clínica (>90%).',
          tipo: 'Oral 1ª Linha'
        });
        prescricoes.push({
          farmaco: 'Opção Tópica: Miconazol nitrato creme vaginal 2%',
          posologia: 'Aplicar 1 aplicador cheio à noite ao deitar por 7 noites consecutivas.',
          justificativa: 'Para pacientes que preferem via tópica ou com intolerância gástrica ao fluconazol.',
          tipo: 'Tópico 1ª Linha'
        });
      }

      condutas.push('Orientações de Higiene: Evitar sabonetes perfumados, preferir calcinhas de algodão, evitar roupas sintéticas e justas e secar bem a região vulvar após o banho.');
      condutas.push('Parceiro sexual: NÃO tratar parceiro assintomático de rotina (Candidíase não é considerada uma IST). Tratar apenas se parceiro apresentar balanite/balanopostite com prurido ou eritema.');

    } else if (scoreVaginose >= scoreTricomoniase && scoreVaginose >= 3) {
      diagnostico = 'VAGINOSE_BACTERIANA';
      diagnosticoDescricao = 'Vaginose Bacteriana (Gardnerella vaginalis, Atopobium vaginae, anaeróbios)';

      condutas.push('Critérios de Amsel (>= 3 de 4): Corrimento fino homogêneo acinzentado, pH vaginal > 4.5, Whiff test positivo (odor de aminas com KOH 10%) e presença de Clue Cells na microscopia.');

      // Alerta Dissulfiram
      alertas.push('⚠️ ALERTA FARMACOLÓGICO: Abstinência total de bebidas alcoólicas durante o uso de Metronidazol e até 24 a 48 horas após a última dose devido ao risco de Efeito Dissulfiram / Antabuse (náuseas intensas, vômitos, palpitações e rubor).');

      if (!alergiaMetronidazol) {
        prescricoes.push({
          farmaco: 'Metronidazol 250 mg VO',
          posologia: 'Tomar 2 comprimidos (500 mg) por via oral de 12 em 12 horas por 7 dias (ingerir junto às refeições).',
          justificativa: 'Tratamento de 1ª linha recomendado pelo Ministério da Saúde e CDC. Cura em 85-90% dos casos.',
          tipo: 'Oral 1ª Linha REMUME'
        });
        prescricoes.push({
          farmaco: 'Alternativa Tópica: Metronidazol gel vaginal 0,75%',
          posologia: 'Aplicar 1 aplicador cheio (5g) intravaginal ao deitar por 5 a 7 dias.',
          justificativa: 'Excelente alternativa para pacientes com intolerância gastrointestinal ao metronidazol oral.',
          tipo: 'Tópico 1ª Linha'
        });
        prescricoes.push({
          farmaco: 'Alternativa Oral Dose Única: Secnidazol 2 g VO',
          posologia: 'Tomar 2 comprimidos de 1000 mg (2 g) em dose única com refeição.',
          justificativa: 'Opção para casos com dificuldade previsível de adesão ao tratamento de 7 dias.',
          tipo: 'Dose Única'
        });
      } else {
        prescricoes.push({
          farmaco: 'Clindamicina creme vaginal 2%',
          posologia: 'Aplicar 1 aplicador cheio (5g) intravaginal ao deitar por 7 noites consecutivas.',
          justificativa: 'Opção de escolha para pacientes com alergia comprovada ao Metronidazol.',
          tipo: 'Alternativa Alergia a Nitroimidazólicos'
        });
      }

      if (gestante) {
        condutas.push('Gestantes sintomáticas devem ser tratadas: Metronidazol 250 mg 2 cp VO 12/12h por 7 dias é seguro no 2º e 3º trimestres conforme Diretrizes do Ministério da Saúde. O tratamento reduz o risco de corioamnionite e parto prematuro.');
      }

      condutas.push('Parceiro sexual: NÃO tratar parceiro assintomático de rotina (evidências científicas demonstram que tratar o parceiro não reduz a taxa de recorrência da vaginose bacteriana).');

    } else if (scoreTricomoniase >= 3) {
      diagnostico = 'TRICOMONIASE';
      diagnosticoDescricao = 'Tricomoníase (Trichomonas vaginalis - Infecção Sexualmente Transmissível)';

      condutas.push('Quadro clínico clássico: Corrimento abundante, bolhoso, amarelo-esverdeado ou acinzentado, fétido, prurido vulvar, disúria e aspecto colposcópico de "colo em framboesa" (colpite focal).');

      alertas.push('🚨 INFECÇÃO SEXUALMENTE TRANSMISSÍVEL (IST): O tratamento simultâneo do(s) parceiro(s) sexual(is) é MANDATÓRIO, mesmo que assintomático(s).');
      alertas.push('⚠️ ALERTA FARMACOLÓGICO: Abstinência alcoólica estrita durante o tratamento com Metronidazol e até 48 horas após pelo risco de efeito dissulfiram.');

      prescricoes.push({
        farmaco: 'Metronidazol 2 g VO (4 comprimidos de 500 mg ou 8 comprimidos de 250 mg)',
        posologia: 'Tomar 2 g por via oral em dose única junto a uma refeição.',
        justificativa: 'Esquema de 1ª linha em dose única (REMUME/MS) com alto índice de cura e excelente adesão.',
        tipo: '1ª Linha Dose Única'
      });
      prescricoes.push({
        farmaco: 'Esquema Alternativo: Metronidazol 500 mg VO',
        posologia: 'Tomar 1 comprimido de 500 mg de 12 em 12 horas por 7 dias.',
        justificativa: 'Indicado se intolerância gástrica à dose única ou falha terapêutica prévia.',
        tipo: 'Alternativa de 7 Dias'
      });

      condutas.push('TRATAR O PARCEIRO: Prescrever Metronidazol 2 g VO em dose única para o parceiro sexual.');
      condutas.push('Abstinência sexual: Manter abstenção de relações sexuais até que ambos os parceiros tenham concluído o tratamento e estejam assintomáticos.');
      condutas.push('Rastreamento de ISTs: Solicitar testes rápidos ou sorologias para Sífilis (VDRL), HIV, Hepatite B (HBsAg) e Hepatite C (Anti-HCV).');

    } else {
      // Abordagem Sindrômica / Indeterminada
      diagnostico = 'SINDROMICO_INDETERMINADO';
      diagnosticoDescricao = 'Manejo Sindrômico do Corrimento Vaginal (Atenção Básica sem microscopia)';
      condutas.push('Na ausência de critérios laboratoriais específicos de certeza, priorizar a avaliação clínica e pH vaginal:');
      condutas.push('1. Se predomínio de prurido intenso com placas brancas e sem odor: Tratar para Candidíase com Miconazol creme vaginal 2% por 7 noites ou Fluconazol 150mg VO dose única.');
      condutas.push('2. Se predomínio de odor fétido e corrimento fluido: Tratar para Vaginose Bacteriana com Metronidazol 500mg 12/12h por 7 dias.');
      condutas.push('3. Se corrimento amarelo-esverdeado bolhoso com colpite: Tratar para Tricomoníase (Metronidazol 2g VO dose única e tratar parceiro).');
    }

    return {
      diagnostico: diagnostico,
      diagnosticoDescricao: diagnosticoDescricao,
      escores: { candidiase: scoreCandidiase, vaginose: scoreVaginose, tricomoniase: scoreTricomoniase },
      gestante: gestante,
      prescricoes: prescricoes,
      condutas: condutas,
      alertas: alertas,
      diretrizReferencia: 'Protocolo Clínico e Diretrizes Terapêuticas (PCDT) para ISTs (Ministério da Saúde) & FEBRASGO'
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 5. RELATÓRIO CLÍNICO ESTRUTURADO UNIFICADO DE GINECOLOGIA AMBULATORIAL
  // ───────────────────────────────────────────────────────────────────────────

  /**
   * Consolida um resumo clínico completo estruturado em texto limpo
   * para exportação rápida no Prontuário Eletrônico (PEP) ou Telegram.
   *
   * @param {Object} cenario
   */
  function gerarResumoGinecologia(cenario) {
    cenario = cenario || {};
    var linhas = [];
    linhas.push('════════════════════════════════════════════════════════════════');
    linhas.push('🌸 AVALIAÇÃO DE GINECOLOGIA AMBULATORIAL — CONSULTÓRIO & APS');
    linhas.push('════════════════════════════════════════════════════════════════');
    linhas.push('TRIAGEM UBS: confirmar possibilidade de gestação, estabilidade hemodinâmica, febre/dor pélvica, sangramento e risco de IST antes da conduta.');
    linhas.push('EXAME: registrar consentimento; especular e toque apenas quando indicados, com achados observados, sem presumir exame normal.');

    // 1. Rastreamento de Colo Uterino
    if (cenario.coloUterino) {
      var cu = avaliarRastreioColoUterino(cenario.coloUterino);
      linhas.push('');
      linhas.push('🔬 [1. RASTREIO DE CÂNCER DO COLO UTERINO (INCA/MS)]');
      linhas.push('• Idade: ' + cu.idade + ' anos | Laudo: ' + cu.citologia);
      linhas.push('• Classificação: ' + cu.classificacao + ' (' + cu.localAtendimento + ')');
      if (cu.prazoRecomendado) linhas.push('• Prazo Recomendado: ' + cu.prazoRecomendado);
      linhas.push('• Condutas:');
      for (var i = 0; i < cu.condutas.length; i++) {
        linhas.push('  - ' + cu.condutas[i]);
      }
      if (cu.alertas && cu.alertas.length > 0) {
        for (var a = 0; a < cu.alertas.length; a++) {
          linhas.push('  ' + cu.alertas[a]);
        }
      }
    }

    // 2. Sangramento Uterino Anormal (SUA)
    if (cenario.sua) {
      var sua = avaliarSangramentoUterinoAnormal(cenario.sua);
      linhas.push('');
      linhas.push('🩸 [2. SANGRAMENTO UTERINO ANORMAL (FIGO / PALM-COEIN)]');
      linhas.push('• Idade: ' + sua.idade + ' anos | Intensidade: ' + sua.intensidade.toUpperCase());
      if (sua.choqueInstavel) {
        linhas.push('• 🚨 ESTADO: INSTABILIDADE HEMODINÂMICA (Índice de Choque: ' + sua.indiceChoque + ')');
      } else {
        linhas.push('• Estabilidade: Hemodinamicamente estável (Índice de Choque: ' + sua.indiceChoque + ')');
      }
      if (sua.alertas && sua.alertas.length > 0) {
        for (var s = 0; s < sua.alertas.length; s++) {
          linhas.push('  ' + sua.alertas[s]);
        }
      }
      if (sua.prescricoesSugeridas && sua.prescricoesSugeridas.length > 0) {
        linhas.push('• Conduta Farmacológica Hemostática Imediata:');
        for (var p = 0; p < sua.prescricoesSugeridas.length; p++) {
          var rx = sua.prescricoesSugeridas[p];
          linhas.push('  💊 ' + rx.farmaco + ' — ' + rx.linha);
          linhas.push('     Posologia: ' + rx.posologia);
        }
      }
      if (sua.condutasAmbulatoriais && sua.condutasAmbulatoriais.length > 0) {
        linhas.push('• Planejamento Ambulatorial & Investigação:');
        for (var ca = 0; ca < sua.condutasAmbulatoriais.length; ca++) {
          linhas.push('  - ' + sua.condutasAmbulatoriais[ca]);
        }
      }
    }

    // 3. Anticoncepção OMS
    if (cenario.anticoncepcao) {
      var ac = avaliarCriteriosElegibilidadeContracepcao(cenario.anticoncepcao);
      linhas.push('');
      linhas.push('🛡️ [3. CRITÉRIOS DE ELEGIBILIDADE DE ANTICONCEPÇÃO (OMS)]');
      linhas.push('• ' + ac.resumoIndicacao);
      if (ac.metodosBloqueadosCat4 && ac.metodosBloqueadosCat4.length > 0) {
        linhas.push('• ⛔ Métodos CONTRAINDICADOS (Categoria 4 OMS - Risco Inaceitável):');
        for (var b = 0; b < ac.metodosBloqueadosCat4.length; b++) {
          var bloq = ac.metodosBloqueadosCat4[b];
          linhas.push('  - ' + bloq.nome);
          for (var j = 0; j < bloq.justificativas.length; j++) {
            linhas.push('    ' + bloq.justificativas[j].motivo);
          }
        }
      }
      if (ac.metodosEvitarCat3 && ac.metodosEvitarCat3.length > 0) {
        linhas.push('• ⚠️ Métodos Não Recomendados (Categoria 3 OMS - Riscos superam benefícios):');
        for (var e = 0; e < ac.metodosEvitarCat3.length; e++) {
          linhas.push('  - ' + ac.metodosEvitarCat3[e].nome);
        }
      }
    }

    // 4. Infecções Vulvovaginais (Leucorreias)
    if (cenario.infeccao) {
      var inf = avaliarInfeccaoVulvovaginal(cenario.infeccao);
      linhas.push('');
      linhas.push('🦠 [4. SÍNDROMES INFECCIOSAS VULVOVAGINAIS (LEUCORREIAS)]');
      linhas.push('• Diagnóstico: ' + inf.diagnosticoDescricao);
      if (inf.alertas && inf.alertas.length > 0) {
        for (var ia = 0; ia < inf.alertas.length; ia++) {
          linhas.push('  ' + inf.alertas[ia]);
        }
      }
      if (inf.prescricoes && inf.prescricoes.length > 0) {
        linhas.push('• Prescrição Farmacológica de Escolha (REMUME/MS):');
        for (var ip = 0; ip < inf.prescricoes.length; ip++) {
          var irx = inf.prescricoes[ip];
          linhas.push('  💊 ' + irx.farmaco + ' (' + irx.tipo + ')');
          linhas.push('     Posologia: ' + irx.posologia);
        }
      }
      if (inf.condutas && inf.condutas.length > 0) {
        linhas.push('• Orientações & Seguimento Clínico:');
        for (var ic = 0; ic < inf.condutas.length; ic++) {
          linhas.push('  - ' + inf.condutas[ic]);
        }
      }
    }

    linhas.push('');
    linhas.push('════════════════════════════════════════════════════════════════');
    linhas.push('Diretrizes de Referência: INCA/MS, OMS, FIGO, FEBRASGO & PCDT/MS');
    linhas.push('════════════════════════════════════════════════════════════════');

    return linhas.join('\n');
  }

  // Exportação Pública
  return {
    avaliarRastreioColoUterino: avaliarRastreioColoUterino,
    avaliarSangramentoUterinoAnormal: avaliarSangramentoUterinoAnormal,
    avaliarCriteriosElegibilidadeContracepcao: avaliarCriteriosElegibilidadeContracepcao,
    avaliarInfeccaoVulvovaginal: avaliarInfeccaoVulvovaginal,
    gerarResumoGinecologia: gerarResumoGinecologia
  };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = GinecologiaAmbulatorialService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_ginecologia_endometriose.js
// ==============================================================================

/**
 * ==============================================================================
 * ULTRA ROTINA - MÓDULO DE GINECOLOGIA ENDÓCRINA E CIRÚRGICA
 * ==============================================================================
 * Manejo Clínico da Endometriose e Dor Pélvica Crônica
 * Diretrizes ESHRE (2022/2024), FEBRASGO (2024-2026), AAGL (2021)
 * 
 * PILARES CLÍNICOS DETERMINÍSTICOS:
 * 1. Diagnóstico Clínico e Mapeamento dos Sintomas (Os "6 Ds" da Endometriose):
 *    - Dismenorreia incapacitante / progressiva
 *    - Dispareunia de profundidade
 *    - Disquezia cíclica (dor evacuatória perimenstrual)
 *    - Disúria cíclica / hematúria
 *    - Dor pélvica acíclica crônica (≥ 6 meses)
 *    - Dificuldade reprodutiva / infertilidade
 * 2. Mapeamento Topográfico por Imagem de Alta Resolução:
 *    - USG Transvaginal com preparo intestinal prévio dedicado
 *    - Ressonância Magnética (RM) de pelve com protocolo para endometriose
 *    - Mapeamento de compartimentos anterior (bexiga, ureteres), médio (miométrio/adenomiose,
 *      ovários/endometriomas) e posterior (ligamentos úterossacros, toro, recesso de Douglas,
 *      septo retovaginal e retossigmoide)
 * 3. Identificação Precoce de Sinais de Alarme Cirúrgico (Red Flags):
 *    - Acometimento ureteral com hidronefrose silenciosa (risco de perda renal ipsilateral)
 *    - Acometimento retossigmoídeo estenosante (≥ 50% de diâmetro luminal ou suboclusão)
 *    - Endometrioma ovariano volumoso (≥ 4-5 cm) ou com suspeita atípica
 * 4. Terapia Farmacológica Escalonada de Supressão Estrogênica:
 *    - 1ª Linha: Progestagênios contínuos (Dienogeste 2 mg/dia como padrão de eficácia e
 *      indução de atrofia dos focos; SIU-Levonorgestrel 52 mg; Desogestrel 75 mcg/dia) e
 *      Anticoncepcionais Hormonais Combinados (AHC) em regime contínuo
 *    - 2ª Linha: Antagonistas orais de GnRH (Relugolix 40 mg/dia com add-back therapy ou Elagolix)
 *      ou Análogos agonistas de GnRH (Goserrelina / Leuprorrelina) com add-back obrigatória
 * 5. Tomada de Decisão Reprodutiva vs Cirúrgica:
 *    - Desejo reprodutivo ativo: Bloqueio estrito de fármacos contraceptivos hormonais
 *    - Avaliação mandatória de reserva ovariana (AMH / CFA)
 *    - Indicação precoce de Fertilização in Vitro (FIV) em idade materna ≥ 35 anos, infertilidade > 2 anos,
 *      AMH baixo ou endometriose profunda/tubária, prevenindo cirurgias ovarianas espoliativas
 *    - Indicações precisas de cirurgia (laparoscopia/robótica) com abordagem multidisciplinar nerve-sparing
 * ==============================================================================
 */

var GinecologiaEndometrioseService = (function () {
  'use strict';

  // ───────────────────────────────────────────────────────────────────────────
  // 1. CATÁLOGO FARMACOLÓGICO E DIRETRIZES (ESHRE / FEBRASGO)
  // ───────────────────────────────────────────────────────────────────────────

  var CATALOGO_FARMACOLOGICO = {
    PRIMEIRA_LINHA: {
      DIENOGESTE: {
        farmaco: "Dienogeste 2 mg",
        posologia: "2 mg VO 1x/dia, uso oral contínuo diário no mesmo horário (sem pausas)",
        classe: "Progestagênio de 4ª geração com potente atividade seletiva antiandrogênica e progestagênica",
        mecanismo: "Induz decidualização seguida de atrofia progressiva dos implantes ectópicos de endométrio. Reduz a síntese de citocinas pró-inflamatórias (IL-6, IL-8, TNF-alfa), angiogênese e níveis de prostaglandinas locais.",
        evidencia: "Padrão de excelência de 1ª linha (ESHRE 2022/2024 / FEBRASGO). Eficácia comparável aos agonistas de GnRH no alívio da dor, sem causar hipoestrogenismo severo ou perda óssea acelerada.",
        efeitosAdversos: "Sangramento de escape ('spotting') nos primeiros 3-6 meses, cefaleia, alterações discretas de humor ou mastalgia."
      },
      SIU_LEVONORGESTREL: {
        farmaco: "Sistema Intrauterino Liberador de Levonorgestrel (SIU-LNG 52 mg - Mirena)",
        posologia: "Inserção intrauterina estéril em consultório (duração de até 8 anos para contracepção / 5 anos para controle da dor)",
        classe: "Progestagênio intrauterino de liberação local contínua (20 mcg/dia)",
        mecanismo: "Promove pronunciada atrofia endometrial local, redução da vascularização e decréscimo drástico do fluxo menstrual e da dismenorreia.",
        evidencia: "Excelente opção de 1ª linha, particularmente indicada na endometriose associada à ADENOMIOSE e hipermenorreia.",
        vantagens: "Ação predominantemente local com níveis séricos mínimos, alta adesão terapêutica."
      },
      DESOGESTREL: {
        farmaco: "Desogestrel 75 mcg",
        posologia: "1 comprimido VO 1x/dia continuamente sem intervalo entre as cartelas",
        classe: "Progestagênio oral contínuo (pílula isolada)",
        mecanismo: "Inibe a ovulação em 97% dos ciclos e promove supressão estrogênica moderada e atrofia endometrial.",
        evidencia: "Opção de baixo custo e ampla disponibilidade no SUS para pacientes com contraindicações a estrogênios."
      },
      AHC_CONTINUO: {
        farmaco: "Anticoncepcionais Hormonais Combinados em Regime Contínuo",
        posologia: "1 comprimido VO ao dia sem pausa de intervalo (ex: Etinilestradiol 20-30 mcg + Levonorgestrel/Gestodeno/Drospirenona)",
        classe: "Estroprogestativo oral contínuo",
        mecanismo: "Bloqueia a menstruação retrógrada pela indução de amenorreia sustentada e inibe a maturação folicular cíclica.",
        precaucoes: "Avaliar critérios de elegibilidade da OMS (MEC 1/2). Evitar em tabagistas > 35 anos, histórico de TEV, enxaqueca com aura ou hipertensão."
      }
    },
    SEGUNDA_LINHA: {
      ANTAGONISTAS_GNRH: {
        RELUGOLIX_COMBINADO: {
          farmaco: "Relugolix 40 mg + Estradiol 1 mg + Acetato de Noretisterona 0,5 mg (Ryeqo)",
          posologia: "1 comprimido VO 1x/dia contínuo, iniciado preferencialmente nos primeiros 5 dias da menstruação",
          classe: "Antagonista oral não peptídico do receptor de GnRH com Terapia Add-Back integrada",
          mecanismo: "Bloqueio imediato e competitivo dos receptores hipofisários de GnRH, promovendo rápida supressão de FSH e LH sem o fenômeno de 'flare-up'. A terapia add-back incorporada previne perda óssea e sintomas vasomotores.",
          evidencia: "2ª Linha de alta eficácia aprovada em consensos internacionais recentes para dor pélvica moderada a grave refratária a progestagênios."
        },
        ELAGOLIX: {
          farmaco: "Elagolix",
          posologia: "150 mg VO 1x/dia por até 24 meses OU 200 mg VO 2x/dia por até 6 meses (adicionar add-back se > 6 meses)",
          classe: "Antagonista oral de GnRH de dosagem ajustável"
        }
      },
      ANALOGOS_GNRH: {
        GOSSERRELINA: {
          farmaco: "Acetato de Gosserrelina (Zoladex 3,6 mg)",
          posologia: "3,6 mg SC em depósito na parede abdominal a cada 28 dias",
          classe: "Agonista do receptor de GnRH (GnRHa de depósito)",
          mecanismo: "Promove estimulação inicial transitória ('flare-up' nos primeiros 10-14 dias) seguida por profunda dessensibilização dos receptores hipofisários de GnRH, induzindo estado de hipoestrogenismo profundo ('menopausa farmacológica').",
          alertaAddBack: "MANDATÓRIO associar Terapia Add-Back (ex: Noretisterona 2,5 mg/dia ou Estradiol 1 mg + Noretisterona 0,5 mg) se tratamento previsto > 3 a 6 meses, visando prevenir osteopenia severa e sintomas climatéricos incapacitantes.",
          duracaoMaxima: "Máximo de 6 meses sem add-back; até 12 a 24 meses com add-back e monitoramento de densitometria óssea (DMO)."
        },
        LEUPRORRELINA: {
          farmaco: "Acetato de Leuprorrelina 3,75 mg",
          posologia: "3,75 mg IM em depósito a cada 28 dias (com add-back se > 3 meses)"
        }
      }
    },
    ANALGESIA_ADJUVANTE: {
      AINES: "AINEs (ex: Cetoprofeno 100-150 mg/dia ou Ibuprofeno 600 mg 8/8h) para manejo de exacerbações álgicas pontuais em cursos curtos (3 a 5 dias). Não reduzem os focos de endometriose.",
      NEUROMODULADORES: "Em dor pélvica crônica com sensibilização central e dor nociplástica/neuropática: Gabapentina 300 a 900 mg/dia, Pregabalina 75 a 150 mg/dia ou Duloxetina 30 a 60 mg/dia."
    }
  };

  // ───────────────────────────────────────────────────────────────────────────
  // 2. AVALIAÇÃO DETERMINÍSTICA DO CASO CLÍNICO
  // ───────────────────────────────────────────────────────────────────────────

  function avaliarEndometriose(dados) {
    dados = dados || {};

    var idade = parseInt(dados.idade, 10) || 0;
    var evaDor = parseFloat(dados.evaDor) || 0;
    var tempoInfertilidadeAnos = parseFloat(dados.tempoInfertilidadeAnos) || 0;
    var amh = parseFloat(dados.amh) || 0;
    var cfa = parseInt(dados.cfa, 10) || 0;

    // Sintomas clínicos dos 6 Ds
    var dismenorreia = Boolean(dados.dismenorreia);
    var dispareunia = Boolean(dados.dispareunia);
    var disquezia = Boolean(dados.disquezia);
    var disuria = Boolean(dados.disuria);
    var dorPelvicaCronica = Boolean(dados.dorPelvicaCronica);
    var infertilidade = Boolean(dados.infertilidade) || tempoInfertilidadeAnos > 0;
    var desejoGestacional = Boolean(dados.desejoGestacional) || Boolean(dados.tentandoEngravidar);

    // Achados de Imagem e Topografia
    var tipoExame = (dados.tipoExame || '').trim();
    var imagemRealizada = Boolean(dados.usgComPreparo || dados.rmPelve || /usg|ultrassom|rm|resson/i.test(tipoExame));
    var superficial = Boolean(dados.superficial);
    var endometrioma = Boolean(dados.endometrioma) || parseFloat(dados.endometriomaTamanhoCm) > 0 || parseFloat(dados.endometriomaTamanhoMm) > 0;
    
    var endometriomaCm = parseFloat(dados.endometriomaTamanhoCm) || 0;
    if (!endometriomaCm && parseFloat(dados.endometriomaTamanhoMm) > 0) {
      endometriomaCm = parseFloat(dados.endometriomaTamanhoMm) / 10.0;
    }
    var endometriomaBilateral = Boolean(dados.endometriomaBilateral);

    // Endometriose Profunda e Compartimentos
    var profunda = Boolean(dados.profunda);
    var acometimentoUreteral = Boolean(dados.acometimentoUreteral || dados.ureter || dados.hidronefrose);
    var hidronefrose = Boolean(dados.hidronefrose);
    var acometimentoIntestinal = Boolean(dados.acometimentoIntestinal || dados.reto || dados.sigmoide || dados.retossigmoide);
    var estenoseIntestinal = parseFloat(dados.estenoseIntestinalPercentual) || 0;
    var sintomasSuboclusivos = Boolean(dados.sintomasSuboclusivos || dados.suboclusao);
    var ligamentosUterossacros = Boolean(dados.ligamentosUterossacros || dados.uterossacro);
    var toroUterino = Boolean(dados.toroUterino);
    var obliteracaoDouglas = Boolean(dados.obliteracaoDouglas);
    var septoRetovaginal = Boolean(dados.septoRetovaginal);
    var bexiga = Boolean(dados.bexiga);
    var adenomiose = Boolean(dados.adenomiose);

    if (acometimentoUreteral || acometimentoIntestinal || ligamentosUterossacros || septoRetovaginal || bexiga || obliteracaoDouglas) {
      profunda = true;
    }

    // Histórico de Tratamentos Prévios
    var falhaDienogeste = Boolean(dados.falhaDienogeste);
    var falhaAhc = Boolean(dados.falhaAhc);
    var falhaSiuLng = Boolean(dados.falhaSiuLng);
    var usoDienogeste = Boolean(dados.usoDienogeste);
    var usoAhc = Boolean(dados.usoAhc);
    var cirurgiaPrevia = Boolean(dados.cirurgiaPrevia);
    var numCirurgiasPrevias = parseInt(dados.numCirurgiasPrevias, 10) || (cirurgiaPrevia ? 1 : 0);

    // ─────────────────────────────────────────────────────────────────────────
    // A. Contabilização e Estratificação dos Sintomas (Os "6 Ds")
    // ─────────────────────────────────────────────────────────────────────────
    var contagem6Ds = 0;
    var listaSintomasPresentes = [];

    if (dismenorreia) { contagem6Ds++; listaSintomasPresentes.push("Dismenorreia progressiva/incapacitante"); }
    if (dispareunia) { contagem6Ds++; listaSintomasPresentes.push("Dispareunia de profundidade"); }
    if (disquezia) { contagem6Ds++; listaSintomasPresentes.push("Disquezia cíclica (perimenstrual)"); }
    if (disuria) { contagem6Ds++; listaSintomasPresentes.push("Disúria cíclica / desconforto vesical menstrual"); }
    if (dorPelvicaCronica) { contagem6Ds++; listaSintomasPresentes.push("Dor pélvica crônica acíclica (≥ 6 meses)"); }
    if (infertilidade) { contagem6Ds++; listaSintomasPresentes.push("Dificuldade para engravidar / Infertilidade conjugal"); }

    var intensidadeDorTexto = "Não informada";
    if (evaDor >= 7) {
      intensidadeDorTexto = "DOR GRAVE / INCAPACITANTE (EVA " + evaDor + "/10)";
    } else if (evaDor >= 4) {
      intensidadeDorTexto = "DOR MODERADA (EVA " + evaDor + "/10)";
    } else if (evaDor > 0) {
      intensidadeDorTexto = "DOR LEVE (EVA " + evaDor + "/10)";
    }

    // ─────────────────────────────────────────────────────────────────────────
    // B. Auditoria de Red Flags (Critérios de Alarme Cirúrgico / Emergencial)
    // ─────────────────────────────────────────────────────────────────────────
    var redFlags = [];
    var indicacaoCirurgicaUrgente = false;

    if (acometimentoUreteral || hidronefrose) {
      redFlags.push({
        orgao: "Trato Urinário (Ureter / Rim)",
        achado: hidronefrose ? "Hidronefrose / Pielocaliectasia diagnosticada" : "Envolvimento de ureter por endometriose profunda retroperitoneal",
        risco: "Risco iminente de perda silenciosa e irreversível da função renal ipsilateral.",
        conduta: "Indicação cirúrgica obrigatória de desobstrução (ureterólise vs reimplante ureterovesical com duplo J) em conjunto com Urologia."
      });
      indicacaoCirurgicaUrgente = true;
    }

    if (acometimentoIntestinal && (estenoseIntestinal >= 50 || sintomasSuboclusivos)) {
      redFlags.push({
        orgao: "Trato Gastrointestinal (Retossigmoide)",
        achado: "Estenose luminal retossigmoídea significativa (≥ 50%) ou sintomas suboclusivos mecânicos",
        risco: "Risco de obstrução intestinal mecânica completa.",
        conduta: "Avaliação cirúrgica compartilhada com Coloproctologia (shaving, ressecção discoide ou ressecção segmentar de reto/sigmoide com margens seguras)."
      });
      indicacaoCirurgicaUrgente = true;
    }

    if (endometrioma && endometriomaCm >= 4.0) {
      redFlags.push({
        orgao: "Anexo Ovariano",
        achado: "Endometrioma volumoso (≥ " + endometriomaCm.toFixed(1) + " cm)",
        risco: "Risco aumentado de torção anexial, rotura espontânea e dano tecidual ovariano.",
        conduta: "Avaliação cuidadosa. Se cirurgia for indicada, atentar estritamente para o risco de falência ovariana prematura pós-cistectomia."
      });
    }

    // ─────────────────────────────────────────────────────────────────────────
    // C. Tomada de Decisão: Desejo Reprodutivo vs Cirurgia vs Fármacos
    // ─────────────────────────────────────────────────────────────────────────
    var condutaInvestigativa = [];
    var condutaFarmacologica = [];
    var planoCirurgico = [];
    var planoReprodutivo = [];
    var alertasSeguranca = [];

    // 1. Investigação por Imagem
    if (!imagemRealizada) {
      alertasSeguranca.push("Mapeamento incompleto: Exames ginecológicos convencionais sem preparo falham em detectar até 80% das lesões profundas.");
      condutaInvestigativa.push("Solicitar IMEDIATAMENTE Mapeamento de Alta Resolução por profissionais experientes: USG Transvaginal com preparo intestinal prévio e/ou Ressonância Magnética (RM) de pelve com protocolo específico para endometriose profunda.");
    }

    // 2. PACIENTE COM DESEJO DE ENGRAVIDAR ATUALMENTE
    if (desejoGestacional) {
      alertasSeguranca.push("🚨 BLOQUEIO MANDATÓRIO DE TRATAMENTO HORMONAL: Não prescrever Dienogeste, AHC, SIU-LNG ou análogos de GnRH para pacientes tentando engravidar ativamente. A supressão hormonal impede a gestação e NÃO melhora taxas de gravidez espontânea após a descontinuação (Diretriz ESHRE).");

      var orientarFivPrecoce = false;
      var motivosFiv = [];

      if (idade >= 35) {
        orientarFivPrecoce = true;
        motivosFiv.push("Idade materna avançada (≥ 35 anos) associada a declínio fisiológico da qualidade oocitária");
      }
      if (tempoInfertilidadeAnos >= 2) {
        orientarFivPrecoce = true;
        motivosFiv.push("Infertilidade prolongada (≥ 2 anos)");
      }
      if (amh > 0 && amh < 1.1) {
        orientarFivPrecoce = true;
        motivosFiv.push("Reserva ovariana diminuída comprovada por AMH baixo (" + amh.toFixed(2) + " ng/mL < 1.1 ng/mL)");
      }
      if (profunda && (obliteracaoDouglas || acometimentoIntestinal || acometimentoUreteral)) {
        orientarFivPrecoce = true;
        motivosFiv.push("Endometriose profunda extensa com provável distorção da anatomia pélvica e fator tuboperitoneal severo");
      }
      if (numCirurgiasPrevias >= 1 && endometrioma) {
        orientarFivPrecoce = true;
        motivosFiv.push("Histórico de cirurgia ovariana prévia: nova cistectomia ovariana impõe altíssimo risco de insuficiência ovariana prematura");
      }

      planoReprodutivo.push("1. Avaliação Obrigatória da Reserva Ovariana: Solicitar dosagem de AMH (Hormônio Antimülleriano) e Contagem de Folículos Antrais (CFA) por USG transvaginal.");
      planoReprodutivo.push("2. Avaliação do Fator Masculino: Espermograma completo do parceiro antes de qualquer decisão intervencionista.");

      if (orientarFivPrecoce) {
        planoReprodutivo.push("3. 🎯 CONDUTA REPRODUTIVA DE 1ª LINHA: Indicação DIRETA de Reprodução Assistida de Alta Complexidade (Fertilização in Vitro - FIV).");
        planoReprodutivo.push("   Motivos para FIV imediata: " + motivosFiv.join("; ") + ".");
        planoReprodutivo.push("4. Prevenção de Dano Iatrogênico: Evitar cirurgias ovarianas repetidas, que reduzem dramaticamente o número de oócitos recuperáveis.");
        if (endometrioma && !indicacaoCirurgicaUrgente) {
          planoReprodutivo.push("5. Conduta em Endometrioma assintomático ou oligosintomático: Não operar apenas para 'melhorar taxas de FIV'. Proceder à punção folicular com profilaxia antibiótica.");
        }
      } else {
        planoReprodutivo.push("3. Paciente jovem (< 35 anos) com reserva ovariana preservada (AMH > 1.5 ng/mL), espermograma normal e doença leve/moderada:");
        planoReprodutivo.push("   - Se laparoscopia for realizada para dor: lise de aderências e ressecção completa dos implantes restaura a anatomia e aumenta as taxas de gestação natural nos primeiros 6-12 meses pós-operatórios.");
        planoReprodutivo.push("   - Tentar concepção espontânea ou indução de ovulação/inseminação intrauterina por no máximo 6 a 12 meses. Se não engravidar, migrar para FIV.");
      }

      // Se cirurgia ovariana for inevitável em paciente com desejo gestacional
      if (endometrioma && (indicacaoCirurgicaUrgente || evaDor >= 8)) {
        planoReprodutivo.push("⚠️ PRESERVAÇÃO DE FERTILIDADE: Recomenda-se fortemente Criopreservação de Oócitos pré-operatória antes de cistectomia ovariana (especialmente em casos bilaterais).");
      }

    } else {
      // 3. PACIENTE SEM DESEJO REPRODUTIVO ATUAL (FOCO: ALÍVIO DA DOR E CONTROLE DA DOENÇA)
      
      // Avaliação de 1ª vs 2ª Linha Farmacológica
      var refratariaPrimeiraLinha = falhaDienogeste || (falhaAhc && evaDor >= 7);

      if (indicacaoCirurgicaUrgente) {
        condutaFarmacologica.push("🚨 CONDUTA CIRÚRGICA PRIORITÁRIA DEVIDO A RED FLAGS: Paciente apresenta complicações anatômicas graves (ureteral/intestinal). O tratamento exclusivamente clínico é insuficiente.");
      } else if (refratariaPrimeiraLinha) {
        condutaFarmacologica.push("💊 ESCALONAMENTO PARA 2ª LINHA FARMACOLÓGICA (Falha / Intolerância à 1ª Linha):");
        condutaFarmacologica.push("Opção A (Antagonista oral de GnRH de última geração): " + CATALOGO_FARMACOLOGICO.SEGUNDA_LINHA.ANTAGONISTAS_GNRH.RELUGOLIX_COMBINADO.farmaco + " - " + CATALOGO_FARMACOLOGICO.SEGUNDA_LINHA.ANTAGONISTAS_GNRH.RELUGOLIX_COMBINADO.posologia + ". Vantagem: Rápido bloqueio hormonal sem efeito flare-up, com Add-Back incorporada.");
        condutaFarmacologica.push("Opção B (Análogo agonista de GnRH de depósito): " + CATALOGO_FARMACOLOGICO.SEGUNDA_LINHA.ANALOGOS_GNRH.GOSSERRELINA.farmaco + " - " + CATALOGO_FARMACOLOGICO.SEGUNDA_LINHA.ANALOGOS_GNRH.GOSSERRELINA.posologia + ".");
        condutaFarmacologica.push("⚠️ REGRA DE SEGURANÇA MANDATÓRIA: Add-Back Therapy OBRIGATÓRIA se uso de agonista de GnRH > 3 a 6 meses para prevenir perda de densidade mineral óssea e fogachos severos.");
        condutaFarmacologica.push("Opção Cirúrgica Eletiva: Laparoscopia / Robótica se dor persistente com prejuízo de qualidade de vida a despeito da 2ª linha.");
      } else {
        condutaFarmacologica.push("💊 1ª LINHA FARMACOLÓGICA (Padrão ESHRE / FEBRASGO):");
        
        if (adenomiose) {
          condutaFarmacologica.push("1ª Escolha Preferencial (Endometriose + Adenomiose): " + CATALOGO_FARMACOLOGICO.PRIMEIRA_LINHA.SIU_LEVONORGESTREL.farmaco + " (" + CATALOGO_FARMACOLOGICO.PRIMEIRA_LINHA.SIU_LEVONORGESTREL.posologia + ") OU Dienogeste 2 mg/dia.");
        } else {
          condutaFarmacologica.push("1ª Escolha Padrão-Ouro: " + CATALOGO_FARMACOLOGICO.PRIMEIRA_LINHA.DIENOGESTE.farmaco + " — Posologia: " + CATALOGO_FARMACOLOGICO.PRIMEIRA_LINHA.DIENOGESTE.posologia + ".");
          condutaFarmacologica.push("Mecanismo e Justificativa: " + CATALOGO_FARMACOLOGICO.PRIMEIRA_LINHA.DIENOGESTE.mecanismo);
          condutaFarmacologica.push("Alternativa: " + CATALOGO_FARMACOLOGICO.PRIMEIRA_LINHA.SIU_LEVONORGESTREL.farmaco + " ou " + CATALOGO_FARMACOLOGICO.PRIMEIRA_LINHA.AHC_CONTINUO.farmaco + ".");
        }

        condutaFarmacologica.push("Seguimento: Reavaliar sintomatologia clínica em 3 a 6 meses. O tratamento deve ser mantido a longo prazo até a menopausa ou até a paciente desejar engravidar.");
      }

      // Analgesia de Suporte
      condutaFarmacologica.push("Analgesia Aguda de Resgate: " + CATALOGO_FARMACOLOGICO.ANALGESIA_ADJUVANTE.AINES);
      if (dorPelvicaCronica || evaDor >= 7) {
        condutaFarmacologica.push("Manejo da Sensibilização Central da Dor: " + CATALOGO_FARMACOLOGICO.ANALGESIA_ADJUVANTE.NEUROMODULADORES);
      }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // D. Planejamento Cirúrgico e Critérios Multidisciplinares
    // ─────────────────────────────────────────────────────────────────────────
    if (indicacaoCirurgicaUrgente || evaDor >= 8 || falhaDienogeste || (endometrioma && endometriomaCm >= 4.0)) {
      planoCirurgico.push("Critérios de Encaminhamento ao Especialista: Indicada avaliação ginecológica cirúrgica especializada devido a " + (indicacaoCirurgicaUrgente ? "SINAIS DE ALARME (Red Flag orgânico/obstrutivo)." : (falhaDienogeste ? "refratariedade à terapia hormonal de 1ª linha." : (evaDor >= 8 ? "dor incapacitante severa (EVA >= 8)." : "endometrioma volumoso >= 4 cm."))));
      planoCirurgico.push("Abordagem Especializada: Equipe multidisciplinar com foco na preservação funcional/nervosa (nerve-sparing) e prevenção de lesão iatrogênica.");
      if (endometrioma) {
        planoCirurgico.push("Conduta em Endometrioma: Cistectomia conservadora com preservação máxima do parênquima ovariano são e da reserva folicular (evitar eletrocoagulação agressiva do leito).");
      }
      if (acometimentoIntestinal) {
        planoCirurgico.push("Acometimento Intestinal: Avaliação conjunta com Coloproctologia para definir ressecção conservadora (shaving/discoide) ou segmentar.");
      }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // E. Cuidados Não Farmacológicos e Multidisciplinares
    // ─────────────────────────────────────────────────────────────────────────
    var suporteMultidisciplinar = [
      "Fisioterapia Pélvica especializada: Essencial para reabilitação do assoalho pélvico hiperativo, alívio de dor miofascial e melhora da dispareunia.",
      "Acompanhamento Nutricional: Dieta anti-inflamatória com redução de ultraprocessados, suporte à microbiota intestinal.",
      "Acompanhamento Psicológico: Suporte cognitivo-comportamental para manejo do impacto crônico da dor e qualidade de vida."
    ];

    // Resumo Diagnóstico
    var diagnostico = {
      suspeitaClinica: contagem6Ds >= 2 || evaDor >= 5,
      classificacaoSintomas: {
        total6Ds: contagem6Ds,
        lista: listaSintomasPresentes,
        intensidadeDor: intensidadeDorTexto,
        eva: evaDor
      },
      topografia: {
        imagemRealizada: imagemRealizada,
        superficial: superficial,
        endometrioma: endometrioma,
        endometriomaTamanhoCm: endometriomaCm,
        endometriomaBilateral: endometriomaBilateral,
        profunda: profunda,
        adenomiose: adenomiose,
        compartimentoAnterior: { bexiga: bexiga, ureter: acometimentoUreteral, hidronefrose: hidronefrose },
        compartimentoPosterior: { ligamentosUterossacros: ligamentosUterossacros, toroUterino: toroUterino, septoRetovaginal: septoRetovaginal, obliteracaoDouglas: obliteracaoDouglas, retossigmoide: acometimentoIntestinal, estenosePercentual: estenoseIntestinal }
      },
      redFlags: redFlags,
      indicacaoCirurgicaUrgente: indicacaoCirurgicaUrgente
    };

    return {
      sucesso: true,
      diagnostico: diagnostico,
      alertas: alertasSeguranca,
      condutaInvestigativa: condutaInvestigativa,
      condutaFarmacologica: condutaFarmacologica,
      planoReprodutivo: planoReprodutivo,
      planoCirurgico: planoCirurgico,
      suporteMultidisciplinar: suporteMultidisciplinar,
      diretrizes: "Diretrizes ESHRE (2022/2024), FEBRASGO (2024-2026), Consenso AAGL (2021)"
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 3. PARSER DE LINGUAGEM NATURAL E COMANDO TELEGRAM
  // ───────────────────────────────────────────────────────────────────────────

  function extrairParametrosTexto(texto) {
    texto = (texto || '').toString().toLowerCase();

    // Idade
    var matchIdade = texto.match(/(?:idade\s*[:=]?\s*|(\d{1,2})\s*anos)/i);
    var idade = matchIdade ? parseInt(matchIdade[1] || matchIdade[0].replace(/\D/g, ''), 10) : 0;

    // Dor / EVA
    var matchEva = texto.match(/(?:eva\s*[:=]?\s*|dor\s*[:=]?\s*)(\d{1,2})/i);
    var evaDor = matchEva ? parseFloat(matchEva[1]) : 0;
    if (evaDor === 0) {
      if (/dor (grave|severa|insuportavel|incapacitante)/i.test(texto)) evaDor = 8;
      else if (/dor (moderada|intensa)/i.test(texto)) evaDor = 6;
      else if (/dor leve/i.test(texto)) evaDor = 3;
    }

    // Sintomas dos 6 Ds
    var dismenorreia = /dismenor|colica/i.test(texto);
    var dispareunia = /dispareun|dor na relacao|profundidade/i.test(texto);
    var disquezia = /disquez|dor ao evacuar|dor evacuat/i.test(texto);
    var disuria = /disur|dor ao urinar/i.test(texto);
    var dorPelvicaCronica = /cronica|dor pelvica|dpc|aciclica/i.test(texto);
    var infertilidade = /infertil|esteril|nao engravida|dificuldade para engravidar/i.test(texto);
    
    // Desejo reprodutivo
    var desejoGestacional = /desejo (gestacional|reprodutivo)|tentando engravidar|quer engravidar|engravidar/i.test(texto);

    // Tempo de infertilidade
    var matchTempoInf = texto.match(/(\d+)\s*anos?\s*(?:de\s*)?infertil/i);
    var tempoInfertilidadeAnos = matchTempoInf ? parseFloat(matchTempoInf[1]) : (infertilidade ? 1 : 0);

    // AMH e CFA
    var matchAmh = texto.match(/amh\s*[:=]?\s*(\d+[\.,]?\d*)/i);
    var amh = matchAmh ? parseFloat(matchAmh[1].replace(',', '.')) : 0;

    var matchCfa = texto.match(/cfa\s*[:=]?\s*(\d+)/i);
    var cfa = matchCfa ? parseInt(matchCfa[1], 10) : 0;

    // Imagem / Topografia
    var usgComPreparo = /usg com preparo|ultrassom com preparo|preparo intestinal/i.test(texto);
    var rmPelve = /rm|ressonancia|rnm/i.test(texto);
    var tipoExame = usgComPreparo ? "USG Transvaginal com preparo intestinal" : (rmPelve ? "RM de Pelve com protocolo para endometriose" : "");

    var endometrioma = /endometrioma|cisto endometr/i.test(texto);
    var matchTamanhoEndo = texto.match(/endometrioma[^\d]*(\d+[\.,]?\d*)\s*(cm|mm)?/i) || texto.match(/(\d+[\.,]?\d*)\s*(?:cm|mm)\s*(?:no\s*)?ovario/i);
    var endometriomaTamanhoCm = 0;
    if (matchTamanhoEndo) {
      var val = parseFloat(matchTamanhoEndo[1].replace(',', '.'));
      var unidade = (matchTamanhoEndo[2] || '').toLowerCase();
      if (unidade === 'mm' || val > 15) {
        endometriomaTamanhoCm = val / 10.0;
      } else {
        endometriomaTamanhoCm = val;
      }
      endometrioma = true;
    }
    var endometriomaBilateral = /bilateral|ambos os ovarios/i.test(texto);

    // Compartimentos profundos
    var acometimentoUreteral = /ureter|ureteral|hidronefrose/i.test(texto);
    var hidronefrose = /hidronefrose|pielocaliectasia/i.test(texto);
    var acometimentoIntestinal = /retossigmoide|reto|sigmoide|intestinal/i.test(texto);
    var matchEstenose = texto.match(/estenose\s*[:=]?\s*(\d+)%?/i);
    var estenoseIntestinalPercentual = matchEstenose ? parseFloat(matchEstenose[1]) : (/estenose (significativa|severa|grave)/i.test(texto) ? 50 : 0);
    var sintomasSuboclusivos = /suboclus|oclusao/i.test(texto);
    var ligamentosUterossacros = /uterossacr|ligamento/i.test(texto);
    var toroUterino = /toro/i.test(texto);
    var obliteracaoDouglas = /douglas|obliteracao/i.test(texto);
    var septoRetovaginal = /septo/i.test(texto);
    var bexiga = /bexiga|vesical/i.test(texto);
    var adenomiose = /adenomiose/i.test(texto);

    // Fármacos prévios
    var falhaDienogeste = /falha (do|de)?\s*dienogeste|refrataria ao dienogeste/i.test(texto);
    var usoDienogeste = /uso de dienogeste|dienogeste/i.test(texto) && !falhaDienogeste;
    var falhaAhc = /falha (do|de)?\s*aco|falha (do|de)?\s*ahc/i.test(texto);
    var cirurgiaPrevia = /cirurgia previa|cistectomia previa|laparoscopia previa/i.test(texto);

    return {
      idade: idade,
      evaDor: evaDor,
      dismenorreia: dismenorreia,
      dispareunia: dispareunia,
      disquezia: disquezia,
      disuria: disuria,
      dorPelvicaCronica: dorPelvicaCronica,
      infertilidade: infertilidade,
      tempoInfertilidadeAnos: tempoInfertilidadeAnos,
      desejoGestacional: desejoGestacional,
      amh: amh,
      cfa: cfa,
      tipoExame: tipoExame,
      usgComPreparo: usgComPreparo,
      rmPelve: rmPelve,
      endometrioma: endometrioma,
      endometriomaTamanhoCm: endometriomaTamanhoCm,
      endometriomaBilateral: endometriomaBilateral,
      acometimentoUreteral: acometimentoUreteral,
      hidronefrose: hidronefrose,
      acometimentoIntestinal: acometimentoIntestinal,
      estenoseIntestinalPercentual: estenoseIntestinalPercentual,
      sintomasSuboclusivos: sintomasSuboclusivos,
      ligamentosUterossacros: ligamentosUterossacros,
      toroUterino: toroUterino,
      obliteracaoDouglas: obliteracaoDouglas,
      septoRetovaginal: septoRetovaginal,
      bexiga: bexiga,
      adenomiose: adenomiose,
      falhaDienogeste: falhaDienogeste,
      usoDienogeste: usoDienogeste,
      falhaAhc: falhaAhc,
      cirurgiaPrevia: cirurgiaPrevia
    };
  }

  function formatarTextoTelegram(resultado) {
    if (!resultado || !resultado.diagnostico) {
      return "⚠️ Erro ao processar dados de endometriose.";
    }

    var diag = resultado.diagnostico;
    var texto = "🌸 *MÓDULO DE ENDOMETRIOSE E DOR PÉLVICA CRÔNICA*\n";
    texto += "*(Diretrizes ESHRE 2022-2024 / FEBRASGO 2024-2026)*\n\n";

    texto += "📋 *ESTRATIFICAÇÃO CLÍNICA & SINTOMATOLOGIA (6 Ds):*\n";
    texto += "• *Dor / Intensidade:* " + diag.classificacaoSintomas.intensidadeDor + "\n";
    texto += "• *Sintomas Cardinais Presentes:* " + diag.classificacaoSintomas.total6Ds + " de 6\n";
    for (var i = 0; i < diag.classificacaoSintomas.lista.length; i++) {
      texto += "  - " + diag.classificacaoSintomas.lista[i] + "\n";
    }

    texto += "\n🗺️ *MAPEAMENTO TOPOGRÁFICO DE IMAGEM:*\n";
    if (diag.topografia.endometrioma) {
      texto += "• *Endometrioma:* Sim (" + (diag.topografia.endometriomaTamanhoCm > 0 ? diag.topografia.endometriomaTamanhoCm.toFixed(1) + " cm" : "diâmetro não especificado") + (diag.topografia.endometriomaBilateral ? ", bilateral" : "") + ")\n";
    }
    if (diag.topografia.profunda) {
      texto += "• *Endometriose Profunda:* Presente\n";
      if (diag.topografia.compartimentoAnterior.ureter || diag.topografia.compartimentoAnterior.hidronefrose) {
        texto += "  - Ureter/Rim: Envolvimento ureteral (" + (diag.topografia.compartimentoAnterior.hidronefrose ? "COM hidronefrose" : "sem hidronefrose relatada") + ")\n";
      }
      if (diag.topografia.compartimentoPosterior.retossigmoide) {
        texto += "  - Retossigmoide: Acometimento intestinal (" + (diag.topografia.compartimentoPosterior.estenosePercentual > 0 ? diag.topografia.compartimentoPosterior.estenosePercentual + "% estenose" : "infiltração parietal") + ")\n";
      }
      if (diag.topografia.compartimentoPosterior.ligamentosUterossacros) {
        texto += "  - Ligamentos úterossacros envolvidos\n";
      }
      if (diag.topografia.compartimentoPosterior.obliteracaoDouglas) {
        texto += "  - Obliteração de fundo de saco de Douglas\n";
      }
    }
    if (diag.topografia.adenomiose) {
      texto += "• *Adenomiose Concomitante:* Presente\n";
    }

    if (resultado.alertas && resultado.alertas.length > 0) {
      texto += "\n⚠️ *ALERTAS CRÍTICOS & SEGURANÇA:*\n";
      for (var a = 0; a < resultado.alertas.length; a++) {
        texto += "• " + resultado.alertas[a] + "\n";
      }
    }

    if (diag.redFlags && diag.redFlags.length > 0) {
      texto += "\n🚨 *RED FLAGS / ALARME CIRÚRGICO:*\n";
      for (var r = 0; r < diag.redFlags.length; r++) {
        var rf = diag.redFlags[r];
        texto += "• *" + rf.orgao + ":* " + rf.achado + "\n";
        texto += "  ↳ *Risco:* " + rf.risco + "\n";
        texto += "  ↳ *Conduta:* " + rf.conduta + "\n";
      }
    }

    if (resultado.planoReprodutivo && resultado.planoReprodutivo.length > 0) {
      texto += "\n👶 *CONDUTA REPRODUTIVA & FERTILIDADE:*\n";
      for (var p = 0; p < resultado.planoReprodutivo.length; p++) {
        texto += resultado.planoReprodutivo[p] + "\n";
      }
    }

    if (resultado.condutaFarmacologica && resultado.condutaFarmacologica.length > 0) {
      texto += "\n💊 *CONDUTA FARMACOLÓGICA ESCALONADA:*\n";
      for (var c = 0; c < resultado.condutaFarmacologica.length; c++) {
        texto += "• " + resultado.condutaFarmacologica[c] + "\n";
      }
    }

    if (resultado.planoCirurgico && resultado.planoCirurgico.length > 0) {
      texto += "\n🚨 *CRITÉRIOS DE ENCAMINHAMENTO CIRÚRGICO / ESPECIALIZADO:*\n";
      for (var s = 0; s < resultado.planoCirurgico.length; s++) {
        texto += "• " + resultado.planoCirurgico[s] + "\n";
      }
    }

    texto += "\n🩺 *CONDUTA BEIRA-LEITO / UBS (MÉDICO GENERALISTA):*\n";
    texto += "• *Alívio Imediato da Dor:* Analgesia escalonada (Dipirona 1g VO/IV + AINEs em cursos curtos de 3-5 dias nas crises) sem retardar supressão hormonal.\n";
    texto += "• *Terapia Empírica de 1ª Linha:* Iniciar precocemente Progestagênio contínuo (Dienogeste 2 mg/dia contínuo ou Desogestrel 75 mcg/dia no SUS). Não aguardar confirmação cirúrgica/laparoscópica para tratar a dor.\n";
    texto += "• *Orientação à Paciente:* Informar que USG pélvico/transvaginal comum normal NÃO exclui endometriose peritoneal. Solicitar USG com preparo intestinal prévio ou RM de pelve com protocolo dedicado.\n";

    texto += "\n🌱 *SUPORTE MULTIDISCIPLINAR:*\n";
    for (var m = 0; m < resultado.suporteMultidisciplinar.length; m++) {
      texto += "• " + resultado.suporteMultidisciplinar[m] + "\n";
    }

    return texto;
  }

  function processarComandoTelegram(texto) {
    var params = extrairParametrosTexto(texto);
    var resultado = avaliarEndometriose(params);
    return formatarTextoTelegram(resultado);
  }

  return {
    avaliar: avaliarEndometriose,
    avaliarEndometriose: avaliarEndometriose,
    extrairParametrosTexto: extrairParametrosTexto,
    formatarTextoTelegram: formatarTextoTelegram,
    processarComandoTelegram: processarComandoTelegram,
    CATALOGO_FARMACOLOGICO: CATALOGO_FARMACOLOGICO
  };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = GinecologiaEndometrioseService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_hematologia_anemias.js
// ==============================================================================

/**
 * ═══════════════════════════════════════════════════════════════════════════════
 * MÓDULO 02: HEMATOLOGIA CLÍNICA — MANEJO E INVESTIGAÇÃO DE ANEMIAS
 * ═══════════════════════════════════════════════════════════════════════════════
 * Motor Determinístico Beira-Leito para Diagnóstico e Manejo de Anemias:
 *  1. Análise Automatizada do Hemograma (Critérios OMS / MS / ABHH)
 *  2. Classificação Morfológica por Índices Hematimétricos (VCM, HCM, CHCM, RDW)
 *  3. Diagnóstico Diferencial de Microcitose (Índice de Mentzer e Green & King)
 *  4. Avaliação Cinética e Resposta Medular (Índice de Produção Reticulocitária - IPR)
 *  5. Integração com Marcadores Bioquímicos (Ferritina, SatTransferrina, B12, Folato, Hemólise)
 *  6. Calculadora de Reposição de Ferro Oral (VO) com Tetos Seguros de Hepcidina e Tolerância
 *  7. Critérios Formais e Fórmula de Ganzoni para Ferro Endovenoso (Noripurum IV / Venofer)
 *  8. Gatilhos Transfusionais Restritivos Beira-Leito e Bloqueios de Segurança
 *
 * REFERÊNCIAS CLÍNICAS OFICIAIS:
 *  - Organização Mundial da Saúde (OMS) - Haemoglobin concentrations for the diagnosis of anaemia (2024-2026)
 *  - Associação Brasileira de Hematologia, Hemoterapia e Terapia Celular (ABHH) - Diretrizes de Anemia Ferropriva
 *  - Sociedade Brasileira de Pediatria (SBP) - Departamento de Hematologia e Nutrologia (2021-2026)
 *  - Ministério da Saúde do Brasil - PCDT da Anemia por Deficiência de Ferro
 *  - American Society of Hematology (ASH) / British Society of Gastroenterology (BSG) Iron Deficiency Guidelines
 *  - Ganzoni AM. "Intravenous iron-dextran: therapeutic and experimental aspects." (Schweiz Med Wochenschr 1970)
 * ═══════════════════════════════════════════════════════════════════════════════
 */

var HematologiaAnemiasService = (function () {
  'use strict';

  var EPS = 1e-9;

  // ───────────────────────────────────────────────────────────────────────────
  // 1. LIMITES DE HEMOGLOBINA E CONSTANTES (OMS / MS / ABHH)
  // ───────────────────────────────────────────────────────────────────────────
  var LIMITES_HB = {
    ADULTO_MASCULINO: 13.0,
    ADULTO_FEMININO: 12.0,
    GESTANTE_GERAL: 11.0,
    GESTANTE_2TRI: 10.5,
    PEDIATRICO_6M_59M: 11.0,
    PEDIATRICO_5A_11A: 11.5,
    PEDIATRICO_12A_14A: 12.0,
    LACTENTE_2M_6M: 9.5
  };

  // ───────────────────────────────────────────────────────────────────────────
  // 2. FUNÇÕES AUXILIARES DE DETERMINAÇÃO DE PERFIL
  // ───────────────────────────────────────────────────────────────────────────
  function inferirLimiteHb(params) {
    params = params || {};
    var idadeAnos = typeof params.idadeAnos === 'number' ? params.idadeAnos : null;
    var idadeMeses = typeof params.idadeMeses === 'number' ? params.idadeMeses : null;
    if (idadeAnos === null && idadeMeses !== null) {
      idadeAnos = idadeMeses / 12;
    }

    var sexo = String(params.sexo || '').toUpperCase();
    var ehGestante = Boolean(params.gestante || params.gestacao || params.ehGestante);
    var trimestre = parseInt(params.trimestre || params.trimestreGestacional, 10);

    // Gestante
    if (ehGestante) {
      if (trimestre === 2) {
        return { perfil: 'Gestante (2º Trimestre)', limiteMinimoHb: LIMITES_HB.GESTANTE_2TRI, alvoHbGanzoni: 14.0 };
      }
      return { perfil: 'Gestante (1º ou 3º Trimestre)', limiteMinimoHb: LIMITES_HB.GESTANTE_GERAL, alvoHbGanzoni: 14.0 };
    }

    // Pediátrico por idade
    if (idadeAnos !== null) {
      if (idadeAnos < 0.5) {
        return { perfil: 'Lactente jovem (2 a 6 meses)', limiteMinimoHb: LIMITES_HB.LACTENTE_2M_6M, alvoHbGanzoni: 12.0 };
      }
      if (idadeAnos >= 0.5 && idadeAnos < 5) {
        return { perfil: 'Criança (6 meses a 4 anos e 11 meses)', limiteMinimoHb: LIMITES_HB.PEDIATRICO_6M_59M, alvoHbGanzoni: 12.0 };
      }
      if (idadeAnos >= 5 && idadeAnos < 12) {
        return { perfil: 'Criança (5 a 11 anos)', limiteMinimoHb: LIMITES_HB.PEDIATRICO_5A_11A, alvoHbGanzoni: 13.0 };
      }
      if (idadeAnos >= 12 && idadeAnos < 15) {
        return { perfil: 'Adolescente (12 a 14 anos)', limiteMinimoHb: LIMITES_HB.PEDIATRICO_12A_14A, alvoHbGanzoni: 13.5 };
      }
    }

    // Adulto por sexo
    if (sexo === 'F' || sexo === 'FEM' || sexo === 'FEMININO' || sexo === 'MULHER') {
      return { perfil: 'Mulher Adulta não-gestante', limiteMinimoHb: LIMITES_HB.ADULTO_FEMININO, alvoHbGanzoni: 14.0 };
    }

    // Padrão masculino / adulto geral
    return { perfil: 'Homem Adulto', limiteMinimoHb: LIMITES_HB.ADULTO_MASCULINO, alvoHbGanzoni: 15.0 };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 3. ANÁLISE MORFOLÓGICA E CINÉTICA DO HEMOGRAMA
  // ───────────────────────────────────────────────────────────────────────────
  function interpretarHemogramaAnemia(params) {
    params = params || {};
    var hb = parseFloat(params.hb || params.hemoglobina);
    if (isNaN(hb) || hb <= 0) {
      throw new Error('Hemoglobina (Hb) válida é obrigatória para interpretação.');
    }

    var ht = parseFloat(params.ht || params.hematocrito);
    var htEstimado = false;
    if (isNaN(ht) || ht <= 0) {
      ht = Math.round(hb * 3 * 10) / 10;
      htEstimado = true;
    }

    var vcm = parseFloat(params.vcm);
    var hcm = parseFloat(params.hcm);
    var chcm = parseFloat(params.chcm);
    var rdw = parseFloat(params.rdw);
    var hemacias = parseFloat(params.hemacias || params.rbc || params.eritrocitos); // em milhões/mcL
    var reticulocitosPct = parseFloat(params.reticulocitos || params.reticulocitosPct);

    var infoPerfil = inferirLimiteHb(params);
    var limiteMinimoHb = infoPerfil.limiteMinimoHb;
    var temAnemia = hb < limiteMinimoHb;

    // Severidade da Anemia
    var severidade = 'NORMAL';
    var descricaoSeveridade = 'Hemoglobina dentro dos parâmetros de normalidade para a faixa etária/perfil.';
    if (temAnemia) {
      if (hb <= 6.5) {
        severidade = 'CRITICA';
        descricaoSeveridade = 'Anemia Crítica / Severa Acentuada com risco de hipóxia tecidual e descompensação hemodinâmica.';
      } else if (hb < 8.0) {
        severidade = 'GRAVE';
        descricaoSeveridade = 'Anemia Grave (Hb < 8.0 g/dL). Avaliar estabilidade hemodinâmica e gatilhos transfusionais.';
      } else if (hb < 10.0) {
        severidade = 'MODERADA';
        descricaoSeveridade = 'Anemia Moderada (Hb entre 8.0 e 9.9 g/dL). Necessita investigação etiológica e tratamento imediato.';
      } else {
        severidade = 'LEVE';
        descricaoSeveridade = 'Anemia Leve (Hb entre 10.0 g/dL e o limite inferior do perfil).';
      }
    }

    // Classificação Morfológica (VCM)
    var classificacaoVcm = 'INDEFINIDA';
    var descVcm = 'VCM não informado.';
    if (!isNaN(vcm)) {
      if (vcm < 80) {
        classificacaoVcm = 'MICROCITICA';
        descVcm = 'Microcitose (VCM < 80 fL): redução no volume dos eritrócitos.';
      } else if (vcm > 100) {
        classificacaoVcm = 'MACROCITICA';
        descVcm = 'Macrocitose (VCM > 100 fL): hemácias aumentadas de tamanho.';
      } else {
        classificacaoVcm = 'NORMOCITICA';
        descVcm = 'Normocitose (VCM entre 80 e 100 fL): volume eritrocitário preservado.';
      }
    }

    // Classificação de Cromia (HCM / CHCM)
    var classificacaoCromia = 'INDEFINIDA';
    var descCromia = 'Índices de cromia (HCM/CHCM) não informados.';
    if (!isNaN(hcm) || !isNaN(chcm)) {
      var ehHipo = (!isNaN(hcm) && hcm < 27) || (!isNaN(chcm) && chcm < 32);
      var ehHiper = (!isNaN(chcm) && chcm > 36) || (!isNaN(hcm) && hcm > 33);
      if (ehHipo) {
        classificacaoCromia = 'HIPOCROMICA';
        descCromia = 'Hipocromia (HCM < 27 pg ou CHCM < 32 g/dL): eritrócitos com menor conteúdo hemoglobínico.';
      } else if (ehHiper) {
        classificacaoCromia = 'HIPERCROMICA';
        descCromia = 'Hipercromia (CHCM > 36 g/dL): sugere esferocitose hereditária ou presença de crioaglutininas.';
      } else {
        classificacaoCromia = 'NORMOCROMICA';
        descCromia = 'Normocromia (HCM 27-33 pg e CHCM 32-36 g/dL): coloração eritrocitária fisiológica.';
      }
    }

    // Análise de Anisocitose (RDW)
    var classificacaoRdw = 'INDEFINIDA';
    var descRdw = 'RDW não informado.';
    if (!isNaN(rdw)) {
      if (rdw > 14.5) {
        classificacaoRdw = 'HETEROGENEA';
        descRdw = 'Anisocitose acentuada (RDW > 14.5%): alta variabilidade no tamanho das hemácias (típico de carência nutricional ou resposta medular).';
      } else {
        classificacaoRdw = 'HOMOGENEA';
        descRdw = 'População eritrocitária homogênea (RDW <= 14.5%): tamanho uniforme das hemácias.';
      }
    }

    // Índices de Diagnóstico Diferencial na Microcitose (Mentzer e Green & King)
    var mentzer = null;
    var interpretacaoMentzer = null;
    if (!isNaN(vcm) && !isNaN(hemacias) && hemacias > 0) {
      var valMentzer = Math.round((vcm / hemacias) * 10) / 10;
      mentzer = valMentzer;
      if (valMentzer < 13) {
        interpretacaoMentzer = {
          indice: valMentzer,
          padrao: 'SUGESTAO_TALASSEMIA_MENOR',
          texto: 'Índice de Mentzer < 13 (' + valMentzer + '): Sugere fortemente Traço Talassêmico (Talassemia Menor). Produção de muitas hemácias pequenas com contagem elevada para o grau de anemia.'
        };
      } else {
        interpretacaoMentzer = {
          indice: valMentzer,
          padrao: 'SUGESTAO_ANEMIA_FERROPRIVA',
          texto: 'Índice de Mentzer >= 13 (' + valMentzer + '): Sugere fortemente Anemia Ferropriva. A deficiência de substrato limita a contagem de hemácias proporcionalmente ao seu tamanho.'
        };
      }
    }

    var greenKing = null;
    var interpretacaoGreenKing = null;
    if (!isNaN(vcm) && !isNaN(rdw) && !isNaN(hb) && hb > 0) {
      var valGk = Math.round(((vcm * vcm * rdw) / (100 * hb)) * 10) / 10;
      greenKing = valGk;
      if (valGk < 65) {
        interpretacaoGreenKing = {
          indice: valGk,
          padrao: 'SUGESTAO_TALASSEMIA_MENOR',
          texto: 'Índice de Green & King < 65 (' + valGk + '): Favorece Traço Talassêmico.'
        };
      } else if (valGk > 72) {
        interpretacaoGreenKing = {
          indice: valGk,
          padrao: 'SUGESTAO_ANEMIA_FERROPRIVA',
          texto: 'Índice de Green & King > 72 (' + valGk + '): Favorece Anemia Ferropriva.'
        };
      } else {
        interpretacaoGreenKing = {
          indice: valGk,
          padrao: 'INDETERMINADO',
          texto: 'Índice de Green & King na faixa intermediária 65-72 (' + valGk + '): Zona cinzenta, correlacionar com ferritina e cinética de ferro.'
        };
      }
    }

    // Cinética Medular: Reticulócitos e IPR (Índice de Produção Reticulocitária)
    var analiseReticulocitaria = null;
    if (!isNaN(reticulocitosPct)) {
      var htNormal = 45;
      var reticCorrigidos = Math.round((reticulocitosPct * (ht / htNormal)) * 100) / 100;
      var shiftFactor = 1.0;
      if (ht < 15) shiftFactor = 2.5;
      else if (ht < 25) shiftFactor = 2.0;
      else if (ht < 35) shiftFactor = 1.5;

      var ipr = Math.round((reticCorrigidos / shiftFactor) * 100) / 100;
      var ehRegenerativa = ipr > 2.0;

      analiseReticulocitaria = {
        reticulocitosPct: reticulocitosPct,
        reticulocitosCorrigidosPct: reticCorrigidos,
        shiftFactor: shiftFactor,
        ipr: ipr,
        tipoResposta: ehRegenerativa ? 'REGENERATIVA_HIPERPROLIFERATIVA' : 'HIPOPROLIFERATIVA_ARREGENERATIVA',
        conclusao: ehRegenerativa
          ? 'Anemia Regenerativa / Hiperproliferativa (IPR > 2.0 = ' + ipr + '). Medula óssea íntegra com resposta eritropoietica acelerada: investigar Sangramento Agudo Recente ou Hemólise.'
          : 'Anemia Hipoproliferativa / Arregenerativa (IPR <= 2.0 = ' + ipr + '). Resposta medular inadequada ou deficiência de substratos: sugere carência de Ferro/B12/Folato, Anemia de Doença Crônica, Insuficiência Renal ou falência medular.'
      };
    }

    // Hipóteses Diagnósticas Principais e Raciocínio Clínico Integrado
    var hipoteses = [];
    var investigacaoRecomendada = [];
    var alertasClinicos = [];

    if (!temAnemia) {
      hipoteses.push({
        diagnostico: 'Hemograma sem anemia evidente',
        probabilidade: 'Alta',
        detalhe: 'Hb (' + hb + ' g/dL) acima do corte do perfil (' + limiteMinimoHb + ' g/dL).'
      });
      if (classificacaoVcm === 'MICROCITICA') {
        hipoteses.push({
          diagnostico: 'Microcitose isolada sem anemia',
          probabilidade: 'Moderada',
          detalhe: 'Possível depleção inicial de ferro (estágio pré-anêmico) ou traço talassêmico assintomático.'
        });
        investigacaoRecomendada.push('Dosar Ferritina Sérica para descartar ferropenia latente.');
      }
    } else {
      // Cenários de Anemia
      if (classificacaoVcm === 'MICROCITICA') {
        if (classificacaoRdw === 'HETEROGENEA' || (mentzer && mentzer >= 13)) {
          hipoteses.push({
            diagnostico: 'Anemia Ferropriva (Deficiência de Ferro)',
            probabilidade: 'Alta',
            detalhe: 'Microcítica e hipocrômica com anisocitose/Mentzer >= 13. Causa mais prevalente no mundo.'
          });
        }
        if (classificacaoRdw === 'HOMOGENEA' || (mentzer && mentzer < 13)) {
          hipoteses.push({
            diagnostico: 'Talassemia Menor (Traço Talassêmico Alfa ou Beta)',
            probabilidade: 'Alta',
            detalhe: 'Microcitose com RDW homogêneo e Mentzer < 13. Investigar com Eletroforese de Hemoglobina.'
          });
        }
        hipoteses.push({
          diagnostico: 'Anemia de Doença Crônica / Inflamatória (fase avançada)',
          probabilidade: 'Moderada',
          detalhe: 'Pode se apresentar microcítica e hipocrômica por bloqueio da ferroportina via hepcidina elevada.'
        });
        investigacaoRecomendada.push('Cinética de Ferro completa: Ferritina sérica, Ferro sérico, Saturação de Transferrina e TIBC.');
        investigacaoRecomendada.push('Eletroforese de Hemoglobina em pH alcalino (quantificação de HbA2 e HbF).');
      } else if (classificacaoVcm === 'MACROCITICA') {
        hipoteses.push({
          diagnostico: 'Anemia Megaloblástica (Deficiência de Vitamina B12 ou Folato)',
          probabilidade: 'Alta',
          detalhe: 'Macrocitose acentuada. Avaliar neutrófilos hipersegmentados, gastrite atrófica, metformina, IBP ou etilismo.'
        });
        hipoteses.push({
          diagnostico: 'Anemia Não-Megaloblástica (Hepatopatia crônica, Etilismo, Hipotireoidismo, Mielodisplasia)',
          probabilidade: 'Moderada',
          detalhe: 'VCM aumentado secundário à alteração de membrana eritrocitária ou mielotoxicidade.'
        });
        if (analiseReticulocitaria && analiseReticulocitaria.tipoResposta === 'REGENERATIVA_HIPERPROLIFERATIVA') {
          hipoteses.push({
            diagnostico: 'Reticulocitose Marcada (pseudo-macrocitose)',
            probabilidade: 'Alta',
            detalhe: 'Reticulócitos jovens são maiores que hemácias maduras e elevam o VCM mensurado.'
          });
        }
        investigacaoRecomendada.push('Dosagem sérica de Vitamina B12 e Ácido Fólico.');
        investigacaoRecomendada.push('Avaliação de função tireoidiana (TSH, T4 livre) e função hepática (TGO, TGP, Gama-GT).');
        investigacaoRecomendada.push('Hematoscopia de sangue periférico para busca de neutrófilos hipersegmentados.');
      } else {
        // NORMOCÍTICA
        hipoteses.push({
          diagnostico: 'Anemia de Doença Crônica / Inflamação Sistêmica',
          probabilidade: 'Alta',
          detalhe: 'Padrão clássico normocítico/normocrômico associado a infecções, neoplasias ou doenças autoimunes.'
        });
        hipoteses.push({
          diagnostico: 'Anemia da Doença Renal Crônica (Déficit de Eritropoietina)',
          probabilidade: 'Moderada',
          detalhe: 'Avaliar Creatinina, Taxa de Filtração Glomerular (ClCr) e clearance renal.'
        });
        hipoteses.push({
          diagnostico: 'Hemorragia Aguda Recente (Perda Sanguínea Oculta ou Digestiva)',
          probabilidade: 'Moderada',
          detalhe: 'Normocítica e normocrômica com reticulocitose compensatória nas primeiras 48-72h.'
        });
        hipoteses.push({
          diagnostico: 'Anemia Hemolítica (Autoimune ou Microangiopática)',
          probabilidade: analiseReticulocitaria && analiseReticulocitaria.tipoResposta === 'REGENERATIVA_HIPERPROLIFERATIVA' ? 'Alta' : 'Moderada',
          detalhe: 'Acompanhada de elevação de LDH, bilirrubina indireta e queda de haptoglobina.'
        });
        hipoteses.push({
          diagnostico: 'Anemia Mista (Carência combinada de Ferro e B12/Folato)',
          probabilidade: 'Moderada',
          detalhe: 'A microcitose do ferro e a macrocitose da B12 se anulam no VCM médio, gerando RDW muito aumentado.'
        });
        investigacaoRecomendada.push('Proteína C Reativa (PCR), VHS, Creatinina e Ureia.');
        investigacaoRecomendada.push('Painel de Hemólise: Bilirrubinas total e frações, DHL/LDH, Haptoglobina e Teste de Coombs Direto.');
      }
    }

    // Integração com Exames Bioquímicos caso fornecidos
    var achadosBioquimicos = [];
    var ferritina = parseFloat(params.ferritina);
    var satTransf = parseFloat(params.saturacaoTransferrina || params.satTransferrina);
    var vitB12 = parseFloat(params.vitaminaB12 || params.b12);
    var folato = parseFloat(params.acidoFolico || params.folato);

    if (!isNaN(ferritina)) {
      if (ferritina < 30) {
        achadosBioquimicos.push('Ferritina Baixa (< 30 ng/mL = ' + ferritina + ' ng/mL): Confirma depleção absoluta de reservas corporais de ferro (Anemia Ferropriva).');
      } else if (ferritina >= 30 && ferritina < 100) {
        achadosBioquimicos.push('Ferritina limítrofe (' + ferritina + ' ng/mL): Em estados inflamatórios, valores até 100 ng/mL ainda podem representar deficiência real de ferro.');
      } else {
        achadosBioquimicos.push('Ferritina elevada (> 100 ng/mL = ' + ferritina + ' ng/mL): Reservas de ferro aparentemente preservadas ou proteína de fase aguda elevada por inflamação sistêmica.');
      }
    }

    if (!isNaN(satTransf)) {
      if (satTransf < 20) {
        achadosBioquimicos.push('Saturação de Transferrina Baixa (< 20% = ' + satTransf + '%): Indica aporte insuficiente de ferro circulante para a eritropoiese.');
      } else {
        achadosBioquimicos.push('Saturação de Transferrina Adequada (>= 20% = ' + satTransf + '%).');
      }
    }

    if (!isNaN(vitB12)) {
      if (vitB12 < 200) {
        achadosBioquimicos.push('Vitamina B12 Baixa (< 200 pg/mL = ' + vitB12 + ' pg/mL): Confirma deficiência grave de cobalamina. Risco de dano neurológico irreversível.');
      } else if (vitB12 >= 200 && vitB12 <= 350) {
        achadosBioquimicos.push('Vitamina B12 Limítrofe (200-350 pg/mL = ' + vitB12 + ' pg/mL): Sugere-se dosagem de Ácido Metilmalônico e Homocisteína séricos.');
      }
    }

    if (!isNaN(folato) && folato < 4.0) {
      achadosBioquimicos.push('Ácido Fólico Baixo (< 4.0 ng/mL = ' + folato + ' ng/mL): Deficiência de folato confirmada.');
    }

    // Gatilhos Transfusionais
    var gatilhoTransfusional = {
      indicado: false,
      alvoHb: '7.0 a 9.0 g/dL',
      orientacao: 'Paciente clinicamente estável: manter estratégia transfusional restritiva. Tratar causa de base.'
    };

    if (hb < 7.0) {
      gatilhoTransfusional.indicado = true;
      gatilhoTransfusional.orientacao = 'GATILHO ATINGIDO (Hb < 7.0 g/dL): Indicação de Concentrado de Hemácias (CHAD) para a maioria dos pacientes hospitalizados estáveis em enfermaria ou UTI (Estratégia Restritiva Padrão-Ouro). 1 bolsa de CHAD eleva Hb em ~1 g/dL e Ht em ~3%.';
      alertasClinicos.push('Hb < 7.0 g/dL: Gatilho para transfusão de concentrado de hemácias ativado.');
    } else if (hb < 8.0 && (params.cardiopatiaIsquemica || params.sca || params.infarto || params.posOperatorioCardiovascular)) {
      gatilhoTransfusional.indicado = true;
      gatilhoTransfusional.alvoHb = '8.0 a 10.0 g/dL';
      gatilhoTransfusional.orientacao = 'GATILHO ATINGIDO PARA CARDIOPATA (Hb < 8.0 g/dL): Paciente com Síndrome Coronariana Aguda ou pós-operatório cardiovascular tem alvo restritivo estendido para manter Hb >= 8.0 g/dL para prevenir isquemia miocárdica.';
      alertasClinicos.push('Paciente com cardiopatia isquêmica e Hb < 8.0 g/dL: Indicação de CHAD.');
    }

    if (hb < 6.0) {
      alertasClinicos.push('ALERTA VERMELHO: Hb crítica (< 6.0 g/dL). Risco iminente de isquemia de órgãos nobres, acidose lática e colapso circulatório. Transfusão prioritária e monitorização contínua.');
    }

    return {
      sucesso: true,
      perfil: infoPerfil.perfil,
      limiteMinimoHb: limiteMinimoHb,
      hb: hb,
      ht: ht,
      htEstimado: htEstimado,
      temAnemia: temAnemia,
      severidade: severidade,
      descricaoSeveridade: descricaoSeveridade,
      morfologia: {
        vcm: vcm,
        classificacaoVcm: classificacaoVcm,
        descVcm: descVcm,
        hcm: hcm,
        chcm: chcm,
        classificacaoCromia: classificacaoCromia,
        descCromia: descCromia,
        rdw: rdw,
        classificacaoRdw: classificacaoRdw,
        descRdw: descRdw
      },
      indicesEspeciais: {
        mentzer: mentzer,
        interpretacaoMentzer: interpretacaoMentzer,
        greenKing: greenKing,
        interpretacaoGreenKing: interpretacaoGreenKing
      },
      cineticaReticulocitaria: analiseReticulocitaria,
      achadosBioquimicos: achadosBioquimicos,
      hipotesesDiagnosticas: hipoteses,
      investigacaoRecomendada: investigacaoRecomendada,
      gatilhoTransfusional: gatilhoTransfusional,
      alertasClinicos: alertasClinicos
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 4. CALCULADORA DE REPOSIÇÃO DE FERRO ORAL E INTRAVENOSO (FÓRMULA DE GANZONI)
  // ───────────────────────────────────────────────────────────────────────────
  function calcularReposicaoFerro(params) {
    params = params || {};
    var pesoKg = parseFloat(params.pesoKg || params.peso);
    if (isNaN(pesoKg) || pesoKg <= 0) {
      throw new Error('Peso corporal (kg) é obrigatório para cálculo posológico de ferro.');
    }

    var hbAtual = parseFloat(params.hbAtual || params.hb || params.hemoglobina);
    if (isNaN(hbAtual) || hbAtual <= 0) {
      throw new Error('Hemoglobina atual (g/dL) é obrigatória.');
    }

    var infoPerfil = inferirLimiteHb(params);
    var hbAlvo = parseFloat(params.hbAlvo);
    if (isNaN(hbAlvo) || hbAlvo <= 0) {
      hbAlvo = infoPerfil.alvoHbGanzoni;
    }

    var idadeAnos = typeof params.idadeAnos === 'number' ? params.idadeAnos : null;
    var ehPediatrico = (idadeAnos !== null && idadeAnos < 12) || pesoKg < 35;
    var ehGestante = Boolean(params.gestante || params.gestacao || params.ehGestante);

    // ─────────────────────────────────────────────────────────
    // 4.1. CÁLCULO DA FÓRMULA DE GANZONI (FERRO ENDOVENOSO)
    // ─────────────────────────────────────────────────────────
    // Déficit Total (mg) = [Peso (kg) × (Hb Alvo - Hb Atual) × 2.4] + Reserva de Ferro (mg)
    var deltaHb = Math.max(0, hbAlvo - hbAtual);
    var reservaFerroMg = 500; // Padrão adulto >= 35 kg
    if (pesoKg < 35 || ehPediatrico) {
      reservaFerroMg = Math.round(15 * pesoKg); // 15 mg/kg em crianças e < 35 kg
    }

    // Fator 2.4 = 0.08 (vol sangue L/kg) * 0.34 (ferro na Hb %) * 100 (conversão de unidades)
    var deficitHbMg = Math.round(pesoKg * deltaHb * 2.4);
    var deficitTotalGanzoniMg = deficitHbMg + reservaFerroMg;

    // Noripurum IV / Sacarato de Hidróxido de Ferro III: 100 mg por ampola de 5 mL (20 mg/mL)
    var ampolas100mgTotal = Math.ceil(deficitTotalGanzoniMg / 100);
    // Dose máxima por aplicação: 200 mg (2 ampolas) infundidas em SF 0.9% 100-200 mL em 30-60 min
    var maxDoseSessaoMg = 200;
    if (pesoKg < 35) {
      maxDoseSessaoMg = Math.min(200, Math.round(7 * pesoKg)); // máx ~7 mg/kg por infusão em pediatria
    }
    var sessoesNecessarias = Math.ceil(deficitTotalGanzoniMg / maxDoseSessaoMg);

    // ─────────────────────────────────────────────────────────
    // 4.2. CRITÉRIOS DE INDICAÇÃO PARA FERRO INTRAVENOSO (IV)
    // ─────────────────────────────────────────────────────────
    var criteriosIv = [];
    var indicacaoIvForte = false;

    var motivoIv = String(params.motivoIv || '').toLowerCase();
    var comorbidades = Array.isArray(params.comorbidades) ? params.comorbidades.map(function(c){ return String(c).toLowerCase(); }) : [];

    if (motivoIv.includes('intoleran') || comorbidades.includes('intolerancia_vo')) {
      criteriosIv.push('Intolerância gastrointestinal grave ou refratária ao ferro oral (náuseas, vômitos incoercíveis, dor epigástrica incapacitante).');
      indicacaoIvForte = true;
    }
    if (motivoIv.includes('bariat') || comorbidades.includes('bariatrica') || comorbidades.includes('pos_bariatrica')) {
      criteriosIv.push('Pós-operatório de Cirurgia Bariátrica disabsortiva (bypass gástrico em Y-de-Roux ou duodenal switch com perda de duodeno/jejuno proximal para absorção).');
      indicacaoIvForte = true;
    }
    if (motivoIv.includes('dii') || motivoIv.includes('crohn') || motivoIv.includes('retocolite') || comorbidades.includes('dii')) {
      criteriosIv.push('Doença Inflamatória Intestinal ativa (DII - Doença de Crohn ou RCUI) onde ferro oral causa toxicidade mucosa e tem absorção bloqueada.');
      indicacaoIvForte = true;
    }
    if (motivoIv.includes('celiac') || comorbidades.includes('doenca_celiaca')) {
      criteriosIv.push('Doença Celíaca com atrofia vilosa duodenal severa e má absorção comprovada.');
      indicacaoIvForte = true;
    }
    if (ehGestante && (hbAtual < 9.0 || params.trimestreGestacional >= 2 || motivoIv.includes('gestan'))) {
      criteriosIv.push('Gestante no 2º ou 3º trimestre com anemia moderada a severa (necessidade de rápida repleção antes do parto com janela de tempo curta).');
      indicacaoIvForte = true;
    }
    if (comorbidades.includes('drc') || comorbidades.includes('hemodialise') || motivoIv.includes('renal')) {
      criteriosIv.push('Doença Renal Crônica em estágio IV-V ou em Hemodiálise com uso de Agentes Estimuladores da Eritropoiese (EPO).');
      indicacaoIvForte = true;
    }
    if (comorbidades.includes('icc') || comorbidades.includes('icfer') || motivoIv.includes('insuficiencia_cardiaca')) {
      criteriosIv.push('Insuficiência Cardíaca com Fração de Ejeção Reduzida (ICFEr / NYHA II-IV) e deficiência de ferro (estudos FAIR-HF / CONFIRM-HF demonstrando melhora de sobrevida e capacidade funcional).');
      indicacaoIvForte = true;
    }
    if (motivoIv.includes('sangramento_ativo') || motivoIv.includes('perda_cronica')) {
      criteriosIv.push('Sangramento contínuo que excede a capacidade de absorção fisiológica da mucosa intestinal (ex: angiodisplasia, Rendu-Osler-Weber).');
      indicacaoIvForte = true;
    }

    if (criteriosIv.length === 0) {
      criteriosIv.push('Sem contraindicação expressa ao ferro oral; tentar 1ª linha com via oral antes da indicação venosa, salvo piora sintomática ou má absorção documentada.');
    }

    // ─────────────────────────────────────────────────────────
    // 4.3. POSOLOGIA DO FERRO ORAL (VO)
    // ─────────────────────────────────────────────────────────
    var esquemaVo = {};
    if (ehPediatrico) {
      // 3 a 5 mg/kg/dia de ferro elementar
      var dosePediatricaMgDia = Math.round(3 * pesoKg);
      var dosePediatricaSeveraMgDia = Math.round(5 * pesoKg);
      // Teto máximo pediátrico: 60 mg/dia
      var doseFinalPediatrica = Math.min(60, dosePediatricaMgDia);
      var doseFinalSevera = Math.min(60, dosePediatricaSeveraMgDia);

      // Sulfato ferroso gotas (25 mg Fe/mL ~ 20 gotas = ~1.25 mg Fe/gota)
      var gotasSulfato = Math.round(doseFinalPediatrica / 1.25);
      // Noripurum gotas (50 mg Fe/mL ~ 20 gotas = 2.5 mg Fe/gota)
      var gotasNoripurum = Math.round(doseFinalPediatrica / 2.5);

      esquemaVo = {
        populacao: 'Pediátrica (SBP / MS)',
        doseRecomendadaMgKgDia: '3 a 5 mg/kg/dia de Ferro Elementar',
        doseCalculadaMgDia: doseFinalPediatrica,
        doseSeveraMgDia: doseFinalSevera,
        tetoSegurancaMgDia: 60,
        fracionamento: '1 a 2 vezes ao dia, preferencialmente 1h antes das refeições ou com suco de fruta cítrica (vitamina C).',
        opcoesPrescricao: [
          'Sulfato Ferroso gotas (25 mg Fe/mL): prescrever ' + gotasSulfato + ' gotas via oral 1 vez ao dia (ou fracionado em 2 tomadas).',
          'Ferropolimaltose / Noripurum gotas (50 mg Fe/mL): prescrever ' + gotasNoripurum + ' gotas via oral 1 vez ao dia (pode ser administrado junto ou após as refeições).'
        ],
        duracaoTratamento: 'Manter por 3 a 6 meses após a normalização da hemoglobina para reconstituir os estoques de ferritina.'
      };
    } else {
      // Adulto / Gestante: Evidência moderna preconiza 60 a 100 mg de Fe elementar/dia ou em dias alternados
      esquemaVo = {
        populacao: ehGestante ? 'Gestante' : 'Adulto Geral',
        doseRecomendadaMgDia: '60 a 100 mg de Ferro Elementar ao dia (ou 100 a 200 mg em dias alternados)',
        tetoSegurancaMgDia: 200,
        racionalCientifico: 'Doses elevadas (> 200 mg/dia) causam pico imediato de Hepcidina sérica que bloqueia a ferroportina e anula a absorção intestinal nas 24-48h seguintes, além de maximizar eventos gastrointestinais (dor epigástrica, náuseas, constipação). A administração em dose única matinal ou em dias alternados maximiza a absorção fracionada com excelente tolerabilidade.',
        opcoesPrescricao: [
          'Sulfato Ferroso 300 mg drágeas (~60 mg de Fe elementar): Tomar 1 drágea ao dia pela manhã em jejum com água ou suco de laranja/limão.',
          'Sulfato Ferroso 200 mg comprimidos (~40 mg de Fe elementar): Tomar 1 a 2 comprimidos ao dia pela manhã.',
          'Ferropolimaltose (Noripurum VO) 100 mg comprimidos mastigáveis: Tomar 1 comprimido ao dia durante a refeição principal (excelente tolerância gastrointestinal).'
        ],
        orientacoesPaciente: [
          'Tomar com água ou suco cítrico rico em vitamina C (aumenta absorção intestinal).',
          'NÃO ingerir junto com leite, queijo, iogurte, antiácidos, cálcio, café ou chá preto (quelam o ferro e impedem absorção). Manter intervalo mínimo de 2 horas.',
          'Alerte o paciente de que as fezes ficarão escurecidas (efeito inócuo esperado do ferro não absorvido).'
        ],
        duracaoTratamento: 'Continuar o tratamento por no mínimo 3 a 6 meses após a normalização da Hb, até atingir Ferritina sérica > 50-100 ng/mL.'
      };
    }

    // ─────────────────────────────────────────────────────────
    // 4.4. PRESCRIÇÃO E PROTOCOLO DO FERRO INTRAVENOSO (NORIPURUM IV)
    // ─────────────────────────────────────────────────────────
    var esquemaIv = {
      droga: 'Sacarato de Óxido de Ferro III (Noripurum IV / Venofer)',
      apresentacao: 'Ampola de 5 mL contendo 100 mg de Ferro Elementar (20 mg/mL)',
      deficitTotalGanzoniMg: deficitTotalGanzoniMg,
      reservaEstoqueMg: reservaFerroMg,
      deficitPorHbMg: deficitHbMg,
      deltaHb: Math.round(deltaHb * 10) / 10,
      hbAlvoGanzoni: hbAlvo,
      hbAtual: hbAtual,
      totalAmpolasNecessarias: ampolas100mgTotal,
      dosePorSessaoMg: maxDoseSessaoMg,
      ampolasPorSessao: Math.round(maxDoseSessaoMg / 100),
      totalSessoes: sessoesNecessarias,
      diluicaoRecomendada: maxDoseSessaoMg + ' mg (' + Math.round(maxDoseSessaoMg / 100) + ' ampolas de 5 mL) diluídos em 100 mL a 200 mL de Soro Fisiológico 0.9% (NUNCA usar Soro Glicosado 5% pela instabilidade físico-química da solução coloidal).',
      tempoInfusao: 'Infundir por via intravenosa estrita em no mínimo 30 a 60 minutos, com vazão controlada em bomba de infusão.',
      frequencia: 'Administrar 2 a 3 vezes por semana (em dias alternados, ex: Seg-Qua-Sex) até atingir a dose cumulativa total de ' + deficitTotalGanzoniMg + ' mg.',
      bloqueiosESeguranca: (function () {
        var b = [
          'CONTRAINDICAÇÃO FORMAL NO 1º TRIMESTRE DE GESTAÇÃO (seguro no 2º e 3º trimestres).',
          'SUSPENDER FERRO ORAL durante todo o tratamento com ferro intravenoso (evitar saturação reticuloendotelial desnecessária).',
          'CUIDADO RIGOROSO COM EXTRAVASAMENTO: o ferro fora da veia causa hiperpigmentação dérmica marrom permanente ("tatuagem") e necrose tecidual inflamatória local. Testar patência do acesso venoso com SF 0.9% antes da infusão.',
          'MONITORIZAÇÃO DE HIPERSENSIBILIDADE: monitorar sinais vitais nos primeiros 15 minutos de infusão (risco de hipotensão, rubor facial e broncoespasmo).'
        ];
        if (pesoKg > 150) {
          b.unshift('⚠️ OBESIDADE SEVERA (> 150 kg): O cálculo pelo peso real superestima o volume sanguíneo e o déficit de ferro pela fórmula de Ganzoni. Recomenda-se utilizar o Peso Ideal (IBW) ou Peso Ajustado para evitar sobrecarga tecidual de ferro.');
        }
        if (pesoKg < 1.0) {
          b.unshift('⚠️ RECÉM-NASCIDO PREMATURO EXTREMO (< 1 kg): Sacarato de ferro IV não é rotineiramente recomendado. A suplementação é realizada via enteral com gotas (2 a 4 mg/kg/dia) após tolerância alimentar plena atingida (SBP).');
        }
        if (hbAtual <= 4.0) {
          b.unshift('🚨 HEMOGLOBINA CRÍTICA / EXTREMA (Hb ≤ 4.0 g/dL): Risco iminente de colapso circulatório anóxico e parada cardíaca. A reposição de ferro IV NÃO supre a emergência imediata; acionar Concentrado de Hemácias (CHAD) de urgência com monitorização em UTI.');
        }
        return b;
      })()
    };

    return {
      sucesso: true,
      pesoKg: pesoKg,
      hbAtual: hbAtual,
      hbAlvo: hbAlvo,
      indicacaoIvForte: indicacaoIvForte,
      criteriosIv: criteriosIv,
      esquemaVo: esquemaVo,
      esquemaIv: esquemaIv
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 5. RESUMO CLÍNICO UNIFICADO (BEIRA-LEITO & TELEGRAM)
  // ───────────────────────────────────────────────────────────────────────────
  function gerarRelatorioCompleto(params) {
    params = params || {};
    var analiseHemograma = interpretarHemogramaAnemia(params);
    var reposicao = null;

    if (params.pesoKg || params.peso) {
      try {
        reposicao = calcularReposicaoFerro(params);
      } catch (e) {
        reposicao = null;
      }
    }

    var linhas = [];
    linhas.push('🩸 *MÓDULO DE HEMATOLOGIA: INVESTIGAÇÃO & MANEJO DE ANEMIAS*');
    linhas.push('────────────────────────────────────────');
    linhas.push('👤 *Perfil:* ' + analiseHemograma.perfil);
    linhas.push('🔬 *Hemoglobina (Hb):* ' + analiseHemograma.hb + ' g/dL | *Hematócrito (Ht):* ' + analiseHemograma.ht + '%' + (analiseHemograma.htEstimado ? ' _(estimado)_' : ''));
    linhas.push('📊 *Status:* *' + (analiseHemograma.temAnemia ? 'ANEMIA DETECTADA (' + analiseHemograma.severidade + ')' : 'SEM ANEMIA') + '*');
    linhas.push('ℹ️ _' + analiseHemograma.descricaoSeveridade + '_');
    linhas.push('');

    // Morfologia
    linhas.push('📐 *ÍNDICES ERITROCITÁRIOS & MORFOLOGIA:*');
    linhas.push('• *VCM:* ' + (isNaN(analiseHemograma.morfologia.vcm) ? 'Não informado' : analiseHemograma.morfologia.vcm + ' fL (' + analiseHemograma.morfologia.classificacaoVcm + ')'));
    if (!isNaN(analiseHemograma.morfologia.hcm)) {
      linhas.push('• *HCM:* ' + analiseHemograma.morfologia.hcm + ' pg | *CHCM:* ' + (isNaN(analiseHemograma.morfologia.chcm) ? '-' : analiseHemograma.morfologia.chcm + ' g/dL') + ' (' + analiseHemograma.morfologia.classificacaoCromia + ')');
    }
    if (!isNaN(analiseHemograma.morfologia.rdw)) {
      linhas.push('• *RDW:* ' + analiseHemograma.morfologia.rdw + '% (' + analiseHemograma.morfologia.classificacaoRdw + ')');
    }

    // Mentzer e Green-King
    if (analiseHemograma.indicesEspeciais.interpretacaoMentzer) {
      linhas.push('• *Índice de Mentzer:* ' + analiseHemograma.indicesEspeciais.mentzer + ' → _' + analiseHemograma.indicesEspeciais.interpretacaoMentzer.texto + '_');
    }
    if (analiseHemograma.indicesEspeciais.interpretacaoGreenKing) {
      linhas.push('• *Índice Green & King:* ' + analiseHemograma.indicesEspeciais.greenKing + ' → _' + analiseHemograma.indicesEspeciais.interpretacaoGreenKing.texto + '_');
    }
    linhas.push('');

    // Cinética Reticulocitária
    if (analiseHemograma.cineticaReticulocitaria) {
      linhas.push('⚡ *CINÉTICA & RESPOSTA MEDULAR (RETICULÓCITOS):*');
      linhas.push('• *Reticulócitos:* ' + analiseHemograma.cineticaReticulocitaria.reticulocitosPct + '% | *Retic. Corrigidos:* ' + analiseHemograma.cineticaReticulocitaria.reticulocitosCorrigidosPct + '%');
      linhas.push('• *IPR (Índice Produção Reticulocitária):* ' + analiseHemograma.cineticaReticulocitaria.ipr + ' (*' + analiseHemograma.cineticaReticulocitaria.tipoResposta + '*)');
      linhas.push('• _' + analiseHemograma.cineticaReticulocitaria.conclusao + '_');
      linhas.push('');
    }

    // Hipóteses Diagnósticas
    linhas.push('🎯 *HIPÓTESES DIAGNÓSTICAS PRINCIPAIS:*');
    for (var i = 0; i < analiseHemograma.hipotesesDiagnosticas.length; i++) {
      var h = analiseHemograma.hipotesesDiagnosticas[i];
      linhas.push('• *' + h.diagnostico + '* (' + h.probabilidade + '): ' + h.detalhe);
    }
    linhas.push('');

    // Gatilho Transfusional
    if (analiseHemograma.gatilhoTransfusional.indicado) {
      linhas.push('🚨 *GATILHO TRANSFUSIONAL (CHAD):*');
      linhas.push('⚠️ ' + analiseHemograma.gatilhoTransfusional.orientacao);
      linhas.push('');
    }

    // Reposição de Ferro se calculada
    if (reposicao && reposicao.sucesso) {
      linhas.push('💊 *TERAPIA COM FERRO & FÓRMULA DE GANZONI:*');
      linhas.push('• *Peso:* ' + reposicao.pesoKg + ' kg | *Hb Alvo:* ' + reposicao.hbAlvo + ' g/dL');
      linhas.push('• *Déficit Total de Ferro (Ganzoni):* *' + reposicao.esquemaIv.deficitTotalGanzoniMg + ' mg* (Hb: ' + reposicao.esquemaIv.deficitPorHbMg + ' mg + Estoque: ' + reposicao.esquemaIv.reservaEstoqueMg + ' mg)');
      linhas.push('• *Total de Ampolas Noripurum IV (100mg/5mL):* *' + reposicao.esquemaIv.totalAmpolasNecessarias + ' ampolas*');
      linhas.push('• *Cronograma IV:* ' + reposicao.esquemaIv.totalSessoes + ' sessões de ' + reposicao.esquemaIv.dosePorSessaoMg + ' mg (' + reposicao.esquemaIv.ampolasPorSessao + ' ampolas) em 100-200 mL SF 0.9% 2-3x/semana.');
      linhas.push('');
      linhas.push('🌿 *Esquema Oral de 1ª Linha:* ' + reposicao.esquemaVo.opcoesPrescricao[0]);
      linhas.push('🛡️ _Teto seguro diário de Fe elementar: ' + reposicao.esquemaVo.tetoSegurancaMgDia + ' mg/dia (prevenção de bloqueio por hepcidina e intolerância gastrointestinal)._');
      linhas.push('');
    }

    // Alertas
    if (analiseHemograma.alertasClinicos.length > 0) {
      linhas.push('⚠️ *ALERTAS DE SEGURANÇA BEIRA-LEITO:*');
      for (var a = 0; a < analiseHemograma.alertasClinicos.length; a++) {
        linhas.push('• ' + analiseHemograma.alertasClinicos[a]);
      }
    }

    var textoFormatado = linhas.join('\n');

    return {
      sucesso: true,
      analiseHemograma: analiseHemograma,
      reposicaoFerro: reposicao,
      textoFormatado: textoFormatado
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 6. FORMATADOR PARA TELEGRAM
  // ───────────────────────────────────────────────────────────────────────────
  function formatarTextoTelegram(resultado) {
    if (!resultado || !resultado.sucesso) {
      return '❌ Erro ao processar avaliação de anemia.';
    }
    return resultado.textoFormatado;
  }

  // ───────────────────────────────────────────────────────────────────────────
  // 7. MÉTODOS UTILITÁRIOS DETERMINÍSTICOS BEIRA-LEITO
  // ───────────────────────────────────────────────────────────────────────────

  function classificarGravidadeAnemia(hb, perfilOpcoes) {
    var opts = perfilOpcoes || {};
    var info = inferirLimiteHb(opts);
    var limiteMinimo = info.limiteMinimoHb;
    var valorHb = parseFloat(hb);
    var temAnemia = valorHb < limiteMinimo;
    var gravidade = 'Sem Anemia';
    var riscoCritico = false;

    if (temAnemia) {
      if (valorHb < 6.0) {
        gravidade = 'Muito Grave / Crítica';
        riscoCritico = true;
      } else if (valorHb < 8.0) {
        gravidade = 'Grave / Severa';
        riscoCritico = true;
      } else if (valorHb < 10.0) {
        gravidade = 'Moderada';
      } else {
        gravidade = 'Leve';
      }
    }

    return {
      temAnemia: temAnemia,
      hb: valorHb,
      limiarNormal: limiteMinimo,
      deficitHb: temAnemia ? Math.round((limiteMinimo - valorHb) * 10) / 10 : 0,
      grupoDescricao: info.perfil,
      gravidade: gravidade,
      riscoCritico: riscoCritico
    };
  }

  function classificarMorfologia(vcm, hcm, chcm, rdw) {
    var v = parseFloat(vcm);
    var h = parseFloat(hcm);
    var c = parseFloat(chcm);
    var r = parseFloat(rdw);

    var tamanho = 'Normocítica';
    if (!isNaN(v)) {
      if (v < 80) tamanho = 'Microcítica';
      else if (v > 100) tamanho = 'Macrocítica';
    }

    var cor = 'Normocrômica';
    if ((!isNaN(h) && h < 27) || (!isNaN(c) && c < 32)) {
      cor = 'Hipocrômica';
    } else if (!isNaN(c) && c > 36) {
      cor = 'Hipercrômica';
    }

    var anisocitose = (!isNaN(r) && r > 14.5);
    var classificacaoCombinada = tamanho + ' ' + cor + (anisocitose ? ' com anisocitose (RDW elevado)' : ' homogênea (RDW normal)');

    var achados = [];
    if (!isNaN(v) && v > 115) {
      achados.push('Macrocitose acentuada (VCM > 115 fL): forte correlação com causa megaloblástica (B12/Folato) ou Síndrome Mielodisplásica.');
    }
    if (anisocitose) {
      achados.push('Anisocitose acentuada (RDW > 14.5%): alta variabilidade no volume eritrocitário.');
    }

    return {
      tamanho: tamanho,
      cor: cor,
      anisocitose: anisocitose,
      classificacaoCombinada: classificacaoCombinada,
      achados: achados
    };
  }

  function calcularIndiceMentzer(vcm, hemacias) {
    var v = parseFloat(vcm);
    var he = parseFloat(hemacias);
    if (isNaN(v) || isNaN(he) || he <= 0) return null;
    var valor = Math.round((v / he) * 10) / 10;
    var ehTalassemia = valor < 13;
    return {
      valor: valor,
      sugestao: ehTalassemia ? 'Traço Talassêmico (Talassemia Minor)' : 'Anemia Ferropriva',
      probabilidade: 'Elevada',
      explicacao: ehTalassemia
        ? 'Índice de Mentzer < 13 reflete microcitose com alta contagem eritrocitária ("muitas hemácias pequenas"), característico de traço talassêmico. Solicitar Eletroforese de Hemoglobina.'
        : 'Índice de Mentzer >= 13 reflete carência de substrato (ferro) que limita tanto o tamanho quanto o número de hemácias. Solicitar Ferritina e Cinética de Ferro.'
    };
  }

  function calcularGreenKing(vcm, rdw, hb) {
    var v = parseFloat(vcm);
    var r = parseFloat(rdw);
    var h = parseFloat(hb);
    if (isNaN(v) || isNaN(r) || isNaN(h) || h <= 0) return null;
    var valor = Math.round(((v * v * r) / (100 * h)) * 10) / 10;
    var padrao = valor < 72 ? 'Talassemia Minor' : 'Anemia Ferropriva';
    return {
      valor: valor,
      sugestao: padrao,
      explicacao: valor < 72
        ? 'Índice Green & King < 72 favorece fortemente Traço Talassêmico.'
        : 'Índice Green & King >= 72 favorece fortemente Anemia Ferropriva.'
    };
  }

  function calcularIPR(reticulocitosPct, ht) {
    var retic = parseFloat(reticulocitosPct);
    var htc = parseFloat(ht);
    if (isNaN(retic) || isNaN(htc) || htc <= 0) return null;
    var reticCorr = Math.round((retic * (htc / 45)) * 100) / 100;
    var factor = 1.0;
    if (htc < 15) factor = 2.5;
    else if (htc < 25) factor = 2.0;
    else if (htc < 35) factor = 1.5;
    var ipr = Math.round((reticCorr / factor) * 100) / 100;
    var regenerativa = ipr >= 2.0;
    return {
      reticulocitosPerc: retic,
      reticulocitosPct: retic,
      reticulocitosCorrigidos: reticCorr,
      fatorShift: factor,
      shiftFactor: factor,
      ipr: ipr,
      tipo: regenerativa ? 'REGENERATIVA' : 'HIPOPROLIFERATIVA',
      regenerativa: regenerativa,
      classificacao: regenerativa ? 'Hiperproliferativa / Regenerativa (IPR ≥ 2,0)' : 'Hipoproliferativa / Arregenerativa (IPR < 2,0)',
      conclusao: regenerativa
        ? 'IPR >= 2.0: Resposta medular hiperproliferativa / regenerativa adequada (Hemólise ou Sangramento Agudo recente).'
        : 'IPR < 2.0: Resposta medular hipoproliferativa / arregenerativa inadequada (Carência de Ferro/B12/Folato, Anemia de Doença Crônica ou Insuficiência Renal).'
    };
  }
  var calcularIpr = calcularIPR;

  function avaliarCineticaFerro(ferritina, ferroSerico, tibc, istInformado, contextoInflamatorio) {
    var ferr = parseFloat(ferritina);
    var fe = parseFloat(ferroSerico);
    var cap = parseFloat(tibc);
    var ist = !isNaN(parseFloat(istInformado)) ? parseFloat(istInformado) : (!isNaN(fe) && !isNaN(cap) && cap > 0 ? Math.round((fe / cap) * 1000) / 10 : null);

    var padrao = 'Indeterminado';
    var detalhes = [];

    if (!isNaN(ferr)) {
      if (ferr < 30) {
        padrao = 'Deficiência Absoluta de Ferro (Ferropenia Estrita)';
        detalhes.push('Ferritina < 30 ng/mL confirma depleção de estoques.');
      } else if (ferr > 500 || (ist !== null && ist > 50)) {
        padrao = 'Sobrecarga de Ferro / Hiperferritinemia';
        detalhes.push('Sobrecarga de ferro ou síndrome de ativação macrofágica.');
      } else if (contextoInflamatorio || ferr > 100) {
        padrao = 'Anemia de Doença Crônica / Inflamatória';
        detalhes.push('Ferritina preservada ou elevada com bloqueio reticuloendotelial.');
      }
    }

    return {
      padrao: padrao,
      ferritina: !isNaN(ferr) ? ferr : null,
      ferroSerico: !isNaN(fe) ? fe : null,
      tibc: !isNaN(cap) ? cap : null,
      ist: ist,
      detalhes: detalhes
    };
  }

  function calcularDoseFerroOral(params) {
    var p = params || {};
    var pesoKg = parseFloat(p.pesoKg || 70);
    var perfil = String(p.perfil || 'adulto').toLowerCase();
    var ehPediatrico = perfil === 'pediatria' || (p.idadeMeses !== undefined && p.idadeMeses < 144) || pesoKg < 35;

    if (ehPediatrico) {
      var doseCalc = Math.round(4 * pesoKg);
      var doseFinal = Math.min(60, doseCalc);
      return {
        doseFeElementarMgDia: doseFinal,
        gotasSulfatoPediátrico: doseFinal,
        esquemaPosologico: doseFinal + ' mg/dia de ferro elementar (' + doseFinal + ' gotas de Sulfato Ferroso)',
        orientacoes: ['Tomar 1h antes das refeições ou com suco rico em vitamina C.'],
        alertasToxicos: ['⚠️ SEGURANÇA DOMÉSTICA: Manter fora do alcance de crianças pelo risco de intoxicação acidental aguda fatal por ferro.']
      };
    }

    return {
      doseFeElementarMgDia: 80,
      esquemaPosologico: '60 a 100 mg de Ferro Elementar em DIAS ALTERNADOS (ou 60 a 120 mg/dia diário).',
      orientacoes: ['Tomar pela manhã em jejum com água ou suco rico em vitamina C.'],
      alertasToxicos: ['TETO DE TOLERÂNCIA ORAL: Doses diárias > 200 mg/dia não aumentam a absorção e geram bloqueio por hepcidina e intolerância gastrointestinal.']
    };
  }

  function calcularProfilaxiaPediatricaSBP(pesoNascimentoGramas, idadeMeses, emUsoFormulaInfantil) {
    var pesoNasc = Number(pesoNascimentoGramas);
    var idade = Number(idadeMeses || 6);

    var dose = 1.0;
    var faixa = '';
    var inicio = '';

    if (pesoNasc < 1000) {
      faixa = 'Extremo Baixo Peso (< 1.000g)';
      dose = idade < 12 ? 4.0 : 1.0;
      inicio = 'Aos 30 dias de vida';
    } else if (pesoNasc < 1500) {
      faixa = 'Muito Baixo Peso (1.000g a 1.499g)';
      dose = idade < 12 ? 3.0 : 1.0;
      inicio = 'Aos 30 dias de vida';
    } else if (pesoNasc < 2500) {
      faixa = 'Baixo Peso ao Nascer (1.500g a 2.499g)';
      dose = idade < 12 ? 2.0 : 1.0;
      inicio = 'Aos 30 dias de vida';
    } else {
      faixa = 'A Termo e Peso Adequado (≥ 2.500g)';
      dose = 1.0;
      inicio = 'Aos 6 meses de vida';
    }

    return {
      pesoNascimentoGramas: pesoNasc,
      idadeMeses: idade,
      doseRecomendadaMgKgDia: dose,
      faixaNascimento: faixa,
      momentoInicio: inicio,
      duracao: 'Até os 2 anos de idade',
      orientacao: dose + ' mg/kg/dia até ' + (idade < 12 ? '1 ano e depois 1 mg/kg/dia até 2 anos' : '2 anos.')
    };
  }

  function calcularGanzoni(pesoKgOrParams, hbAtual, hbAlvo, depositoMg) {
    var p = typeof pesoKgOrParams === 'object' && pesoKgOrParams !== null ? pesoKgOrParams : {
      pesoKg: pesoKgOrParams,
      hbAtual: hbAtual,
      hbAlvo: hbAlvo,
      depositoMg: depositoMg
    };

    var peso = parseFloat(p.pesoKg || p.peso);
    if (isNaN(peso) || peso <= 0) peso = 70;
    var atual = parseFloat(p.hbAtual || p.hb);
    if (isNaN(atual) || atual < 0) atual = 10;
    var alvo = parseFloat(p.hbAlvo);
    if (isNaN(alvo) || alvo <= 0) alvo = (p.gestante || p.sexo === 'F') ? 14.0 : 15.0;

    var deltaHb = Math.max(0, alvo - atual);
    var dep = typeof p.depositoMg === 'number' ? p.depositoMg : (peso < 35 ? Math.round(15 * peso) : 500);
    var deficitHbMg = Math.round(peso * deltaHb * 2.4);
    var deficitTotal = deficitHbMg + dep;

    var ampolasNoripurum = Math.ceil(deficitTotal / 100);
    var maxDoseNoripurum = 200;
    var sessoesNoripurum = Math.ceil(deficitTotal / maxDoseNoripurum);

    var frascosFerinject = Math.ceil(deficitTotal / 500);
    var sessoesFerinject = Math.ceil(deficitTotal / 1000);

    var aptoParaFerroEv = true;
    var bloqueios = [];

    if (peso < 1.0) {
      bloqueios.push('⚠️ PREMATURO EXTREMO (< 1 kg): O ferro intravenoso é desaconselhado. Seguir protocolo de profilaxia enteral da UTI Neonatal (SBP 2024: 3-4 mg/kg/dia a partir do 15º-30º dia).');
    }
    if (peso > 150) {
      bloqueios.push('⚠️ OBESIDADE SEVERA (> 150 kg): A fórmula de Ganzoni calculada pelo peso real superestima o déficit corporal de ferro pelo excesso de adiposidade. Recomenda-se utilizar o Peso Ajustado ou limite teto para prevenir toxicidade.');
    }
    if (atual <= 4.0) {
      bloqueios.push('🚨 HEMOGLOBINA CRÍTICA (Hb ≤ 4.0 g/dL): Anemia extrema com risco iminente de colapso circulatório anóxico. Priorizar transfusão emergencial de Concentrado de Hemácias e monitorização intensiva antes de aguardar resposta do ferro IV.');
    }
    if (p.gestante && (p.trimestre === 1 || p.primeiroTrimestre)) {
      aptoParaFerroEv = false;
      bloqueios.push('Primeiro trimestre de gestação: contraindicação formal a ferro IV.');
    }
    if (p.infeccaoAtiva || p.bacteriemia) {
      aptoParaFerroEv = false;
      bloqueios.push('Infecção bacteriana sistêmica ativa: suspender ferro IV até controle infeccioso.');
    }
    if (p.sobrecargaFerro) {
      aptoParaFerroEv = false;
      bloqueios.push('Sobrecarga de ferro sérica ou tecidual: contraindicação absoluta.');
    }

    return {
      pesoKg: peso,
      hbAtual: atual,
      hbAlvo: alvo,
      depositoMg: dep,
      deficitTotalFerroMg: deficitTotal,
      formulaGanzoniTexto: '[' + peso + ' kg × (' + alvo + ' - ' + atual + ') × 2.4] + ' + dep + ' mg',
      noripurum: {
        ampolasTotal: ampolasNoripurum,
        dosePorSessaoMg: maxDoseNoripurum,
        sessoesNecessarias: sessoesNoripurum
      },
      ferinject: {
        frascosTotal: frascosFerinject,
        dosePorSessaoMg: Math.min(deficitTotal, 1000),
        sessoesNecessarias: sessoesFerinject
      },
      aptoParaFerroEv: aptoParaFerroEv,
      bloqueiosSeguranca: bloqueios
    };
  }

  function analisarCasoCompleto(params) {
    var p = params || {};
    var hb = parseFloat(p.hb || p.hemoglobina);
    var vcm = parseFloat(p.vcm);
    var hcm = parseFloat(p.hcm);
    var chcm = parseFloat(p.chcm);
    var rdw = parseFloat(p.rdw);
    var hemacias = parseFloat(p.hemacias || p.he);
    var ht = parseFloat(p.ht || (hb ? Math.round(hb * 3 * 10) / 10 : 0));
    var retic = parseFloat(p.reticulocitos || p.retic);

    var est = classificarGravidadeAnemia(hb, p);
    var mor = classificarMorfologia(vcm, hcm, chcm, rdw);
    var ment = calcularIndiceMentzer(vcm, hemacias);
    var gk = calcularGreenKing(vcm, rdw, hb);
    var ipr = calcularIPR(retic, ht);
    var cin = avaliarCineticaFerro(p.ferritina, p.ferroSerico, p.tibc, p.ist, p.inflamacao);
    var oral = calcularDoseFerroOral(p);
    var ganz = calcularGanzoni(p);

    var hemolise = {
      alertaEmergencia: Boolean(p.esquizocitos),
      diagnostico: Boolean(p.esquizocitos) ? 'Microangiopatia Trombótica (MAT / PTT / SHU)' : (p.coombsDireto ? 'Anemia Hemolítica Autoimune (AHAI)' : 'Sem hemólise evidente'),
      achados: []
    };

    var hipotesePrincipal = 'Anemia a esclarecer';
    if (!est.temAnemia) {
      hipotesePrincipal = 'Sem anemia';
    } else if (p.esquizocitos) {
      hipotesePrincipal = 'Microangiopatia Trombótica (MAT / PTT / SHU)';
    } else if (vcm && vcm < 80) {
      if (ment && ment.valor < 13 && (!rdw || rdw <= 14.5)) {
        hipotesePrincipal = 'Traço Talassêmico (Talassemia Menor)';
      } else {
        hipotesePrincipal = 'Anemia Ferropriva';
      }
    } else if (vcm && vcm > 100) {
      hipotesePrincipal = 'Anemia Megaloblástica vs Macrocítica';
    } else {
      hipotesePrincipal = 'Anemia Normocítica e Normocrômica';
    }

    var baseRelatorio = gerarRelatorioCompleto(p);

    return {
      sucesso: true,
      hb: hb,
      vcm: vcm,
      hcm: hcm,
      chcm: chcm,
      rdw: rdw,
      hemacias: hemacias,
      ht: ht,
      estratificacao: est,
      morfologia: mor,
      mentzer: ment,
      greenKing: gk,
      ipr: ipr,
      cinetica: cin,
      hemolise: hemolise,
      doseOral: oral,
      ganzoni: ganz,
      hipotesePrincipal: hipotesePrincipal,
      textoFormatado: baseRelatorio.textoFormatado,
      analiseHemograma: baseRelatorio.analiseHemograma,
      reposicaoFerro: baseRelatorio.reposicaoFerro
    };
  }

  // ───────────────────────────────────────────────────────────────────────────
  // EXPORTAÇÃO PÚBLICA
  // ───────────────────────────────────────────────────────────────────────────
  return {
    LIMITES_HB: LIMITES_HB,
    inferirLimiteHb: inferirLimiteHb,
    interpretarHemogramaAnemia: interpretarHemogramaAnemia,
    calcularReposicaoFerro: calcularReposicaoFerro,
    gerarRelatorioCompleto: gerarRelatorioCompleto,
    analisarCasoCompleto: analisarCasoCompleto,
    classificarGravidadeAnemia: classificarGravidadeAnemia,
    classificarMorfologia: classificarMorfologia,
    calcularIndiceMentzer: calcularIndiceMentzer,
    calcularGreenKing: calcularGreenKing,
    calcularIPR: calcularIPR,
    calcularIpr: calcularIpr,
    avaliarCineticaFerro: avaliarCineticaFerro,
    calcularDoseFerroOral: calcularDoseFerroOral,
    calcularProfilaxiaPediatricaSBP: calcularProfilaxiaPediatricaSBP,
    calcularGanzoni: calcularGanzoni,
    formatarTextoTelegram: formatarTextoTelegram
  };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = HematologiaAnemiasService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_hepatologia_colestase_gestacional.js
// ==============================================================================

/**
 * @file 02_hepatologia_colestase_gestacional.js
 * @description Módulo de Hepatologia & Emergência Obstétrica: Colestase Intra-hepática
 * da Gestação (CIG) e Esteatose Hepática Aguda da Gestação (EHAG / AFLP).
 *
 * Fontes (rastreabilidade clínica):
 *  - RCOG Green-top Guideline No. 43: Obstetric Cholestasis (2024 revision).
 *  - SMFM Consult Series #53: Intrahepatic Cholestasis of Pregnancy (2021, atualização 2024).
 *  - Ovadia C et al. Association of adverse perinatal outcomes of ICP with biochemical markers:
 *    results of aggregate and individual patient data meta-analyses. Lancet 2019;393:899-909.
 *  - ACOG Practice Bulletin: Liver Disease in Pregnancy (2022).
 *  - Ch'ng CL et al. Prospective study of liver dysfunction in pregnancy in Southwest Wales.
 *    Gut 2002;51:876-880 (Critérios de Swansea para EHAG).
 *  - Knight M et al. A prospective national study of AFLP in the UK.
 *    Gut 2008;57:951-956 (validação Swansea).
 *  - FEBRASGO — Protocolo de Hepatopatias na Gestação (2024).
 *  - AASLD Position Statement: Liver Disease in Pregnancy (Terrault NA et al., Hepatology 2021).
 *
 * Escopo:
 *  - Estratificação de gravidade da CIG por ácidos biliares totais séricos (ABT).
 *  - Posologia ponderada de Ácido Ursodesoxicólico (UDCA) como 1ª linha.
 *  - Programação do momento ideal do parto (delivery timing).
 *  - Critérios de Swansea para diagnóstico clínico de EHAG/AFLP.
 *  - Protocolo de estabilização pré-parto na EHAG.
 *  - Diagnóstico diferencial entre CIG, EHAG, pré-eclâmpsia/HELLP.
 */

var HepatologiaColestaseGestacionalService = (function() {
  'use strict';

  // ═══════════════════════════════════════════════════════════════════════════
  // 1. CONSTANTES CLÍNICAS — CIG (Colestase Intra-hepática da Gestação)
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Estratificação por ácidos biliares totais séricos (mcmol/L).
   * - Leve: 10-39 mcmol/L
   * - Moderada: 40-99 mcmol/L (risco fetal significativo: parto precoce pode ser necessário)
   * - Grave: >= 100 mcmol/L (risco de óbito fetal súbito — Lancet 2019 meta-análise)
   *
   * Ponto de corte diagnóstico: >= 19 mcmol/L em jejum (RCOG) ou >= 10 mcmol/L (SMFM).
   * Este módulo utiliza >= 10 mcmol/L como limiar diagnóstico para maximizar sensibilidade.
   */
  var FAIXAS_ABT = {
    NORMAL:   { min: 0,   max: 9,   gravidade: 'NORMAL',   risco_fetal: 'Populacionamento basal' },
    LEVE:     { min: 10,  max: 39,  gravidade: 'LEVE',     risco_fetal: 'Baixo (OR natimorto ~1,0-1,5)' },
    MODERADA: { min: 40,  max: 99,  gravidade: 'MODERADA', risco_fetal: 'Intermediário (OR natimorto ~1,5-2,5)' },
    GRAVE:    { min: 100, max: Infinity, gravidade: 'GRAVE', risco_fetal: 'Elevado (OR natimorto ~3,4; risco ~3,44% — Ovadia Lancet 2019)' }
  };

  /**
   * Programação do parto conforme gravidade bioquímica (Timing of delivery).
   * Baseado em SMFM 2021/2024, RCOG 2024, FEBRASGO 2024.
   */
  var TIMING_PARTO = {
    LEVE:     { ig_semanas: 38, ig_texto: '38+0 a 39+0 semanas', justificativa: 'CIG leve (ABT 10-39): risco fetal discretamente elevado, equilibrar prematuridade iatrogênica.' },
    MODERADA: { ig_semanas: 37, ig_texto: '37+0 a 38+0 semanas', justificativa: 'CIG moderada (ABT 40-99): risco fetal significativo; parto precoce justificado.' },
    GRAVE:    { ig_semanas: 36, ig_texto: '36+0 a 37+0 semanas', justificativa: 'CIG grave (ABT >= 100): risco de óbito fetal súbito sem aviso cardiotocográfico (Ovadia Lancet 2019). NÃO postergar além de 37 semanas.' }
  };

  // Dose terapêutica de UDCA: 10-15 mg/kg/dia, dividida em 2-3 tomadas.
  var UDCA_DOSE_MIN_MG_KG = 10;
  var UDCA_DOSE_MAX_MG_KG = 15;
  var UDCA_DOSE_ABS_MAX_MG = 2000; // Dose máxima absoluta por dia

  // ═══════════════════════════════════════════════════════════════════════════
  // 2. CONSTANTES CLÍNICAS — EHAG (Esteatose Hepática Aguda da Gestação)
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Critérios de Swansea (Ch'ng et al., Gut 2002; Knight et al., Gut 2008).
   * Diagnóstico: >= 6 critérios presentes, na ausência de outra etiologia.
   */
  var CRITERIOS_SWANSEA = [
    { id: 'vomitos',           descricao: 'Vômitos',                         categoria: 'clínico' },
    { id: 'dor_abdominal',     descricao: 'Dor abdominal (epigástrica ou HCD)', categoria: 'clínico' },
    { id: 'polidipsia_poliuria', descricao: 'Polidipsia / Poliúria',         categoria: 'clínico' },
    { id: 'encefalopatia',     descricao: 'Encefalopatia hepática',          categoria: 'clínico' },
    { id: 'bilirrubina_elevada', descricao: 'Bilirrubina elevada (> 0,8 mg/dL ou > 14 µmol/L)', categoria: 'laboratorial' },
    { id: 'hipoglicemia',      descricao: 'Hipoglicemia (< 72 mg/dL ou < 4 mmol/L)', categoria: 'laboratorial' },
    { id: 'acido_urico_elevado', descricao: 'Ácido úrico elevado (> 5,7 mg/dL ou > 340 µmol/L)', categoria: 'laboratorial' },
    { id: 'leucocitose',       descricao: 'Leucocitose (> 11.000/mm³)',      categoria: 'laboratorial' },
    { id: 'ascite_usg',        descricao: 'Ascite ou fígado brilhante na USG', categoria: 'imagem' },
    { id: 'transaminases_elevadas', descricao: 'Transaminases elevadas (AST ou ALT > 42 UI/L)', categoria: 'laboratorial' },
    { id: 'amonia_elevada',    descricao: 'Amônia elevada (> 47 µmol/L)',    categoria: 'laboratorial' },
    { id: 'insuf_renal',       descricao: 'Insuficiência renal (creatinina > 1,7 mg/dL ou > 150 µmol/L)', categoria: 'laboratorial' },
    { id: 'coagulopatia',      descricao: 'Coagulopatia (TP > 14s ou TTPa > 34s)',  categoria: 'laboratorial' },
    { id: 'esteatose_biopsia', descricao: 'Esteatose microvesicular na biópsia hepática', categoria: 'histológico' }
  ];

  var SWANSEA_LIMIAR = 6; // >= 6 critérios = diagnóstico de EHAG

  // ═══════════════════════════════════════════════════════════════════════════
  // 3. REFERÊNCIAS BIBLIOGRÁFICAS
  // ═══════════════════════════════════════════════════════════════════════════

  var REFERENCIAS = [
    'RCOG Green-top Guideline No. 43: Obstetric Cholestasis (2024).',
    'SMFM Consult Series #53: ICP (2021, atualização 2024).',
    'Ovadia C et al. Lancet 2019;393:899-909 (meta-análise ABT e desfecho perinatal).',
    'ACOG Practice Bulletin: Liver Disease in Pregnancy (2022).',
    "Ch'ng CL et al. Gut 2002;51:876-880 (Critérios de Swansea para EHAG).",
    'Knight M et al. Gut 2008;57:951-956 (validação prospectiva dos critérios de Swansea).',
    'FEBRASGO — Protocolo de Hepatopatias na Gestação (2024).',
    'Terrault NA et al. Hepatology 2021 (AASLD Position Statement: Liver Disease in Pregnancy).'
  ];

  // ═══════════════════════════════════════════════════════════════════════════
  // 4. FUNÇÕES — CIG
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Classifica a gravidade da CIG com base nos ácidos biliares totais séricos.
   * @param {number} abt - Ácidos biliares totais séricos (mcmol/L).
   * @returns {{ gravidade: string, faixa: object, timing_parto: object|null }}
   */
  function classificarGravidadeCIG(abt) {
    if (typeof abt !== 'number' || isNaN(abt) || abt < 0) {
      throw new Error('Ácidos biliares totais (ABT) devem ser um número >= 0.');
    }

    if (abt < 10) {
      return { gravidade: 'NORMAL', faixa: FAIXAS_ABT.NORMAL, timing_parto: null };
    }
    if (abt <= 39) {
      return { gravidade: 'LEVE', faixa: FAIXAS_ABT.LEVE, timing_parto: TIMING_PARTO.LEVE };
    }
    if (abt <= 99) {
      return { gravidade: 'MODERADA', faixa: FAIXAS_ABT.MODERADA, timing_parto: TIMING_PARTO.MODERADA };
    }
    return { gravidade: 'GRAVE', faixa: FAIXAS_ABT.GRAVE, timing_parto: TIMING_PARTO.GRAVE };
  }

  /**
   * Calcula a posologia ponderada de Ácido Ursodesoxicólico (UDCA).
   * @param {number} peso - Peso corporal em kg.
   * @returns {{ dose_min_mg: number, dose_max_mg: number, dose_diaria_texto: string, posologia: string }}
   */
  function calcularDoseUDCA(peso) {
    if (typeof peso !== 'number' || isNaN(peso) || peso <= 0) {
      throw new Error('Peso deve ser um número positivo em kg.');
    }

    var doseMin = Math.round(peso * UDCA_DOSE_MIN_MG_KG);
    var doseMax = Math.round(peso * UDCA_DOSE_MAX_MG_KG);

    // Aplicar teto absoluto
    if (doseMin > UDCA_DOSE_ABS_MAX_MG) doseMin = UDCA_DOSE_ABS_MAX_MG;
    if (doseMax > UDCA_DOSE_ABS_MAX_MG) doseMax = UDCA_DOSE_ABS_MAX_MG;

    // Arredondar para múltiplos de 50mg (apresentação comercial: cáps 150mg, 300mg)
    var doseMinArredondada = Math.round(doseMin / 50) * 50;
    var doseMaxArredondada = Math.round(doseMax / 50) * 50;

    // Calcular número de tomadas (geralmente 2-3x/dia)
    // Dose prática: preferência por divisão em 2x se dose <= 900mg, 3x se > 900mg
    var numTomadas = doseMaxArredondada > 900 ? 3 : 2;
    var dosePorTomada = Math.round(doseMaxArredondada / numTomadas / 50) * 50;

    return {
      dose_min_mg: doseMinArredondada,
      dose_max_mg: doseMaxArredondada,
      dose_diaria_texto: doseMinArredondada + ' a ' + doseMaxArredondada + ' mg/dia',
      posologia: dosePorTomada + ' mg VO a cada ' + (numTomadas === 2 ? '12h (2x/dia)' : '8h (3x/dia)'),
      num_tomadas: numTomadas,
      dose_por_tomada_mg: dosePorTomada,
      apresentacao: 'Comprimidos/cápsulas de 150 mg ou 300 mg'
    };
  }

  /**
   * Avaliação completa de CIG — estratificação, tratamento e plano de parto.
   * @param {object} params - Parâmetros clínicos.
   * @param {number} params.acidos_biliares - Ácidos biliares totais séricos (mcmol/L).
   * @param {number} [params.peso] - Peso corporal em kg (para cálculo de UDCA).
   * @param {number} [params.ig_semanas] - Idade gestacional em semanas completas.
   * @param {number} [params.ig_dias] - Dias adicionais da IG.
   * @param {boolean} [params.prurido] - Prurido presente.
   * @param {number} [params.tgo] - TGO/AST (UI/L).
   * @param {number} [params.tgp] - TGP/ALT (UI/L).
   * @param {number} [params.bilirrubina_total] - Bilirrubina total (mg/dL).
   * @param {boolean} [params.antecedente_cig] - CIG em gestação prévia.
   * @param {boolean} [params.gestacao_gemelar] - Gestação gemelar.
   * @returns {object} Análise completa com classificação, tratamento e plano.
   */
  function avaliarCIG(params) {
    if (!params || typeof params.acidos_biliares !== 'number') {
      throw new Error('O parâmetro "acidos_biliares" (mcmol/L) é obrigatório para avaliação de CIG.');
    }

    var abt = params.acidos_biliares;
    var classificacao = classificarGravidadeCIG(abt);

    var ig = null;
    if (params.ig_semanas != null) {
      var sem = parseInt(params.ig_semanas, 10);
      var dias = params.ig_dias ? parseInt(params.ig_dias, 10) : 0;
      ig = { semanas: sem, dias: dias, texto: sem + 's' + (dias > 0 ? dias + 'd' : '') };
    }

    var resultado = {
      diagnostico: 'COLESTASE_INTRAHEPATICA_GESTACIONAL',
      acidos_biliares_mcmol: abt,
      classificacao: classificacao,
      ig: ig,
      tratamento: null,
      vigilancia: null,
      parto: null,
      alertas: [],
      bloqueios_seguranca: [],
      diagnostico_diferencial: [],
      referencias: REFERENCIAS.slice()
    };

    // Se ABT < 10, não confirma CIG
    if (classificacao.gravidade === 'NORMAL') {
      resultado.diagnostico = 'NAO_CONFIRMADO';
      resultado.alertas.push('⚠️ ABT < 10 mcmol/L: CIG não confirmada. Considerar diagnósticos diferenciais de prurido gestacional (dermatose gestacional, dermatite alérgica, hepatites virais).');
      resultado.alertas.push('💡 Repetir dosagem em 1-2 semanas se prurido persistir (sensibilidade dos ABT é tempo-dependente).');
      return resultado;
    }

    // ── Tratamento ──
    var tratamento = {
      farmacologico: [],
      nao_farmacologico: []
    };

    // UDCA
    if (params.peso) {
      var doseUDCA = calcularDoseUDCA(params.peso);
      tratamento.farmacologico.push({
        farmaco: 'Ácido Ursodesoxicólico (UDCA)',
        linha: '1ª linha',
        dose: doseUDCA.dose_diaria_texto,
        posologia: doseUDCA.posologia,
        apresentacao: doseUDCA.apresentacao,
        observacao: 'Iniciar e titular até dose máxima tolerada. Melhora do prurido em 1-2 semanas. Pode não reduzir risco de natimorto (PITCHES trial), mas reduz ABT e melhora sintomas maternos.'
      });
    } else {
      tratamento.farmacologico.push({
        farmaco: 'Ácido Ursodesoxicólico (UDCA)',
        linha: '1ª linha',
        dose: '10-15 mg/kg/dia (informar peso para cálculo exato)',
        posologia: 'Dividido em 2-3 tomadas diárias',
        apresentacao: 'Comprimidos/cápsulas de 150 mg ou 300 mg',
        observacao: 'Iniciar e titular até dose máxima tolerada (máx 2000 mg/dia).'
      });
    }

    // Anti-histamínicos para prurido (2ª linha sintomática)
    tratamento.farmacologico.push({
      farmaco: 'Hidroxizina',
      linha: 'Adjuvante (prurido)',
      dose: '25 mg VO à noite',
      observacao: 'Uso noturno para alívio do prurido refratário ao UDCA. Evitar no 3º trimestre próximo ao parto (sedação neonatal).'
    });

    // Medidas não farmacológicas
    tratamento.nao_farmacologico.push('Hidratante corporal emoliente (sem fragrância) para alívio sintomático do prurido.');
    tratamento.nao_farmacologico.push('Banhos mornos (evitar quentes, pioram prurido).');
    tratamento.nao_farmacologico.push('Roupas de algodão folgadas.');

    resultado.tratamento = tratamento;

    // ── Vigilância ──
    var vigilancia = {
      laboratorial: 'ABT séricos semanais até o parto (monitorar progressão para faixa grave).',
      hepatica: 'TGO, TGP, bilirrubinas e coagulograma semanal.',
      fetal: 'Cardiotocografia (CTG) 2x/semana a partir de 32 semanas.',
      nota: '⚠️ A CTG NÃO previne óbito fetal súbito na CIG grave. O parto programado é a principal intervenção para reduzir risco.'
    };

    if (classificacao.gravidade === 'GRAVE') {
      vigilancia.fetal = 'CTG diária. Internação para monitorização intensiva a partir de 34 semanas.';
      vigilancia.laboratorial = 'ABT séricos 2x/semana. Coagulograma 2x/semana (risco de coagulopatia por má absorção de vitamina K).';
    }

    resultado.vigilancia = vigilancia;

    // ── Parto ──
    if (classificacao.timing_parto) {
      var parto = {
        ig_alvo_semanas: classificacao.timing_parto.ig_semanas,
        ig_alvo_texto: classificacao.timing_parto.ig_texto,
        justificativa: classificacao.timing_parto.justificativa,
        via_parto: 'Via obstétrica habitual (indução do trabalho de parto é preferida).',
        parto_indicado_agora: false
      };

      // Verificar se IG atual já atingiu o alvo
      if (ig && ig.semanas >= parto.ig_alvo_semanas) {
        parto.parto_indicado_agora = true;
      }

      // Corticoide antenatal
      parto.corticoide = { indicado: false };
      if (ig && ig.semanas >= 24 && ig.semanas < 37) {
        // Se parto previsto em <= 7 dias e < 34+6 semanas
        if (ig.semanas < 37 && classificacao.timing_parto.ig_semanas - ig.semanas <= 1) {
          parto.corticoide = {
            indicado: true,
            esquema: 'Betametasona 12 mg IM a cada 24h (2 doses) OU Dexametasona 6 mg IM a cada 12h (4 doses).',
            observacao: 'Maturação pulmonar fetal. Administrar se parto previsto em < 7 dias e IG 24-36+6 semanas (ALPS trial).'
          };
        }
      }

      // Vitamina K
      if (classificacao.gravidade === 'GRAVE') {
        parto.vitamina_k = {
          indicada: true,
          dose: 'Vitamina K1 (Fitomenadiona) 10 mg IM/IV pré-parto.',
          justificativa: 'CIG grave causa má absorção de vitamina K por redução de sais biliares no intestino, aumentando risco de coagulopatia materna e hemorragia pós-parto.'
        };
      }

      resultado.parto = parto;
    }

    // ── Alertas ──
    if (params.antecedente_cig) {
      resultado.alertas.push('🔄 Antecedente de CIG em gestação prévia: risco de recorrência de 45-90%.');
    }
    if (params.gestacao_gemelar) {
      resultado.alertas.push('👶👶 Gestação gemelar: risco aumentado de CIG (maior carga hormonal placentária).');
    }
    if (classificacao.gravidade === 'GRAVE') {
      resultado.alertas.push('🚨 CIG GRAVE (ABT >= 100 mcmol/L): Risco de natimorto de ~3,44% (Ovadia Lancet 2019). O parto é a principal intervenção de proteção fetal.');
      resultado.alertas.push('⚠️ CTG NÃO é preditiva de óbito fetal na CIG grave. O evento é frequentemente SÚBITO e sem sinais premonitórios cardiotocográficos.');
    }
    if (params.tgo && params.tgo > 200) {
      resultado.alertas.push('🔬 TGO > 200 UI/L: Excluir hepatites virais agudas (HAV, HBV, HCV, HEV) e EHAG/AFLP.');
    }
    if (params.bilirrubina_total && params.bilirrubina_total > 2.0) {
      resultado.alertas.push('🟡 Bilirrubina > 2,0 mg/dL é incomum na CIG isolada. Investigar EHAG, HELLP ou obstrução biliar.');
    }

    // ── Diagnóstico diferencial ──
    resultado.diagnostico_diferencial = [
      'EHAG / AFLP (Esteatose Hepática Aguda da Gestação) — encefalopatia, hipoglicemia, coagulopatia.',
      'Síndrome HELLP — plaquetopenia, hemólise (LDH elevada), dor epigástrica.',
      'Pré-eclâmpsia com sinais de gravidade — hipertensão arterial, proteinúria.',
      'Hepatite viral aguda (A, B, C, E) — sorologia viral.',
      'Coledocolitíase — dor em HCD, icterícia colestática, dilatação de vias biliares à USG.',
      'Dermatose gestacional (PUPPP, penfigoide gestacional) — prurido sem elevação de ABT.'
    ];

    // ── Bloqueios de segurança ──
    resultado.bloqueios_seguranca.push('🚫 NÃO utilizar Colestiramina como monoterapia (inferior ao UDCA e interfere na absorção de vitaminas lipossolúveis e medicamentos).');
    resultado.bloqueios_seguranca.push('🚫 NÃO utilizar Dexametasona para tratamento da CIG (sem evidência de benefício e efeitos adversos materno-fetais).');
    resultado.bloqueios_seguranca.push('🚫 S-adenosilmetionina (SAMe) NÃO é recomendada como monoterapia (evidência insuficiente).');
    resultado.bloqueios_seguranca.push('⚠️ Monitorar coagulograma: CIG grave pode causar deficiência de vitamina K por colestase.');
    resultado.bloqueios_seguranca.push('⚠️ NÃO postergar o parto além do limiar recomendado para a faixa de ABT — o principal risco é o óbito fetal súbito.');

    return resultado;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // 5. FUNÇÕES — EHAG / AFLP (Esteatose Hepática Aguda da Gestação)
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Avalia os Critérios de Swansea para diagnóstico de EHAG/AFLP.
   * @param {object} criterios - Objeto com booleans para cada critério.
   * @returns {{ diagnostico: string, criterios_presentes: string[], total: number,
   *             limiar: number, confirmado: boolean, protocolo: object }}
   */
  function avaliarSwansea(criterios) {
    if (!criterios || typeof criterios !== 'object') {
      throw new Error('Critérios de Swansea devem ser informados como objeto.');
    }

    var presentes = [];
    var ausentes = [];

    CRITERIOS_SWANSEA.forEach(function(c) {
      if (criterios[c.id]) {
        presentes.push(c.descricao);
      } else {
        ausentes.push(c.descricao);
      }
    });

    var total = presentes.length;
    var confirmado = total >= SWANSEA_LIMIAR;

    var resultado = {
      diagnostico: confirmado ? 'EHAG_CONFIRMADA' : 'EHAG_NAO_CONFIRMADA',
      criterios_presentes: presentes,
      criterios_ausentes: ausentes,
      total_presentes: total,
      total_criterios: CRITERIOS_SWANSEA.length,
      limiar: SWANSEA_LIMIAR,
      confirmado: confirmado,
      protocolo: null,
      alertas: [],
      bloqueios_seguranca: [],
      referencias: REFERENCIAS.slice()
    };

    if (confirmado) {
      resultado.protocolo = gerarProtocoloEHAG(criterios);
      resultado.alertas.push('🚨 EHAG/AFLP CONFIRMADA: EMERGÊNCIA OBSTÉTRICA. O parto é o tratamento DEFINITIVO.');
      resultado.alertas.push('⚠️ Mortalidade materna: 1,8% (séries recentes). Mortalidade perinatal: 9-23%.');
      resultado.alertas.push('⚡ A recuperação hepática inicia tipicamente 48-72h após o parto, mas CIVD e insuficiência hepática podem progredir no pós-parto imediato.');
    } else {
      resultado.alertas.push('ℹ️ Critérios de Swansea não preenchidos (' + total + '/' + SWANSEA_LIMIAR + '). Reavaliar em 24-48h se quadro clínico-laboratorial progredir.');
    }

    return resultado;
  }

  /**
   * Gera o protocolo de estabilização e manejo da EHAG.
   * @param {object} criterios - Critérios avaliados.
   * @returns {object} Protocolo de manejo.
   */
  function gerarProtocoloEHAG(criterios) {
    var protocolo = {
      prioridade: 'EMERGÊNCIA OBSTÉTRICA',
      equipe: [
        'Obstetra sênior',
        'Hepatologista / Intensivista',
        'Anestesiologista',
        'Hematologista (se CIVD)',
        'Neonatologista'
      ],
      estabilizacao_pre_parto: [],
      parto: {},
      pos_parto: [],
      suporte_uti: []
    };

    // Estabilização pré-parto
    protocolo.estabilizacao_pre_parto.push('Acesso venoso calibroso (2 acessos periféricos 16-18G ou acesso central).');
    protocolo.estabilizacao_pre_parto.push('Monitorização hemodinâmica contínua (PA, FC, SpO2, débito urinário).');
    protocolo.estabilizacao_pre_parto.push('Reserva de hemoderivados: 4U CHAD, 4U PFC, 6U crio, 1 pool de plaquetas.');
    protocolo.estabilizacao_pre_parto.push('Coleta imediata: hemograma, coagulograma (TP, TTPa, fibrinogênio), TGO, TGP, bilirrubinas, glicemia, creatinina, ácido úrico, lactato, amônia, gasometria arterial.');

    if (criterios.hipoglicemia) {
      protocolo.estabilizacao_pre_parto.push('💉 HIPOGLICEMIA: Glicose hipertônica 50% — 40 mL IV em bolus + SG 10% em infusão contínua (100-150 mL/h). Monitorar glicemia capilar a cada 1h.');
    }

    if (criterios.coagulopatia) {
      protocolo.estabilizacao_pre_parto.push('🩸 COAGULOPATIA/CIVD: Plasma Fresco Congelado (PFC) 15-20 mL/kg IV. Crioprecipitado 10U se fibrinogênio < 150 mg/dL. Plaquetas se < 50.000/mm³ pré-parto.');
      protocolo.estabilizacao_pre_parto.push('Vitamina K1 (Fitomenadiona) 10 mg IV lento.');
    }

    if (criterios.encefalopatia) {
      protocolo.estabilizacao_pre_parto.push('🧠 ENCEFALOPATIA HEPÁTICA: Lactulose 30 mL VO/SNG a cada 6-8h (alvo: 2-3 evacuações pastosas/dia). Evitar sedativos.');
      protocolo.estabilizacao_pre_parto.push('Considerar N-acetilcisteína (NAC) IV 150 mg/kg em 60 min (protocolo de insuficiência hepática aguda não paracetamol — AASLD).');
    }

    // Parto
    protocolo.parto = {
      urgencia: 'Parto URGENTE após estabilização materna (não postergar > 24-48h do diagnóstico).',
      via: 'Cesariana é frequentemente necessária, mas indução vaginal pode ser considerada se condição materna estável e colo favorável.',
      anestesia: 'Avaliação anestésica OBRIGATÓRIA: bloqueio neuroaxial somente se plaquetas > 75.000 e coagulograma adequado; caso contrário, anestesia geral com intubação de sequência rápida.',
      nota: 'A decisão da via de parto deve ser INDIVIDUALIZADA com base na gravidade da coagulopatia e estabilidade hemodinâmica.'
    };

    // Pós-parto
    protocolo.pos_parto.push('Monitoramento em UTI por no mínimo 48-72h após o parto.');
    protocolo.pos_parto.push('Controle laboratorial seriado a cada 12-24h: TGO, TGP, bilirrubinas, coagulograma, glicemia, creatinina, hemograma, lactato.');
    protocolo.pos_parto.push('Melhora esperada em 48-72h. Se piora progressiva após 72h → considerar transplante hepático (acionar centro de referência).');
    protocolo.pos_parto.push('Manter suporte glicêmico e correção de coagulopatia até normalização.');

    // Suporte de UTI
    protocolo.suporte_uti.push('Fluidoterapia com cristaloides balanceados (evitar sobrecarga).');
    protocolo.suporte_uti.push('Profilaxia de úlcera de estresse: Pantoprazol 40 mg IV 1x/dia.');
    protocolo.suporte_uti.push('Se insuficiência renal aguda: considerar diálise precoce (hemodiafiltração venovenosa contínua).');
    protocolo.suporte_uti.push('Contatar centro de transplante hepático se critérios de King\'s College para insuficiência hepática aguda.');

    return protocolo;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // 6. DIAGNÓSTICO DIFERENCIAL UNIFICADO
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Diferencial clínico entre CIG, EHAG e HELLP.
   * @param {object} dados - Dados clínico-laboratoriais.
   * @returns {{ diagnosticos_provaveis: string[], tabela: object[] }}
   */
  function diagnosticoDiferencial(dados) {
    if (!dados) dados = {};

    var tabela = [
      {
        diagnostico: 'CIG (Colestase Intra-hepática)',
        prurido: 'Intenso (palmas e plantas)',
        transaminases: 'Normais a moderadamente elevadas',
        bilirrubina: 'Normal ou levemente elevada',
        plaquetas: 'Normais',
        coagulopatia: 'Rara (apenas em CIG grave por def. vit K)',
        hipoglicemia: 'Ausente',
        hipertensao: 'Ausente',
        encefalopatia: 'Ausente',
        abt_elevados: 'SIM (> 10 mcmol/L)',
        pico_incidencia: '3º trimestre (> 28 semanas)'
      },
      {
        diagnostico: 'EHAG / AFLP',
        prurido: 'Incomum',
        transaminases: 'Elevadas (geralmente < 500-1000)',
        bilirrubina: 'Elevada',
        plaquetas: 'Normais ou reduzidas',
        coagulopatia: 'Frequente (CIVD)',
        hipoglicemia: 'Frequente (sinal cardinal)',
        hipertensao: 'Presente em ~50%',
        encefalopatia: 'Pode ocorrer (insuf. hepática)',
        abt_elevados: 'Podem estar elevados',
        pico_incidencia: '3º trimestre (> 30 semanas)'
      },
      {
        diagnostico: 'Síndrome HELLP',
        prurido: 'Ausente',
        transaminases: 'Elevadas',
        bilirrubina: 'Elevada (hemólise)',
        plaquetas: 'REDUZIDAS (< 100.000)',
        coagulopatia: 'Possível (CIVD em formas graves)',
        hipoglicemia: 'Rara',
        hipertensao: 'Presente (pré-eclâmpsia)',
        encefalopatia: 'Rara',
        abt_elevados: 'Normais',
        pico_incidencia: '3º trimestre'
      }
    ];

    var provaveis = [];

    // Heurística de sugestão diagnóstica
    if (dados.acidos_biliares && dados.acidos_biliares >= 10) {
      provaveis.push('CIG');
    }
    if (dados.hipoglicemia || dados.encefalopatia || (dados.coagulopatia && dados.transaminases_elevadas)) {
      provaveis.push('EHAG/AFLP');
    }
    if (dados.plaquetas_baixas && dados.hipertensao) {
      provaveis.push('HELLP');
    }
    if (provaveis.length === 0) {
      provaveis.push('Dados insuficientes para sugestão diagnóstica');
    }

    return {
      diagnosticos_provaveis: provaveis,
      tabela: tabela
    };
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // 7. PARSER DE TEXTO LIVRE (Telegram)
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Extrai parâmetros clínicos de um texto livre para avaliação de CIG/EHAG.
   * @param {string} texto - Texto livre do usuário.
   * @returns {object} Parâmetros extraídos.
   */
  function extrairParametrosTexto(texto) {
    if (!texto || typeof texto !== 'string') return {};

    var t = texto.toLowerCase().replace(/,/g, '.').trim();
    var params = {};

    // Ácidos biliares totais
    var mAbt = t.match(/(?:abt|acidos?\s*biliares?|bile\s*acids?|ab)\s*[:=]?\s*(\d+(?:\.\d+)?)/);
    if (mAbt) params.acidos_biliares = parseFloat(mAbt[1]);

    // Peso
    var mPeso = t.match(/(?:peso|weight)\s*[:=]?\s*(\d+(?:\.\d+)?)\s*(?:kg)?/);
    if (mPeso) params.peso = parseFloat(mPeso[1]);

    // IG
    var mIg = t.match(/(?:ig|idade\s*gestacional)?\s*(\d{1,2})\s*(?:s(?:em(?:anas?)?)?|semanas?)\s*(?:e?\s*(\d)\s*(?:d(?:ias?)?)?)?/);
    if (!mIg) {
      mIg = t.match(/(\d{1,2})\s*\+\s*(\d)/);
    }
    if (mIg) {
      params.ig_semanas = parseInt(mIg[1], 10);
      if (mIg[2]) params.ig_dias = parseInt(mIg[2], 10);
    }

    // TGO/TGP
    var mTgo = t.match(/(?:tgo|ast)\s*[:=]?\s*(\d+(?:\.\d+)?)/);
    if (mTgo) params.tgo = parseFloat(mTgo[1]);
    var mTgp = t.match(/(?:tgp|alt)\s*[:=]?\s*(\d+(?:\.\d+)?)/);
    if (mTgp) params.tgp = parseFloat(mTgp[1]);

    // Bilirrubina
    var mBil = t.match(/(?:bilirrubina|bt|bil)\s*[:=]?\s*(\d+(?:\.\d+)?)/);
    if (mBil) params.bilirrubina_total = parseFloat(mBil[1]);

    // Booleanos
    if (/prurido|coceira|pruri/i.test(t)) params.prurido = true;
    if (/antecedente|previa|anterior|recorrente/i.test(t)) params.antecedente_cig = true;
    if (/gemelar|gemeo|gemeos|twins/i.test(t)) params.gestacao_gemelar = true;

    // Critérios de Swansea (EHAG)
    if (/ehag|aflp|esteatose|fatty\s*liver|swansea/i.test(t)) {
      params.modo = 'EHAG';
      params.swansea = {};
      if (/v[oô]mito/i.test(t)) params.swansea.vomitos = true;
      if (/dor\s*(?:abdominal|epig[aá]strica|hcd)/i.test(t)) params.swansea.dor_abdominal = true;
      if (/polidipsia|poli[uú]ria/i.test(t)) params.swansea.polidipsia_poliuria = true;
      if (/encefalopatia|confus[aã]o\s*mental|rebaixamento/i.test(t)) params.swansea.encefalopatia = true;
      if (/bilirrubina\s*(?:elevada|alta|>)/i.test(t) || (params.bilirrubina_total && params.bilirrubina_total > 0.8)) params.swansea.bilirrubina_elevada = true;
      if (/hipoglicemia|glicose\s*(?:baixa|<)|glicemia\s*(?:baixa|<)/i.test(t)) params.swansea.hipoglicemia = true;
      if (/[aá]cido\s*[uú]rico\s*(?:elevado|alto|>)|hiperuricemia/i.test(t)) params.swansea.acido_urico_elevado = true;
      if (/leucocitose|leuc[oó]citos?\s*(?:elevad|alt|>)|gb\s*>\s*11/i.test(t)) params.swansea.leucocitose = true;
      if (/ascite|f[ií]gado\s*brilhante/i.test(t)) params.swansea.ascite_usg = true;
      if (/transaminases?\s*(?:elevad|alt|>)|tgo\s*>\s*42|tgp\s*>\s*42/i.test(t) || (params.tgo && params.tgo > 42) || (params.tgp && params.tgp > 42)) params.swansea.transaminases_elevadas = true;
      if (/am[oô]nia\s*(?:elevad|alt|>)/i.test(t)) params.swansea.amonia_elevada = true;
      if (/insuf(?:ici[eê]ncia)?\s*renal|creatinina\s*(?:elevad|alt|>)/i.test(t)) params.swansea.insuf_renal = true;
      if (/coagulopatia|civd|dic|tp\s*>\s*14|ttpa\s*>\s*34/i.test(t)) params.swansea.coagulopatia = true;
      if (/bi[oó]psia|esteatose\s*micro/i.test(t)) params.swansea.esteatose_biopsia = true;
    }

    return params;
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // 8. AVALIAÇÃO UNIFICADA (entry point principal)
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Função principal de avaliação. Despacha para CIG ou EHAG conforme os dados.
   * @param {object} params - Parâmetros clínicos.
   * @returns {object} Resultado da avaliação.
   */
  function avaliar(params) {
    if (!params || typeof params !== 'object') {
      throw new Error('Parâmetros clínicos obrigatórios.');
    }

    // Modo EHAG
    if (params.modo === 'EHAG' && params.swansea) {
      return avaliarSwansea(params.swansea);
    }

    // Modo CIG (padrão)
    if (params.acidos_biliares != null) {
      return avaliarCIG(params);
    }

    throw new Error('Informe "acidos_biliares" para avaliação de CIG ou "modo: EHAG" com critérios de Swansea.');
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // 9. FORMATAÇÃO TELEGRAM
  // ═══════════════════════════════════════════════════════════════════════════

  /**
   * Formata o resultado da avaliação em texto Markdown para Telegram.
   * @param {object} resultado - Resultado de avaliar() ou avaliarCIG() ou avaliarSwansea().
   * @returns {string} Texto formatado.
   */
  function formatarTextoTelegram(resultado) {
    if (!resultado) return '';
    var t = [];

    if (resultado.diagnostico === 'COLESTASE_INTRAHEPATICA_GESTACIONAL' || resultado.diagnostico === 'NAO_CONFIRMADO') {
      // ── CIG ──
      t.push('🟡 *COLESTASE INTRA-HEPÁTICA DA GESTAÇÃO (CIG)*');
      t.push('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
      t.push('');

      t.push('📊 *ÁCIDOS BILIARES TOTAIS:* ' + resultado.acidos_biliares_mcmol + ' mcmol/L');
      t.push('🏷️ *CLASSIFICAÇÃO:* ' + resultado.classificacao.gravidade);
      t.push('⚠️ *RISCO FETAL:* ' + resultado.classificacao.faixa.risco_fetal);

      if (resultado.ig) {
        t.push('📅 *IG:* ' + resultado.ig.texto);
      }
      t.push('');

      if (resultado.diagnostico === 'NAO_CONFIRMADO') {
        t.push('ℹ️ *CIG não confirmada (ABT < 10 mcmol/L).*');
        t.push('');
      }

      // Tratamento
      if (resultado.tratamento) {
        t.push('💊 *TRATAMENTO:*');
        resultado.tratamento.farmacologico.forEach(function(f) {
          t.push(' • *' + f.farmaco + '* (' + f.linha + ')');
          t.push('   Dose: ' + f.dose);
          if (f.posologia) t.push('   Posologia: ' + f.posologia);
          if (f.observacao) t.push('   _' + f.observacao + '_');
        });
        if (resultado.tratamento.nao_farmacologico.length > 0) {
          t.push('');
          t.push('🧴 *Medidas não farmacológicas:*');
          resultado.tratamento.nao_farmacologico.forEach(function(m) {
            t.push(' • ' + m);
          });
        }
        t.push('');
      }

      // Vigilância
      if (resultado.vigilancia) {
        t.push('👁️ *VIGILÂNCIA:*');
        t.push(' • Lab: ' + resultado.vigilancia.laboratorial);
        t.push(' • Hepática: ' + resultado.vigilancia.hepatica);
        t.push(' • Fetal: ' + resultado.vigilancia.fetal);
        if (resultado.vigilancia.nota) t.push(' • ' + resultado.vigilancia.nota);
        t.push('');
      }

      // Parto
      if (resultado.parto) {
        t.push('🏥 *PROGRAMAÇÃO DO PARTO:*');
        t.push(' • IG alvo: *' + resultado.parto.ig_alvo_texto + '*');
        t.push(' • Via: ' + resultado.parto.via_parto);
        t.push(' • Justificativa: ' + resultado.parto.justificativa);
        if (resultado.parto.parto_indicado_agora) {
          t.push(' • 🚨 *PARTO INDICADO AGORA* (IG >= alvo)');
        }
        if (resultado.parto.corticoide && resultado.parto.corticoide.indicado) {
          t.push('');
          t.push('💉 *CORTICOIDE ANTENATAL (INDICADO):*');
          t.push(' • ' + resultado.parto.corticoide.esquema);
        }
        if (resultado.parto.vitamina_k && resultado.parto.vitamina_k.indicada) {
          t.push('');
          t.push('💊 *VITAMINA K:*');
          t.push(' • ' + resultado.parto.vitamina_k.dose);
          t.push('   _' + resultado.parto.vitamina_k.justificativa + '_');
        }
        t.push('');

        t.push('🚨 *CRITÉRIOS DE ENCAMINHAMENTO / MATERNIDADE DE ALTO RISCO:*');
        t.push(' • *CIG Grave (ABT >= 100 mcmol/L) ou Moderada (ABT >= 40):* Encaminhamento IMEDIATO para Centro Terciário com Medicina Fetal (risco de óbito fetal súbito e resolução entre 36 e 37 semanas).');
        t.push(' • *CIG com Prurido Intratável ou Piora Bioquímica:* Encaminhar ao Pré-Natal de Alto Risco para ajuste de UDCA e vigilância de bem-estar fetal.');
        t.push(' • *Suspeita de EHAG / Pré-eclâmpsia (Swansea >= 6):* Vaga zero / UTI obstétrica imediata para estabilização e parto de emergência.');
        t.push('');
      }

    } else if (resultado.diagnostico === 'EHAG_CONFIRMADA' || resultado.diagnostico === 'EHAG_NAO_CONFIRMADA') {
      // ── EHAG ──
      t.push('🔴 *ESTEATOSE HEPÁTICA AGUDA DA GESTAÇÃO (EHAG / AFLP)*');
      t.push('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
      t.push('');

      t.push('📊 *CRITÉRIOS DE SWANSEA:* ' + resultado.total_presentes + '/' + resultado.total_criterios + ' (limiar >= ' + resultado.limiar + ')');
      t.push('🏷️ *STATUS:* ' + (resultado.confirmado ? '✅ CONFIRMADA' : '❌ NÃO CONFIRMADA'));
      t.push('');

      if (resultado.criterios_presentes.length > 0) {
        t.push('✅ *Critérios presentes:*');
        resultado.criterios_presentes.forEach(function(c) {
          t.push(' • ' + c);
        });
        t.push('');
      }

      // Protocolo
      if (resultado.protocolo) {
        var p = resultado.protocolo;
        t.push('🚨 *PRIORIDADE:* ' + p.prioridade);
        t.push('');

        t.push('👥 *EQUIPE MULTIDISCIPLINAR:*');
        p.equipe.forEach(function(e) { t.push(' • ' + e); });
        t.push('');

        t.push('⚡ *ESTABILIZAÇÃO PRÉ-PARTO:*');
        p.estabilizacao_pre_parto.forEach(function(e) { t.push(' • ' + e); });
        t.push('');

        t.push('🏥 *PARTO:*');
        t.push(' • *Urgência:* ' + p.parto.urgencia);
        t.push(' • *Via:* ' + p.parto.via);
        t.push(' • *Anestesia:* ' + p.parto.anestesia);
        t.push(' • _' + p.parto.nota + '_');
        t.push('');

        t.push('🔄 *PÓS-PARTO:*');
        p.pos_parto.forEach(function(e) { t.push(' • ' + e); });
        t.push('');
      }
    }

    // Alertas
    if (resultado.alertas && resultado.alertas.length > 0) {
      t.push('⚠️ *ALERTAS:*');
      resultado.alertas.forEach(function(a) { t.push(' • ' + a); });
      t.push('');
    }

    // Diagnóstico diferencial
    if (resultado.diagnostico_diferencial && resultado.diagnostico_diferencial.length > 0) {
      t.push('🔍 *DIAGNÓSTICO DIFERENCIAL:*');
      resultado.diagnostico_diferencial.forEach(function(d) { t.push(' • ' + d); });
      t.push('');
    }

    // Bloqueios de segurança
    if (resultado.bloqueios_seguranca && resultado.bloqueios_seguranca.length > 0) {
      t.push('🛡️ *BLOQUEIOS DE SEGURANÇA:*');
      resultado.bloqueios_seguranca.forEach(function(b) { t.push(' • ' + b); });
      t.push('');
    }

    // Referências
    t.push('📚 Fontes: RCOG 2024, SMFM 2024, Ovadia Lancet 2019, ACOG 2022, Swansea (Gut 2002/2008), FEBRASGO 2024, AASLD 2021.');
    t.push('Decisão final do obstetra e hepatologista assistente.');

    return t.join('\n');
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // 10. API PÚBLICA
  // ═══════════════════════════════════════════════════════════════════════════

  return {
    classificarGravidadeCIG: classificarGravidadeCIG,
    calcularDoseUDCA: calcularDoseUDCA,
    avaliarCIG: avaliarCIG,
    avaliarSwansea: avaliarSwansea,
    diagnosticoDiferencial: diagnosticoDiferencial,
    extrairParametrosTexto: extrairParametrosTexto,
    avaliar: avaliar,
    formatarTextoTelegram: formatarTextoTelegram,
    CRITERIOS_SWANSEA: CRITERIOS_SWANSEA,
    FAIXAS_ABT: FAIXAS_ABT,
    REFERENCIAS: REFERENCIAS
  };
})();

if (typeof module !== 'undefined' && typeof module.exports !== 'undefined') {
  module.exports = HepatologiaColestaseGestacionalService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_hepatologia_hda.js
// ==============================================================================

/**
 * ==============================================================================
 * MÓDULO 02: HEPATOLOGIA CLÍNICA E HEMORRAGIA DIGESTIVA ALTA (HDA)
 * ==============================================================================
 * Diretrizes Clínicas Oficiais:
 *  - AASLD / EASL Guidelines for Management of Portal Hypertension and Variceal Bleeding
 *  - Sociedade Brasileira de Hepatologia (SBH)
 *
 * PILARES CLÍNICOS DETERMINÍSTICOS:
 *  1. Escore MELD / MELD-Na (Model for End-Stage Liver Disease) e Child-Pugh:
 *     - Classificação de gravidade e ajuste posológico.
 *  2. Protocolo Ágil de Manejo de HDA Varicosa:
 *     - IBP IV Contínuo (Esomeprazol ou Pantoprazol: 80 mg bolus seguido de 8 mg/h contínuo).
 *     - Fármacos vasoativos: Terlipressina (2 mg IV bolus 4/4h inicial) ou Octreotide (50 mcg bolus + 50 mcg/h).
 *     - Profilaxia de PBE: Ceftriaxona 1g IV 1x/dia por 7 dias (máx).
 *     - Restrição volêmica (alvo PAS 90-100 mmHg; HR < 100).
 *     - Gatilhos transfusionais (alvo Hb 7-8 g/dL).
 */

const HepatologiaHdaService = (function() {

  function calcularChildPugh(bilirrubina, albumina, inr, ascite, encefalopatia) {
    let pontos = 0;
    
    // Bilirrubina (mg/dL)
    if (bilirrubina < 2.0) pontos += 1;
    else if (bilirrubina <= 3.0) pontos += 2;
    else pontos += 3;

    // Albumina (g/dL)
    if (albumina > 3.5) pontos += 1;
    else if (albumina >= 2.8) pontos += 2;
    else pontos += 3;

    // INR
    if (inr < 1.7) pontos += 1;
    else if (inr <= 2.2) pontos += 2;
    else pontos += 3;

    // Ascite (0=ausente, 1=leve/controlada, 2=moderada/tensa)
    if (ascite === 0) pontos += 1;
    else if (ascite === 1) pontos += 2;
    else pontos += 3;

    // Encefalopatia (0=ausente, 1=grau 1-2, 2=grau 3-4)
    if (encefalopatia === 0) pontos += 1;
    else if (encefalopatia === 1) pontos += 2;
    else pontos += 3;

    let classe = '';
    let sobrevida1ano = '';
    let sobrevida2anos = '';
    if (pontos <= 6) { classe = 'A'; sobrevida1ano = '100%'; sobrevida2anos = '85%'; }
    else if (pontos <= 9) { classe = 'B'; sobrevida1ano = '80%'; sobrevida2anos = '60%'; }
    else { classe = 'C'; sobrevida1ano = '45%'; sobrevida2anos = '35%'; }

    return { pontos, classe, sobrevida1ano, sobrevida2anos };
  }

  function calcularMeldNa(bilirrubina, inr, creatinina, sodio, dialise) {
    // Limits
    let cr = Math.max(1.0, creatinina);
    if (cr > 4.0 || dialise) cr = 4.0;
    
    let bil = Math.max(1.0, bilirrubina);
    let myInr = Math.max(1.0, inr);
    
    // Original MELD (UNOS formula)
    let meldOriginal = (3.78 * Math.log(bil)) + (11.2 * Math.log(myInr)) + (9.57 * Math.log(cr)) + 6.43;
    meldOriginal = Math.round(meldOriginal);
    
    if (meldOriginal < 11) {
        return { meldOriginal: meldOriginal, meldNa: meldOriginal };
    }

    let na = sodio;
    if (na < 125) na = 125;
    if (na > 137) na = 137;

    // MELD-Na formula
    let meldNa = meldOriginal - na - (0.025 * meldOriginal * (140 - na)) + 140;
    meldNa = Math.round(meldNa);

    return { meldOriginal, meldNa };
  }

  function manejarHdaVaricosa(peso, estabilidadeHemodinamica, contraindicacaoTerlipressina) {
    let t = [];
    
    t.push("💊 *Protocolo de HDA Varicosa (Hemorragia Digestiva Alta)*");
    t.push("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    
    // Ressuscitação e Metas
    t.push("💧 *1. Ressuscitação e Metas Hemodinâmicas:*");
    if (estabilidadeHemodinamica === false) {
       t.push(" • Acesso venoso duplo e calibroso. Iniciar ressuscitação volêmica cuidadosa.");
    }
    t.push(" • **Restrição de Cristaloides:** Evitar sobrecarga (risco de rebote de hipertensão portal). Alvo de PAS 90-100 mmHg.");
    t.push(" • **Transfusão Restritiva:** Transfundir CHAD apenas se Hb < 7 g/dL (alvo Hb 7 a 8 g/dL).");
    t.push("");

    // Fármaco Vasoativo
    t.push("🩸 *2. Droga Vasoativa (Iniciar IMEDIATAMENTE, antes da EDA):*");
    if (!contraindicacaoTerlipressina) {
       let doseTerli = (peso && peso < 50) ? "1 mg" : "2 mg";
       t.push(` • **Terlipressina:** ${doseTerli} IV em bolus a cada 4 horas (primeiras 24-48h).`);
       t.push("   ↳ _Alerta:_ Monitorar isquemia miocárdica/periférica e hiponatremia.");
    } else {
       t.push(" • **Octreotide:** 50 mcg IV em bolus, seguido de infusão contínua de 50 mcg/h.");
       t.push("   ↳ _(Indicado devido à contraindicação ou indisponibilidade de Terlipressina)_");
    }
    t.push("");

    // Profilaxia Infecciosa
    t.push("🦠 *3. Profilaxia para PBE (Peritonite Bacteriana Espontânea):*");
    t.push(" • **Ceftriaxona:** 1g IV a cada 24 horas (máx 7 dias).");
    t.push("   ↳ _Obrigatório em todo cirrótico com sangramento TGI, reduz mortalidade e ressangramento._");
    t.push("");

    // IBP
    t.push("💊 *4. Supressão Ácida (IBP):*");
    t.push(" • **Pantoprazol ou Esomeprazol:** 80 mg IV em bolus (2 ampolas).");
    t.push(" • Seguida de infusão contínua de 8 mg/h por 72h (ou 40 mg IV de 12/12h se infusão não disponível).");
    t.push("");

    // EDA
    t.push("🔬 *5. Endoscopia Digestiva Alta (EDA):*");
    t.push(" • Deve ser realizada em **< 12 horas** da admissão.");
    t.push(" • Considerar Eritromicina 250mg IV 30-120 min antes para esvaziamento gástrico (se disponível).");

    return t.join("\n");
  }

  function avaliarHepatopatia(params) {
    let p = params || {};
    let t = [];
    
    if (p.bilirrubina !== undefined && p.albumina !== undefined && p.inr !== undefined && p.ascite !== undefined && p.encefalopatia !== undefined) {
      const child = calcularChildPugh(p.bilirrubina, p.albumina, p.inr, p.ascite, p.encefalopatia);
      t.push(`📊 *Escore de Child-Pugh:* ${child.pontos} pontos (Classe ${child.classe})`);
      t.push(` • Sobrevida estimada: ${child.sobrevida1ano} (1 ano) / ${child.sobrevida2anos} (2 anos).`);
      
      if (child.classe === 'C') {
         t.push(" ⚠️ *Atenção:* Insuficiência hepática grave. Ajustar rigorosamente doses de medicações de metabolismo hepático.");
      }
      t.push("");
    }

    if (p.bilirrubina !== undefined && p.inr !== undefined && p.creatinina !== undefined && p.sodio !== undefined) {
      const meld = calcularMeldNa(p.bilirrubina, p.inr, p.creatinina, p.sodio, p.dialise || false);
      t.push(`📈 *Escore MELD-Na:* ${meld.meldNa}`);
      t.push(` • MELD Original: ${meld.meldOriginal}`);
      t.push(` • Reflete a mortalidade em 3 meses e indica prioridade para transplante hepático.`);
      t.push("");
    }

    if (p.hda) {
      t.push(manejarHdaVaricosa(p.peso || 70, p.estabilidadeHemodinamica, p.contraindicacaoTerlipressina));
    }

    return t.join("\n").trim();
  }

  return {
    calcularChildPugh: calcularChildPugh,
    calcularMeldNa: calcularMeldNa,
    manejarHdaVaricosa: manejarHdaVaricosa,
    avaliarHepatopatia: avaliarHepatopatia
  };

})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = HepatologiaHdaService;
  module.exports.HepatologiaHdaService = HepatologiaHdaService;
}


