  function obterDiretrizesTrimestre(trimestreNum) {
    var num = parseInt(trimestreNum, 10);
    if (num < 1 || num > 3) num = 1;
    return DIRETRIZES_PRENATAL_POR_TRIMESTRE[num];
  }

