  'cardio': 'has_rotina',
  'cardiovascular': 'has_rotina',
  'dm': 'dm_rotina',
  'respiratorio': 'respiratorio_ivas',
  'ivas': 'respiratorio_ivas',
  'pneumo': 'respiratorio_ivas',
  'gastro': 'dispepsia_gastro',
  'abdome': 'dispepsia_gastro',
  'neuro': 'cefaleia_neuro',
